window.PHY_LESSONS = (window.PHY_LESSONS || []).concat([{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":1,"lesson_title":"الموصل الكروي المنفرد المعزول","order_index":1,"hook":"افرك بالوناً بشعرك ثم قرّبه من جدار — يلتصق! لقد خزّنت عليه شحنة. لكن جرّب أن تضع شحنة أكبر وأكبر على كرة معدنية معزولة… ستكتشف أنك سرعان ما تصطدم بجدار خفيّ: يقفز شرر من الكرة إلى الهواء وتهرب الشحنة. لماذا لا نستطيع خزن ما نشاء على موصل منفرد؟ الجواب يقودنا مباشرة إلى المتسعة.","concepts":[],"laws":[{"name":"جهد الموصل الكروي عند سطحه","formula":"V = kQ / r","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها:","items":["الكرة الصغيرة (r صغير) تصل إلى جهد عالٍ بشحنة قليلة — لأن r في المقام.","لذلك أطراف الأجسام المدبّبة (r ضئيل جداً) تُولّد مجالاً هائلاً عندها، وهذا سرّ عمل مانعة الصواعق: طرفها المدبّب يفرّغ الشحنة في الهواء قبل أن تتراكم."],"ministerial":false}],"tables":[],"examples":[{"problem":"موصل كروي نصف قطره r = 9cm شُحن بشحنة Q = 2×10⁻⁸ C (خذ k = 9×10⁹). احسب: ١) جهد سطحه. ٢) المجال الكهربائي عند سطحه.","givens":"المعطيات: r = 9cm = 0.09m — Q = 2×10⁻⁸ C — k = 9×10⁹","solution_steps":["الخطوة ١: جهد السطح: V = kQ/r = 9×10⁹ × 2×10⁻⁸ / 0.09 = 2000 V","الخطوة ٢: المجال عند السطح (أسرع طريق: E = V/r): E = V/r = 2000 / 0.09 ≈ 2.22×10⁴ V/m 💡 هذا المجال أقل بكثير من عتبة انهيار الهواء (3×10⁶ V/m)، فالكرة آمنة عند هذه الشحنة."],"ministerial":false}],"qa":[{"question":"نادراً ما يُستعمل الموصل الكروي المنفرد المعزول لتخزين الشحنات الكهربائية.","answer":"لأن زيادة شحنته تزيد جهده (V=kQ/r) ويزداد معه المجال الكهربائي عند سطحه، حتى يبلغ قوة العزل الكهربائي للهواء فيحصل انهيار كهربائي وتفريغ للشحنة خلال الهواء عبر شرارة — فلا يمكنه خزن كمية كبيرة من الشحنة.","type":"علل","ministerial":true},{"question":"ما الحلّ الذي يقودنا إليه فشل الموصل المنفرد؟","answer":"بدل موصل واحد، نستعمل موصلَين متقابلين يفصل بينهما عازل: نضع شحنة موجبة على أحدهما وسالبة على الآخر. هذا النظام يخزن شحنة أكبر بكثير عند جهد أقل بكثير — وهو المتسعة، موضوع الدرس القادم.","type":"انتبه!","ministerial":false}],"has_simulation":true,"simulation_title":"🌐 مختبر الموصل الكروي المنفرد"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":2,"lesson_title":"المتسعة والمتسعة ذات الصفيحتين المتوازيتين","order_index":2,"hook":"فلاش الكاميرا يومض بضوء يخطف البصر خلال جزء من الألف من الثانية — والبطارية لا تقدر على دفع طاقتها بهذه السرعة أبداً، فهي تُفرّغ ببطء. من أين جاءت هذه الدفقة المفاجئة؟ الجواب: قطعة صغيرة اسمها المتسعة، تمتلئ بالشحنة على مهل ثم تُفرّغها دفعة واحدة — تماماً مثل خزان الماء فوق سطح البيت.","concepts":[{"term":"المتسعة:","text":"جهاز يُستعمل لتخزين الشحنات الكهربائية والطاقة الكهربائية، يتكوّن من زوج (أو أكثر) من الصفائح الموصلة يفصل بينها عازل (فراغ أو هواء أو مادة عازلة). صافي شحنة المتسعة المشحونة يساوي صفراً دائماً، لأن +Q على صفيحة و−Q على الأخرى.","ministerial":false}],"laws":[{"name":"تعريف السعة","formula":"C = Q / ΔV","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها:","items":["السعة مثل حجم «التانكي» فوق سطح دارك — سعته 1000 لتر سواء كان ملآن أم فارغاً، فهو صفة في التانكي نفسه لا في الماء.","كذلك C صفة في المتسعة نفسها (هندستها وعازلها)، لا تتغيّر بشحنها أو تفريغها.","غيّر الشحنة Q في المختبر أدناه — سيتغيّر الجهد ΔV معها، لكن النسبة Q/ΔV تبقى ثابتة تماماً."],"ministerial":false}],"tables":[],"examples":[{"problem":"متسعة سعتها 10pF رُبطت ببطارية فرق جهدها 12V. احسب مقدار الشحنة المختزنة في أيٍّ من صفيحتيها.","givens":"المعطيات: C = 10pF = 10×10⁻¹² F — ΔV = 12V — المطلوب: Q = ؟","solution_steps":["الخطوة ١: من تعريف السعة C = Q/ΔV، نعيد ترتيبها لإيجاد الشحنة: Q = C × ΔV","الخطوة ٢: نعوّض القيم: Q = 10×10⁻¹² × 12 = 120×10⁻¹² C = 120 pC 💡 لا تنسَ ذكر الوحدة — الجواب العددي بلا وحدة ناقص بالتصحيح الوزاري."],"ministerial":true},{"problem":"متسعة اختُزنت في إحدى صفيحتيها شحنة 60μC عندما كان فرق الجهد بينهما 20V. ما مقدار سعتها؟ وكم تصبح شحنتها لو رُفع الجهد إلى 50V؟","givens":"المعطيات: Q₁ = 60μC — ΔV₁ = 20V","solution_steps":["الخطوة ١: السعة (ثابتة لا تتغيّر بالجهد): C = Q/ΔV = 60/20 = 3 μF","الخطوة ٢: عند رفع الجهد إلى 50V، السعة نفسها C=3μF: Q₂ = C×ΔV₂ = 3×50 = 150 μC 💡 السعة لم تتغيّر — الذي تغيّر هو الشحنة، تماماً كما يقول تعريف المتسعة."],"ministerial":false}],"qa":[{"question":"هل تعتمد السعة على مقدار الشحنة أو فرق الجهد؟","answer":"لا إطلاقاً — هذا أكثر خطأ شائع بالوزاري. السعة تعتمد فقط على الأبعاد الهندسية ونوع العازل (تدرسها بالتفصيل في الدرس ٤). فإذا ضاعفنا فرق الجهد، الذي يتغيّر هو الشحنة المختزنة (تتضاعف)، أما السعة فتبقى كما هي.","type":"انتبه!","ministerial":false},{"question":"صافي الشحنة الكلية للمتسعة المشحونة يساوي صفراً.","answer":"لأن إحدى صفيحتيها تحمل شحنة موجبة (+Q) والأخرى تحمل شحنة سالبة مساوية لها في المقدار (−Q)، فمجموعهما الجبري صفر — رغم أنها «مشحونة» وتختزن طاقة.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🧮 مختبر مفهوم المتسعة: C = Q/ΔV"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":3,"lesson_title":"العازل الكهربائي","order_index":3,"hook":"لو أخبرتك أن مجرّد وضع قطعة من البلاستيك أو الزجاج بين صفيحتي متسعة يمكن أن يضاعف قدرتها على خزن الشحنة عدة مرات — دون تغيير حجمها ولا جهد البطارية — لبدا الأمر سحراً. لكنه فيزياء بحتة اسمها الاستقطاب. تعال نفهم كيف.","concepts":[{"term":"العازل الكهربائي (Dielectric):","text":"مادة لا تحتوي على شحنات حرة تتحرك خلالها، تُوضع بين صفيحتي المتسعة. عند تعريضها للمجال الكهربائي تستقطب جزيئاتها: يظهر طرف موجب وآخر سالب لكل جزيء، فتنتظم الجزيئات بحيث تظهر شحنات سطحية على وجهي العازل معاكسة لشحنات الصفيحتين.","ministerial":false}],"laws":[{"name":"أثر العازل في السعة","formula":"C_k = k × C₀","variables_note":""}],"notes":[{"heading":"الحالتان اللتان يخلط بينهما الطلبة:","items":["• موصولة بالبطارية: فرق الجهد ΔV ثابت.","إدخال العازل يزيد C، ومن Q=CΔV تزداد الشحنة Q (البطارية تضخّ شحنة إضافية).","• مفصولة عن البطارية: الشحنة Q ثابتة (لا مصدر يغيّرها).","إدخال العازل يزيد C، ومن ΔV=Q/C يقلّ فرق الجهد، ويقلّ المجال إلى E/k."],"ministerial":false}],"tables":[],"examples":[{"problem":"متسعة سعتها والهواء بينها 4μF، مُلئ الحيّز بين صفيحتيها بمادة عازلة ثابت عزلها k=5. ١) ما سعتها الجديدة؟ ٢) إذا بقيت موصولة ببطارية 20V، كم تصبح شحنتها المختزنة؟","givens":"المعطيات: C₀ = 4μF — k = 5 — ΔV = 20V (موصولة ⟹ الجهد ثابت)","solution_steps":["الخطوة ١: السعة الجديدة: C_k = k×C₀ = 5×4 = 20 μF","الخطوة ٢: موصولة بالبطارية فالجهد ثابت 20V، والشحنة: Q = C_k×ΔV = 20×20 = 400 μC 💡 لو كانت مفصولة لبقيت Q ثابتة ونقص الجهد إلى ΔV/k بدلاً من ذلك — انتبه للحالة!"],"ministerial":false}],"qa":[{"question":"إدخال عازل كهربائي بين صفيحتي المتسعة بدلاً من الهواء يزيد من فائدتها العملية.","answer":"لسببين: ١) يزيد سعة المتسعة بمقدار ثابت العزل (C_k=kC₀). ٢) يزيد قدرة تحمّل المتسعة لفروق الجهد العالية (يرفع جهد الانهيار)، لأن قوة العزل الكهربائي للمادة أكبر من قوة عزل الهواء، فضلاً عن إمكانية تقريب الصفيحتين دون تلامس.","type":"علل","ministerial":true},{"question":"متسعة مشحونة ومفصولة عن البطارية، أُدخل بينها عازل. ماذا يحصل للمجال الكهربائي بين صفيحتيها؟","answer":"يقلّ. العازل يستقطب فتظهر شحنات سطحية على وجهيه تولّد مجالاً معاكساً للمجال المؤثر، فيصبح المجال المحصّل E_k = E/k (بينما الشحنة Q تبقى ثابتة لأن المتسعة مفصولة).","type":"سؤال","ministerial":true}],"has_simulation":true,"simulation_title":"🧊 مختبر العازل الكهربائي"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":4,"lesson_title":"العوامل المؤثرة في سعة المتسعة","order_index":4,"hook":"لو كنت مهندساً في مصنع متسعات وطُلب منك تصميم متسعة بسعة عالية جداً في حجم صغير — أيّ «مقابض» تملك لتكبير السعة؟ الجواب ثلاثة فقط: كبّر المساحة، قرّب الصفيحتين، أو اختر عازلاً أقوى. هذا الدرس هو دفتر شروط أي متسعة في العالم.","concepts":[],"laws":[{"name":"سعة المتسعة ذات الصفيحتين المتوازيتين","formula":"C = k ε₀ A / d","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها:","items":["عُد إلى «التانكي».","المساحة A مثل مساحة قاعدة الخزان (أوسع = يسع أكثر)، والبعد d مثل… كلما قرّبت الصفيحتين اشتدّ جذب الشحنات المتعاكسة عبر الفجوة فثبتت شحنة أكبر عند الجهد نفسه.","لهذا المتسعات العملية تجعل d صغيراً جداً وA كبيرة جداً (لفّ الصفائح)."],"ministerial":false}],"tables":[],"examples":[{"problem":"متسعة ذات صفيحتين متوازيتين، البعد بينهما 0.5cm وكل صفيحة مربعة طول ضلعها 10cm ويفصل بينهما الفراغ (ε₀=8.85×10⁻¹²). احسب: ١) سعتها. ٢) الشحنة المختزنة بعد تسليط فرق جهد 10V.","givens":"المعطيات: d = 0.5cm = 5×10⁻³ m — L = 0.1m — ΔV = 10V — k=1 (فراغ)","solution_steps":["الخطوة ١: المساحة المتقابلة: A = L² = (0.1)² = 1×10⁻² m²","الخطوة ٢: السعة: C = ε₀A/d = 8.85×10⁻¹² × (10⁻²/5×10⁻³) = 17.7×10⁻¹² F = 17.7 pF","الخطوة ٣: الشحنة: Q = C×ΔV = 17.7×10⁻¹² × 10 = 177×10⁻¹² C 💡 لا يمكن حساب الشحنة قبل معرفة السعة — رتّب خطواتك بحسب اعتماد كل مقدار على ما قبله."],"ministerial":false}],"qa":[{"question":"يُحدَّد مقدار أقصى فرق جهد كهربائي يمكن أن تعمل عنده المتسعة.","answer":"لأن استمرار زيادة فرق الجهد يزيد المجال الكهربائي بين الصفيحتين حتى يحصل عنده الانهيار الكهربائي للعازل نتيجة عبور شرارة كهربائية خلاله، فتتفرّغ المتسعة من كل شحنتها — وهذا يعني تلفها. (من أكثر تعاليل الفصل تكراراً بالوزاري!)","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🔋 مختبر المتسعة المستوية"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":5,"lesson_title":"طرائق ربط المتسعات (توازٍ وتوالٍ)","order_index":5,"hook":"عندك بطارية 12V ومتسعة مكتوب عليها «أقصى جهد 8V» — إن ربطتها مباشرة انهار عازلها وتلفت (تذكّر الدرس ٤!). وعندك مشروع يحتاج سعة 30μF ولا يتوفّر بالسوق إلا 10μF. الحل: الربط — على التوالي يتوزّع الجهد الكبير فلا تتحمّل الواحدة إلا جزءاً منه، أو على التوازي فتتجمع السعات وكأنها متسعة عملاقة واحدة.","concepts":[{"term":"","text":"١) قانون جمع المقلوبات هو للتوالي — عكس المقاومات تماماً كما ستدرس لاحقاً، فلا تخلط بينهما. ٢) إذا حصلت على 1/C_eq = 1/3 فالجواب C_eq = 3μF وليس 1/3! اختم دائماً بقلب الكسر. ٣) في التوالي لا تُجمع الشحنات (كلها واحدة)، وفي التوازي لا تُجمع الجهود (كلها واحدة). اسأل نفسك أولاً: «مَن المشترك في هذا الربط؟»","ministerial":false}],"laws":[{"name":"السعة المكافئة — التوازي","formula":"C_eq = C₁ + C₂ + C₃ + ⋯","variables_note":""},{"name":"السعة المكافئة — التوالي","formula":"1/C_eq = 1/C₁ + 1/C₂ + ⋯","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها:","items":["الصفائح المشتركة بسلك واحد تعمل كهربائياً كصفيحة واحدة كبيرة مساحتها مجموع المساحات.","وبما أن C ∝ A، فربط التوازي يكافئ زيادة المساحة السطحية — لذا تكون السعة المكافئة دائماً أكبر من أكبر سعة في المجموعة."],"ministerial":false},{"heading":"افهمها ولا تحفظها:","items":["الصفيحتان الخارجيتان فقط تتصلان بالبطارية، والبعد الفعلي بينهما هو مجموع الأبعاد الداخلية.","وبما أن C ∝ 1/d، فربط التوالي يكافئ زيادة البعد — لذا تكون السعة المكافئة دائماً أصغر من أصغر سعة في المجموعة."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١ (توازي): أربع متسعات (6μF, 12μF, 8μF, 4μF) مربوطة على التوازي، رُبطت المجموعة ببطارية 12V. احسب: ١) السعة المكافئة. ٢) الشحنة الكلية المختزنة.","givens":"المعطيات: توازٍ ⟹ ΔV=12V على كل متسعة","solution_steps":["الخطوة ١: السعة المكافئة (جمع مباشر): C_eq = 4+8+12+6 = 30 μF","الخطوة ٢: الشحنة الكلية: Q_total = C_eq × ΔV = 30×12 = 360 μC 💡 تحقّق: شحنة كل متسعة Q=CΔV تعطي (48,96,144,72)μC ومجموعها 360μC ✓"],"ministerial":false},{"problem":"مثال ٢ (توالي): ثلاث متسعات (18μF, 9μF, 6μF) على التوالي، شُحنت بشحنة كلية 300μC. احسب: ١) السعة المكافئة. ٢) الجهد الكلي. ٣) جهد المتسعة (6μF).","givens":"المعطيات: توالٍ ⟹ Q₁=Q₂=Q₃=300μC (الشحنة نفسها للجميع)","solution_steps":["الخطوة ١: السعة المكافئة: 1/C_eq = 1/6+1/9+1/18 = (3+2+1)/18 = 1/3 ⟹ C_eq = 3 μF","الخطوة ٢: الجهد الكلي: ΔV_total = Q/C_eq = 300/3 = 100 V","الخطوة ٣: جهد المتسعة 6μF: ΔV = Q/C = 300/6 = 50 V 💡 أصغر سعة أخذت أكبر جهد — لأن ΔV=Q/C والشحنة واحدة، فالعلاقة عكسية."],"ministerial":false}],"qa":[{"question":"ازدياد مقدار السعة المكافئة لمجموعة متسعات مربوطة على التوازي.","answer":"لأن ربط التوازي يكافئ زيادة المساحة السطحية المتقابلة (الصفائح الموصولة بالقطب نفسه تعمل عمل صفيحة واحدة كبيرة)، وبما أن السعة تتناسب طردياً مع المساحة فإن C_eq=C₁+C₂+⋯ تكون أكبر من أكبر سعة في المجموعة.","type":"علل","ministerial":true},{"question":"نقصان السعة المكافئة لمجموعة متسعات مربوطة على التوالي.","answer":"لأن ربط التوالي يكافئ زيادة البعد بين الصفيحتين الخارجيتين (البعد الفعلي هو مجموع الأبعاد)، وبما أن السعة تتناسب عكسياً مع البعد فإن السعة المكافئة تنقص وتكون أصغر من أصغر سعة في المجموعة.","type":"علل","ministerial":true},{"question":"ما الفائدة العملية من ربط مجموعة من المتسعات على التوالي؟","answer":"تقليل السعة المكافئة ليكون بالإمكان وضع فرق جهد أكبر على طرفي المجموعة، لأن فرق الجهد الكلي يتوزّع بين المتسعات فلا يقع على الواحدة إلا جزء منه — بخلاف متسعة منفردة قد لا تتحمّل هذا الجهد.","type":"سؤال","ministerial":true}],"has_simulation":true,"simulation_title":"🔗 مختبر طرائق ربط المتسعات"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":6,"lesson_title":"الطاقة المختزنة والقدرة","order_index":6,"hook":"جهاز إنعاش القلب (Defibrillator) يعيد الحياة بصدمة كهربائية. سرّه متسعة تشحن ببطء من البطارية ثم تُفرّغ نحو 200 جول في المريض خلال أقل من خمسة أجزاء من الألف من الثانية. البطارية عاجزة عن هذه القدرة الهائلة — لكن المتسعة تجعلها ممكنة. كيف؟ الجواب في مفهومَي الطاقة والقدرة.","concepts":[],"laws":[{"name":"الطاقة المختزنة في المتسعة (ثلاث صيغ متكافئة)","formula":"PE = ½ Q ΔV = ½ C ΔV² = Q² / 2C","variables_note":""},{"name":"القدرة عند التفريغ","formula":"P = PE / t","variables_note":""}],"notes":[{"heading":"أيّ صيغة أستعمل؟","items":["اختر الصيغة حسب المعطيات: عندك Q وΔV ⟵ استعمل ½QΔV؛ عندك C وΔV ⟵ استعمل ½CΔV²؛ عندك Q وC ⟵ استعمل Q²/2C.","الثلاث تعطي النتيجة نفسها دائماً."],"ministerial":false}],"tables":[],"examples":[{"problem":"متسعة سعتها 100μF شُحنت إلى فرق جهد 200V. احسب: ١) الطاقة المختزنة فيها. ٢) القدرة المتوسطة إذا فُرّغت خلال 4ms (أي 4×10⁻³ s).","givens":"المعطيات: C = 100μF = 10⁻⁴ F — ΔV = 200V — t = 4×10⁻³ s","solution_steps":["الخطوة ١: الطاقة (نملك C وΔV فنستعمل ½CΔV²): PE = ½CΔV² = ½ × 10⁻⁴ × (200)² = 2 J","الخطوة ٢: القدرة عند التفريغ: P = PE/t = 2 / (4×10⁻³) = 500 W 💡 لاحظ القدرة الضخمة (500 واط) من متسعة صغيرة — لأن الزمن قصير جداً. هذا سرّ الفلاش وجهاز الإنعاش."],"ministerial":false}],"qa":[{"question":"يمكن للمتسعة أن تجهّز قدرة كهربائية لحظية أكبر بكثير من البطارية التي شحنتها.","answer":"لأن المتسعة تختزن الطاقة أثناء شحنها البطيء ثم تُفرّغها في زمن قصير جداً t، والقدرة P=PE/t؛ فصغر الزمن يجعل القدرة كبيرة جداً — بينما البطارية تجهّز طاقتها ببطء فقدرتها اللحظية محدودة.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🔺 مختبر الطاقة المختزنة والقدرة"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":7,"lesson_title":"دائرة RC — الشحن والتفريغ","order_index":7,"hook":"لماذا يومض ضوء بعض الأجهزة ببطء بعد فصل الكهرباء بدل أن ينطفئ فوراً؟ ولماذا تُبقي إشارات المرور توقيتاً دقيقاً؟ خلف الكثير من هذه «المؤقتات» تقف دائرة RC: متسعة تُشحن وتُفرَّغ عبر مقاومة بمنحنى زمني يمكن التحكّم به بدقة.","concepts":[{"term":"انتبه! فخّا سؤال الرسم الأشهر بالوزاري:","text":"دائرة التفريغ بلا بطارية — مصدر الطاقة هو المتسعة المشحونة نفسها، ووجود بطارية في الرسم يُصفّر درجة السؤال. ودائماً سمِّ كل عنصر (متسعة، مفتاح، مصباح أو مقاومة، بطارية في الشحن فقط) — رسم صامت درجته ناقصة.","ministerial":true}],"laws":[],"notes":[],"tables":[],"examples":[{"problem":"دائرة شحن تحتوي بطارية ΔV=12V ومقاومة R=20Ω ومتسعة C=100μF ومفتاحاً. احسب: ١) أعظم تيار شحن لحظة غلق المفتاح. ٢) فرق الجهد بين صفيحتي المتسعة بعد اكتمال الشحن. ٣) الشحنة المختزنة.","givens":"المعطيات: ΔV=12V — R=20Ω — C=100μF","solution_steps":["الخطوة ١: أعظم تيار شحن (المتسعة فارغة، كل الجهد على R): I = ΔV/R = 12/20 = 0.6 A","الخطوة ٢: بعد اكتمال الشحن التيار صفر، فلا هبوط جهد على R: ΔV_C = ΔV_battery = 12 V","الخطوة ٣: الشحنة المختزنة: Q = C×ΔV = 100×10⁻⁶ × 12 = 1200 μC 💡 قوانين الشحنة والطاقة هي نفسها قوانين الدروس السابقة — المتسعة نفسها، فقط أضفنا زمناً ومقاومة."],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"⚡ مختبر النشاط: شحن وتفريغ المتسعة (G، K، C، R، L1، L2)"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":8,"lesson_title":"أنواع المتسعات والتطبيقات العملية","order_index":8,"hook":"أنت تحمل هذا الدرس كله في جيبك الآن: شاشة اللمس التي تستجيب لإصبعك متسعاتٌ تتغيّر سعتها عند اللمس، وفلاش الكاميرا متسعة تُفرّغ طاقتها دفعة واحدة، والمايكروفون متسعة تهتز صفيحتها مع صوتك. وفي المستشفى، جهاز إنعاش القلب الذي يعيد الحياة بصدمة كهربائية… متسعة أيضاً!","concepts":[],"laws":[],"notes":[{"heading":"افهمها ولا تحفظها — لماذا سعة الإلكتروليتية ضخمة، ولماذا جهدها محدود؟","items":["عد إلى C = kε₀A/d.","طبقة الأكسيد العازلة في الإلكتروليتية سُمكها من رتبة أجزاء من المليون من الملّيمتر — أي d ضئيل جداً — كما تُخشَّن صفيحة الألمنيوم لتكبر مساحتها الفعلية أضعافاً، فـA كبيرة جداً.","صغر d وكبر A معاً يرفعان C ارتفاعاً هائلاً في حجم صغير.","لكن هذا نفسه ثمنه: المجال E = ΔV/d، وصغر d يعني بلوغ المجال قوةَ عزل الأكسيد عند فرق جهد منخفض نسبياً.","لذلك الإلكتروليتية تُصنع عادةً لفروق جهد محدودة (وحدات إلى مئات الفولطات فقط)، بينما المتسعة ذات الورق المشمّع أقدر منها على تحمّل الجهد العالي لأن عازلها أسمك.","لا توجد متسعة «الأفضل في كل شيء» — بل مقايضة بين السعة وتحمّل الجهد."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"يجب ربط المتسعة الإلكتروليتية بقطبية صحيحة.","answer":"لأن مادة عزلها تتولّد كيميائياً باتجاه واحد بين الألمنيوم والإلكتروليت — عكس القطبية يهدم طبقة العزل ويُتلف المتسعة.","type":"علل","ministerial":true},{"question":"اذكر تطبيقين عمليين للمتسعة مع الفائدة العملية لكل منهما.","answer":"مثال: ١) مصباح الكاميرا الومضي: تجهّز المصباح بطاقة تكفي لتوهّجه المفاجئ الساطع أثناء تفريغها. ٢) اللاقطة الصوتية: تحويل الذبذبات الميكانيكية (الصوت) إلى ذبذبات كهربائية. (اختر أي تطبيقين مع فائدة كل منهما نصاً — يتكرر هذا السؤال بصيغ مختلفة كثيراً).","type":"سؤال","ministerial":true}],"has_simulation":true,"simulation_title":"🗂️ معرض أنواع المتسعات وتطبيقاتها"},{"chapter_number":"g6c1","chapter_title":"المتسعات","lesson_number":9,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":9,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"متسعة ذات الصفيحتين المتوازيتين، مشحونة ومفصولة عن البطارية، الهواء يملأ الحيز بين صفيحتيها، أُدخلت مادة عازلة ثابت عزلها (k = 2) ملأت الحيز بين الصفيحتين، فإن مقدار المجال الكهربائي (Ek) بين صفيحتيها بوجود المادة العازلة مقارنة مع مقداره (E) في حالة الهواء، يصير:","answer":"E/2 — المتسعة معزولة (مفصولة عن البطارية) فالشحنة Q ثابتة. E = σ/(ε₀κ) = Q/(ε₀κA). عند k=2 يصبح المجال = Q/(ε₀×2×A) = E/2.","type":"سؤال","ministerial":false},{"question":"وحدة (Farad) تُستعمل لقياس سعة المتسعة وهي لا تكافئ إحدى الوحدات الآتية:","answer":"Coulomb × V² — C=Q/V ⇒ Coulomb/V صحيحة. من U=Q²/2C ⇒ C=Q²/2U وحدتها Coulomb²/J صحيحة. من U=½CV² ⇒ C=2U/V² وحدتها J/V² صحيحة. أما Coulomb×V² فليست مكافئة للفاراد (أبعادها C·V² وليست C/V).","type":"سؤال","ministerial":false},{"question":"متسعة ذات الصفيحتين المتوازيتين، سعتها C، قُرّبت صفيحتاها من بعضهما حتى صار البعد بينهما (⅓) ما كان عليه، فإن مقدار سعتها الجديدة يساوي:","answer":"3C — C = ε₀A/d، فإذا صار d الجديد = d/3 فإن C الجديدة = ε₀A/(d/3) = 3×(ε₀A/d) = 3C.","type":"سؤال","ministerial":false},{"question":"متسعة مقدار سعتها (20μF)، لكي تختزن طاقة في مجالها الكهربائي مقدارها (2.5J) يتطلب ربطها بمصدر فرق جهده مستمر يساوي:","answer":"500V — U=½CV² ⇒ V=√(2U/C)=√(2×2.5/20×10⁻⁶)=√(250000)=500V.","type":"سؤال","ministerial":false},{"question":"متسعة ذات الصفيحتين المتوازيتين سعتها (50 μF)، الهواء يملأ الحيز بين صفيحتيها، إذا أُدخلت مادة عازلة بين صفيحتيها ازدادت سعتها بمقدار (60 μF)، فإن ثابت عزل تلك المادة يساوي:","answer":"2.2 — السعة الجديدة = 50+60=110μF. k = C_جديدة/C_هواء = 110/50 = 2.2.","type":"سؤال","ministerial":false},{"question":"وأنت في المختبر تحتاج إلى متسعة سعتها (10μF) والمتوافر لديك مجموعة من المتسعات المتماثلة من ذوات السعة (15 μF)، فإن عدد المتسعات التي تحتاجها وطريقة الربط التي تختارها هي:","answer":"العدد 3 اثنان منها تُربط على التوازي ومجموعتهما تُربط مع الثالثة على التوالي — اثنتان على التوازي: 15+15=30μF. بالتوالي مع الثالثة (15μF): (30×15)/(30+15)=450/45=10μF ✓ يطابق المطلوب.","type":"سؤال","ministerial":false},{"question":"متسعة ذات الصفيحتين المتوازيتين ربطت صفيحتاها بين قطبي بطارية تجهز فرق جهد ثابت، فإذا أُبعدت الصفيحتان عن بعضهما قليلاً مع بقاء البطارية موصولة بهما فإن مقدار المجال الكهربائي بين الصفيحتين:","answer":"يقل والشحنة المختزنة في أي من صفيحتيها تقل — V ثابت (بطارية موصولة). زيادة d تقلل C=ε₀A/d فتقل Q=CV. والمجال E=V/d يقل أيضاً لأن d ازداد و V ثابت.","type":"سؤال","ministerial":false},{"question":"للحصول على أكبر مقدار سعة مكافئة لمجموعة المتسعات في الشكل (37)، اختر الدائرة المربوطة في الشكل:","answer":"d — a: (2∥4)=6µF، بالتوالي مع 3 ⇒ (6×3)/9=2µF. b: 2∥1=3µF. c: 12 بالتوالي مع 6 ⇒ (12×6)/18=4µF. d: 4µF بالتوازي مع (2∥2=4µF) ⇒ 4+4=8µF (الأكبر).","type":"سؤال","ministerial":false},{"question":"متسعتان (C1، C2) رُبطتا مع بعضهما على التوالي، ومجموعتهما رُبطت بين قطبي بطارية، وكان مقدار سعة الأولى أكبر من مقدار سعة الثانية. وعند مقارنة فرق الجهد بين صفيحتي المتسعة الأولى (ΔV1) مع فرق الجهد بين صفيحتي المتسعة الثانية (ΔV2) نجد أن:","answer":"ΔV2 أكبر من ΔV1 — في التوالي: نفس الشحنة Q على الاثنتين. ΔV=Q/C، وبما أن C1>C2 فإن ΔV1=Q/C1 أصغر من ΔV2=Q/C2. إذن ΔV2 أكبر من ΔV1.","type":"سؤال","ministerial":false},{"question":"ثلاث متسعات (C1، C2، C3) مربوطة مع بعضها على التوازي ومجموعتها رُبطت بين قطبي بطارية، كان مقدار سعاتها (C1>C2>C3). وعند مقارنة مقدار الشحنات (Q1، Q2، Q3) المختزنة في أي من صفيحتي كل متسعة، نجد أن:","answer":"Q1>Q2>Q3 — في التوازي: نفس فرق الجهد V على الجميع. Q=CV، فتتناسب Q طردياً مع C، وبما أن C1>C2>C3 فإن Q1>Q2>Q3.","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين (الهواء عازل بينهما)، عند زيادة المساحة السطحية المتقابلة للصفيحتين مع بقاء البعد بينهما ونوع العازل ثابتين، فإن سعتها:","answer":"تزداد طردياً مع المساحة، وفق العلاقة C=ε₀κA/d — من C=ε₀κA/d: C تتناسب طردياً وخطياً مع A مع بقاء d وκ ثابتين.","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين، عند زيادة البعد بين الصفيحتين مع بقاء المساحة ونوع العازل ثابتين، فإن سعتها:","answer":"تقل عكسياً مع البعد، وفق العلاقة C=ε₀κA/d — من C=ε₀κA/d: C تتناسب عكسياً مع d (تناسب خطي عكسي) مع بقاء A وκ ثابتين.","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين (الهواء عازل بينهما)، عند إدخال مادة عازلة ثابت عزلها κ لتملأ الحيز بين الصفيحتين بدلاً من الهواء، مع بقاء المساحة والبعد ثابتين، فإن سعة المتسعة الجديدة تصبح:","answer":"تساوي سعة الهواء مضروبة في κ، وفق العلاقة C=ε₀κA/d — C_هواء = ε₀A/d (κ=1). بإدخال عازل ثابته κ: C = ε₀κA/d = κ×C_هواء.","type":"سؤال","ministerial":false},{"question":"عند مضاعفة مقدار فرق الجهد الكهربائي بين صفيحتي متسعة ذات سعة ثابتة، فإن:","answer":"تتضاعف الشحنة وتصبح الطاقة أربعة أمثالها — Q=CV، فمضاعفة V تُضاعف Q. أما U=½CV² فتعتمد على مربع V، فمضاعفة V تجعل U أربعة أمثالها.","type":"سؤال","ministerial":false},{"question":"متسعة مشحونة، فرق الجهد بين صفيحتيها عالٍ جداً وهي مفصولة عن مصدر الفولطية، تبقى لمدة زمنية طويلة خطرة عند لمس صفيحتيها مباشرة. ما تفسير ذلك؟","answer":"لأن العزل يمنع تسرّب الشحنة فتبقى المتسعة مشحونة مدة طويلة، واللمس يوفّر مسار تفريغ عبر الجسم — المتسعة المعزولة تحتفظ بشحنتها Q (وفولطيتها وطاقتها) لأن لا مسار تفريغ إلا عبر عزل جيد بطيء التسرب؛ لمسها مباشرة يوفر مساراً عبر الجسم يُفرِّغ الطاقة المختزنة فجأة. الصياغة الكاملة للجواب: لأن العزل بين صفيحتيها يمنع تسرّب الشحنة بسرعة، فتبقى الشحنة (وبالتالي فرق الجهد والطاقة المختزنة) محتفَظاً بها لفترة طويلة، ولمس الصفيحتين يوفر مساراً يُفرِّغ هذه الطاقة فجأة خلال الجسم","type":"سؤال","ministerial":false},{"question":"في دائرة كهربائية لشحن متسعة عبر مقاومة R من بطارية ثم تفريغها، أي وصف للدائرة صحيح؟","answer":"الشحن: بطارية ومقاومة ومتسعة في حلقة مغلقة؛ والتفريغ: الحلقة نفسها بلا بطارية إطلاقاً — دائرة RC النموذجية: عند الشحن تُغلق الحلقة على البطارية والمقاومة والمتسعة. للتفريغ تُفصل البطارية وتُبقى المتسعة موصولة بالمقاومة في حلقة مغلقة فيتدفق التيار عكسياً حتى تتلاشى الشحنة. الصياغة الكاملة للجواب: الشحن: بطارية + مقاومة + متسعة في حلقة مغلقة بمفتاح؛ والتفريغ: إزالة البطارية من الحلقة وإبقاء المتسعة والمقاومة في حلقة مغلقة، فتندفع الشحنة عكسياً عبر R حتى تتلاشى","type":"سؤال","ministerial":false},{"question":"لديك ثلاث متسعات متماثلة سعة كل منها C ومصدر فولطية مستمر فرق جهده ثابت V. أي طريقة ربط تعطي أكبر مقدار من الطاقة الكهربائية المختزنة في المجموعة؟","answer":"ربط الثلاث جميعاً على التوازي (Ceq=3C) — U=½CeqV² وV ثابت (مصدر واحد)، فتعظيم U يستلزم تعظيم Ceq. أكبر Ceq لثلاث متماثلات هو ربطها جميعاً على التوازي: Ceq=3C.","type":"سؤال","ministerial":false},{"question":"المتسعات المؤلَّفة من صفائح دوّارة متعددة (متسعة متغيرة السعة تُستعمل في أجهزة الاستقبال) تكون فيها المتسعات الأولية (بين كل صفيحتين متجاورتين) مربوطة مع بعضها:","answer":"على التوازي، لأن جميع الصفائح الدوّارة مربوطة كهربائياً معاً (لوح واحد فعلياً) وكذلك جميع الصفائح الثابتة، فتتشارك كل الأزواج فرق الجهد نفسه — كل الصفائح الدوّارة متصلة معاً كهربائياً (قطب واحد) وكل الصفائح الثابتة متصلة معاً (القطب الآخر)، فكل زوج متجاور يشكّل متسعة بين نفس العقدتين ⇒ ربط توازي، وCeq=مجموع السعات الأولية.","type":"سؤال","ministerial":false},{"question":"ثلاث متسعات متماثلة سعة كل منها C، رُبطت بأربع طرائق: (a) الثلاث على التوالي، (b) اثنتان على التوازي وناتجهما على التوالي مع الثالثة، (c) اثنتان على التوالي وناتجهما على التوازي مع الثالثة، (d) الثلاث على التوازي. رتّب السعة المكافئة للمجموعة من الأكبر إلى الأصغر:","answer":"d > c > b > a — a=C/3، b=(2C×C)/(2C+C)=2C/3، c=(C/2)+C=3C/2، d=3C. بالترتيب التنازلي: d(3C) > c(3C/2) > b(2C/3) > a(C/3).","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين مشحونة ومفصولة عن البطارية، لو مُلئ الحيز بين صفيحتيها بالماء النقي بدلاً من الهواء، فإن فرق الجهد الكهربائي بين صفيحتيها سينخفض. ما السبب؟","answer":"لأن الماء عازل يزيد السعة، والشحنة ثابتة (معزولة) فينخفض الجهد — الماء عازل ثابت عزله كبير (κ≈80)، فإدخاله يزيد C = κC_هواء بمقدار كبير. المتسعة معزولة فـ Q ثابتة، وV=Q/C ينخفض بشدة.","type":"سؤال","ministerial":false},{"question":"في بعض لوحات مفاتيح الحاسوب تُستعمل متسعة تحت كل مفتاح لاستشعار الضغط عليه. عند الضغط على المفتاح، ما العامل الفيزيائي الذي يتغيّر في تلك المتسعة مسبباً تغيّر سعتها؟","answer":"البعد بين صفيحتيها، إذ يقترب اللوحان عند الضغط فتزداد السعة — الضغط على المفتاح يقرّب صفيحتي المتسعة (يقلل d)، فتزداد C=ε₀κA/d، ويستشعر الدارة الإلكترونية هذا التغير.","type":"سؤال","ministerial":false},{"question":"ما مصدر الطاقة الكهربائية في جهاز الصدمات القلبية (Defibrillator) المستعمل لتوليد الصدمة الكهربائية لغرض تحفيز وإعادة انتظام عمل قلب المريض؟","answer":"متسعة تُشحن ببطء لجهد عالٍ ثم تُفرّغ بسرعة عبر جسم المريض — الجهاز يشحن متسعة كبيرة تدريجياً لفرق جهد عالٍ (طاقة U=½CV² كبيرة)، ثم يُفرّغها فجأة (زمن قصير جداً) عبر جسم المريض فتنتج نبضة تيار عالية القدرة. الصياغة الكاملة للجواب: متسعة كبيرة تُشحن ببطء إلى فرق جهد عالٍ ثم تُفرّغ شحنتها بسرعة عبر جسم المريض مطلقةً طاقة كبيرة خلال زمن قصير جداً","type":"سؤال","ministerial":false},{"question":"ما التفسير الفيزيائي الصحيح لازدياد السعة المكافئة عند ربط المتسعات على التوازي، ونقصانها عند ربطها على التوالي؟","answer":"التوازي يزيد المساحة الفعالة فتزداد C، والتوالي يزيد البعد الفعّال فتقل C — من C=ε₀κA/d: التوازي يُكافئ زيادة المساحة الكلية A فتزداد Ceq، والتوالي يُكافئ زيادة البعد الكلي d فتقل Ceq. الصياغة الكاملة للجواب: التوازي يزيد المساحة السطحية الفعالة المشتركة (كأنها متسعة واحدة أكبر مساحة) فتزداد C؛ والتوالي يزيد البعد الفعال الكلي بين الصفيحتين الطرفيتين (كأنها متسعة واحدة أكبر بعداً) فتقل C","type":"سؤال","ministerial":false},{"question":"علّل: المتسعة المشحونة والموضوعة في دائرة التيار المستمر تُعدّ مفتاحاً مفتوحاً؟","answer":"لأن عزلها الداخلي يمنع مرور التيار المستمر بعد اكتمال الشحن — في الحالة المستقرة (بعد اكتمال الشحن) لا ينساب تيار مستمر عبر متسعة لأن بين صفيحتيها عازل يمنع مرور الشحنات، فتتصرف الدائرة كأن ذلك الفرع مفتوح. الصياغة الكاملة للجواب: لأن عزلها الداخلي بين صفيحتيها يمنع مرور التيار المستمر خلالها في الحالة المستقرة بعد اكتمال الشحن، فلا ينساب تيار في ذلك الفرع كما لو كان مفتاحاً مفتوحاً","type":"سؤال","ministerial":false},{"question":"علّل: يقل مقدار المجال الكهربائي بين صفيحتي متسعة مشحونة ومفصولة عن البطارية عند إدخال مادة عازلة بين صفيحتيها؟","answer":"لأن استقطاب العازل يولّد شحنات سطحية ذات مجال معاكس، فيقل المجال إلى E₀/κ — استقطاب جزيئات العازل يولّد شحنات سطحية مستحثة مجالها معاكس للمجال الأصلي، فيقل المجال المحصّل الصافي داخل العازل إلى E₀/κ. الصياغة الكاملة للجواب: لأن جزيئات المادة العازلة تستقطب مكوّنةً شحنات سطحية مستحثة تولّد مجالاً معاكساً للمجال الأصلي، فيقل المجال المحصّلة بمقدار κ من قيمته الأصلية (E=E₀/κ)","type":"سؤال","ministerial":false},{"question":"علّل: يحدَّد مقدار أقصى فرق جهد كهربائي يمكن أن تعمل عنده المتسعة؟","answer":"بقوة العزل الكهربائي للمادة العازلة، فتجاوزها يُحدث انهياراً — لكل مادة عازلة حد أقصى للمجال الكهربائي تتحمله (قوة العزل الكهربائي)؛ تجاوزه يسبب انهيار العزل الكهربائي وتفريغاً مفاجئاً، فيحدد ذلك أقصى فرق جهد آمن للمتسعة. الصياغة الكاملة للجواب: قوة تحمّل المادة العازلة (قوة العزل الكهربائي)؛ فإذا تجاوز المجال الكهربائي بين الصفيحتين الحد الذي تتحمله المادة العازلة، ينهار العزل ويصبح موصلاً فيحدث تفريغ مفاجئ يُتلف المتسعة","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين، الهواء عازل بينهما، شُحنت بوساطة بطارية ثم فُصلت عنها. عند إدخال لوح عازل كهربائي ثابت عزله (k=2) بين صفيحتيها، ماذا يحدث لكل من: الشحنة Q، السعة C، فرق الجهد V، المجال الكهربائي E، الطاقة المختزنة U؟","answer":"Q ثابتة (معزولة)، C تتضاعف (=2C)، V تنخفض للنصف (=V/2)، E ينخفض للنصف (=E/2)، U تنخفض للنصف (=U/2) — معزولة ⇒ Q ثابتة. C_جديدة=kC=2C. V=Q/C ⇒ V/2. E=V/d ⇒ E/2. U=Q²/2C ⇒ U/2 (أو U=½QV تعطي نفس النتيجة).","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين، الهواء عازل بينهما، رُبطت بين قطبي بطارية، وعند إدخال عازل كهربائي ثابت عزله (k=6) بين صفيحتيها والمتسعة ما زالت موصولة بالبطارية، ماذا يحدث لكل من: فرق الجهد V، السعة C، الشحنة Q، المجال الكهربائي E، الطاقة المختزنة U؟","answer":"V يبقى ثابتاً (تفرضه البطارية)، C تصبح 6 أمثالها، Q تصبح 6 أمثالها، E يبقى ثابتاً (=V/d ولم يتغير كل من V وd)، U تصبح 6 أمثالها — البطارية موصولة ⇒ V ثابت. C_جديدة=kC=6C. Q=CV ⇒ Q تصبح 6 أمثالها. E=V/d ثابت لأن V وd لم يتغيرا. U=½CV² ⇒ U تصبح 6 أمثالها.","type":"سؤال","ministerial":false},{"question":"دائرة RC كما في الشكل (40): بطارية جهدها الطرفي V=12V، متسعة C=100µF، مقاومة R=20Ω مربوطة على التوالي مع مفتاح. ما أعظم مقدار لتيار الشحن لحظة إغلاق المفتاح؟","answer":"I=0.6A — لحظة الإغلاق Vc=0 (المتسعة فارغة)، فكل جهد البطارية يقع على R: I_max=V/R=12/20=0.6A. لاحقاً (بعد زمن طويل، اكتمال الشحن): V_C=12V، Q=CV=1200µC=1.2mC، U=½CV²=7.2mJ.","type":"سؤال","ministerial":false},{"question":"متسعة ذات صفيحتين متوازيتين سعتها (C=4µF) رُبطت بين قطبي بطارية فرق الجهد بين قطبيها (20V). ما مقدار الشحنة المختزنة في أي من صفيحتي المتسعة؟","answer":"Q=80µC — Q=CV=4µF×20V=80µC.","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) إذا فُصلت المتسعة عن البطارية وأُدخل لوح عازل كهربائي بين صفيحتيها فهبط فرق الجهد بين صفيحتيها إلى (10V)، فإن ثابت عزل ذلك اللوح يساوي:","answer":"k=2 — بعد الفصل Q ثابتة (80µC). k=V/V'=20/10=2. (والسعة الجديدة C'=kC=8µF).","type":"سؤال","ministerial":false},{"question":"متسعتان (C1=9µF، C2=18µF) من ذوات الصفائح المتوازية مربوطتان مع بعضهما على التوالي، وربطت مجموعتهما مع مصدر فرق جهد كهربائي ثابت مقداره (12V) بين قطبيه. ما مقدار فرق الجهد بين صفيحتي المتسعة (C1)؟","answer":"ΔV1=8V — Ceq=(9×18)/27=6µF. Q=Ceq×V=72µC (نفسها على الاثنتين لأنهما على التوالي). ΔV1=Q/C1=72/9=8V (وΔV2=72/18=4V، والمجموع=12V ✓). U1=Q²/2C1=288µJ، U2=144µJ.","type":"سؤال","ministerial":false},{"question":"إذا أُدخل لوح عازل كهربائي ثابت عزله (k=4) بين صفيحتي المتسعة (C1) فقط من المسألة السابقة، مع بقاء البطارية مربوطة بين طرفي المجموعة، فإن فرق الجهد الجديد بين صفيحتي (C2) يصبح:","answer":"8V — C1الجديدة=4×9=36µF. Ceqالجديدة=(36×18)/54=12µF. Q'=12×12=144µC. ΔV2'=Q'/C2=144/18=8V (وΔV1'=144/36=4V، المجموع=12V ✓).","type":"سؤال","ministerial":false},{"question":"متسعتان من ذوات الصفائح المتوازيتين (C1=16µF، C2=24µF) مربوطتان مع بعضهما على التوازي ومجموعتهما مربوطة بين قطبي بطارية فرق الجهد بينهما (48V). إذا أُدخل لوح من مادة عازلة ثابت عزلها (k) بين صفيحتي المتسعة الأولى ومازالت المجموعة موصولة بالبطارية فكانت الشحنة الكلية للمجموعة (3456µC)، فإن ثابت العزل (k) يساوي:","answer":"k=3 — V=48V ثابت (توازي، بطارية موصولة). Q_كلية=(k×16+24)×48=3456 ⇒ 16k+24=72 ⇒ k=3. (قبل العزل: Q1=768µC، Q2=1152µC؛ بعده: Q1'=48×48=2304µC، Q2 ثابتة=1152µC؛ المجموع=3456µC ✓).","type":"سؤال","ministerial":false},{"question":"متسعتان (C1=4µF، C2=8µF) مربوطتان مع بعضهما على التوازي، فإذا شُحنت مجموعتهما بشحنة كلية مقدارها (600µC) بوساطة مصدر فولطية مستمرة ثم فُصلت عنه، فإن فرق الجهد بين طرفي المجموعة (وكل من المتسعتين) يساوي:","answer":"V=50V — Ceq=4+8=12µF. V=Q/Ceq=600/12=50V. Q1=C1V=200µC، Q2=C2V=400µC. U1=½C1V²=5mJ، U2=½C2V²=10mJ.","type":"سؤال","ministerial":false},{"question":"إذا أُدخل لوح عازل كهربائي ثابت عزله (k=2) بين صفيحتي المتسعة الثانية (C2) بعد فصل المجموعة عن المصدر (مع بقاء المتسعتين مربوطتين مع بعضهما)، فإن الشحنة الجديدة على المتسعة (C2) تصبح:","answer":"480µC — C2الجديدة=2×8=16µF. Ceqالجديدة=4+16=20µF. الشحنة الكلية محفوظة=600µC (متسعتان متصلتان مع بعضهما فقط، منعزلتان عن الخارج). V'=600/20=30V. Q2'=16×30=480µC (وQ1'=4×30=120µC).","type":"سؤال","ministerial":false},{"question":"لديك ثلاث متسعات سعاتها (C1=6µF، C2=9µF، C3=18µF) ومصدر فرق جهد كهربائي مستمر مقداره (6V). لأكبر مقدار للسعة المكافئة يجب ربط المتسعات الثلاث:","answer":"على التوازي جميعها — أكبر Ceq تكون بالتوازي دائماً: Ceq=6+9+18=33µF. الشحنات: Q1=C1V=36µC، Q2=54µC، Q3=108µC، ومجموعها 198µC.","type":"سؤال","ministerial":false},{"question":"أما لأصغر مقدار للسعة المكافئة لنفس المتسعات الثلاث (C1=6µF، C2=9µF، C3=18µF) مع نفس مصدر (6V)، فإن مقدار الشحنة المختزنة على صفيحتي كل متسعة (وهي نفسها على الثلاث لأنها على التوالي) يساوي:","answer":"Q=18µC — أصغر Ceq تكون بالتوالي: 1/Ceq=1/6+1/9+1/18=6/18 ⇒ Ceq=3µF. الشحنة (نفسها على الثلاث لأنها على التوالي) Q=CeqV=3×6=18µC.","type":"سؤال","ministerial":false},{"question":"أربع متسعات (C1=6µF، C2=3µF، C3=2µF، C4=4µF) رُبطت مع بعضها كما في الشكل (41): (C1) على التوالي مع (C2) وهذه المجموعة على التوازي مع (C3)، والمحصّلة على التوالي مع (C4)، وفرق الجهد الكلي بين طرفي الشبكة (ΔV=40V). ما مقدار السعة المكافئة للمجموعة؟","answer":"Ceq=2µF — C1توالي C2=(6×3)/9=2µF. بالتوازي مع C3(2µF)=4µF. بالتوالي مع C4(4µF)=(4×4)/8=2µF ⇒ Ceq=2µF. Q_كلي=Ceq×ΔV=80µC (على C4). فرق جهد الفرع المتوازي=80/4=20V (وV4=20V أيضاً). Q3=2×20=40µC، وQ1=Q2=2µF×20V=40µC (V1=40/6≈6.7V، V2=40/3≈13.3V). U4=½C4V4²=0.8mJ.","type":"سؤال","ministerial":false},{"question":"متسعتان (C1=6µF، C2=3µF) رُبطتا على التوالي مع بعضهما ثم رُبطت مجموعتهما بين قطبي بطارية فرق الجهد بينهما (90V) كما في الشكل (42-a). بعد اكتمال الشحن، فُصلت المتسعتان عن بعضهما وعن البطارية دون حدوث ضياع للطاقة، ثم أُعيد ربطهما مع بعضهما بحيث تتلامس الصفائح المتشابهة الشحنة (كما في الشكل 42-b). ما مقدار الشحنة المختزنة على المتسعة (C1) بعد إعادة الربط؟","answer":"240µC — قبل الفصل (على التوالي): Ceq=(6×3)/9=2µF، Q=Ceq×90=180µC (نفس الشحنة على كل من C1،C2). عند إعادة الربط بتماسّ الشحنات المتشابهة: الشحنة الكلية=180+180=360µC تتوزع على Ceq_توازي=6+3=9µF بفرق جهد مشترك V'=360/9=40V. Q1'=C1×V'=6×40=240µC (وQ2'=3×40=120µC).","type":"سؤال","ministerial":false},{"question":"أما إذا أُعيد ربط المتسعتين من المسألة السابقة (C1=6µF، C2=3µF، كل منهما كانت مشحونة بـ180µC) بحيث تتلامس الصفائح المختلفة الشحنة (كما في الشكل 42-c)، فإن مقدار الشحنة المختزنة على كل من المتسعتين بعد إعادة الربط يصبح:","answer":"صفراً لكلتا المتسعتين — كانت شحنتاهما الابتدائيتان متساويتين بالمقدار (180µC لكل منهما، لأنهما كانتا على التوالي)؛ فعند تلامس القطبين المختلفين تُلغي إحداهما الأخرى تماماً (الشحنة الصافية = 180-180=0)، فيصبح فرق الجهد المشترك صفراً وتتفرغ المتسعتان كلياً.","type":"سؤال","ministerial":false},{"question":"خمس متسعات (C2=3µF، C3=6µF، C4=18µF، C5=12µF، C6=9µF) رُبطت على هيئة شبكة جسر بين نقطتين (a) و(b) كما في الشكل (43): تصل (C3) و(C4) من (a) إلى عقدتين وسطيتين، وتصل (C2) و(C6) من العقدتين الوسطيتين إلى (b)، وتصل (C5) بين العقدتين الوسطيتين (ذراع الجسر). ما مقدار السعة المكافئة للمجموعة بين (a) و(b)؟","answer":"Ceq=8µF — نسبة الذراعين: C3/C2=6/3=2 وC4/C6=18/9=2 (متساويتان) ⇒ الجسر متوازن، فلا تنساب شحنة خلال C5 ويمكن إهمالها. تُختزل الشبكة إلى مسارين متوازيين بين a وb: مسار (C3 توالي C2)=(6×3)/9=2µF، ومسار (C4 توالي C6)=(18×9)/27=6µF. مجموعهما بالتوازي: Ceq=2+6=8µF. (لو طُبق فرق جهد 20V بين a وb: Q_كلية=160µC، موزعة 40µC على مسار C3-C2 و120µC على مسار C4-C6، وQ5=0).","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":1,"lesson_title":"القوة على شحنة متحركة وقوة لورنتز","order_index":1,"hook":"في شاشات التلفاز والراسمات القديمة (CRT)، تنطلق إلكترونات بسرعة هائلة داخل أنبوب مفرّغ، ثم تنحرف يميناً ويساراً وأعلى وأسفل لترسم الصورة على الشاشة — بلا أي لمسة يد. من يوجّه هذه الإلكترونات؟ الجواب: قوة خفية تصنعها مجالات كهربائية ومغناطيسية معاً. هذه القوة اسمها قوة لورنتز، وهي بطل درسنا اليوم.","concepts":[],"laws":[{"name":"القوة المغناطيسية على شحنة متحركة","formula":"F_b = q v B sin θ","variables_note":""},{"name":"قوة لورنتز","formula":"F_Lorentz = F_e + F_b","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها — حالتان حديّتان:","items":["إذا تحركت الشحنة موازية للمجال (θ=0°)، فإن sin 0 = 0 ⟹ لا قوة إطلاقاً مهما كانت سرعتها.","إذا تحركت الشحنة عمودية على المجال (θ=90°)، فإن sin 90 = 1 ⟹ القوة في أعظم مقدار لها: F_b = qvB."],"ministerial":false}],"tables":[],"examples":[{"problem":"شحنة q = 4×10⁻⁶ C تتحرك بسرعة v = 2×10⁵ m/s داخل مجال مغناطيسي منتظم B = 0.3 T، والزاوية بين السرعة والمجال 30°. احسب مقدار القوة المغناطيسية المؤثرة في الشحنة.","givens":"المعطيات: q = 4×10⁻⁶ C — v = 2×10⁵ m/s — B = 0.3 T — θ = 30° (sin30°=0.5)","solution_steps":["الخطوة ١: نكتب قانون القوة المغناطيسية: F_b = q v B sinθ","الخطوة ٢: نعوّض القيم ونحسب: F_b = 4×10⁻⁶ × 2×10⁵ × 0.3 × 0.5 = 0.12 N 💡 لاحظ أننا لم نستعمل أعظم قيمة (qvB) لأن الزاوية ليست 90°، بل ضربنا في sin30°=0.5 فقط."],"ministerial":false}],"qa":[{"question":"شحنة تتحرك موازية لمجال مغناطيسي منتظم لا تتأثر بأي قوة مغناطيسية.","answer":"لأن القوة المغناطيسية F_b = qvBsinθ، وعندما تكون السرعة موازية للمجال فإن الزاوية بينهما θ=0°، وبما أن sin 0° = 0 فإن F_b = صفر، أي لا قوة تؤثر في الشحنة.","type":"علل","ministerial":true},{"question":"لماذا لا تُغيّر القوة المغناطيسية مقدار سرعة الشحنة؟","answer":"لأن القوة المغناطيسية عمودية دائماً على متجه السرعة، وأي قوة عمودية على الحركة لا تبذل شغلاً عليها (W=Fd cos90°=0)، فلا تُغيّر طاقتها الحركية ولا مقدار سرعتها — تُغيّر اتجاهها فقط، فترسم مساراً منحنياً أو دائرياً.","type":"انتبه!","ministerial":false}],"has_simulation":true,"simulation_title":"🧲 مختبر الشحنة المتحركة في مجال مغناطيسي"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":2,"lesson_title":"القوة الدافعة المحتثة الحركية","order_index":2,"hook":"عام 1819 اكتشف أورستد أن التيار الكهربائي يصنع مجالاً مغناطيسياً حوله. فتساءل العلماء: هل يصحّ العكس — أن يصنع المغناطيس تياراً؟ ظلّ السؤال بلا جواب 12 عاماً، حتى حرّك فاراداي مغناطيساً بجانب ملف موصول بأميتر… فانحرف المؤشر فجأة بلا أي بطارية! لكن حين أسكن المغناطيس، عاد المؤشر للصفر فوراً. الحركة وحدها — أي التغيّر — هي ما ولّد التيار.","concepts":[],"laws":[{"name":"القوة الدافعة الكهربائية الحركية","formula":"ε = v B ℓ","variables_note":""},{"name":"التيار المحتث في الدائرة المقفلة","formula":"I = ε/R = vBℓ/R","variables_note":""}],"notes":[{"heading":"⭐ القاعدة الذهبية لكل هذا الفصل:","items":["التغيّر في الفيض المغناطيسي هو ما يولّد التيار المحتث — لا الفيض نفسه.","مغناطيس ساكن مهما كان قوياً لا يولّد أي تيار؛ لا بدّ من حركة نسبية أو تغيّر عبر الزمن."],"ministerial":false},{"heading":"💡 افهمها ولا تحفظها:","items":["القدرة الميكانيكية المبذولة لسحب الساق (P=F×v) تساوي تماماً القدرة الكهربائية المتبدّدة في المقاومة (P=I²R) — لا زيادة ولا نقصان.","لا توجد \"كهرباء مجانية\": كل جول من الطاقة الكهربائية دفعتَ ثمنه شغلاً ميكانيكياً.","وهذا بالضبط مبدأ عمل كل مولّد كهربائي في محطات الطاقة — تُدير التوربينَ بالماء أو البخار أو الرياح، فتتحوّل تلك الطاقة الميكانيكية إلى كهرباء بالحث، لا من العدم."],"ministerial":false}],"tables":[],"examples":[{"problem":"اشتقاق: كيف نصل من اتزان القوتين على الشحنة إلى قانون القوة الدافعة الكهربائية الحركية؟","givens":"الفكرة: الشحنات المتجمّعة عند طرفي الساق تُنشئ مجالاً كهربائياً E يعاكس استمرار الفصل، حتى تتوازن القوتان.","solution_steps":["الخطوة ١: عند الاتزان تتساوى القوة الكهربائية المعاكسة مع القوة المغناطيسية: F_E = F_B  ⟹  qE = qvB  ⟹  E = vB","الخطوة ٢: وبما أن المجال الكهربائي يساوي انحدار الجهد على طول الساق: E = ΔV/ℓ  ⟹  ΔV/ℓ = vB","الخطوة ٣: فرق الجهد بين طرفي الساق هو نفسه القوة الدافعة الكهربائية الحركية: ε = ΔV = v B ℓ 💡 لاحظ أن ε تعتمد على سرعة الساق وكثافة الفيض وطولها فقط — لا على نوع معدنها أو مقدار شحناتها."],"ministerial":false},{"problem":"ساق موصلة طولها 2m انزلقت على سكة موصلة بانطلاق 5 m/s عمودياً على مجال مغناطيسي منتظم كثافته 0.8T، وكانت مقاومة المصباح المربوط مع السكة 16Ω (بإهمال مقاومة الساق والسكة). احسب: ① القوة الدافعة الحركية المحتثة ② التيار المحتث ③ القدرة الكهربائية المجهَّزة للمصباح.","givens":"المعطيات: ℓ = 2 m — v = 5 m/s — B = 0.8 T — R = 16 Ω","solution_steps":["الخطوة ١: نوجد القوة الدافعة الحركية: ε = vBℓ = 5 × 0.8 × 2 = 8 V","الخطوة ٢: نوجد التيار المحتث بقانون أوم: I = ε/R = 8/16 = 0.5 A","الخطوة ٣: نوجد القدرة المجهَّزة للمصباح: P = I²R = (0.5)² × 16 = 4 W  (أو P = εI = 8 × 0.5 = 4W)"],"ministerial":false}],"qa":[{"question":"مغناطيس ساكن تماماً بجانب ملف موصل، مهما كانت قوته، لا يولّد فيه أي تيار محتث.","answer":"لأن التيار المحتث ينشأ فقط نتيجة تغيّر الفيض المغناطيسي المخترق للملف عبر الزمن. والمغناطيس الساكن نسبةً للملف يعطي فيضاً ثابتاً لا يتغيّر (ΔΦ_B=0)، فلا تتولد أي قوة دافعة محتثة ولا أي تيار.","type":"علل","ministerial":true},{"question":"هل يمكن أن تستمر الساق بالحركة بسرعة ثابتة دون أي قوة خارجية تسحبها؟","answer":"لا. فور انسياب التيار المحتث تنشأ القوة المعرقلة F=BIℓ فوراً وتعمل على تبطيء الساق. فإذا لم تُسحب الساق بقوة خارجية تساويها بالضبط، ستفقد سرعتها تدريجياً حتى تتوقف — ويتوقف التيار المحتث معها.","type":"انتبه!","ministerial":false},{"question":"ساق طولها 60cm تنزلق على سكة بتأثير قوة ساحبة ثابتة 0.06N عمودياً على مجال 0.5T، ومقاومة الدائرة الكلية 120Ω. جد: القوة الدافعة الحركية، سرعة الساق، والقدرة المتبدّدة.","answer":"نبدأ من القوة الساحبة (تساوي القوة المعرقلة عند السرعة الثابتة): F=IℓB ⟹ I=F/(Bℓ)=0.06/(0.5×0.6)=0.2A.\n① ε=IR=0.2×120=24V.\n② من ε=vBℓ: v=ε/(Bℓ)=24/(0.5×0.6)=80 m/s.\n③ P=I²R=(0.2)²×120=4.8W (أو F×v=0.06×80=4.8W).","type":"سؤال محلول","ministerial":true}],"has_simulation":true,"simulation_title":"🛤️ مختبر الساق المنزلقة"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":3,"lesson_title":"الفيض المغناطيسي","order_index":3,"hook":"لماذا تُركَّب ألواح الطاقة الشمسية بزاوية ميل محسوبة بدقة، لا أفقياً ولا عمودياً عشوائياً؟ لأن كمية الضوء الفعلية التي \"تخترق\" اللوح لا تعتمد على مساحته فقط، بل على زاوية ميله بالنسبة لأشعة الشمس أيضاً. نفس الفكرة بالضبط تحكم المغناطيسية: الفيض المغناطيسي هو مقياس لعدد خطوط المجال التي تخترق حلقة ما عمودياً — لا التي تمرّ بمحاذاتها فقط.","concepts":[],"laws":[{"name":"الفيض المغناطيسي","formula":"Φ_B = B A cos θ","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها — حالتان حديّتان:","items":["إذا واجه متجه المساحة المجال مباشرة (θ=0°)، فإن cos 0° = 1 ⟹ الفيض في أعظم مقدار له: Φ = BA.","إذا كان متجه المساحة عمودياً على المجال (θ=90°، أي مستوى الحلقة يوازي المجال)، فإن cos 90° = 0 ⟹ الفيض صفر مهما كانت مساحة الحلقة أو قوة المجال."],"ministerial":false},{"heading":"🔑 الطرائق الثلاث:","items":["تغيير الزاوية θ: بتدوير الحلقة داخل مجال ثابت — هذا هو مبدأ عمل كل مولّد كهربائي.","تغيير المساحة A: بكبس الحلقة أو شدّها، فيتغيّر الفيض بمقدار ΔΦ = B·ΔA — وهذا قريب من فكرة الساق المنزلقة بالدرس الماضي (فالمساحة المحصورة بين الساق والطرف المغلق تكبر مع حركتها).","تغيير كثافة الفيض B: بتقريب مغناطيس أو إبعاده، أو بإدخال الحلقة في المجال وإخراجها — وهي الطريقة التي شاهدتها في تجربة فاراداي بالدرس الماضي (تحريك المغناطيس قرب الملف)."],"ministerial":false}],"tables":[],"examples":[{"problem":"حلقة دائرية قطرها 0.4m داخل مجال مغناطيسي منتظم كثافته B=0.5T. جد الفيض المخترق لها: ① حين يوازي متجه مساحتها المجال تماماً، ② حين تدور الحلقة زاوية 45° عن وضعها الأول.","givens":"المعطيات: القطر = 0.4m ⟹ نصف القطر r = 0.2m — B = 0.5T (استعمل π≈3.14)","solution_steps":["الخطوة ١: نوجد مساحة الحلقة: A = πr² = 3.14 × (0.2)² = 12.56×10⁻² m²","الخطوة ٢: عند θ=0° (المتجه يوازي المجال): Φ = BA = 0.5 × 12.56×10⁻² = 6.28×10⁻² Wb","الخطوة ٣: عند θ=45°: Φ = BA cos45° = 6.28×10⁻² × 0.707 = 4.44×10⁻² Wb 💡 لاحظ أن الفيض قلّ بعد الدوران رغم أن B وA لم يتغيّرا — الزاوية وحدها غيّرته."],"ministerial":false}],"qa":[{"question":"لا تخلط بين جيب الزاوية sinθ (الدرس الماضي) وجيب تمامها cosθ (هذا الدرس)","answer":"في الدرس الأول استعملنا الجيب F_b=qvBsinθ لأن الزاوية θ هناك كانت بين متجه السرعة ومتجه المجال. أما هنا فالزاوية θ بين متجه المساحة (العمودي على الحلقة) ومتجه المجال، لذلك نستعمل جيب التمام cosθ. اقرأ السؤال جيداً لتعرف أي زاوية أُعطيت لك قبل اختيار الدالة المثلثية المناسبة.","type":"انتبه!","ministerial":false},{"question":"عندما يوازي مستوى حلقة موصلة خطوط مجال مغناطيسي منتظم، يكون الفيض المخترق لها صفراً.","answer":"لأن متجه المساحة (العمودي على مستوى الحلقة) يكون حينئذٍ عمودياً على المجال، أي θ=90°. وبما أن cos90°=0 فإن Φ_B=BAcos90°=صفر — بمعنى أن خطوط المجال \"تنزلق\" بمحاذاة سطح الحلقة دون أن تخترقه فعلياً.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🌀 مختبر دوران الحلقة"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":4,"lesson_title":"قانون فاراداي","order_index":4,"hook":"جرّب هذا ذهنياً: لو أدخلتَ مغناطيساً ببطء شديد داخل ملف موصول بمصباح صغير، سيومض المصباح بخفوت بالكاد يُلاحَظ. لكن لو دفعتَ نفس المغناطيس داخل نفس الملف بسرعة أكبر بكثير… يتوهّج المصباح فجأة أقوى بكثير! لم يتغيّر المغناطيس ولا الملف — تغيّرت السرعة فقط. قانون فاراداي يفسّر بالضبط لماذا.","concepts":[],"laws":[{"name":"قانون فاراداي","formula":"ε_ind = − N × (ΔΦ_B/Δt)","variables_note":""},{"name":"حالة تغيّر B فقط (A وθ ثابتتان، θ=0)","formula":"ε_ind = N A (ΔB/Δt)","variables_note":""}],"notes":[{"heading":"💡 افهمها ولا تحفظها:","items":["القوة الدافعة المحتثة لا تهتم بـ\"كم تغيّر الفيض\" بمفرده، بل بـ\"كم كان ذلك التغيّر سريعاً\".","نفس مقدار التغيّر ΔB خلال زمن أقصر (Δt أصغر) يعطي قوة دافعة أكبر — وهذا بالضبط سرّ المصباح الذي توهّج أكثر في تجربة الحركة السريعة أعلاه."],"ministerial":false}],"tables":[],"examples":[{"problem":"ملف من 50 لفة، مساحة اللفة 20cm²، تغيّرت كثافة الفيض من صفر إلى 0.8T خلال 0.4s (متجه المساحة يوازي المجال طوال الوقت). احسب: ① القوة الدافعة المحتثة ② التيار المحتث إذا كانت مقاومة الملف R=80Ω.","givens":"المعطيات: N = 50 — A = 20cm² = 20×10⁻⁴ m² — ΔB = 0.8T − 0.0T = 0.8T — Δt = 0.4s — R = 80Ω","solution_steps":["الخطوة ١: نطبّق صيغة تغيّر B فقط (بعد تحويل المساحة لمتر مربع): ε = N A (ΔB/Δt) = 50 × 20×10⁻⁴ × (0.8/0.4) = 0.2 V","الخطوة ٢: نوجد التيار المحتث بقانون أوم: I = ε/R = 0.2/80 = 2.5×10⁻³ A ⚠️ انتبه دائماً لتحويل المساحة من cm² إلى m² قبل التعويض (20cm² = 20×10⁻⁴ m²) — من أكثر أخطاء الأسئلة الوزارية شيوعاً."],"ministerial":true}],"qa":[{"question":"يُصنع المولّد الكهربائي من ملف بعدد لفّات كبير جداً، لا من لفة واحدة.","answer":"لأن القوة الدافعة المحتثة تتناسب طردياً مع عدد اللفات N (ε=NΔΦ/Δt). فزيادة عدد اللفات تزيد القوة الدافعة الناتجة عن نفس معدّل تغيّر الفيض، دون الحاجة لتحريك المغناطيس أسرع أو استعمال مجال أقوى.","type":"علل","ministerial":true},{"question":"طبّق قانون فاراداي على الساق المنزلقة من الدرس الثاني — هل تصل لنفس القانون ε=vBℓ؟","answer":"نعم بالضبط! الفيض المحصور بين الساق والطرف المغلق هو Φ=Bℓx (حيث x بُعد الساق عن الطرف المغلق). وبما أن x يتغيّر بمعدّل v=Δx/Δt، فإن: ΔΦ/Δt = Bℓ(Δx/Δt) = Bℓv. وبتطبيق قانون فاراداي على لفة واحدة (N=1): ε=NΔΦ/Δt=Bℓv — نفس قانون القوة الدافعة الحركية تماماً! قانون فاراداي هو الصورة الشاملة التي تختصر كل حالات الحث الخاصة في قانون واحد.","type":"تحقّق!","ministerial":false}],"has_simulation":true,"simulation_title":"⏱️ مختبر السرعة والقوة الدافعة"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":5,"lesson_title":"قانون لنز","order_index":5,"hook":"لماذا لا يسقط مغناطيس قوي بحرّية داخل أنبوب نحاسي رأسي — رغم أن النحاس ليس مغناطيسياً ولا يجذب المغناطيس أصلاً؟ بل يهبط ببطء شديد، كأنّ يداً خفية تُمسك به! هذه اليد الخفية هي قانون لنز: حركة المغناطيس تُحدث تيارات دوّامية في جدار الأنبوب، وهذه التيارات تُنشئ مجالها المغناطيسي الخاص الذي يُعارض سقوط المغناطيس.","concepts":[],"laws":[],"notes":[{"heading":"💡 افهمها ولا تحفظها:","items":["لماذا \"يقاوم\" التيار المحتث دائماً؟","لأنه لو ساعد التغيير بدل معارضته، لتسارع المغناطيس من تلقاء نفسه وحصلنا على طاقة كهربائية مجانية بلا أي شغل — وهذا مستحيل فيزيائياً.","مقاومةُ لنز تعني أنك تبذل شغلاً لتحريك المغناطيس (تقريباً أو إبعاداً)، وهذا الشغل بالذات هو مصدر الطاقة الكهربائية المتولّدة.","لذا يُعدّ قانون لنز تطبيقاً مباشراً لقانون حفظ الطاقة — تماماً كما رأيتَ مع الساق المنزلقة بالدرس الثاني."],"ministerial":false}],"tables":[],"examples":[{"problem":"ملف من 50 لفة، مساحة اللفة 20cm²، تغيّرت كثافة الفيض المغناطيسي من صفر إلى 0.8T خلال 0.4s. احسب القوة الدافعة المحتثة عندما: ① يوازي متجه مساحة اللفة متجه المجال تماماً. ② يصنع متجه المجال زاوية 30° مع مستوى اللفة (لا مع متجه مساحتها).","givens":"المعطيات: N = 50 — A = 20cm² = 20×10⁻⁴ m² — ΔB = 0.8T — Δt = 0.4s","solution_steps":["الخطوة ١: في الحالة الأولى، متجه المساحة يوازي المجال (θ=0°)، فنطبّق القانون مباشرة: ε₁ = N A (ΔB/Δt) = 50 × 20×10⁻⁴ × (0.8/0.4) = 0.2 V","الخطوة ٢: ⚠️ انتبه: الزاوية 30° معطاة مع مستوى اللفة، لا مع متجه مساحتها! وبما أن متجه المساحة عمودي دائماً على المستوى: الزاوية مع متجه المساحة = 90° − 30° = 60°","الخطوة ٣: نضرب في جيب تمام هذه الزاوية الصحيحة: ε₂ = ε₁ × cos60° = 0.2 × 0.5 = 0.1 V 💡 هذا الفخّ (زاوية مع المستوى بدل متجه المساحة) من أكثر أخطاء الأسئلة الوزارية شيوعاً — راجع الدرس الثالث إذا التبس عليك الفرق."],"ministerial":true}],"qa":[{"question":"يُعدّ قانون لنز تطبيقاً لقانون حفظ الطاقة.","answer":"لأن التيار المحتث يعارض دائماً التغيّر الذي ولّده (تقريب المغناطيس أو إبعاده)، فيتطلّب ذلك إنجاز شغل ميكانيكي لتحريك المغناطيس نسبةً للملف. يتحوّل هذا الشغل إلى طاقة كهربائية (ثم حرارية في الحمل) — فلا طاقة تُخلق من العدم، وهذا نصّ مبدأ حفظ الطاقة.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🔄 مختبر تحديد القطب المحتث"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":6,"lesson_title":"الحث الذاتي","order_index":6,"hook":"لماذا تنطلق أحياناً شرارة صغيرة عند فصل قابس جهاز فيه محرك كهربائي (كمروحة) من الكهرباء، رغم أنك فصلته بهدوء تام؟ الملف الكهربائي بداخل المحرك \"يقاوم\" أي توقف مفاجئ لتياره، فيحاول الحفاظ عليه بقوة دافعة ذاتية قد تصل لمئات الفولتات لحظياً — كافية لتوليد شرارة تقفز عبر الهواء، رغم أن الجهاز يعمل بفولتية منزلية عادية لا تتجاوز 220V!","concepts":[],"laws":[{"name":"تعريف المحاثة (معامل الحث الذاتي)","formula":"N Φ_B = L I","variables_note":""},{"name":"القوة الدافعة الذاتية","formula":"ε_ind = − L (ΔI/Δt)","variables_note":""},{"name":"الطاقة المختزنة في المحث","formula":"PE = ½ L I²","variables_note":""}],"notes":[{"heading":"افهمها ولا تحفظها — وحدة المحاثة:","items":["تُقاس L بوحدة الهنري (H).","فالملف محاثته 1H إذا ولّد قوة دافعة ذاتية مقدارها 1V عند تغيّر تياره بمعدّل 1A/s.","وغالباً تُقاس بالميلي هنري (mH) أو المايكرو هنري (µH) لصغر قيمتها العملية."],"ministerial":false},{"heading":"⚠️ انتبه — المحث لا يستهلك طاقة:","items":["المحث ملف مهمَل المقاومة، وهذا يعني أنه لا يتسبّب في ضياع طاقة (لا يحوّلها حرارة كالمقاومة)، بل يختزنها في مجاله المغناطيسي ثم يعيدها إلى الدائرة عند تلاشي التيار."],"ministerial":false}],"tables":[],"examples":[{"problem":"اشتقاق: كيف نصل من تعريف المحاثة إلى قانون القوة الدافعة الذاتية؟","givens":"الفكرة: نطبّق قانون فاراداي مباشرة على تعريف NΦ_B=LI.","solution_steps":["الخطوة ١: من التعريف، نأخذ معدّل التغيّر الزمني للطرفين: N Φ_B = L I  ⟹  N (ΔΦ_B/Δt) = L (ΔI/Δt)","الخطوة ٢: نتذكّر قانون فاراداي: ε_ind = −N (ΔΦ_B/Δt)","الخطوة ٣: نعوّض الطرف الأيمن من الخطوة الأولى: ε_ind = −L (ΔI/Δt) 💡 الإشارة السالبة هي لنز: القوة الدافعة تعاكس تغيّر التيار — تكبح نموّه عند الغلق، وتكبح تلاشيه عند الفتح (وهذا مصدر الشرارة في الهوك أعلاه)."],"ministerial":false},{"problem":"ملف معامل حثه الذاتي 2.5mH وعدد لفّاته 500، ينساب فيه تيار مستمر 4A. احسب: ① الفيض المخترق للفة الواحدة ② الطاقة المختزنة في مجاله ③ معدّل القوة الدافعة المحتثة إذا انعكس اتجاه التيار خلال 0.25s.","givens":"المعطيات: L = 2.5mH = 2.5×10⁻³H — N = 500 — I = 4A","solution_steps":["الخطوة ١: من تعريف المحاثة: N Φ_B = L I  ⟹  500 × Φ_B = 2.5×10⁻³ × 4  ⟹  Φ_B = 2×10⁻⁵ Wb","الخطوة ٢: الطاقة المختزنة: PE = ½ L I² = ½ × 2.5×10⁻³ × (4)² = 0.02 J","الخطوة ٣: عند انعكاس التيار، يقفز من 4+A إلى 4−A، فمقدار التغيّر 8A وليس 4A: ΔI = −4 − (+4) = −8A  ⟹  ε_ind = −L(ΔI/Δt) = −2.5×10⁻³×(−8/0.25) = 0.08 V"],"ministerial":false}],"qa":[{"question":"لا يمكن أن يتغيّر التيار في ملف تغيّراً فجائياً (قفزة لحظية من الصفر لقيمته الكاملة).","answer":"لأن أي تغيّر في التيار يولّد قوة دافعة ذاتية محتثة تعارض ذلك التغيّر بالذات (قانون لنز). فلحظة غلق المفتاح تنمو هذه القوة المعارضة لتكبح نموّ التيار، فينمو تدريجياً بدل أن يقفز فجأة — ولحظة فتح المفتاح تعارض تلاشيه، فيتلاشى تدريجياً أيضاً (وقد تسبّب شرارة إن كان التلاشي سريعاً جداً).","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"⚡ مختبر قطع التيار والقوة الدافعة الذاتية"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":7,"lesson_title":"الحث المتبادل","order_index":7,"hook":"هل تصدّق أن طبيباً يستطيع \"الوصول\" لخلايا دماغك العصبية كهربائياً، دون أي جراحة ولا حتى إبرة واحدة؟ جهاز التحفيز المغناطيسي عبر الجمجمة (TMS) يفعل ذلك بالضبط: ملف يُمسك فوق رأس المريض، فيه تيار متغيّر بسرعة كبيرة، يولّد مجالاً مغناطيسياً متغيّراً يخترق الدماغ ويحتثّ فيه تياراً كهربائياً ينظّم نشاط الخلايا العصبية — يُستعمل فعلياً لعلاج بعض أعراض الاكتئاب دون أي جراحة.","concepts":[],"laws":[{"name":"الحث المتبادل بين ملفين","formula":"N₂ Φ_B(2) = M I₁","variables_note":""},{"name":"القوة الدافعة المحتثة في الثانوي","formula":"ε_ind(2) = − M (ΔI₁/Δt)","variables_note":""},{"name":"معامل الحث المتبادل عند الاقتران التام","formula":"M = √(L₁ × L₂)","variables_note":""}],"notes":[{"heading":"💡 افهمها ولا تحفظها:","items":["الحث المتبادل هو مبدأ عمل المحوّلة الكهربائية (Transformer) التي تُغيّر فولتية التيار المتناوب في شبكات الكهرباء، وهو أيضاً أساس الشحن اللاسلكي للهواتف: ملف في قاعدة الشحن وملف آخر داخل الهاتف، يتبادلان الطاقة بلا أي سلك بينهما."],"ministerial":false}],"tables":[],"examples":[{"problem":"ملفان متجاوران حول حلقة مقفلة من الحديد المطاوع. رُبط الابتدائي ببطارية 100V ومفتاح على التوالي، فكان معامل حثه الذاتي 0.5H ومقاومته 20Ω. احسب: ① معدّل تغيّر تيار الابتدائي لحظة الغلق ② معامل الحث المتبادل إذا تولّدت في الثانوي 40V لحظة الغلق ③ التيار الثابت في الابتدائي ④ معامل الحث الذاتي للثانوي.","givens":"المعطيات: V=100V — L₁=0.5H — R=20Ω — ε₂ لحظة الغلق = 40V","solution_steps":["الخطوة ١: العلاقة العامة V=L(ΔI₁/Δt)+IR، ولحظة الغلق I=0: 100 = 0.5(ΔI₁/Δt)  ⟹  ΔI₁/Δt = 200 A/s","الخطوة ٢: نطبّق قانون الحث المتبادل: ε_ind(2) = M(ΔI₁/Δt)  ⟹  40 = M × 200  ⟹  M = 0.2 H","الخطوة ٣: بعد استقرار التيار (ΔI/Δt=0)، لا قوة دافعة ذاتية، فقانون أوم وحده يحكم: I_ثابت = V/R = 100/20 = 5 A","الخطوة ٤: من علاقة الاقتران التام: M = √(L₁L₂)  ⟹  0.2 = √(0.5×L₂)  ⟹  0.04 = 0.5L₂  ⟹  L₂ = 0.08 H"],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🔗 مختبر الحث المتبادل"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":8,"lesson_title":"المجالات الكهربائية المحتثة","order_index":8,"hook":"تخيّل حلقة نحاسية ساكنة تماماً — لا تتحرك قيد أنملة — موضوعة داخل مجال مغناطيسي يتغيّر بمرور الزمن. ستُفاجأ: ينساب فيها تيار محتث فعلاً! لكن قانون قوة لورنتز الذي درسته بالدرس الأول ينصّ صراحة أن القوة المغناطيسية F=qvB تحتاج شحنة متحركة. والحلقة هنا ساكنة كلياً، وسرعة شحناتها (النسبية للحلقة) صفر. فما القوة التي حرّكت الشحنات إذن؟","concepts":[],"laws":[],"notes":[{"heading":"🔒 مجالات كهربائية مستقرة (Electrostatic):","items":["تنشأ بوساطة شحنات ساكنة — وهي كل المجالات الكهربائية التي درستها في فصل المتسعات.","خطوطها تبدأ من شحنة موجبة وتنتهي بشحنة سالبة — لها نقطة بداية ونهاية محددتان دائماً."],"ministerial":false},{"heading":"🔄 مجالات كهربائية غير مستقرة (محتثة):","items":["تنشأ بوساطة التغيّر في الفيض المغناطيسي — لا بوساطة أي شحنة.","لذا خطوطها مغلقة على نفسها (كحلقات مقفلة) — لا تبدأ من شحنة ولا تنتهي عندها إطلاقاً."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"خطوط المجال الكهربائي المحتث مغلقة دائماً، بعكس خطوط المجال الكهربائي المستقر.","answer":"لأن المجال الكهربائي المستقر ينشأ من شحنات كهربائية، فتبدأ خطوطه من الشحنة الموجبة وتنتهي بالسالبة حتماً. أما المجال المحتث فلا ينشأ من أي شحنة إطلاقاً، بل من التغيّر المستمر في الفيض المغناطيسي — فلا توجد نقطة بداية أو نهاية \"تُلزم\" الخطوط بالتوقف عندها، فتنغلق على نفسها بدلاً من ذلك.","type":"علل","ministerial":true},{"question":"هل يحتاج المجال الكهربائي المحتث إلى موصل ليتواجد؟","answer":"لا. المجال الكهربائي المحتث ينشأ من تغيّر المجال المغناطيسي بحد ذاته، ويملأ تلك المنطقة من الفضاء بغضّ النظر عن وجود موصل من عدمه. الموصل (كحلقة نحاسية) لا يخلق هذا المجال، بل يسمح فقط برؤية أثره: مرور تيار محتث فيه. لو أزلت الحلقة، يبقى المجال الكهربائي المحتث موجوداً في الفضاء نفسه — لكن بلا شحنات حرّة تتحرك به لنرصد أثره مباشرة.","type":"انتبه!","ministerial":false}],"has_simulation":true,"simulation_title":"⚖️ مختبر مقارنة المجالين"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":9,"lesson_title":"المولّدات والمحرّكات الكهربائية","order_index":9,"hook":"كل كيلوواط كهرباء يصل بيتك وُلد في مولّد: توربين يدور (بالماء أو البخار أو الرياح) فيُدير ملفاً داخل مجال مغناطيسي. وكل مروحة وغسّالة وسيارة كهربائية تعمل بمحرّك: يأخذ الكهرباء فيصنع منها حركة. المدهش أن الآلتين متطابقتان بالتركيب — الفرق فقط باتجاه تحويل الطاقة. وكلتاهما تقومان على ما تعرفه تماماً: ملفٌ يدور فيتغيّر الفيض المخترق له، فتتولّد قوة دافعة.","concepts":[{"term":"تذكّر:","text":"A=πr² — فتغيير قطر الملف يغيّر ε_max بمربّع النسبة (تناسب مربّعي)، بينما N وω تناسب طردي بسيط.","ministerial":false}],"laws":[{"name":"القوة الدافعة اللحظية للمولّد (ω=2πf)","formula":"ε = ε_max sin(ωt)  ،  ε_max = N B A ω","variables_note":""},{"name":"أعظم قوة دافعة","formula":"ε_max = N B A ω","variables_note":""},{"name":"أعظم تيار محتث","formula":"I_max = N B A ω / R","variables_note":""},{"name":"متوسط تيار المولّد المستمر","formula":"I_average = 0.636 × I_max","variables_note":""},{"name":"القوة الدافعة المضادّة والتيار بالمحرّك","formula":"I = (V_applied − ε_back) / R","variables_note":""}],"notes":[{"heading":"💡 افهمها ولا تحفظها","items":["الفرق بين الفولطية المسلّطة والقوة الدافعة المضادّة هو ما يحدّد التيار.","لذا حين تُشغّل محرّكاً (مروحة أو غسّالة) يسحب تياراً عالياً لحظة البدء (لأن ε_back=0 والملف ساكن)، ثم يقلّ التيار كلما تسارع الملف وكبرت ε_back.","لهذا تخفت الأضواء لحظة تشغيل المكيّف!"],"ministerial":false}],"tables":[],"examples":[{"problem":"كيف نصل من الفيض الجيبي إلى قانون قوة المولّد الدافعة؟","givens":"","solution_steps":["الخطوة ١: الفيض جيبي: Φ = BA cos(ωt)","الخطوة ٢: معدّل تغيّره (لأن مشتقة cos(ωt) هي −ω sin(ωt)): ΔΦ/Δt = −BAω sin(ωt)","الخطوة ٣: بقانون فاراداي: ε = −N·ΔΦ/Δt = N B A ω sin(ωt) 💡 القوة الدافعة جيبية: تبدأ صفراً، تبلغ ذروتها بعد ربع دورة، ثم تنعكس — تماماً كتيار الكهرباء بالبيت."],"ministerial":false},{"problem":"مولّد ملفه 200 لفة، مساحة اللفة 0.01 m²، كثافة الفيض 0.5T، يدور بسرعة زاوية 100 rad/s. جد ذروة القوة الدافعة ε_max.","givens":"المعطيات: N=200 — A=0.01 m² — B=0.5T — ω=100 rad/s","solution_steps":["الخطوة الوحيدة: نعوّض مباشرة بقانون الذروة: ε_max = N B A ω = 200 × 0.5 × 0.01 × 100 = 100 V 💡 جرّب هذي القيم بالضبط بالمحاكاة فوق (N=200 خارج مدى السلايدر الأعلى إلى 500 فهو متاح، B=0.5، والمساحة 100 سم²... لاحظ فقط أن وحدة المساحة بالمحاكاة سم² لا م²، فحوّل 0.01m²=100cm² لمقارنة صحيحة) وتحقّق أن القراءة تقارب 100V عند f المكافئ لـω=100rad/s (أي f=ω/2π≈15.9Hz، خارج مدى السلايدر — النتيجة هنا حسابية بحتة)."],"ministerial":false}],"qa":[{"question":"أثبت أن القوة الدافعة المحتثة على طرفي ملف مساحة لفته A وعدد لفّاته N، يدور بسرعة زاوية ω داخل مجال منتظم B، تُعطى بالعلاقة ε=NBAω sin(ωt).","answer":"الفيض المخترق للملف عند الزاوية θ=ωt: Φ=BAcos(ωt). معدّل التغيّر الزمني للفيض: ΔΦ/Δt=BA×[−ωsin(ωt)]=−BAωsin(ωt). وبقانون فاراداي لملف عدد لفّاته N: ε=−N·ΔΦ/Δt=−N[−BAωsin(ωt)]=NBAω sin(ωt) — وهي دالة جيبية، وهو المطلوب إثباته. ∎","type":"برهان وزاري","ministerial":true},{"question":"ترتفع درجة حرارة محرّك كهربائي بشدة ويحترق ملفه إذا مُنع من الدوران (انحشر) وبقيت الفولطية مسلَّطة عليه.","answer":"لأن القوة الدافعة المضادّة ε_back تتولّد فقط بدوران الملف، فإن مُنع من الدوران تصبح ε_back=0، فيصبح التيار I=(V_applied−0)/R=V_applied/R في أعظم مقدار له بلا أي كابح — تيار كبير جداً يُسخّن الملف بشدة عبر مقاومته حتى يحترق.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🔄 مختبر المولّد الكهربائي المتناوب"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":10,"lesson_title":"التطبيقات العملية","order_index":10,"hook":"بطاقة بنكية، قيثار كهربائي، وموقد مطبخ — ثلاثة أشياء لا يبدو أن بينها أي صلة. لكن الثلاثة تعمل بالضبط بنفس المبدأ الذي درسته طوال هذا الفصل: تغيّر الفيض المغناطيسي يولّد تياراً محتثاً. فيزياء واحدة، ثلاثة تطبيقات مختلفة كلياً.","concepts":[],"laws":[],"notes":[{"heading":"💡 افهمها ولا تحفظها:","items":["🔗 المبدأ المستعمل: التيارات الدوّامة (الدرس 5) + قانون لنز (المقاومة الحرارية الناتجة عن معارضة التيار المحتث).","ولهذا بالضبط لا يعمل الطباخ الحثّي مع أواني الألمنيوم أو الزجاج العادية — فهي غير مغناطيسية، فلا تتولّد فيها تيارات دوّامة قوية بما يكفي للتسخين."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"يعمل الطباخ الحثّي بكفاءة مع إناء الحديد الزهر، لكنه لا يسخّن إناء الألمنيوم بنفس الكفاءة.","answer":"لأن التيارات الدوّامة المسؤولة عن التسخين تعتمد على مدى تفاعل المعدن مغناطيسياً مع المجال المتغيّر. الحديد الزهر مادة فيرومغناطيسية قوية التفاعل، فتتولّد فيه تيارات دوّامة كبيرة تُسخّنه بكفاءة. أما الألمنيوم فموصل جيد لكنه غير مغناطيسي (نفوذيته المغناطيسية منخفضة)، فتضعف التيارات الدوّامة المتولّدة فيه ويقلّ التسخين كثيراً.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🔧 استكشف التطبيقات الثلاثة"},{"chapter_number":"g6c2","chapter_title":"الحث الكهرومغناطيسي","lesson_number":11,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":11,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"أي من الأشكال الآتية (لاحظ الشكل 57) يبيّن الاتجاه الصحيح للتيار الكهربائي المحتث في الحلقة الموصلة (الملف) بسبب حركة المغناطيس؟","answer":"a — القطب المواجه للملف هو القطب السفلي من المغناطيس (الأقرب للملف). في (a): القطب المواجه N يقترب (v↓) فيزداد الفيض النازل داخل الملف، فيعاكسه تيار محتث يصنع فيضاً صاعداً؛ بقاعدة اليد اليمنى هذا يعني تياراً عكس عقارب الساعة كما يُرى من فوق (من جهة المغناطيس) — يطابق الرسم ✓. في (b): السرعة صفر فلا قوة دافعة كهربائية محتثة إطلاقاً بصرف النظر عمّا هو مرسوم، فهو خطأ حتماً. في (c): نفس القطب المواجه N يبتعد الآن (v↑) فيتناقص الفيض النازل، فيحاول التيار المحتث الحفاظ عليه بصنع فيض نازل أيضاً = تيار مع عقارب الساعة من فوق؛ لكن الرسم في (c) مطابق لـ(a) (عكس عقارب الساعة) وهو خطأ لهذه الحالة. في (d): القطب المواجه S يبتعد (v↑) فيتناقص الفيض الصاعد، فيحاول التيار الحفاظ عليه = عكس عقارب الساعة من فوق؛ لكن الرسم يُظهره مع عقارب الساعة، فهو خطأ أيضاً. النتيجة: (a) فقط هو الصحيح فيزيائياً.","type":"سؤال","ministerial":false},{"question":"في الشكل (58) حلقة مصنوعة من النحاس، وضعت في مستوي الورقة وموصولة مع المقاومة R، سُلط عليها مجال مغناطيسي باتجاه عمودي على مستوي الورقة خارجاً منه نحو الناظر. في أي حالة من الحالات التالية ينساب تيار محتث في المقاومة R اتجاهه من اليسار نحو اليمين؟","answer":"عند تناقص الفيض المغناطيسي الذي يخترق الحلقة — المجال خارج من مستوي الورقة نحو الناظر. لكي ينساب التيار في R من اليسار إلى اليمين، يجب أن يهبط عبر الساق اليسرى للحلقة ثم يمر بـR يساراً-يميناً ثم يصعد عبر الساق اليمنى، أي أن التيار في الحلقة نفسها يدور عكس عقارب الساعة كما يراه الناظر (من الأعلى للأسفل ثم يمين للأعلى). بقاعدة اليد اليمنى، تيار عكس عقارب الساعة (والمجال قادم نحو الناظر) ينتج مجالاً محتثاً خارجاً من الصفحة أيضاً — أي بنفس اتجاه المجال الأصلي. وبقانون لنز، التيار المحتث يحاول تعويض/الحفاظ على الفيض حين يكون في طريقه للتناقص (لا التزايد)، لذا يجب أن يكون الفيض الأصلي في حالة تناقص. إذن الإجابة: عند تناقص الفيض المغناطيسي.","type":"سؤال","ministerial":false},{"question":"عند سقوط الساق المغناطيسية خلال حلقة واسعة من الألمنيوم موضوعة أفقياً بوساطة حامل تحت الساق (لاحظ الشكل 59)، إذا نظرت إلى الحلقة من موقع فوقها وباتجاه السهم لتحديد اتجاه التيار المحتث فيها، فإن اتجاه التيار المحتث في الحلقة يكون:","answer":"باتجاه معاكس لدوران عقارب الساعة، ثم يكون صفراً للحظة، ثم يكون باتجاه دوران عقارب الساعة — انتبه أولاً: الفيض المخترق للحلقة يبقى نازلاً في الحالتين — فخطوط المجال تخرج من القطب N (السفلي) نازلةً قبل الوصول، وتعود لتدخل القطب S (العلوي) نازلةً أيضاً بعد الاجتياز. الذي يتغيّر هو مقداره لا اتجاهه. ① الاقتراب: القطب N يقترب فيتزايد الفيض النازل، فيعاكس التيار المحتث هذا التزايد بصنع فيض صاعد داخل الحلقة = تيار عكس عقارب الساعة (من فوق). ② لحظة مرور مركز المغناطيس بمستوي الحلقة: الفيض أعظمي لكن معدل تغيّره لحظياً صفر، فالتيار صفر للحظة. ③ الابتعاد: المغناطيس صار تحت الحلقة وقطبه S هو الأقرب لها، فيتناقص الفيض النازل، فيحاول التيار المحتث الحفاظ عليه بصنع فيض نازل أيضاً = تيار مع عقارب الساعة (من فوق). النمط الكامل إذن: عكس عقارب الساعة ← صفر ← مع عقارب الساعة.","type":"سؤال","ministerial":false},{"question":"عند سقوط الساق المغناطيسية خلال حلقة من الألمنيوم غير مقفلة (بها فتحة/قطع) موضوعة أفقياً تحت الساق، لاحظ الشكل (60):","answer":"لا تتأثر الساق بأية قوة في أثناء اقترابها من الحلقة، أو في أثناء ابتعادها عن الحلقة — الحلقة هنا غير مقفلة (بها فتحة/قطع)، أي أن الدائرة الكهربائية مفتوحة، فلا يمكن أن ينساب فيها أي تيار محتث مهما تغيّر الفيض خلالها (لا يوجد مسار مغلق للشحنات). وبما أن قوى التنافر/التجاذب المغناطيسية بين الساق والحلقة في مثل هذه التجارب ناتجة أصلاً عن تفاعل المجال مع التيار المحتث (F=BIℓ)، فبانعدام التيار تنعدم القوة، فلا تتأثر الساق بأي قوة إطلاقاً في أي من الحالتين (الاقتراب أو الابتعاد).","type":"سؤال","ministerial":false},{"question":"في الشكل (61) ملف محزون مجوف مربوط على التوالي مع مصباح كهربائي ومقاومة وبطارية ومفتاح. عندما كان المفتاح مغلقاً في الدائرة كانت شدة توهج المصباح ثابتة. إذا أُدخلت ساق من الحديد المطاوع في جوف الملف، فإن توهج المصباح في أثناء دخول الساق (اللحظة الانتقالية فقط):","answer":"يقل — إدخال الساق الحديدية (المطاوعة) في جوف الملف يزيد معامل حثه الذاتي L تدريجياً أثناء الإدخال. وبما أن الملف يحمل تياراً بالفعل، فإن ازدياد L أثناء استمرار سريان التيار يولّد قوة دافعة كهربائية محتثة ذاتياً معاكسة (تعاكس الزيادة في الفيض)، فتقاوم هذه القوة المضادة ازدياد/استمرار التيار مؤقتاً فيقل التيار قليلاً أثناء لحظة الإدخال نفسها، فيخفت توهج المصباح خلال تلك الفترة الانتقالية فقط. (بعد استقرار الساق داخل الملف يعود التيار المستمر إلى قيمته الأصلية V/R لأن الملف في الحالة المستقرة لا يُسقط جهداً، فيعود توهج المصباح لحالته الأصلية).","type":"سؤال","ministerial":false},{"question":"عندما يدور ملف دائري حول محور شاقولي موازٍ لوجهه ويمر من مركزه والمحور عمودي على فيض مغناطيسي كثافته B أفقية ومنتظمة (لاحظ الشكل 62)، تولد أعظم مقدار للقوة الدافعة الكهربائية المحتثة εmax. وعند زيادة عدد لفات الملف إلى ثلاثة أمثال ما كانت عليه، وتقليل قطر الملف إلى نصف ما كان عليه، ومضاعفة التردد الدوراني للملف، فإن المقدار الأعظم الجديد للقوة الدافعة الكهربائية المحتثة يكون:","answer":"(3/2) εmax — εmax = NBAω، والمساحة A تتناسب مع مربع القطر فتصبح A/4 عند تنصيف القطر. εmax الجديدة = (3N)×B×(A/4)×(2ω) = (3×1×2/4)×NBAω = (6/4)NBAω = (3/2)εmax.","type":"سؤال","ministerial":false},{"question":"تتحقق ظاهرة الحث الذاتي في ملف معين عندما:","answer":"ينساب في هذا الملف تيار كهربائي متغير المقدار لوحدة الزمن — الحث الذاتي (Self-Induction) يعني أن يُحدث الملف قوة دافعة كهربائية محتثة في نفسه بسبب تغيّر تياره الخاص هو (لا تياراً في ملف مجاور، ولا حركة مغناطيس خارجي، ولا دوران في مجال). الخيار (b) يصف الحث المتبادل بين ملفين، و(a) و(d) يصفان حثاً ناتجاً عن حركة نسبية/مصدر خارجي. الوصف الدقيق للحث الذاتي هو الخيار (c): تغيّر التيار المنساب في الملف نفسه.","type":"سؤال","ministerial":false},{"question":"مقدار القوة الدافعة الكهربائية المحتثة على طرفي ساق موصلة تتحرك نسبة إلى مجال مغناطيسي (في حالة لا سكون) لا يعتمد على:","answer":"قطر الساق — صيغة القوة الدافعة الكهربائية الحركية: ε = Bℓv sinθ، وهي تعتمد على كثافة الفيض B، وطول الساق ℓ، وسرعتها v، وزاوية وضعيتها θ نسبة إلى المجال؛ لكنها لا تعتمد إطلاقاً على قُطر (سُمك) الساق.","type":"سؤال","ministerial":false},{"question":"عندما تقل السرعة الزاوية لدوران ملف نواة المحرك الكهربائي نتيجة لازدياد الحمل الموصول مع ملفه، فإن ذلك يتسبب في هبوط مقدار:","answer":"القوة الدافعة الكهربائية المحتثة المضادة — القوة الدافعة الكهربائية المحتثة المضادة (Back-EMF) في المحرك تتناسب طردياً مع سرعته الزاوية (ε_back = k·ω تقريباً). فعند زيادة الحمل تقل السرعة الزاوية فتقل هذه القوة المضادة مباشرة. أما الفولطية المطبقة من المصدر فتبقى ثابتة، والتيار في الواقع يزداد (لا يقل) لأن I=(V-ε_back)/R وقد قلّت ε_back.","type":"سؤال","ministerial":false},{"question":"يمكن أن يُستحث تيار كهربائي في حلقة موصلة ومقفلة في العمليات التالية جميعها ما عدا واحدة منها. فالعملية التي لا يُستحث فيها التيار هي:","answer":"وضع حلقة موصلة ومقفلة ومتجه مساحتها عمودياً على فيض مغناطيسي متغير لوحدة الزمن — الفيض المخترق للحلقة Φ=B·A·cosθ حيث θ الزاوية بين متجه المساحة (العمودي على مستوي الحلقة) والمجال B. إذا كان متجه المساحة عمودياً على B (θ=90°) فإن Φ=BAcos90°=0 دائماً وباستمرار، بصرف النظر عن كيفية تغيّر B مع الزمن (لأن B يبقى واقعاً في مستوي الحلقة نفسه ولا يخترقها إطلاقاً)، فمشتقته الزمنية أيضاً صفر دائماً، ولا تُستحث أي قوة دافعة كهربائية. أما بقية الحالات (أ: تدوير يغيّر الزاوية، b: متجه موازٍ فالفيض أعظمي ويتغير مع B، d: كبس الحلقة يغيّر المساحة) فكلها تؤدي إلى تغيّر الفيض وتُحدث تياراً محتثاً.","type":"سؤال","ministerial":false},{"question":"وحدة قياس كثافة الفيض المغناطيسي هي:","answer":"weber/m² — كثافة الفيض المغناطيسي B (التسلا) = ويبر/م² (Wb/m²)، لأن الفيض Φ=B×A ⇒ B=Φ/A، ووحدة Φ هي الويبر ووحدة A هي م².","type":"سؤال","ministerial":false},{"question":"في الشكل (63)، عندما تدور حلقة موصلة حول محور شاقولي موازٍ لوجهها ومار من مركزها، والمحور عمودي على فيض مغناطيسي أفقي ومنتظم، فإن قطبية القوة الدافعة الكهربائية المحتثة تكون دالة جيبية تتغير مع الزمن وتنعكس خلال كل:","answer":"نصف دورة — القوة الدافعة الكهربائية المحتثة تُعطى بدالة جيبية ε=εmax sin(ωt)، وهذه الدالة تقطع الصفر وتنعكس إشارتها (قطبيتها) عند ωt=0,π,2π,... أي كل نصف دورة (π radian)، وليس كل دورة كاملة (التي يكتمل بعدها دورة جيبية كاملة لكن القطبية تكون قد انعكست مرتين خلالها).","type":"سؤال","ministerial":false},{"question":"معامل الحث الذاتي لملف لا يعتمد على:","answer":"المعدل الزمني للتغير في التيار المنساب في الملف — معامل الحث الذاتي L خاصية هندسية-مادية بحتة للملف (تعتمد على N² وأبعاده وشكله الهندسي ونفوذية قلبه μ)، ولا يعتمد إطلاقاً على مقدار التيار أو معدل تغيره الزمني (رغم أن القوة الدافعة الكهربائية المحتثة ε=-L(dI/dt) نفسها تعتمد على dI/dt، فإن L ذاته ثابت لا يتغير بتغير التيار).","type":"سؤال","ministerial":false},{"question":"علّل: يتوهج مصباح النيون المربوط بالتوازي مع ملف بضوء ساطع لبرهة قصيرة من الزمن لحظة فتح المفتاح، على الرغم من فصل البطارية عن الدائرة عندئذٍ، ولا يتوهج عند إغلاق المفتاح.","answer":"لأن الملف يعارض هبوط تياره المفاجئ عند الفتح بقوة دافعة ذاتية عالية جداً — الملف يقاوم أي تغيّر مفاجئ في تياره (قصور ذاتي كهرومغناطيسي). عند فتح المفتاح يهبط التيار من قيمته المستقرة إلى الصفر خلال زمن قصير جداً، فيكون |dI/dt| ضخماً، ومنه تنتج قوة دافعة كهربائية ذاتية عالية جداً (ε=-L dI/dt) كافية لتأيين غاز النيون وإصدار ومضة ضوئية قصيرة، رغم فصل البطارية. أما عند الإغلاق فالتيار يتصاعد بمعدل محدود بثابت الزمن (L/R) فتبقى ε صغيرة نسبياً ولا تصل لجهد التأيين. الصياغة الكاملة للجواب: لأن الملف يعاكس الانخفاض المفاجئ للتيار عند الفتح بقوة دافعة كهربائية ذاتية كبيرة جداً (ε=-L·dI/dt، وdI/dt كبير جداً لأن التيار يهبط لشبه الصفر خلال زمن قصير جداً)، فينتج فرق جهد عالٍ يكفي لتأيين غاز النيون؛ أما عند الإغلاق فالتيار يتصاعد تدريجياً (يحدّه ثابت الزمن L/R) فتبقى القوة الدافعة الذاتية صغيرة ولا تكفي لإضاءة المصباح","type":"سؤال","ministerial":false},{"question":"علّل: يغلي الماء داخل الإناء المعدني الموضوع على السطح العلوي لطباخ حثّي فيغلي بسرعة، ولا يغلي الماء الذي يوضع إناؤه الزجاجي على السطح العلوي لنفس الطباخ.","answer":"لأن تيارات دوامة تُستحث في المعدن فتسخّنه، ولا تُستحث في الزجاج العازل — الطباخ الحثّي يولّد مجالاً مغناطيسياً متردداً أسفل سطحه. إذا كانت قاعدة الإناء من مادة موصلة (معدن)، تُستحث فيها تيارات دوامة كبيرة تبدد طاقة حرارية مباشرة داخل المعدن نفسه (I²R) فيسخن ويُغلي الماء فوقه. أما الزجاج فعازل كهربائياً، فلا تُستحث فيه أي تيارات دوامة مهما تردد المجال، فلا يتولد فيه تسخين حثّي إطلاقاً. الصياغة الكاملة للجواب: لأن المجال المغناطيسي المتردد أسفل السطح يستحث تيارات دوامة (Eddy Currents) في قاع الإناء المعدني الموصل فتولّد حرارة مباشرة فيه (فقد I²R) تنتقل للماء؛ أما الزجاج فمادة عازلة غير موصلة كهربائياً فلا تُستحث فيه تيارات دوامة، فلا يتولد فيه فقد حراري مباشر ولا يسخن الماء","type":"سؤال","ministerial":false},{"question":"علّل: إذا تغيّر تيار كهربائي منساب في أحد ملفين متجاورين، يتولد تيار محتث في الملف الآخر.","answer":"لأن فيض الملف الأول المتغيّر يخترق الثاني فتُحتثّ فيه قوة دافعة — هذا وصف مباشر لظاهرة الحث المتبادل (Mutual Induction): تغيّر تيار الملف الابتدائي I₁ يُغيّر فيضه المغناطيسي المحيط، وجزء من هذا الفيض المتغير يخترق لفات الملف الثانوي المجاور، فيُستحث فيه بقانون فاراداي قوة دافعة كهربائية ε₂=-M(dI₁/dt) حيث M معامل الحث المتبادل بين الملفين، دون أي اتصال سلكي مباشر بينهما. الصياغة الكاملة للجواب: لأن تغيّر تيار الملف الأول يُغيّر فيضه المغناطيسي الخاص، وجزء من هذا الفيض يرتبط (يخترق) الملف الثاني المجاور؛ وبما أن هذا الفيض المرتبط بالملف الثاني يتغير مع الزمن، فبقانون فاراداي تُستحث فيه قوة دافعة كهربائية (ε₂=-M·dI₁/dt)، وينساب تيار محتث إن كانت دائرته مقفلة — وهذا جوهر الحث المتبادل","type":"سؤال","ministerial":false},{"question":"وضّح كيف يمكنك عملياً معرفة فيما إذا كان مجالاً مغناطيسياً أم مجالاً كهربائياً موجوداً في حيّز معين؟","answer":"بشحنة اختبار: إن تأثرت وهي ساكنة فالمجال كهربائي، وإن لم تتأثر إلا متحركةً فهو مغناطيسي — الفارق الجوهري: القوة الكهربائية F=qE تؤثر في الشحنة سواء كانت ساكنة أم متحركة، بينما القوة المغناطيسية F=qv×B لا تؤثر إطلاقاً في شحنة ساكنة (v=0 ⇒ F=0)، ولا تؤثر إلا في الشحنة المتحركة، وتكون القوة الناتجة عمودية دوماً على اتجاه حركتها. فبوضع شحنة اختبار ومراقبة تأثرها وهي ساكنة ثم وهي متحركة، يمكن التمييز عملياً بين وجود مجال كهربائي و/أو مغناطيسي. الصياغة الكاملة للجواب: ضع شحنة اختبار صغيرة موجبة: إذا أثّرت فيها قوة وهي ساكنة تماماً فهناك مجال كهربائي (لأن E يؤثر في الشحنات الساكنة والمتحركة معاً)؛ أما إذا لم تتأثر الشحنة إلا عند تحريكها (وكانت القوة الناتجة عمودية دوماً على اتجاه سرعتها، F=qv×B) فهناك مجال مغناطيسي فقط (B لا يؤثر في الشحنة الساكنة)","type":"سؤال","ministerial":false},{"question":"عند دوران ملف مساحة اللفة الواحدة فيه (A) بسرعة زاوية (ω) داخل مجال مغناطيسي كثافة فيضه (B) منتظمة، فإن الفيض المغناطيسي الذي يخترق اللفة الواحدة يُعطى بشكل دالة جيب تمام [Φ_B=BAcos(ωt)]. ما ناتج تطبيق قانون فاراداي (ε=-N·dΦ_B/dt) على هذه العلاقة؟","answer":"ε = NBAω·sin(ωt) — باشتقاق Φ_B=BAcos(ωt) بالنسبة للزمن: dΦ_B/dt = BA×d/dt[cos(ωt)] = BA×(-ω sin(ωt)) = -BAω sin(ωt). وبتطبيق قانون فاراداي: ε=-N(dΦ_B/dt) = -N×(-BAω sin ωt) = NBAω sin(ωt). أي أن القوة الدافعة الكهربائية المحتثة دالة جيبية (sin) عظماها εmax=NBAω، بينما الفيض نفسه دالة جيب تمام (cos) — أي أن ε وΦ خارج الطور بمقدار 90°. ⚠️ الأخطاء الشائعة في هذه المسألة: ε = -NBAω·cos(ωt) ← بإبقاء الدالة جيب تمام كما هي ε = NBAω²·sin(ωt) ← بإضافة ω إضافية سهواً ε = -NBA·sin(ωt) ← بإسقاط عامل ω من الناتج","type":"سؤال","ministerial":false},{"question":"ما المقصود بالمجالات الكهربائية غير المستقرة (Non-static Electric Fields)؟","answer":"مجالات محتثة من تغيّر المجال المغناطيسي، خطوطها حلقات مغلقة لا شحنات لها — المجالات الكهربائية غير المستقرة (المحتثة) هي مجالات تنشأ عن تغيّر الفيض المغناطيسي مع الزمن (تعميم فاراداي)، وتختلف جوهرياً عن المجالات الكهروستاتيكية: خطوطها تشكّل حلقات مغلقة على نفسها (لا تصدر من شحنات موجبة ولا تنتهي عند سالبة)، وهي غير محافظة (لا مصونة) — أي يمكن أن تبذل شغلاً صافياً على شحنة تتحرك في مسار مغلق كامل، بخلاف المجال الكهروستاتيكي المحافظ. الصياغة الكاملة للجواب: هي مجالات كهربائية محتثة تنشأ نتيجة تغيّر مجال مغناطيسي مع الزمن (لا من شحنات ساكنة)، وخطوط مجالها حلقات مغلقة (لا تبدأ ولا تنتهي عند شحنات)، وهي مجالات لا محافظة (غير مصونة) بخلاف المجالات الكهروستاتيكية الناتجة عن شحنات ساكنة","type":"سؤال","ministerial":false},{"question":"اذكر بعض المجالات (التطبيقات) التي تُستثمر فيها التيارات الدوامة (Eddy Currents)، ووضّح كل منها.","answer":"الكبح المغناطيسي، والتسخين الحثّي، وكاشفات المعادن، وتخميد إبر الموازين — التيارات الدوامة (التيارات المستحثة داخل جسم موصل صلب نتيجة تغيّر الفيض خلاله) تُستثمر عملياً في: الكبح الكهرومغناطيسي (قطارات، ملاهٍ) حيث تعاكس القوة الناتجة عنها حركة الجسم فتبطئه دون تلامس ميكانيكي؛ والتسخين الحثّي (مواقد الحث، أفران صهر المعادن) حيث تولّد حرارة I²R مباشرة داخل المعدن؛ وكاشفات المعادن التي تحسّ بتشوّه المجال الناتج عن التيارات الدوامة المستحثة في معدن مخفي؛ وتخميد اهتزاز إبر الموازين الحساسة وعدادات القياس القديمة لإيقافها بسرعة عند التوازن. الصياغة الكاملة للجواب: الكبح الكهرومغناطيسي (مكابح تيارات دوامة في القطارات وألعاب الملاهي)، وأفران/مواقد التسخين الحثّي لصهر أو طبخ المعادن، وكاشفات المعادن، وتخميد اهتزاز إبرة الموازين والأجهزة الحساسة","type":"سؤال","ministerial":false},{"question":"إذا تحركت الساق الموصلة (ab) في الشكل (64) في مستوى الورقة أفقياً نحو اليسار، داخل مجال مغناطيسي منتظم مسلط عمودياً على الورقة متجهاً نحو الناظر، يتولد مجال كهربائي داخل الساق يتجه نحو الطرف (b). أما إذا تحركت هذه الساق نحو اليمين (وداخل المجال المغناطيسي نفسه) فإن اتجاه المجال الكهربائي داخلها ينعكس ليتجه نحو الطرف (a). ما تفسير ذلك؟","answer":"لأن F=qv×B، وعكس اتجاه v يعكس اتجاه القوة فتنعكس جهة تجمّع الشحنات — القوة المؤثرة في شحنة موجبة داخل الساق المتحركة هي F=qv×B. عكس اتجاه v (من اليسار لليمين) يعكس تماماً اتجاه الجداء الاتجاهي v×B (لأن الجداء الاتجاهي خطي في كل من عامليه)، فتنعكس جهة اندفاع الشحنات الموجبة داخل الساق، وبالتبعية ينعكس اتجاه المجال الكهربائي الاستقطابي (الداخلي) الذي يتشكل في حالة الاتزان ليوازن هذه القوة المغناطيسية (qE=qv×B). الصياغة الكاملة للجواب: لأن القوة المغناطيسية المؤثرة في حاملات الشحنة داخل الساق تُعطى بـF=qv×B، وعكس اتجاه السرعة v يعكس اتجاه الجداء الاتجاهي v×B تماماً (بمقدار 180°)، فتنعكس تبعاً لذلك جهة تجمّع الشحنات (وبالتالي اتجاه المجال الكهربائي الداخلي الناتج عن الاستقطاب) من الاتجاه نحو b إلى الاتجاه نحو a","type":"سؤال","ministerial":false},{"question":"في الشكل (65) ملف سلكي محزون بقلب حديدي، مربوط على التوالي مع بطارية ومفتاح، ووُضعت أمام أحد طرفيه حلقة نحاسية مقفلة (غير ملامسة له). ما الذي يحدث لحلقة النحاس لحظة إغلاق المفتاح، وما الذي يحدث لها لحظة فتحه (بعد أن كان مغلقاً لفترة)؟","answer":"لحظة الإغلاق: تنافر فتُدفع الحلقة بعيداً؛ ولحظة الفتح: تجاذب فتُجذب نحو الملف — لحظة إغلاق المفتاح يتصاعد تيار الملف من صفر فيتزايد الفيض المخترق للحلقة المجاورة؛ بقانون لنز يعاكس التيار المحتث في الحلقة هذا التزايد بجعل وجهها المقابل للملف بنفس قطبية الملف (تنافر)، فتُدفع الحلقة بعيداً (كما في تجربة الحلقة القافزة الشهيرة). أما لحظة فتح المفتاح (بعد استقرار التيار) فيهبط تيار الملف فجأة نحو الصفر فيتناقص الفيض؛ فيتولد تيار محتث معاكس الاتجاه يحاول الحفاظ على الفيض المتناقص بجعل وجه الحلقة بقطبية معاكسة لقطبية الملف (تجاذب)، فتُجذب الحلقة نحو الملف للحظة. الصياغة الكاملة للجواب: لحظة الإغلاق: يتزايد الفيض المخترق للحلقة فيتولد فيها تيار محتث يعاكس هذا التزايد (بقانون لنز) فتصبح قوة التفاعل بين الحلقة والملف تنافرية فتُدفع الحلقة بعيداً؛ ولحظة الفتح: يتناقص الفيض فيتولد تيار محتث يحاول الحفاظ عليه فتصبح القوة تجاذبية فتُجذب الحلقة نحو الملف","type":"سؤال","ministerial":false},{"question":"افترض أن الملف والمغناطيس الموضح في الشكل (66)، كل منهما يتحرك بالسرعة نفسها نسبةً إلى الأرض (يحملهما نفس الشخص بيده أثناء المشي)، هل يشير الميلي أميتر الرقمي (أو الكلفانوميتر) المربوط مع الملف إلى انسياب تيار في الدائرة؟ وضّح ذلك.","answer":"لا، لأن السرعة النسبية بينهما صفر فلا يتغيّر الفيض المخترق للملف (ΔΦ/Δt=0) — الحث الكهرومغناطيسي (وفق قانون فاراداي) يعتمد على معدل تغيّر الفيض المخترق للملف مع الزمن، وهذا التغيّر ناتج فقط عن الحركة النسبية بين المصدر (المغناطيس) والملف. بما أن الملف والمغناطيس يتحركان معاً بنفس السرعة والاتجاه بالضبط، فإن سرعتهما النسبية صفر، ووضع المغناطيس بالنسبة للملف يبقى ثابتاً تماماً طوال الحركة، فلا يتغير الفيض إطلاقاً (بصرف النظر عن مدى سرعة حركتهما معاً نسبة للأرض)، ولا يُستحث أي تيار. الصياغة الكاملة للجواب: لا، لأن السرعة النسبية بين الملف والمغناطيس تساوي صفراً (يتحركان معاً بنفس السرعة والاتجاه)، فلا يتغير موضع المغناطيس بالنسبة للملف مطلقاً، وبالتالي لا يتغير الفيض المغناطيسي المخترق للملف مع الزمن (dΦ/dt=0)، فلا تُستحث أي قوة دافعة كهربائية ولا ينساب أي تيار، ويقرأ الجهاز صفراً","type":"سؤال","ministerial":false},{"question":"ما الكمية الفيزيائية التي تُقاس بوحدة (Weber)؟","answer":"الفيض المغناطيسي Φ — الويبر (Weber, Wb) هو وحدة قياس الفيض المغناطيسي Φ في النظام الدولي، حيث Φ=B×A، فوحدته = تسلا×م² = ويبر.","type":"سؤال","ministerial":false},{"question":"ما الكمية الفيزيائية التي تُقاس بوحدة (Weber/s)؟","answer":"القوة الدافعة الكهربائية المحتثة ε — بقانون فاراداي ε=-N(dΦ/dt)، فوحدة القوة الدافعة الكهربائية المحتثة هي وحدة الفيض مقسومة على وحدة الزمن، أي ويبر/ثانية (Wb/s)، وهذه الوحدة تكافئ الفولط (V) تماماً. الصياغة الكاملة للجواب: القوة الدافعة الكهربائية المحتثة ε (لأن ε=dΦ/dt، ووحدتها ويبر/ثانية = فولط)","type":"سؤال","ministerial":false},{"question":"ما الكمية الفيزيائية المشتركة التي تُقاس بكل من وحدتي (Tesla) و(Weber/m²)؟","answer":"كثافة الفيض المغناطيسي B — كثافة الفيض المغناطيسي B تُقاس بوحدة التسلا (Tesla)، وهي مكافئة تماماً لوحدة ويبر/م² (Wb/m²)، لأن B=Φ/A.","type":"سؤال","ministerial":false},{"question":"ما الكمية الفيزيائية التي تُقاس بوحدة (Henry)؟","answer":"معامل الحث (الذاتي L أو المتبادل M) — الهنري (Henry, H) هو وحدة قياس معامل الحث في النظام الدولي، سواء كان معامل حث ذاتي L (في ε=-L·dI/dt) أو معامل حث متبادل M (في ε₂=-M·dI₁/dt).","type":"سؤال","ministerial":false},{"question":"كيف تعمل التيارات الدوامة على كبح اهتزاز الصفيحة المعدنية المهتزة عمودياً على مجال مغناطيسي منتظم؟","answer":"تيارات دوامة تُحدث قوى تعاكس حركة الصفيحة فتُبدّد طاقة اهتزازها حرارياً — أثناء اهتزاز الصفيحة المعدنية داخل المجال، يتغيّر الفيض المخترق لعناصرها الداخلية باستمرار فتُستحث فيها تيارات دوامة دائرية. بقانون لنز، تتفاعل هذه التيارات مع المجال الخارجي B لتولّد قوى (F=IL×B) تُعارض دوماً سبب نشوئها، أي حركة الصفيحة ذاتها، فتُبدد الطاقة الحركية للاهتزاز على هيئة حرارة (فقد I²R) حتى يخمد الاهتزاز تماماً — وهذا أساس آلية \"الكبح المغناطيسي\". الصياغة الكاملة للجواب: حركة الصفيحة (اهتزازها) ضمن المجال تُغيّر الفيض المخترق لأجزائها محلياً فتُستحث فيها تيارات دوامة؛ وبقانون لنز تتفاعل هذه التيارات مع المجال لتولّد قوى تُعاكس دوماً حركة الصفيحة نفسها (سبب الاهتزاز)، فتُبدد طاقة الاهتزاز حرارياً (I²R) داخل الصفيحة تدريجياً، فيخمد الاهتزاز ويتوقف","type":"سؤال","ministerial":false},{"question":"شريحة من النحاس وُضعت بين قطبي مغناطيس كهربائي منتظم كثافة فيضه كبيرة وبمستوٍ شاقولي، وكان مستوى الصفيحة عمودياً على الفيض المغناطيسي. وعندما سُحبت الصفيحة أفقياً بسرعة معينة لإخراجها من المجال، وُجد أن عملية السحب تتطلب تسليط قوة معينة، ويزداد مقدار القوة الساحبة بازدياد مقدار تلك السرعة. ما تفسير الحالتين؟","answer":"لأن التيارات الدوامة تولّد قوة كابحة تعاكس السحب، وتزداد بازدياد السرعة — أثناء خروج الصفيحة من بين القطبين تتغيّر مساحة تقاطعها مع المجال فيتغيّر الفيض المخترق لها مع الزمن، فتُستحث فيها تيارات دوامة. بقانون لنز، تتفاعل هذه التيارات مع B لتولّد قوة معاكسة لحركة السحب (قوة كبح مغناطيسي)، فيجب تسليط قوة سحب مساوية لها للتغلب عليها والحفاظ على السرعة. وبما أن القوة الدافعة الكهربائية المحتثة تتناسب طردياً مع سرعة السحب (ε∝v)، فإن التيار والقوة الكابحة يزدادان معها، فتزداد القوة الساحبة اللازمة تبعاً لذلك. الصياغة الكاملة للجواب: أثناء سحب الشريحة يتناقص الفيض المخترق لأجزائها الخارجة من بين القطبين فتُستحث فيها تيارات دوامة تعاكس (بقانون لنز) حركة السحب نفسها، فتنشأ قوة معاكسة (كابحة) يجب التغلب عليها بالقوة المُسلَّطة؛ وبما أن القوة الدافعة الكهربائية المحتثة (وبالتالي التيار والقوة المعاكسة) تتناسب طردياً مع سرعة السحب، فإن ازدياد السرعة يستلزم قوة ساحبة أكبر للتغلب على القوة الكابحة المتزايدة","type":"سؤال","ministerial":false},{"question":"في كل من الشكلين (67) و(68) سلك نحاسي مستقيم يحمل تياراً متغيراً، وحلقة من النحاس مقفلة بالقرب منه بوضعية مختلفة في كل شكل. في أي وضعية ينساب تيار محتث في الحلقة عندما يتزايد التيار الكهربائي المنساب في السلك؟","answer":"في الشكل (68) فقط، لأن مجال السلك يخترق مساحة الحلقة هناك فعلاً — في الشكل (67) تحيط الحلقة بالسلك بحيث يكون محورها منطبقاً على السلك (السلك يمر من مركزها عمودياً على مستواها). خطوط مجال السلك المستقيم دوائر متمركزة حوله وتقع كلياً في مستوٍ عمودي على السلك — وهو نفس مستوى الحلقة هنا — أي أن المجال عند موضع الحلقة مماسٍ لمستواها دوماً (لا مركبة له عمودية على مستوى الحلقة)، فالفيض المخترق لمساحتها صفر دائماً بصرف النظر عن مقدار أو تغيّر التيار، فلا يُستحث فيها تيار أبداً. أما في الشكل (68) فالحلقة موضوعة بجانب السلك (مستواها يحوي السلك أو موازٍ لجزء منه بشكل مختلف)، فتخترق خطوطُ مجال السلك مساحةَ الحلقة فعلياً، وعند تغيّر التيار يتغيّر هذا الفيض المخترق، فيُستحث تيار في الحلقة وفق قانون فاراداي. الصياغة الكاملة للجواب: في الشكل (68) فقط؛ ففي هذه الوضعية يخترق مجال السلك مساحة الحلقة فعلاً (له مركبة عمودية على مستواها)، بينما في الشكل (67) تكون الحلقة محيطة بالسلك بحيث يكون مجال السلك مماساً لمستوى الحلقة في كل نقطة منه (خطوط المجال الدائرية حول السلك تقع بأكملها ضمن مستوي الحلقة نفسه)، فلا يخترق مساحتها إطلاقاً (الفيض صفر دائماً) مهما تغيّر التيار، فلا يُستحث فيها أي تيار","type":"سؤال","ministerial":false},{"question":"يتوافر لك سلك ذو طول ثابت، وترغب في الحصول على مولد بسيط يجهزك بأعظم مقدار للقوة الدافعة الكهربائية. أيتطلب منك أن تجعل السلك بشكل ملف ذي لفة واحدة دائرية الشكل، أم ملف ذي لفتين دائريتي الشكل، أم ملف ذي ثلاث لفات دائرية الشكل، عند تدوير الملف الذي تحصل عليه بسرعة زاوية معينة داخل مجال مغناطيسي منتظم؟ وضّح إجابتك.","answer":"ملف ذو لفة واحدة، لأن εmax تتناسب عكسياً مع N عند ثبوت طول السلك — بما أن طول السلك L محدد وثابت ويُوزَّع على عدد اللفات N، فمحيط كل لفة (دائرية) = L/N، ونصف قطرها r=L/(2πN)، فمساحتها A=πr²=L²/(4πN²) — تتناقص بشكل تربيعي مع N. بالتعويض في εmax=NBAω نحصل على εmax=BL²ω/(4πN)، وهذه دالة تتناقص عكسياً مع N. إذن زيادة عدد اللفات (مع ثبوت طول السلك الكلي) تُقلل القوة الدافعة الكهربائية العظمى بدلاً من زيادتها؛ وأعظم قيمة تتحقق مع لفة واحدة فقط (N=1) التي تحصل فيها اللفة على أكبر مساحة ممكنة من طول السلك المتاح. الصياغة الكاملة للجواب: ملف ذو لفة واحدة؛ فبما أن طول السلك L ثابت وموزَّع بالتساوي على عدد اللفات N (محيط اللفة الواحدة=L/N)، فإن مساحة اللفة الواحدة (للشكل الدائري) A=π(L/2πN)²=L²/(4πN²) تتناقص مع مربع N؛ وحيث إن εmax=NBAω=N×B×[L²/(4πN²)]×ω = BL²ω/(4πN)، فإن εmax يتناسب عكسياً مع N، أي أن أكبر قيمة له تتحقق عند N=1 (لفة واحدة فقط)","type":"سؤال","ministerial":false},{"question":"في معظم الملفات يُصنع القلب بشكل سيقان متوازية من الحديد المطاوع، معزولة عن بعضها البعض عزلاً كهربائياً، ومكبوسة كبساً شديداً، بدلاً من قلب من الحديد مصنوع كقطعة واحدة (لاحظ الشكل 69). ما الفائدة العملية من ذلك؟","answer":"تقليل التيارات الدوامة في القلب وما تسببه من فقد حراري، بحصرها في سيقان رفيعة معزولة — قلب الملف نفسه مادة موصلة (حديد) موجودة داخل مجال مغناطيسي متغير (بسبب تيار الملف المتردد)، فتُستحث فيه هو أيضاً تيارات دوامة داخلية. لو كان القلب قطعة معدنية واحدة مصمتة لانسابت هذه التيارات الدوامة بحرية وبمقادير كبيرة مسبّبة فقداً حرارياً كبيراً (I²R) يقلل كفاءة الجهاز (ملف/محول/محرك) ويُسخّنه دون فائدة. بتقطيع القلب (لتصفيح Laminating) إلى سيقان رفيعة معزولة كهربائياً عن بعضها، تنحصر مسارات التيارات الدوامة الممكنة ضمن كل سيقة رفيعة على حدة فقط، فيقل مقدارها بشدة (يتناسب تقريباً مع مربع سُمك الشريحة الموصلة)، فيقل الفقد الحراري وتزداد كفاءة الجهاز. الصياغة الكاملة للجواب: تقليل التيارات الدوامة (Eddy Currents) التي كانت ستُستحث بمقادير كبيرة داخل قلب حديدي مصمت واحد (كونه موصلاً موضوعاً في مجال متغير)، وتُسبب فقداً حرارياً كبيراً (I²R) يقلل كفاءة الملف ويُسخّنه؛ فتقطيع القلب إلى سيقان رفيعة معزولة عن بعضها يحصر التيارات الدوامة المحتملة ضمن مقاطع صغيرة جداً فقط، فيقل مقدارها (وبالتالي فقدها الحراري) بشدة","type":"سؤال","ministerial":false},{"question":"ملف سلكي دائري الشكل، عدد لفاته (40) لفة ونصف قطره (15 cm)، وُضع بين قطبي مغناطيس كهربائي (الشكل 70). إذا تغيّرت كثافة الفيض المغناطيسي المارة خلال الملف من (0.0T) إلى (0.5T) خلال فترة زمنية قدرها (4s)، فما مقدار القوة الدافعة الكهربائية المحتثة في الملف عندما يكون متجه مساحة اللفة الواحدة موازياً لمتجه كثافة الفيض المغناطيسي؟","answer":"≈0.353 V — A=πr²=π(0.15)²≈0.0707 m². معدل تغير الفيض = ΔB/Δt=(0.5-0)/4=0.125 T/s. عند التوازي (θ=0° بين B والمتجه العمودي على مستوي اللفة): ε=N·A·(ΔB/Δt)·cos0° = 40×0.0707×0.125×1 ≈ 0.353 V. ⚠️ الأخطاء الشائعة في هذه المسألة: ≈0.177 V ← استُعمل cos60° سهواً بدل الحالة الموازية ≈1.41 V ← استُعمل القطر 30cm كنصف قطر سهواً ≈0.0088 V ← نُسي ضرب العدد N=40","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) ما مقدار القوة الدافعة الكهربائية المحتثة في الملف نفسه، عندما يصنع متجه كثافة الفيض المغناطيسي زاوية قياسها (30°) مع مستوي الملف؟","answer":"≈0.177 V — الزاوية المعطاة (30°) بين B ومستوي الملف، فالزاوية بينه وبين المتجه العمودي على مستوي اللفة (المطلوبة في قانون فاراداي) = 90°-30°=60°. ε = N·A·(ΔB/Δt)·cos60° = 0.353×0.5 ≈ 0.177 V (نصف قيمة الحالة الموازية تماماً، لأن cos60°=0.5).","type":"سؤال","ministerial":false},{"question":"ملف لمولد دراجة هوائية قطره (4 cm) وعدد لفاته (50) لفة، يدور داخل مجال مغناطيسي منتظم كثافة فيضه (1/π) T. كان أعظم مقدار للفولطية المحتثة على طرفي الملف (16V). ما مقدار السرعة الزاوية التي تدور بها نواة المولد؟","answer":"800 rad/s — نصف القطر r=0.02m، A=πr²=π(0.0004)=0.0004π m². N·B·A = 50×(1/π)×0.0004π = 50×0.0004 = 0.02 (يُلاحظ إلغاء π تماماً، وهو دليل على صحة اختيار B=1/π). من εmax=NBAω: ω=16/0.02=800 rad/s.","type":"سؤال","ministerial":false},{"question":"(تتمة مسألة مولد الدراجة) كانت القدرة العظمى المجهزة للحمل المربوط مع المولد (12W)، وأعظم فولطية على طرفي الملف (16V). ما المقدار الأعظم للتيار المنساب في الحمل؟","answer":"0.75 A — بافتراض أن الفولطية العظمى على طرفي الملف تساوي الفولطية على طرفي الحمل (نفس الدائرة)، فإن القدرة اللحظية العظمى المجهزة للحمل P=V×I، ومنه Imax=P/V=12/16=0.75 A.","type":"سؤال","ministerial":false},{"question":"ملف سلكي مستطيل الشكل، عدد لفاته (50) لفة وأبعاده (10cm × 4cm)، يدور بسرعة زاوية منتظمة مقدارها (15π rad/s) داخل مجال مغناطيسي منتظم كثافة فيضه (0.8 Wb/m²). احسب المقدار الأعظم للقوة الدافعة الكهربائية المحتثة في الملف.","answer":"≈7.54 V — A=0.10×0.04=0.004 m². εmax=N·B·A·ω = 50×0.8×0.004×15π = 0.16×15π = 2.4π ≈ 7.54 V. ⚠️ الأخطاء الشائعة في هذه المسألة: ≈15.08 V ← خطأ مضاعفة 2.4 V ← نُسي عامل π في ω، إذ عومل ω=15 بدل 15π ≈0.75 V ← خطأ في تحويل وحدات المساحة","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) ما القوة الدافعة الكهربائية الآنية المحتثة في الملف بعد مرور s(1/90) من الوضع الذي كان مقدارها فيه يساوي صفراً؟","answer":"≈3.77 V — بما أن ε بدأت من الصفر فإن ε(t)=εmax·sin(ωt). ωt = 15π×(1/90) = π/6 = 30°. sin30°=0.5. ε = 2.4π×0.5 = 1.2π ≈ 3.77 V. ⚠️ الأخطاء الشائعة في هذه المسألة: ≈7.54 V ← كامل القيمة العظمى، بافتراض خاطئ أنها بلغت القيمة القصوى فوراً ≈6.53 V ← استُعمل cos بدل sin سهواً ≈1.25 V ← نُسي عامل π الموجود في ω","type":"سؤال","ministerial":false},{"question":"حلقة موصلة دائرية مساحتها (626 cm²) ومقاومتها (9Ω)، موضوعة في مستوي الورقة، سُلط عليها مجال مغناطيسي منتظم كثافة فيضه (0.15T) باتجاه عمودي على مستوي الحلقة (الشكل 71). سُحبت الحلقة من جانبيها بقوتي شدّ متساويتين فبلغت مساحتها (26 cm²) خلال فترة زمنية (0.2s). احسب مقدار التيار المحتث في الحلقة.","answer":"5 mA — ΔA=(626-26)cm²=600cm²=0.06 m². ΔΦ=B·ΔA=0.15×0.06=0.009 Wb. ε=ΔΦ/Δt=0.009/0.2=0.045 V. I=ε/R=0.045/9=0.005 A = 5 mA. ⚠️ الأخطاء الشائعة في هذه المسألة: 10 A ← خطأ في تحويل الوحدات من cm² إلى m² 5.22 mA ← استُعملت المساحة الأصلية كاملة 626cm² بدل الفرق 600cm² 45 mA ← نُسيت القسمة على المقاومة R","type":"سؤال","ministerial":false},{"question":"ساق موصلة طولها (0.1m) تتحرك على سكتين متوازيتين (الشكل 72) بسرعة مقدارها (2.5 m/s)، والمقاومة الكلية للدائرة (الساق والسكة) (0.03 Ω)، وكثافة الفيض المغناطيسي العمودي على مستوى الدائرة (0.6T). احسب مقدار القوة الدافعة الكهربائية المحتثة على طرفي الساق.","answer":"0.15 V — القوة الدافعة الكهربائية الحركية: ε=Bℓv = 0.6×0.1×2.5 = 0.15 V. ⚠️ الأخطاء الشائعة في هذه المسألة: 0.375 V ← استُعمل v² بدل v سهواً 0.025 V ← خُلطت القيم سهواً 1.5 V ← نُسي ضرب طول الساق ℓ","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) احسب مقدار التيار المحتث في الحلقة (الدائرة المكوّنة من الساق والسكتين).","answer":"5 A — I = ε/R = 0.15/0.03 = 5 A. ⚠️ الأخطاء الشائعة في هذه المسألة: 0.0045 A ← ضُرب بدل القسمة سهواً 0.5 A ← استُعملت مقاومة خاطئة 0.3Ω بدل 0.03Ω 0.15 A ← نُسيت القسمة على المقاومة الكلية","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) احسب مقدار القوة الساحبة (المؤثرة لتحريك الساق بسرعة ثابتة، وتساوي بمقدارها القوة المغناطيسية المعاكسة).","answer":"0.3 N — F = B·I·ℓ = 0.6×5×0.1 = 0.3 N (وهذه القوة المسحوبة تساوي بالمقدار القوة المغناطيسية المعاكسة للحركة عند السرعة الثابتة). ⚠️ الأخطاء الشائعة في هذه المسألة: 0.75 N ← خُلط الحساب مع صيغة القدرة εI سهواً 3 N ← نُسي ضرب طول الساق ℓ 0.03 N ← استُعمل تيار خاطئ 0.5A","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) احسب مقدار القدرة المتبددة في المقاومة الكلية للدائرة.","answer":"0.75 W — P = I²R = (5)²×0.03 = 25×0.03 = 0.75 W. (يمكن التحقق أيضاً بـP=F×v = 0.3×2.5 = 0.75 W، وتطابق النتيجتين دليل على صحة الحل). ⚠️ الأخطاء الشائعة في هذه المسألة: 0.15 W ← نُسي تربيع التيار في I²R 1.5 W ← خُلط الحساب مع F×I سهواً 0.0045 W ← استُعملت الصيغة الخاطئة ε×R","type":"سؤال","ministerial":false},{"question":"كانت الطاقة المغناطيسية المختزنة في ملف تساوي (360 J) عندما كان مقدار التيار المنساب فيه (20A). احسب مقدار معامل الحث الذاتي للملف.","answer":"1.8 H — من U=½LI²: L = 2U/I² = (2×360)/(20)² = 720/400 = 1.8 H. ⚠️ الأخطاء الشائعة في هذه المسألة: 0.56 H ← قُلبت العلاقة خطأً 36 H ← نُسي تربيع التيار 0.9 H ← نُسي المعامل 2 في U=½LI²","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) احسب معدل القوة الدافعة الكهربائية المحتثة في الملف إذا انعكس اتجاه التيار (من 20A+ إلى 20A- أي بتغيّر مقداره 40A) خلال فترة زمنية (0.1s).","answer":"720 V — انعكاس التيار من +20A إلى -20A يعني أن مقدار التغيّر الكلي ΔI=20-(-20)=40A. ε = L×(ΔI/Δt) = 1.8×(40/0.1) = 1.8×400 = 720 V. ⚠️ الأخطاء الشائعة في هذه المسألة: 0.0045 V ← قُلبت العلاقة خطأً 72 V ← استُعمل زمن خاطئ 1s بدل 0.1s 360 V ← اعتُبر ΔI=20A فقط متناسياً أن الانعكاس يعني تغيّراً مقداره 40A","type":"سؤال","ministerial":false},{"question":"ملفان متجاوران بينهما ترابط مغناطيسي تام، معامل الحث الذاتي للملف الابتدائي (0.4H) ومقاومته (16Ω)، ومعامل الحث الذاتي للملف الثانوي (0.9H). الفولطية الموضوعة في دائرة الملف الابتدائي (200V). احسب مقدار التيار الآني في دائرة الملف الابتدائي لحظة ازدياد التيار فيها إلى (80%) من مقداره الثابت النهائي.","answer":"10 A — في الحالة المستقرة النهائية (بعد زمن طويل) يسلك الملف سلوك سلك عادي (لا يُسقط جهداً)، فالتيار الثابت النهائي Imax=V/R=200/16=12.5A. عند لحظة بلوغ التيار (80%) من هذه القيمة: I=0.8×12.5=10 A. ⚠️ الأخطاء الشائعة في هذه المسألة: 160 A ← طُبقت نسبة 80% على الجهد V بدل التيار 12.5 A ← هذه قيمة التيار الثابت النهائي كاملاً، دون تطبيق نسبة 80% 12.8 A ← خُلطت نسبة 80% مع قيمة R سهواً","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) احسب المعدل الزمني لتغيّر التيار (dI/dt) في دائرة الملف الابتدائي في تلك اللحظة نفسها (عندما بلغ التيار 80% من قيمته الثابتة).","answer":"100 A/s — بتطبيق قانون كيرخوف للجهد على الدائرة عند تلك اللحظة: V = I·R + L·(dI/dt). بالتعويض بالتيار الآني I=10A: 200 = (10×16) + 0.4×(dI/dt) ⇒ 200 = 160 + 0.4(dI/dt) ⇒ dI/dt = 40/0.4 = 100 A/s. ⚠️ الأخطاء الشائعة في هذه المسألة: 2.5 A/s ← قُسم الفرق على R بدل L خطأً 500 A/s ← نُسي طرح الهبوط IR على المقاومة قبل القسمة على L 0 A/s ← استُعملت قيمة التيار الثابت النهائي 12.5A بدل قيمته الآنية 10A في تلك اللحظة","type":"سؤال","ministerial":false},{"question":"(تتمة المسألة السابقة) احسب مقدار القوة الدافعة الكهربائية المحتثة على طرفي الملف الثانوي في تلك اللحظة نفسها (الترابط المغناطيسي بين الملفين تام).","answer":"60 V — للترابط المغناطيسي التام: M=√(L1×L2)=√(0.4×0.9)=√0.36=0.6 H. القوة الدافعة الكهربائية المحتثة في الملف الثانوي: ε₂ = M×(dI1/dt) = 0.6×100 = 60 V. ⚠️ الأخطاء الشائعة في هذه المسألة: 36 V ← نُسي الجذر التربيعي في M=√(L1L2) واستُعمل الضرب المباشر L1×L2 90 V ← استُعمل L2 مباشرة بدل M 300 V ← استُعمل معدل التغير الخاطئ 500 A/s","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":1,"lesson_title":"مقدمة والمقدار المؤثر للتيار المتناوب","order_index":1,"hook":"لو التيار المستمر أبسط، ليش كل محطات توليد الكهرباء بالعالم تنتج متناوباً؟ لأن التيار المتناوب وحده يمكن رفع فولطيته أو خفضها بسهولة عبر المحوّلات — فتُنقل الطاقة مسافات طويلة بفولطية عالية وتيار منخفض (فتقلّ الفاقد الحراري P=I²R بالأسلاك)، ثم تُخفَّض الفولطية قرب البيوت. هذا بالضبط سبب اختيار المهندسين للمتناوب قبل أكثر من قرن، وسيبقى معك بقية هذا الفصل.","concepts":[{"term":"فرق الطور Φ:","text":"الزاوية بين متجهَي الفولطية والتيار الدوّارين. إذا بلغا ذروتيهما وصفرا معاً بنفس اللحظة، كانا بطور واحد (Φ=0). كل عنصر بالدائرة (مقاومة، محث، أو متسعة) يفرض قيمة مختلفة لهذه الزاوية — ستكتشف كل حالة بالدروس القادمة.","ministerial":false},{"term":"انتبه — ما تقرؤه الأجهزة:","text":"مقاييس التيار والفولطية المتناوبة (الأميتر والفولتميتر) تقيس المقدار المؤثر لا الأعظم. فقولنا \"فولطية بيتنا 220V\" يعني V_eff=220V، بينما ذروتها الحقيقية V_m = √2×220 ≈ 311V! لذا يُصمَّم عزل الأسلاك ليتحمّل الذروة لا الرقم المكتوب.","ministerial":false}],"laws":[{"name":"الفولطية والتيار الآنيّان (اللحظيّان)","formula":"V = V_m sin(ωt)  ،  I = I_m sin(ωt)  ،  ω = 2πf","variables_note":""},{"name":"المقدار المؤثر للتيار والفولطية","formula":"I_eff = I_m/√2 = 0.707 I_m  ،  V_eff = V_m/√2 = 0.707 V_m","variables_note":""}],"notes":[{"heading":"⭐ القاعدة الذهبية: تعريف المقدار المؤثر","items":["المقدار المؤثر للتيار المتناوب هو مقدار التيار المستمر الذي يولّد — في المقاومة نفسها وخلال الزمن نفسه — التأثير الحراري نفسه الذي يولّده التيار المتناوب."],"ministerial":false}],"tables":[],"examples":[{"problem":"مصدر فولطية متناوبة رُبط بين طرفيه مقاومة صرف R=100Ω، والفولطية بالدائرة تُعطى بالعلاقة V_R=424.2 sin(200πt). أوجد: ① علاقة التيار I(t). ② المقدار المؤثر للفولطية والتيار.","givens":"المعطيات: R=100Ω — V_R=424.2 sin(200πt) ⟹ V_m=424.2V, ω=200π rad/s","solution_steps":["الخطوة ١: نوجد أعظم قيمة للتيار بقانون أوم: I_m = V_m/R = 424.2/100 = 4.242 A فتكون علاقة التيار: I = 4.242 sin(200πt)","الخطوة ٢: نوجد المقدار المؤثر للفولطية: V_eff = V_m/√2 = 424.2/1.414 ≈ 300 V","الخطوة ٣: نوجد المقدار المؤثر للتيار: I_eff = V_eff/R = 300/100 = 3 A  (أو I_eff = I_m/√2 = 4.242/1.414 = 3 A) 💡 لاحظ أن أي طريقة من الاثنتين تعطي نفس الجواب — قانون أوم يصح بالمؤثر كما يصح بالذروة، طالما استعملنا نفس النوع بطرفَي المعادلة."],"ministerial":false}],"qa":[{"question":"تُفضّل محطات توليد الكهرباء إنتاج تيار متناوب لا مستمر لنقله عبر خطوط الجهد العالي.","answer":"لأن التيار المتناوب وحده يمكن رفع فولطيته أو خفضها بسهولة عبر المحوّلات. فتُرفع الفولطية جداً قبل النقل ليصغر التيار عند القدرة نفسها (P=V×I)، فتقلّ الفاقد الحراري بالأسلاك (P_فاقد=I²R) على مسافات النقل الطويلة، ثم تُخفَّض الفولطية قرب المستهلك لتصير آمنة للاستعمال المنزلي.","type":"علل","ministerial":true},{"question":"القدرة المتبدّدة بوساطة تيار متناوب أعظمه I_m لا تساوي القدرة الناتجة عن تيار مستمر يمتلك المقدار نفسه.","answer":"لأن التيار المتناوب لا يبقى عند قيمته العظمى I_m إلا للحظة واحدة كل ربع دورة، وهو أقل منها بقية الزمن. لذا قدرته المتوسطة P_av = ½ I_m² R، أي تكافئ تياراً مستمراً مقداره I_eff = I_m/√2 فقط — وهو أصغر من I_m — فتأثيره الحراري أقل من مستمر بنفس المقدار I_m.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🌊 مختبر الدالة الجيبية ومتجه الطور"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":2,"lesson_title":"دائرة تيار متناوب تحتوي مقاومة صرفة R","order_index":2,"hook":"مصباح بيتك المتصل بالتيار المتناوب يومض فعلياً 100 مرة بالثانية! لأن القدرة اللحظية بمقاومة صرفة تبلغ ذروتها مرتين كل دورة كهربائية (عند +V_m و−V_m). لكن شبكية عينك أبطأ من أن تلاحظ الفرق، فتراه ثابت الإضاءة تماماً.","concepts":[],"laws":[{"name":"الفولطية والتيار بمقاومة صرفة (بطور واحد، Φ=0)","formula":"V_R = V_m sin(ωt)  ،  I_R = I_m sin(ωt) = (V_m/R) sin(ωt)","variables_note":""},{"name":"القدرة المتوسطة بمقاومة صرفة","formula":"P_av = I_m V_m / 2 = I_eff V_eff = I²_eff R","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"دائرة تيار متناوب تحتوي مقاومة صرفة R=50Ω، مربوطة بمصدر فولطيته العظمى V_m=100V. أوجد: ① التيار الأعظم I_m. ② القدرة المتوسطة المستهلكة P_av. ③ القدرة العظمى اللحظية.","givens":"المعطيات: R=50Ω — V_m=100V","solution_steps":["الخطوة ١: بقانون أوم للذروة: I_m = V_m/R = 100/50 = 2 A","الخطوة ٢: القدرة المتوسطة: P_av = I_m V_m/2 = 2×100/2 = 100 W","الخطوة ٣: القدرة العظمى اللحظية (تحدث لحظياً عند كل ذروة، مرتين بالدورة): P_max = I_m V_m = 2×100 = 200 W  (أي ضعف المتوسط بالضبط)"],"ministerial":false}],"qa":[{"question":"يقول زميلك: \"بما أن متوسط التيار المتناوب الجيبي يساوي صفراً خلال دورة كاملة، فهو لا يعطي أي قدرة ولا يسخّن شيئاً.\" أين الخطأ بكلامه؟","answer":"خلط زميلك بين متوسط التيار ومتوسط القدرة. صحيح أن متوسط التيار الجيبي صفر، لكن القدرة تتناسب مع مربّع التيار (P=I²R)، ومربّع أي عدد — سالباً كان أم موجباً — نتيجته موجبة دائماً. لذا فالقدرة موجبة بكل لحظة ومتوسطها لا يساوي صفراً بل ½ I_m² R، ولهذا تسخن المدفأة ويضيء المصباح فعلياً رغم انعكاس التيار مئة مرة بالثانية.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"💡 مختبر المقاومة الصرفة: الفولطية والتيار والقدرة"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":3,"lesson_title":"دائرة تحتوي محث صرف L","order_index":3,"hook":"مصباح الفلورسنت القديم يحتاج تياراً محدوداً وإلا احترق. لماذا يضع المهندسون ملفاً (خانقاً) على التوالي معه بدل مقاومة عادية؟ لأن المقاومة تحدّ التيار لكنها تبدّد طاقة كبيرة حرارةً (هدر وحرّ)، أما رادة المحث فتحدّ التيار دون أن تبدّد أي طاقة — فيعمل المصباح بكفاءة أعلى بكثير. هذا بالضبط ما ستفهمه بهذا الدرس.","concepts":[{"term":"سلوك المحث بالترددات:","text":"رادة الحث X_L تتناسب طردياً مع التردد f ومع معامل الحث L. عند الترددات العالية جداً يعمل المحث كمقاومة كبيرة جداً تكاد تخنق التيار تماماً (لهذا يُسمّى \"خانقاً\"). وعند التردد الواطئ جداً (وصولاً لتيار مستمر، f=0) تصبح X_L=0 — يعمل المحث كسلك عادي (قصر).","ministerial":false}],"laws":[{"name":"الفولطية والتيار بمحث صرف (الفولطية متقدّمة 90°)","formula":"V_L = V_m sin(ωt + 90°)  ،  I_L = I_m sin(ωt)","variables_note":""},{"name":"رادة الحث","formula":"X_L = ωL = 2πf L","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"محث صرف معامل حثه L = 50/π mH، رُبط بمصدر متناوب فولطيته المؤثرة V_eff=20V. احسب رادة الحث والتيار المؤثر عند: ① f=10Hz. ② f=1MHz (مليون هرتز).","givens":"المعطيات: L = 50/π mH = (50/π)×10⁻³ H — V_eff = 20 V","solution_steps":["الخطوة ١ (عند f=10Hz): X_L = 2πfL = 2π × 10 × (50/π)×10⁻³ = 1 Ω I_eff = V_eff/X_L = 20/1 = 20 A","الخطوة ٢ (عند f=1MHz=10⁶Hz): X_L = 2π × 10⁶ × (50/π)×10⁻³ = 10⁵ Ω I_eff = 20/10⁵ = 2×10⁻⁴ A 💡 لاحظ: رفع التردد مئة ألف ضعف رفع الرادة بنفس النسبة تماماً وكاد يخنق التيار بالكامل — هذا بالضبط سبب تسمية المحث بـ\"الخانق\" بالترددات العالية."],"ministerial":false}],"qa":[{"question":"ما مميزات منحني القدرة المتوسطة في دائرة تيار متناوب تحتوي محث صرف فقط؟","answer":"منحني القدرة اللحظية يحوي أجزاءً موجبة وأخرى سالبة متساوية بالمساحة تماماً، فمجموعها خلال دورة كاملة يساوي صفراً — أي أن القدرة المتوسطة تساوي صفراً. فالمحث الصرف لا يبدّد أي طاقة، بل يختزنها في مجاله المغناطيسي خلال ربع دورة ثم يعيدها بالكامل للمصدر بالربع التالي.","type":"سؤال محلول","ministerial":true}],"has_simulation":true,"simulation_title":"🧲 مختبر المحث الصرف: X_L والطور"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":4,"lesson_title":"دائرة تحتوي متسعة ذات سعة صرف C","order_index":4,"hook":"سمّاعة الصوت بجهازك تفصل الجهير عن الصفير بنفس فيزياء هذا الدرس: المتسعة (رادتها تصغر بالترددات العالية) تمرّر الأصوات الحادّة للسمّاعة الصغيرة، بينما المحث (من الدرس الماضي) يمرّر الجهير للسمّاعة الكبيرة. وأشهر تطبيق آخر: المتسعة تمرّر التيار المتناوب وتحجب المستمر تماماً — سرّ \"مكثّف الربط\" بمكبّرات الصوت.","concepts":[{"term":"سلوك المتسعة بالترددات:","text":"رادة السعة X_C تتناسب عكسياً مع التردد f والسعة C. عند f=0 (تيار مستمر) تصبح X_C=∞ — تعمل المتسعة كمفتاح مفتوح فتحجب المرور تماماً (تماماً كما درست بدائرة التيار المستمر). وعند الترددات العالية جداً تصغر X_C كثيراً فتمرّر التيار بسهولة تامة.","ministerial":false}],"laws":[{"name":"الفولطية والتيار بمتسعة صرفة (التيار متقدّم 90°)","formula":"V_C = V_m sin(ωt)  ،  I_C = I_m sin(ωt + 90°)","variables_note":""},{"name":"رادة السعة","formula":"X_C = 1/(ωC) = 1/(2πf C)","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"متسعة سعتها C=100μF، رُبطت بمصدر متناوب فولطيته المؤثرة V_eff=10V. احسب رادة السعة والتيار المؤثر عند: ① f=50Hz. ② f=5000Hz.","givens":"المعطيات: C=100μF=100×10⁻⁶F — V_eff=10V","solution_steps":["الخطوة ١ (عند f=50Hz): X_C = 1/(2πfC) = 1/(2π×50×100×10⁻⁶) ≈ 31.83 Ω I_eff = V_eff/X_C = 10/31.83 ≈ 0.314 A","الخطوة ٢ (عند f=5000Hz): X_C = 1/(2π×5000×100×10⁻⁶) ≈ 0.318 Ω I_eff = 10/0.318 ≈ 31.4 A 💡 لاحظ: رفع التردد مئة ضعف خفّض الرادة مئة ضعف ورفع التيار مئة ضعف — عكس تماماً ما رأيناه بالمحث بالدرس الماضي."],"ministerial":false}],"qa":[{"question":"وصلتَ مصباحاً على التوالي مع متسعة كبيرة بمصدر متناوب فأضاء، وبمصدر مستمر بالفولطية نفسها فانطفأ تماماً. لماذا؟","answer":"لأن رادة المتسعة X_C=1/(2πfC) تعتمد على التردد. مع المتناوب (f=50Hz) تكون الرادة محدودة فيمرّ تيار يكفي لإضاءة المصباح. أمّا مع المستمر (f=0) فتصبح X_C لانهاية — تعمل المتسعة كمفتاح مفتوح فلا يمرّ أي تيار ولا يضيء المصباح. المتسعة \"تمرّر\" المتناوب و\"تقطع\" المستمر تماماً.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🔷 مختبر المتسعة الصرفة: X_C والطور"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":5,"lesson_title":"ربط التوالي R-L-C","order_index":5,"hook":"لا يمكن جمع V_R وV_L وV_C جبرياً كأنها أعداد عادية — لأنها لا تبلغ ذروتها بنفس اللحظة! الحل: نعاملها كمتجهات لها طول واتجاه (زاوية طورها)، ونجمعها متجهياً كما تجمع القوى بالميكانيك. النتيجة مثلث قائم الزاوية أنيق يلخّص الدائرة كلها برقمين فقط: الممانعة Z وزاوية الطور Φ.","concepts":[{"term":"📈 دائرة حثّية","text":"إذا كان X_L > X_C ⟹ Φ موجبة، والفولطية الكلية تتقدّم على التيار.","ministerial":false},{"term":"📉 دائرة سعوية","text":"إذا كان X_C > X_L ⟹ Φ سالبة، والفولطية الكلية تتأخر عن التيار.","ministerial":false}],"laws":[{"name":"الفولطية الكلية وزاوية الطور (مخطط الفولطيات)","formula":"(V_T)² = (V_R)² + (V_L − V_C)²  ،  tan Φ = (V_L − V_C)/V_R","variables_note":""},{"name":"الممانعة الكلية وزاوية الطور","formula":"Z = V_T/I  ،  Z² = R² + (X_L − X_C)²  ،  tan Φ = (X_L − X_C)/R","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"دائرة تيار متناوب متوالية الربط تحتوي مقاومة ومحثاً ومتسعة، مقاومتها R=40Ω، ورادة المحث X_L=120Ω، ورادة المتسعة X_C=90Ω، والفولطية الموضوعة V_T=240V بتردد f=500/π Hz. (سؤال وزاري، الدور الثالث 2022) أوجد: ① معامل الحث الذاتي للملف وسعة المتسعة. ② الممانعة الكلية وتيار الدائرة وزاوية فرق الطور.","givens":"المعطيات: R=40Ω — X_L=120Ω — X_C=90Ω — V_T=240V — f=500/π Hz","solution_steps":["الخطوة ١: من قانون X_L نوجد L: X_L=2πfL ⟹ 120 = 2π×(500/π)×L = 1000L ⟹ L = 0.12 H ومن قانون X_C نوجد C: X_C=1/(2πfC) ⟹ 90 = 1/(1000C) ⟹ C ≈ 11.1 μF","الخطوة ٢: نوجد الممانعة الكلية: Z = √(R² + (X_L−X_C)²) = √(40² + 30²) = √2500 = 50 Ω","الخطوة ٣: نوجد التيار وزاوية الطور: I = V_T/Z = 240/50 = 4.8 A tan Φ = (X_L−X_C)/R = 30/40 = 0.75 ⟹ Φ = 37° (حثّية، لأن X_L>X_C)"],"ministerial":true}],"qa":[],"has_simulation":true,"simulation_title":"📐 مختبر الدائرة المتوالية R-L-C: مثلث الممانعة"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":6,"lesson_title":"عامل القدرة والقدرة المستهلكة","order_index":6,"hook":"لماذا تحاسب شركات الكهرباء المصانع الكبيرة على \"عامل القدرة\" لا على التيار فقط؟ لأن دائرة فيها محركات (محثّات كبيرة) تسحب تياراً كبيراً من الشبكة، لكن جزءاً منه فقط يتحوّل لعمل فعلي — والباقي يتردد ذهاباً وإياباً بلا فائدة. عامل القدرة هو المقياس الدقيق لهذه الكفاءة.","concepts":[{"term":"الحالات الحدّية:","text":"بمقاومة صرفة: Φ=0 ⟹ pf=cos0°=1 (كل القدرة الظاهرية تُستهلك فعلاً). بمحث صرف أو متسعة صرفة: Φ=90° ⟹ pf=cos90°=0 (لا استهلاك إطلاقاً، كل الطاقة تُختزن وتُعاد). والدائرة الحقيقية R-L-C تقع بينهما دائماً: 0 < pf < 1.","ministerial":false}],"laws":[{"name":"القدرة الحقيقية والظاهرية","formula":"P_real = I V_T cos Φ  (واط W)   ،   P_app = I V_T  (فولت-أمبير V·A)","variables_note":""},{"name":"عامل القدرة","formula":"pf = P_real/P_app = cos Φ = R/Z","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"رُبط ملف (محث بمقاومة داخلية) بين قطبي مصدر فولطية متناوبة فرق جهده V_T=100V، فكانت زاوية فرق الطور بين الفولطية الكلية والتيار Φ=37°، ومقدار التيار I=5A. (سؤال وزاري، الدور الثاني 2021 — cos37°=0.8) أوجد: ① مقاومة الملف R. ② تردد المصدر f، إذا كان معامل حث الملف L=1/(10π) H.","givens":"المعطيات: V_T=100V — I=5A — Φ=37° (cos37°=0.8) — L=1/(10π) H","solution_steps":["الخطوة ١: نوجد الممانعة أولاً: Z = V_T/I = 100/5 = 20 Ω","الخطوة ٢: من عامل القدرة نوجد R: pf = cos Φ = R/Z ⟹ 0.8 = R/20 ⟹ R = 16 Ω","الخطوة ٣: نوجد X_L من مثلث الممانعة، ثم f: Z² = R² + X_L² ⟹ 400 = 256 + X_L² ⟹ X_L = 12 Ω X_L = 2πfL ⟹ 12 = 2πf × 1/(10π) = f/5 ⟹ f = 60 Hz"],"ministerial":true}],"qa":[],"has_simulation":true,"simulation_title":"⚖️ مختبر عامل القدرة: القدرة اللحظية بفرق طور عام"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":7,"lesson_title":"دائرة الرنين بربط التوالي","order_index":7,"hook":"حين تدير قرص \"الدوزان\" براديو قديم، أنت فعلياً تغيّر سعة متسعة متغيّرة بدائرة رنين. عند سعة معيّنة يصير التردد الرنيني f_r=1/2π√(LC) مساوياً تردد محطة واحدة، فتُضخَّم إشارتها آلاف المرات بينما تبقى بقية المحطات مهملة ضعيفة. تغيير المحطة = تغيير C = إزاحة قمة الرنين لتردد جديد.","concepts":[],"laws":[{"name":"التردد الرنيني (من شرط ωL=1/ωC)","formula":"ω_r = 1/√(LC)  ،  f_r = 1/(2π√(LC))","variables_note":""},{"name":"عامل النوعية","formula":"Q_f = f_r/Δf = (1/R) √(L/C)","variables_note":""}],"notes":[{"heading":"⭐ القاعدة الذهبية: شرط الرنين","items":["عند الرنين تكون X_L=X_C، فتُلغي إحداهما الأخرى وتصبح الممانعة أصغر ما يمكن (Z=R)، فيبلغ التيار أعظم مقدار له، وتكون Φ=0 وعامل القدرة يساوي 1 بالضبط."],"ministerial":false}],"tables":[],"examples":[{"problem":"دائرة تيار متناوب متوالية الربط تحتوي مقاومة R=3Ω ومعامل حث ذاتي L=0.04H ومتسعة سعتها C=25μF، وُضعت فولطية متناوبة V_T=75V والدائرة في حالة رنين. (سؤال وزاري، الدور الثالث 2019) احسب: ① التيار المنساب. ② الفولطية عبر المحث وعبر المتسعة. ③ عامل النوعية.","givens":"المعطيات: R=3Ω — L=0.04H — C=25μF — V_T=75V (حالة رنين)","solution_steps":["الخطوة ١: نوجد التردد الزاوي الرنيني: ω_r = 1/√(LC) = 1/√(0.04×25×10⁻⁶) = 1/√(10⁻⁶) = 1000 rad/s وعند الرنين Z=R=3Ω، فالتيار: I = V_T/Z = 75/3 = 25 A","الخطوة ٢: نوجد X_L=X_C عند الرنين، ثم الفولطيتين: X_L = ω_r L = 1000×0.04 = 40 Ω  (= X_C أيضاً) V_L = I×X_L = 25×40 = 1000 V  ،  V_C = I×X_C = 1000 V (متساويتان ومتعاكستان بالطور)","الخطوة ٣: نوجد عامل النوعية: Q_f = (1/R)√(L/C) = (1/3)√(0.04/25×10⁻⁶) = (1/3)×40 ≈ 13.33 💡 جرّب هذي القيم بالضبط بالمحاكاة فوق (R=3، L=40، C=25) — راح تلاحظ f_r≈159.2Hz وQ_f≈13.3 مطابقين لحسابنا هنا (فقط I_max بالمحاكاة يختلف لأنها تستعمل مصدراً ثابتاً V=10V لا 75V)."],"ministerial":true}],"qa":[{"question":"يمكن أن تكون زاوية فرق الطور Φ=0 بدائرة تيار متناوب متوالية الربط تحتوي مقاومة ومحثاً ومتسعة.","answer":"يحدث ذلك بحالة الرنين، عندما يساوي تردد المصدر التردد الرنيني للدائرة، فتتساوى الرادتان X_L=X_C ويُلغي أحدهما الآخر، فتصبح الممانعة Z=R (مقاومة صرفة فعلياً). وعندها tan Φ=(X_L−X_C)/R=0 ⟹ Φ=0.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"📶 مختبر رنين دائرة RLC المتوالية"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":8,"lesson_title":"ربط التوازي R-L-C","order_index":8,"hook":"بالتوالي كان التيار مشتركاً والفولطيات تختلف. بالتوازي ينعكس المنطق تماماً: الفولطية V نفسها عبر الجميع، لكن كل فرع (R وL وC) يسحب تياره الخاص بزاوية طور مختلفة عن باقي الفروع — تماماً كما تسحب كل أجهزة بيتك تياراتها المختلفة من نفس فولطية 220V المشتركة.","concepts":[{"term":"⚠️ انتبه — الاتجاه ينعكس عن التوالي!","text":"بالتوالي (الدرس 5): X_L>X_C ⟹ حثّية. لكن بالتوازي هنا: I_L>I_C ⟹ حثّية (عكس اتجاه المقارنة تماماً، لأن التيار في الفرع الأصغر رادةً هو الأكبر مقداراً — علاقة عكسية I=V/X). هذي أشهر نقطة لخبطة بين الطالبين بهذا الموضوع، فانتبه لها بالاختبار.","ministerial":false},{"term":"📋 استراتيجية حل أي مسألة RLC (ملخّص الفصل كله):","text":"① احسب X_L=2πfL وX_C=1/(2πfC) عند التردد f المعطى. ② بالتوالي: اجمع R وX_L−X_C متجهياً لإيجاد Z وΦ. بالتوازي: احسب تيار كل فرع (I=V/X) ثم اجمعها متجهياً لإيجاد I_T وΦ. ③ استخرج ما يُطلب: القدرة الحقيقية (I×V×cosΦ)، عامل القدرة (cosΦ=R/Z)، أو تحقّق من حالة الرنين (X_L=X_C).","ministerial":false}],"laws":[{"name":"تيارات الفروع","formula":"I_R = V/R  ،  I_L = V/X_L  ،  I_C = V/X_C","variables_note":""},{"name":"التيار الرئيس وزاويته","formula":"I_T² = I_R² + (I_C − I_L)²  ،  tan Φ = (I_C − I_L)/I_R","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"دائرة تيار متناوب متوازية الربط تحتوي مقاومة صرفة ومحثاً ومتسعة، فرق الجهد بين طرفيها 240V، وكان التيار في فرع المتسعة I_C=8A، وفرع المحث I_L=12A، وفرع المقاومة I_R=3A. (سؤال وزاري، تمهيدي 2017) جد: ① التيار الرئيس. ② الممانعة الكلية. ③ زاوية فرق الطور. (tan53°=4/3)","givens":"المعطيات: V=240V — I_C=8A — I_L=12A — I_R=3A","solution_steps":["الخطوة ١: نوجد التيار الرئيس بالجمع المتجهي: I_T = √(I_R² + (I_C−I_L)²) = √(3² + (8−12)²) = √(9+16) = √25 = 5 A","الخطوة ٢: نوجد الممانعة الكلية: Z = V/I_T = 240/5 = 48 Ω","الخطوة ٣: نوجد زاوية فرق الطور: tan Φ = (I_C−I_L)/I_R = (8−12)/3 = −4/3 ⟹ Φ = −53° بما أن I_L أكبر من I_C، فالدائرة حثّية الخواص (رغم أن Φ سالبة هنا — عكس قاعدة التوالي تماماً كما نبّهنا أعلاه)."],"ministerial":true}],"qa":[],"has_simulation":true,"simulation_title":"🔀 مختبر الدائرة المتوازية: مخطط أطوار التيارات"},{"chapter_number":"g6c3","chapter_title":"التيار المتناوب","lesson_number":9,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":9,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"تيار متناوب معطى بالعلاقة I=6 sin(100πt). ما مقدار تردده f؟","answer":"50 Hz — ω=100π=2πf ⟹ f=50Hz.","type":"سؤال","ministerial":false},{"question":"فولطية متناوبة أعظمها V_m=150V. ما مقدارها المؤثر تقريباً؟","answer":"≈106.1 V — V_eff = V_m/√2 = 150/1.414 ≈ 106.1 V.","type":"سؤال","ministerial":false},{"question":"تيار متناوب مقداره المؤثر I_eff=4A. ما مقداره الأعظم I_m؟","answer":"≈5.66 A — I_m = I_eff × √2 = 4×1.414 ≈ 5.66 A.","type":"سؤال","ministerial":false},{"question":"متجه الطور بتيار متناوب يدور بسرعة زاوية ω. ما الذي يمثله مسقطه على المحور الشاقولي بأي لحظة؟","answer":"القيمة الآنية (اللحظية) للتيار — مسقط متجه الطور (طوله I_m) على المحور الشاقولي يعطي القيمة الآنية بالضبط i(t)=I_m sinθ.","type":"سؤال","ministerial":false},{"question":"لماذا نستعمل المقدار المؤثر لا الذروة عند وصف تيار أو فولطية متناوبة عملياً؟","answer":"لأنه يكافئ تياراً/فولطية مستمرة بنفس التأثير الحراري، وهو ما تقرؤه الأجهزة (الأميتر والفولتميتر) فعلياً — المقدار المؤثر (RMS) هو ما تقيسه الأجهزة فعلياً، ويكافئ تياراً/فولطية مستمرة بنفس مقدار التأثير الحراري.","type":"سؤال","ministerial":false},{"question":"دائرة تحتوي مقاومة صرفة R=25Ω مربوطة بمصدر V_m=50V. جد التيار الأعظم I_m.","answer":"2 A — I_m = V_m/R = 50/25 = 2 A.","type":"سؤال","ministerial":false},{"question":"بنفس الدائرة أعلاه (R=25Ω, I_m=2A, V_m=50V)، جد القدرة المتوسطة P_av.","answer":"50 W — P_av = I_m V_m/2 = 2×50/2 = 50 W.","type":"سؤال","ministerial":false},{"question":"ما فرق الطور Φ بين الفولطية والتيار بدائرة مقاومة صرفة؟","answer":"0° — بمقاومة صرفة، V وI يبلغان الذروة ويصفران بنفس اللحظة تماماً، أي Φ=0.","type":"سؤال","ministerial":false},{"question":"لماذا تتحول كل القدرة بمقاومة صرفة إلى حرارة، بعكس المحث أو المتسعة؟","answer":"لأن V وI بطور واحد فحاصل ضربهما (القدرة) موجب دائماً بلا أي جزء يُختزن ويُعاد — بما أن الإشارة متطابقة دائماً (Φ=0)، فحاصل الضرب p=vi موجب بكل لحظة، فكل الطاقة تُستهلك حرارة.","type":"سؤال","ministerial":false},{"question":"القدرة اللحظية بمقاومة صرفة تتذبذب بضعف تردد الفولطية نفسها. إذا كان تردد الشبكة 50Hz، فبأي تردد تتذبذب القدرة؟","answer":"100 Hz — لأن p(t)∝sin²(ωt) وترددها ضعف تردد v وi، فتكون 2×50=100Hz.","type":"سؤال","ministerial":false},{"question":"محث صرف L=0.5H بدائرة ترددها f=100Hz. جد رادة الحث X_L (خذ π≈3.14).","answer":"314 Ω — X_L = 2πfL = 2×3.14×100×0.5 = 314 Ω.","type":"سؤال","ministerial":false},{"question":"بدائرة محث صرف، الفولطية V_L بالنسبة للتيار I_L:","answer":"تتقدّم عليه بزاوية 90° — V_L = V_m sin(ωt+90°)، أي الفولطية تسبق التيار بربع دورة.","type":"سؤال","ministerial":false},{"question":"محث رادته X_L=40Ω مربوط بمصدر فولطيته المؤثرة 20V. جد التيار المؤثر.","answer":"0.5 A — I_eff = V_eff/X_L = 20/40 = 0.5 A.","type":"سؤال","ministerial":false},{"question":"عند مضاعفة تردد مصدر مربوط بمحث صرف (مع بقاء L ثابتاً)، ماذا يحدث لرادة الحث X_L؟","answer":"تتضاعف — X_L=2πfL تتناسب طردياً مع f، فمضاعفة f تضاعف X_L.","type":"سؤال","ministerial":false},{"question":"لماذا يُستعمل المحث (لا المقاومة) لتحديد تيار أنبوب الفلورسنت؟","answer":"لأنه يحدّ التيار دون تبديد أي طاقة حرارية (قدرته المتوسطة تساوي صفراً) — المحث الصرف يحدّ التيار بلا تبديد أي طاقة حرارية (Φ=90°⟹P_av=0)، بعكس المقاومة التي تهدر جزءاً كبيراً حرارة.","type":"سؤال","ministerial":false},{"question":"متسعة C=20μF بدائرة ترددها f=1000Hz. جد رادة السعة X_C تقريباً.","answer":"≈8 Ω — X_C = 1/(2πfC) = 1/(2π×1000×20×10⁻⁶) ≈ 8 Ω.","type":"سؤال","ministerial":false},{"question":"بدائرة متسعة صرفة، التيار I_C بالنسبة للفولطية V_C:","answer":"يتقدّم عليها بزاوية 90° — I_C = I_m sin(ωt+90°)، أي التيار يسبق الفولطية بربع دورة — عكس المحث.","type":"سؤال","ministerial":false},{"question":"عند تيار مستمر تماماً (f=0)، كيف تتصرف المتسعة بالدائرة؟","answer":"كمفتاح مفتوح — تحجب المرور تماماً — X_C=1/(2πfC)→∞ عند f=0، أي معارضة كاملة (مفتاح مفتوح) للتيار المستمر.","type":"سؤال","ministerial":false},{"question":"عند مضاعفة تردد مصدر مربوط بمتسعة صرفة (مع بقاء C ثابتة)، ماذا يحدث لرادة السعة X_C؟","answer":"تنخفض للنصف — X_C=1/(2πfC) تتناسب عكسياً مع f، فمضاعفة f تخفّض X_C للنصف.","type":"سؤال","ministerial":false},{"question":"متسعة C=50μF بدائرة ترددها f=200Hz (فتكون X_C≈15.9Ω) وفولطيتها المؤثرة V_eff≈15.9V. جد التيار المؤثر تقريباً.","answer":"≈1 A — I_eff = V_eff/X_C ≈ 15.9/15.9 ≈ 1 A.","type":"سؤال","ministerial":false},{"question":"دائرة توالية R=9Ω، X_L=25Ω، X_C=13Ω. جد الممانعة الكلية Z.","answer":"15 Ω — Z = √(R²+(X_L−X_C)²) = √(9²+12²) = √(81+144) = √225 = 15 Ω.","type":"سؤال","ministerial":false},{"question":"بنفس الدائرة أعلاه (X_L=25Ω > X_C=13Ω)، نوع الدائرة:","answer":"حثّية — بما أن X_L أكبر من X_C، فالدائرة حثّية الخواص وΦ موجبة.","type":"سؤال","ministerial":false},{"question":"دائرة توالية RLC ممانعتها Z=13Ω ومقاومتها R=5Ω. جد مقدار |X_L−X_C|.","answer":"12 Ω — 13² = 5² + d² ⟹ d² = 169−25 = 144 ⟹ d = 12 Ω.","type":"سؤال","ministerial":false},{"question":"متى تكون الدائرة المتوالية RLC 'أومية الخواص' تماماً (Φ=0)؟","answer":"عندما X_L = X_C (حالة الرنين) — عند X_L=X_C تُلغي الرادتان بعضهما فتصبح Z=R وΦ=0 — هذه بالضبط حالة الرنين.","type":"سؤال","ministerial":false},{"question":"دائرة توالية R=8Ω وZ=17Ω. جد زاوية فرق الطور Φ تقريباً.","answer":"≈62° — cos Φ = R/Z = 8/17 ≈ 0.47 ⟹ Φ ≈ 62°.","type":"سؤال","ministerial":false},{"question":"دائرة توالية RLC مقاومتها R=12Ω وممانعتها Z=20Ω. جد عامل القدرة pf.","answer":"0.6 — pf = R/Z = 12/20 = 0.6.","type":"سؤال","ministerial":false},{"question":"دائرة تيارها المؤثر I=3A وفولطيتها الكلية V_T=50V وعامل قدرتها 0.8. جد القدرة الحقيقية P_real.","answer":"120 W — P_real = I V_T cosΦ = 3×50×0.8 = 120 W.","type":"سؤال","ministerial":false},{"question":"بنفس الدائرة أعلاه (I=3A، V_T=50V)، جد القدرة الظاهرية P_app.","answer":"150 V·A — P_app = I × V_T = 3×50 = 150 V·A (بلا اعتبار لعامل القدرة).","type":"سؤال","ministerial":false},{"question":"لماذا تُقاس القدرة الظاهرية بوحدة فولت-أمبير (V·A) لا واط (W)؟","answer":"لتمييزها عن القدرة الحقيقية المستهلكة فعلاً، فهي لا تمثّل استهلاكاً فعلياً كاملاً للطاقة — القدرة الظاهرية I×V لا تراعي فرق الطور، فقد يكون جزء كبير منها متردداً بلا استهلاك فعلي — لذا تُميَّز بوحدة مختلفة.","type":"سؤال","ministerial":false},{"question":"أي دائرة تملك أعلى عامل قدرة ممكن (pf=1)؟","answer":"دائرة مقاومة صرفة (R فقط) — بمقاومة صرفة Φ=0 وpf=cos0°=1 — أعلى عامل قدرة ممكن فيزيائياً.","type":"سؤال","ministerial":false},{"question":"دائرة رنين محثها L=0.5H ومتسعتها C=2μF. جد التردد الرنيني f_r تقريباً.","answer":"≈159 Hz — f_r = 1/(2π√(LC)) = 1/(2π√(0.5×2×10⁻⁶)) = 1/(2π×0.001) ≈ 159 Hz.","type":"سؤال","ministerial":false},{"question":"عند الرنين بدائرة RLC متوالية، ما مقدار عامل القدرة؟","answer":"1 — عند الرنين Z=R وΦ=0، فpf=cos0°=1 بغض النظر عن قيمة R نفسها.","type":"سؤال","ministerial":false},{"question":"دائرة رنين R=5Ω، L=0.1H، C=40μF. جد عامل النوعية Q_f.","answer":"10 — Q_f = (1/R)√(L/C) = (1/5)√(0.1/40×10⁻⁶) = (1/5)×50 = 10.","type":"سؤال","ministerial":false},{"question":"ماذا يحدث لعرض قمة الرنين (نطاق التردد Δf) عند زيادة المقاومة R؟","answer":"يزداد (تصبح القمة أعرض وأقل حدّة، وQ_f ينخفض) — Δω=R/L يزداد طردياً مع R، فتتّسع قمة الرنين ويقلّ عامل النوعية Q_f=ω_r/Δω.","type":"سؤال","ministerial":false},{"question":"دائرة رنين مقاومتها R صغيرة جداً تقترب من الصفر. ماذا يحدث لتيار الرنين تحديداً (I_max=V/R)؟","answer":"يصبح كبيراً جداً — عند الرنين I_max=V/R، فكلما صغرت R اقترب المقام من الصفر فكبر التيار جداً.","type":"سؤال","ministerial":false},{"question":"دائرة توازي: I_R=6A، I_L=8A، I_C=8A. جد التيار الرئيس I_T.","answer":"6 A — I_T = √(I_R²+(I_C−I_L)²) = √(6²+0²) = 6 A (لأن I_C=I_L فيلغي أحدهما الآخر).","type":"سؤال","ministerial":false},{"question":"بنفس الدائرة أعلاه (I_L=I_C بالضبط)، ما خواص الدائرة؟","answer":"أومية صرفة تقريباً (حالة قريبة من الرنين) — عندما يتساوى I_L مع I_C يُلغي أحدهما الآخر تماماً، فتتصرف الدائرة كأنها مقاومة صرفة — أقرب حالة للرنين بالتوازي.","type":"سؤال","ministerial":false},{"question":"دائرة توازي V=100V، I_R=5A، I_L=15A، I_C=3A. جد التيار الرئيس I_T.","answer":"13 A — I_T = √(5²+(3−15)²) = √(25+144) = √169 = 13 A.","type":"سؤال","ministerial":false},{"question":"بنفس الدائرة أعلاه، جد الممانعة الكلية Z.","answer":"≈7.7 Ω — Z = V/I_T = 100/13 ≈ 7.7 Ω.","type":"سؤال","ministerial":false},{"question":"بدائرة توازي RLC، إذا كان I_C أكبر من I_L، فالدائرة:","answer":"سعوية الخواص — بالتوازي: I_C>I_L ⟹ الدائرة سعوية (عكس اتجاه المقارنة بالتوالي حيث تُقارن X_L بـX_C مباشرة).","type":"سؤال","ministerial":false},{"question":"أي من العناصر الثلاثة (R، L، C) هو الوحيد الذي يستهلك طاقة فعلياً وبشكل دائم بدائرة تيار متناوب؟","answer":"R (المقاومة) فقط — المحث والمتسعة يختزنان الطاقة ويعيدانها (P_av=0)، بينما المقاومة وحدها تحوّلها حرارة بشكل دائم.","type":"سؤال","ministerial":false},{"question":"بدائرة RLC متوالية عند تردد أقل من التردد الرنيني (f<f_r)، أيّهما أكبر: X_L أم X_C؟","answer":"X_C أكبر (الدائرة سعوية تحت الرنين) — X_L=2πfL يصغر مع صغر f، وX_C=1/(2πfC) يكبر مع صغر f، فتحت الرنين تكون X_C>X_L حتماً — دائرة سعوية.","type":"سؤال","ministerial":false},{"question":"ما وحدة قياس الرادة (X_L أو X_C) والممانعة Z؟","answer":"أوم (Ω) — نفس وحدة المقاومة تماماً — الرادة والممانعة كلاهما نوع من المعارضة الكهربائية، ويُقاسان بالأوم كالمقاومة تماماً رغم اختلاف طبيعتهما الفيزيائية.","type":"سؤال","ministerial":false},{"question":"بالمخطط المرفق (الضلع الشاقولي متّجه لأسفل، أي X_C أكبر من X_L)، ما مقدار الممانعة Z؟","answer":"13 Ω — Z = √(R²+(X_C−X_L)²) = √(5²+12²) = √(25+144) = √169 = 13 Ω.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، تمهيدي 2020) مصدر فولطية متناوبة رُبط بينه وبين مقاومة صرفة R=100Ω، والفولطية V_R=424.2 sin(200πt). ما المقدار المؤثر للتيار؟","answer":"3 A — V_eff=V_m/√2=424.2/1.414≈300V، ثم I_eff=V_eff/R=300/100=3A.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثالث 2019) علّل: القدرة المتبدّدة بتيار متناوب أعظمه I_m لا تساوي قدرة تيار مستمر بنفس المقدار I_m.","answer":"لأن المتناوب لا يبقى عند I_m إلا لحظة واحدة كل ربع دورة، فمتوسط قدرته ½I_m²R أصغر من قدرة المستمر I_m²R — متوسط قدرة المتناوب ½I_m²R يكافئ مستمراً بمقدار I_eff=I_m/√2 فقط، وهو أصغر من I_m.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثاني 2020) ما مميزات منحني القدرة المتوسطة بدائرة تحتوي محث صرف فقط؟","answer":"أجزاء موجبة وسالبة متساوية المساحة، فمجموعها صفر (لا تبديد طاقة) — بمحث أو متسعة صرفة (Φ=90°) تتساوى مساحتا الجزء الموجب والسالب من منحني القدرة، فمتوسطها صفر تماماً.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثالث 2022) دائرة توالية R=40Ω، X_L=120Ω، X_C=90Ω، فولطيتها V_T=240V. جد تيار الدائرة I.","answer":"4.8 A — Z=√(40²+30²)=√2500=50Ω، ثم I=V_T/Z=240/50=4.8A.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثاني 2021) ملف رُبط بمصدر V_T=100V فمرّ به تيار I=5A بزاوية طور Φ=37° (cos37°=0.8). جد مقاومة الملف R.","answer":"16 Ω — Z=V_T/I=100/5=20Ω، ثم R=Z×cosΦ=20×0.8=16Ω.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثالث 2019) دائرة رنين متوالية R=3Ω، L=0.04H، C=25μF، فولطيتها 75V. جد التيار عند الرنين.","answer":"25 A — عند الرنين Z=R=3Ω، فالتيار I=V/Z=75/3=25A.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، تمهيدي 2017) دائرة توازي فرق جهدها 240V، وتياراتها I_C=8A، I_L=12A، I_R=3A. جد التيار الرئيس I_T.","answer":"5 A — I_T=√(I_R²+(I_C−I_L)²)=√(3²+(8−12)²)=√(9+16)=√25=5A.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثاني 2020) أيّ الحالات التالية تجعل زاوية فرق الطور Φ تساوي صفراً بدائرة RLC متوالية الربط؟","answer":"حالة الرنين، حيث X_L=X_C فتُلغي إحداهما الأخرى — عند الرنين X_L=X_C فتصبح Z=R وtanΦ=(X_L−X_C)/R=0 ⟹ Φ=0.","type":"سؤال","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":1,"lesson_title":"مقدمة","order_index":1,"hook":"ينفجر نجمٌ بعيد بصوتٍ هائل وضوءٍ ساطع. يصلنا ضوؤه عبر الفضاء بعد سنوات، لكن لا يصلنا صوته أبداً مهما انتظرنا. لماذا؟ لأن الصوت موجة ميكانيكية تحتاج جزيئات مادة تهتزّ لتنتقل خلالها، والفضاء بين النجوم فراغٌ شبه تام — فيموت الصوت عند مصدره. أمّا الضوء فموجة كهرومغناطيسية تحمل مجاليها معها ولا تحتاج وسطاً إطلاقاً، فتعبر الفراغ بسهولة. لهذا الفضاء \"صامت\" لكنه مضيء.","concepts":[{"term":"هل تعلم؟","text":"الضوء المرئي وموجة الراديو وأشعة الشمس فوق البنفسجية وأشعة X بالمستشفى — كلها الشيء نفسه فيزيائياً: موجات كهرومغناطيسية، لا تختلف إلا بالتردد. عينك ببساطة \"هوائي\" ضُبط ليكشف شريحة ضيقة منها فقط.","ministerial":false}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"يصلنا ضوء الشمس والنجوم البعيدة عبر الفراغ التام، بينما لا يصلنا أي صوت من الفضاء مهما كان مصدره قوياً.","answer":"لأن الضوء موجة كهرومغناطيسية تحمل مجاليها الكهربائي والمغناطيسي معها أثناء انتشارها، فلا تحتاج وسطاً مادياً إطلاقاً وتنتشر بسهولة بالفراغ. أما الصوت فموجة ميكانيكية تحتاج جزيئات مادة (هواء مثلاً) تهتزّ لتنقل الاضطراب من نقطة لأخرى، والفضاء بين الأجرام فراغٌ شبه تام تقريباً — فيموت الصوت عند مصدره مباشرة.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🌈 مختبر الطيف الكهرومغناطيسي"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":2,"lesson_title":"ماكسويل والنظرية الكهرومغناطيسية","order_index":2,"hook":"لم يكتشف ماكسويل الموجة الكهرومغناطيسية بتجربة معملية — بل استنتج وجودها الحتمي من معادلاته الرياضية البحتة فقط، قبل أن يرصدها هرتز فعلياً بعد سنوات من وفاته. نادراً ما تتنبأ الرياضيات بظاهرة فيزيائية كاملة قبل أن يراها أحد بهذه الدقة.","concepts":[{"term":"انتبه:","text":"بيّن ماكسويل أن المجال المغناطيسي لا ينشأ فقط من تيار التوصيل الاعتيادي (شحنات متحركة بسلك)، بل أيضاً من مجال كهربائي متغيّر مع الزمن — حتى بلا أي سلك أو شحنة متحركة حقيقية بينهما (كما بين لوحَي متسعة تُشحَن).","ministerial":false}],"laws":[{"name":"تيار الإزاحة (مكافئ المجال الكهربائي المتغيّر)","formula":"I_d ∝ ΔE/Δt","variables_note":""}],"notes":[{"heading":"⭐ حقائق ماكسويل الأربع","items":["① الشحنة الساكنة تولّد حولها مجالاً كهربائياً ثابتاً.","② لا يوجد قطب مغناطيسي منفرد (خطوط المجال المغناطيسي مغلقة).","③ المجال الكهربائي المتغيّر مع الزمن يولّد حوله مجالاً مغناطيسياً متغيّراً، عمودياً عليه ومتّفقاً معه بالطور.","④ المجال المغناطيسي المتغيّر مع الزمن يولّد حوله مجالاً كهربائياً متغيّراً، عمودياً عليه ومتّفقاً معه بالطور."],"ministerial":false},{"heading":"⭐ الخصائص الخمس","items":["① تنتشر بالفراغ بخطوط مستقيمة، وتنعكس وتنكسر وتتداخل وتحيد وتستقطب.","② تتألف من مجالين كهربائي ومغناطيسي متعامدين ومتغيّرين مع الزمن، متعامدين مع خط انتشار الموجة، ويتذبذبان بالطور نفسه.","③ هي موجات مستعرضة.","④ تنتشر بالفراغ بسرعة الضوء، وتقلّ سرعتها بالأوساط المادية.","⑤ تحمل طاقة تتوزّع بالتساوي بين مجاليها الكهربائي والمغناطيسي."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ما أهم خصائص الموجات الكهرومغناطيسية؟","answer":"① تنتشر بالفراغ بخطوط مستقيمة، وتنعكس وتنكسر وتتداخل وتحيد وتستقطب. ② تتألف من مجالين كهربائي ومغناطيسي متعامدين ومتغيّرين مع الزمن، عموديين على اتجاه الانتشار، ويتذبذبان بالطور نفسه. ③ موجات مستعرضة. ④ تنتشر بالفراغ بسرعة الضوء، وتقلّ سرعتها بالأوساط المادية. ⑤ تحمل طاقة موزّعة بالتساوي بين مجاليها.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌊 مختبر الموجة الكهرومغناطيسية المستعرضة"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":3,"lesson_title":"توليد الموجات الكهرومغناطيسية من الشحنات المعجلة","order_index":3,"hook":"بطارية موصولة بسلك مستقيم لا تُشِعّ أي موجة كهرومغناطيسية مهما بقيت موصولة طويلاً، وسلك يمرّ به تيار ثابت لا يُشِعّ شيئاً أيضاً. لكن اهزّ نفس الشحنات ذهاباً وإياباً بسرعة — فجأة يبدأ السلك بالإشعاع! الفرق الوحيد: التعجيل.","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"لا تُشعّ الشحنة الساكنة ولا الشحنة المتحركة بسرعة ثابتة أي موجة كهرومغناطيسية، بعكس الشحنة المتذبذبة (المعجّلة).","answer":"لأن إشعاع الموجة الكهرومغناطيسية يتطلّب مجالين متغيّرين مع الزمن يولّد كل منهما الآخر (وفق حقيقتَي ماكسويل الثالثة والرابعة). الشحنة الساكنة تولّد مجالاً كهربائياً ثابتاً فقط (لا مغناطيسي إطلاقاً)، والشحنة المتحركة بسرعة ثابتة تولّد مجالين كهربائياً ومغناطيسياً لكن ثابتَين (غير متغيّرين بالزمن عند نقطة معيّنة بإطار مرجعي ثابت). أما الشحنة المعجَّلة فوحدها تجعل المجالين يتغيّران باستمرار مع الزمن، فيتجدّد كل منهما الآخر وينطلقان بعيداً كموجة.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"⚡ مختبر القطب الثنائي المتذبذب"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":4,"lesson_title":"مبادئ الإرسال والتسلم للموجات الكهرومغناطيسية","order_index":4,"hook":"افتح أي جهاز راديو أو جوال قديم وستجد بداخله، وسط كل التعقيد الإلكتروني، جزأين لا غنى عنهما: دائرة تولّد أو تلتقط التردد المطلوب بالضبط، وهوائي يشعّ الموجة أو يلتقطها من الفضاء. كل الإرسال والاستقبال اللاسلكي بالعالم يقوم على هذين الجزأين فقط.","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"اذكر الأجزاء الأساسية لجهاز إرسال الموجات الكهرومغناطيسية.","answer":"① دائرة الاهتزاز الكهرومغناطيسي: تحتوي ملفاً ومتسعة متغيرة السعة، وتولّد موجات الإشارة الكهربائية، ويُتحكَّم بترددها بتغيير سعة المتسعة. ② الهوائي: سلك معدني حرّ (أو موصل بالأرض) يُشِعّ الموجات الكهرومغناطيسية إلى الفضاء.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"📡 مخطط: رحلة الإشارة من جهاز الإرسال إلى جهاز التسلم"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":5,"lesson_title":"كيفية عمل دائرة الإرسال والتسلم","order_index":5,"hook":"حين تدير قرص \"الدوزان\" براديو، أنت فعلياً تغيّر سعة متسعة متغيرة بدائرة اهتزاز. عند سعة معيّنة يصير التردد الرنيني لدائرتك مساوياً تردد محطة واحدة، فتُضخَّم إشارتها بينما تبقى بقية المحطات مهملة — بالضبط نفس فكرة الرنين اللي تعلّمتها بفصل التيار المتناوب، لكن هنا تُستعمَل لاختيار موجة من الفضاء لا لتضخيم تيار بدائرة.","concepts":[],"laws":[{"name":"التردد الرنيني لدائرة الاهتزاز · وطول الموجة المقابل","formula":"f_r = 1 / (2π√(LC))  ،  λ = c/f  ،  c = 3×10⁸ m/s","variables_note":""},{"name":"طول الهوائي المناسب لتردد معيّن","formula":"ℓ = λ/2  (غير مؤرَّض)   ،   ℓ = λ/4  (مؤرَّض)","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"ضُبطت دائرة موالفة بجهاز راديو محطة إذاعية إذ كانت قيمة المحاثة 6.4 µH وقيمة السعة 1.9 pF. جد: ① التردد الذي يلتقطه الجهاز. ② طول موجته.","givens":"المعطيات: L=6.4 µH=6.4×10⁻⁶ H — C=1.9 pF=1.9×10⁻¹² F","solution_steps":["الخطوة ١: نعوّض بقانون التردد الرنيني: f_r = 1/(2π√(6.4×10⁻⁶ × 1.9×10⁻¹²)) ≈ 45.64×10⁶ Hz = 45.64 MHz","الخطوة ٢: نوجد طول الموجة المقابل: λ = c/f_r = (3×10⁸)/(45.64×10⁶) ≈ 6.57 m 💡 جرّب هذي القيم بالضبط بالمحاكاة تحت (L=6.4، C=1.9) وتحقّق من تطابق القراءة."],"ministerial":false},{"problem":"يُراد استعمال هوائي نصف موجة لإرسال إشارة تردّدها 200 MHz. احسب طول الهوائي المناسب.","givens":"المعطيات: f=200 MHz=200×10⁶ Hz","solution_steps":["الخطوة ١: نوجد طول الموجة: λ = c/f = (3×10⁸)/(200×10⁶) = 1.5 m","الخطوة ٢: نصف طول الموجة: ℓ = λ/2 = 1.5/2 = 0.75 m = 75 cm 💡 ولو أُرِّض الهوائي لكفى ربع الموجة فقط: ℓ=λ/4=37.5cm — أنسب عملياً لأنه أقصر."],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🎛️ مختبر الموالفة: من L وC إلى طول الهوائي"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":6,"lesson_title":"الكشف عن الموجات الكهرومغناطيسية ذات التردد الراديوي","order_index":6,"hook":"لهذا بالضبط تختلف أشكال الهوائيات: هوائي التلفاز القديم سلك مستقيم طويل، بينما هوائي بعض أجهزة الراديو المحمولة حلقة أو ملف ملفوف. كل شكل مصمّم ليتفاعل مع أحد مجالَي الموجة القادمة بأقصى كفاءة.","concepts":[{"term":"الكشف بوساطة المجال الكهربائي (هوائي مستقيم):","text":"المجال الكهربائي E للموجة القادمة يكون موازياً لطول الهوائي المستقيم (ثنائي القطب)، فيدفع الإلكترونات الحرة بالمعدن للتذبذب صعوداً ونزولاً بطول السلك بتردد الموجة نفسه، فيتولّد فرق جهد متردد يُضخَّم ويُعالَج.","ministerial":false},{"term":"الكشف بوساطة المجال المغناطيسي (هوائي حلقي):","text":"المجال المغناطيسي المتغيّر B للموجة القادمة يخترق مساحة الهوائي الحلقي، فبقانون فاراداي (تتذكره من فصل الحث الكهرومغناطيسي: ε=−N ΔΦ/Δt) يُحتث بالحلقة تيار متردد يحمل المعلومة نفسها.","ministerial":false}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[],"has_simulation":true,"simulation_title":"📡 مختبر الكشف: هوائي مستقيم مقابل هوائي حلقي"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":7,"lesson_title":"التضمين — AM وFM وPM","order_index":7,"hook":"فكّر بالأمر كسيارة بريد: صوتك (المعلومة) لا يقدر يقطع مسافات طويلة بنفسه، فتحمّله على \"شاحنة\" سريعة (الموجة الحاملة عالية التردد) توصله لوجهته. بالمحطة النهائية (جهاز الاستقبال) تُفرَّغ الشاحنة من حمولتها فيعود صوتك كما كان. السؤال: كيف بالضبط \"نحمّل\" الصوت على الموجة الحاملة؟ ثلاث طرائق ممكنة.","concepts":[{"term":"انتبه:","text":"يوجد أيضاً التضمين الرقمي (digital) الذي يحوّل المعلومة إلى نبضات، ويقلّل تأثير التشويش الخارجي فيرفع دقّة الإرسال والتسلم — وهو أساس الاتصالات الحديثة (الإنترنت، الجوال).","ministerial":false},{"term":"هل تعلم؟","text":"راديو FM أنقى صوتاً من AM لأن المعلومة فيه محمولة بالتردد لا بالسعة، والتشويش الجوي (كالبرق) يغيّر السعة لا التردد — فلا يكاد يؤثّر بـFM بينما يشوّش AM بوضوح.","ministerial":false}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"ما المقصود بالتضمين السعوي؟","answer":"هو نوع من التضمين التماثلي نغيّر فيه سعة (مقدار) الموجة الحاملة ذات التردد العالي كدالة خطية وفق تردد الإشارة (المعلومة) المحمولة، مع بقاء تردد الموجة الحاملة ثابتاً.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"📡 مختبر التضمين: AM مقابل FM"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":8,"lesson_title":"مدى الموجات الراديوية","order_index":8,"hook":"حين تسمع \"AM\" و\"FM\" براديو سيارتك، أنت فعلياً تتنقل بين منطقتين ترددّيتين مختلفتين كلياً بالطيف الراديوي — لكل منهما مدى تردد محدد ورمز عالمي معروف. لماذا حُدِّدت هذه المناطق بالضبط؟","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"📶 مدى الموجات الراديوية","ministerial":false,"headers":["المنطقة","الرمز","مدى التردد","أهم الاستعمالات"],"rows":[["منخفضة جداً","VLF","3–30 kHz","الملاحة البحرية"],["منخفضة","LF","30–300 kHz","الملاحة"],["متوسطة","MF","300 kHz–3 MHz","البث الإذاعي المتوسط (AM)"],["عالية","HF","3–30 MHz","الطائرات والاتصال بين السفن"],["عالية جداً","VHF","30–300 MHz","التلفاز والإرسال FM وأنظمة الشرطة"]]}],"examples":[],"qa":[],"has_simulation":true,"simulation_title":"📶 مختبر محدِّد المنطقة الترددية"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":9,"lesson_title":"انتشار الموجات الكهرومغناطيسية","order_index":9,"hook":"بالليل تقدر تلتقط محطات راديو AM بعيدة جداً (من دول أخرى أحياناً)، بينما نهاراً تختفي تماماً. السرّ بطبقات الأيونوسفير: نهاراً تتكوّن طبقة واطئة تمتصّ الموجات السماوية فلا تبتعد. ليلاً تختفي هذه الطبقة، فتنعكس الموجات عن طبقة أعلى وأبعد وترتدّ للأرض على مسافات هائلة — أحياناً عبر قارّات. الغلاف الجوي نفسه يعمل \"مرآة\" تظهر بعد الغروب فقط.","concepts":[{"term":"ثوابت الفراغ:","text":"ε₀=8.854×10⁻¹² F/m و μ₀=4π×10⁻⁷ H/m. بالتعويض ينتج c=3×10⁸ m/s — سرعة الضوء بالضبط. وتقلّ السرعة بأي وسط مادي (لأن εμ للوسط أكبر من ε₀μ₀ الفراغ).","ministerial":false}],"laws":[{"name":"سرعة الموجة بوسط · وسرعة الضوء بالفراغ","formula":"v = 1/√(εμ)  ،  c = 1/√(μ₀ε₀) = 3×10⁸ m/s","variables_note":""}],"notes":[],"tables":[],"examples":[],"qa":[{"question":"علامَ يعتمد مقدار سرعة انتشار الموجات الكهرومغناطيسية بالأوساط المختلفة؟","answer":"يعتمد على خاصّتين للوسط الذي تنتشر خلاله: السماحية الكهربائية ε والنفاذية المغناطيسية μ، وفق العلاقة v=1/√(εμ). فكلّما كبرت εμ للوسط قلّت سرعة الموجة فيه، وتبلغ السرعة أعظمها (c) بالفراغ.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🛰️ مختبر مسار الموجة الراديوية"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":10,"lesson_title":"بعض تطبيقات الموجات الكهرومغناطيسية","order_index":10,"hook":"في الحرب العالمية الثانية، بنت بريطانيا سلسلة محطات رادار على سواحلها. كانت ترسل موجات راديوية فترتدّ عن الطائرات المعادية القادمة، فيكشف زمن الارتداد بُعدها واتجاهها قبل أن تُرى بالعين. هذا الإنذار المبكر مكّن حفنة قليلة من الطائرات المدافعة من الوصول بالوقت المناسب، فرجّح كفّة \"معركة بريطانيا\". فكرة فيزيائية بسيطة — قياس زمن ذهاب موجة وإيابها — قلبت موازين حرب.","concepts":[{"term":"الاستعمالات:","text":"المساحة والجيولوجيا والزراعة (رصد صحة المحاصيل عبر الأشعة تحت الحمراء المنعكسة عن النبات، والتنبؤ بالجفاف قبل أن تراه العين) والأرصاد الجوية والتطبيقات العسكرية.","ministerial":false}],"laws":[{"name":"بُعد الهدف من زمن الذهاب والإياب (رحلة كاملة بسرعة الضوء c)","formula":"d = c × t / 2","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"أرسل رادار نبضة راديوية استغرقت 200 μs لترتدّ عن طائرة وتعود إليه. جد بُعد الطائرة عن الرادار.","givens":"المعطيات: t=200 μs=200×10⁻⁶ s (زمن الذهاب والإياب معاً) — c=3×10⁸ m/s","solution_steps":["الخطوة ١: المسافة الكلية المقطوعة (ذهاباً وإياباً): d_كلي = c × t = 3×10⁸ × 200×10⁻⁶ = 60000 m = 60 km","الخطوة ٢: بُعد الطائرة الفعلي (نصف المسافة الكلية، لأن الموجة قطعت المسافة مرتين): d = d_كلي/2 = 60/2 = 30 km 💡 هذا بالضبط سرّ الرادار: قياس زمن قصير جداً (بالميكروثانية) يكفي لحساب مسافات كبيرة، لأن سرعة الضوء هائلة."],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🛰️ استكشف التطبيقين"},{"chapter_number":"g6c4","chapter_title":"الموجات الكهرومغناطيسية","lesson_number":11,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":11,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"أي مما يلي يمثّل ترتيباً صحيحاً للطيف الكهرومغناطيسي من أطول طول موجي إلى أقصره؟","answer":"راديو ← مايكروويف ← مرئي ← فوق بنفسجية ← سينية — الطيف الكهرومغناطيسي مرتّب من أطول طول موجي (وأخفض تردد) إلى أقصره: راديو، مايكروويف، تحت الحمراء، مرئي، فوق بنفسجية، سينية/غاما.","type":"سؤال","ministerial":false},{"question":"كم عدد الحقائق التي بنى عليها ماكسويل نظريته الكهرومغناطيسية؟","answer":"أربع — بنى ماكسويل نظريته على أربع حقائق تربط المجالين الكهربائي والمغناطيسي.","type":"سؤال","ministerial":false},{"question":"وفق حقيقتَي ماكسويل الثالثة والرابعة، ما العلاقة الطورية بين المجال المتغيّر (سبب) والمجال الناتج عنه؟","answer":"يتّفقان بالطور (يبلغان الذروة ويصفران معاً) — تنصّ حقيقتا ماكسويل الثالثة والرابعة على أن المجال الناتج يكون متّفقاً بالطور مع المجال المتغيّر المسبِّب له.","type":"سؤال","ministerial":false},{"question":"تيار الإزاحة I_d الذي قدّمه ماكسويل يتناسب طردياً مع:","answer":"معدّل تغيّر المجال الكهربائي مع الزمن (ΔE/Δt) — I_d ∝ ΔE/Δt — تيار الإزاحة يتناسب مع معدّل التغيّر الزمني للمجال الكهربائي، لا مع مقداره المطلق.","type":"سؤال","ministerial":false},{"question":"أي مما يلي ليس من خصائص الموجة الكهرومغناطيسية الخمس؟","answer":"تحتاج وسطاً مادياً لتنتقل خلاله — على العكس تماماً — من أهم خصائصها أنها لا تحتاج وسطاً مادياً إطلاقاً، وتنتقل بالفراغ التام بسرعة الضوء.","type":"سؤال","ministerial":false},{"question":"لماذا تُوصف الموجة الكهرومغناطيسية بأنها مستعرضة لا طولية؟","answer":"لأن مجالَيها E وB يتذبذبان عموديين على اتجاه انتشار الموجة — الموجة المستعرضة تتذبذب عمودياً على اتجاه انتشارها، وهذا حال E وB بالضبط بالموجة الكهرومغناطيسية.","type":"سؤال","ministerial":false},{"question":"أي شحنة تُشِعّ موجة كهرومغناطيسية؟","answer":"الشحنة المعجَّلة (المتذبذبة) فقط — الشحنة المعجَّلة (المتذبذبة) وحدها تولّد مجالين متغيّرين مع الزمن يولّد كل منهما الآخر، فتنطلق موجة.","type":"سؤال","ministerial":false},{"question":"بأي جهاز عملي نولّد الموجات الكهرومغناطيسية من شحنات معجَّلة؟","answer":"مولّد ذبذبات موصول بساقين معدنيتين (ثنائي قطب كهربائي) — مولّد الذبذبات الموصول بثنائي قطب كهربائي (ساقين معدنيتين) يجعل الشحنات تتذبذب صعوداً ونزولاً بتردده، فتُشِعّ موجات.","type":"سؤال","ministerial":false},{"question":"بأي قانون يُحسب التردد الرنيني لدائرة اهتزاز (L وC) بجهاز الإرسال أو الاستقبال؟","answer":"f_r = 1/(2π√(LC)) — نفس علاقة الرنين المتوالي من فصل التيار المتناوب: f_r=1/(2π√(LC)).","type":"سؤال","ministerial":false},{"question":"دائرة موالفة محاثتها L=4μH وسعتها C=9pF. جد تردّدها الرنيني تقريباً.","answer":"≈26.5 MHz — LC=4×10⁻⁶×9×10⁻¹²=3.6×10⁻¹⁷، و√(LC)=6×10⁻⁹ s. f_r=1/(2π×6×10⁻⁹)≈2.65×10⁷ Hz=26.5 MHz.","type":"سؤال","ministerial":false},{"question":"إذا ضُوعفت سعة C لدائرة الاهتزاز (وبقيت L ثابتة)، ماذا يحدث للتردد الرنيني f_r؟","answer":"يقلّ بمعامل 1/√2 — f_r=1/(2π√(LC))، فمضاعفة C تضاعف الجذر √(LC) بمعامل √2، فيقلّ f_r بمعامل 1/√2 ≈ 0.707 من قيمته الأصلية.","type":"سؤال","ministerial":false},{"question":"محطة إذاعية تبثّ بتردد 150 MHz. ما طول موجتها؟","answer":"2 m — λ=c/f=(3×10⁸)/(150×10⁶)=2 m.","type":"سؤال","ministerial":false},{"question":"ما أفضل طول لهوائي غير مؤرَّض يبثّ إشارة طول موجتها 4 m؟","answer":"2 m — ℓ=λ/2=4/2=2 m.","type":"سؤال","ministerial":false},{"question":"لماذا يُفضَّل تأريض الهوائي عملياً (وصل طرفه بالأرض)؟","answer":"لأن الأرض تُكمِّل كهربائياً نصف الطول الناقص، فيكفي هوائي بطول ربع الموجة فقط بدل نصفها (أقصر وأعملي) — الهوائي المؤرَّض يكفيه طول ربع الموجة ℓ=λ/4 (الأرض تُكمِّل النصف الآخر كهربائياً)، فيكون أقصر وأنسب عملياً من الهوائي غير المؤرَّض (ℓ=λ/2).","type":"سؤال","ministerial":false},{"question":"ما مكوّنا دائرة الإرسال الأساسيان؟","answer":"دائرة اهتزاز كهرومغناطيسي (ملف ومتسعة متغيرة) تولّد الموجة، وهوائي يشعّها للفضاء — دائرة الإرسال: دائرة اهتزاز (L وC متغيرة) تولّد الموجة بالتردد المطلوب، وهوائي يشعّها للفضاء.","type":"سؤال","ministerial":false},{"question":"كيف يكتشف الهوائي المستقيم (ثنائي القطب) المعلومة من موجة واردة؟","answer":"المجال الكهربائي E للموجة (الموازي لطول الهوائي) يدفع إلكترونات المعدن للتذبذب بتردد الموجة، فيتولّد فرق جهد متردد — المجال الكهربائي الموازي لطول الهوائي المستقيم يدفع الإلكترونات الحرة للتذبذب بتردد الموجة، فيتولّد فرق جهد متردد يحمل المعلومة.","type":"سؤال","ministerial":false},{"question":"ما المقصود بالتضمين بشكل عام؟","answer":"تحميل إشارة المعلومة (منخفضة التردد) على موجة حاملة عالية التردد — التضمين هو تحميل إشارة المعلومة ذات التردد الواطئ على الموجة الحاملة ذات التردد العالي لتُبثّ بكفاءة.","type":"سؤال","ministerial":false},{"question":"في التضمين السعوي AM، ماذا يبقى ثابتاً؟","answer":"تردد الموجة الحاملة — بـAM تتغيّر السعة وفق إشارة المعلومة، بينما يبقى تردد الموجة الحاملة ثابتاً بلا تغيير.","type":"سؤال","ministerial":false},{"question":"في التضمين الترددي FM، ماذا يبقى ثابتاً؟","answer":"سعة الموجة الحاملة — بـFM يتغيّر التردد وفق سعة إشارة المعلومة، بينما تبقى سعة الموجة الحاملة ثابتة.","type":"سؤال","ministerial":false},{"question":"ما الذي يتغيّر بالتضمين الطوري PM؟","answer":"طور الموجة الحاملة، وفق سعة إشارة المعلومة — PM = Phase Modulation: يتغيّر طور الموجة الحاملة وفق سعة إشارة المعلومة.","type":"سؤال","ministerial":false},{"question":"لماذا يكون بث الراديو FM عادة أقل تأثراً بالتشويش الجوي (كالبرق) من AM؟","answer":"لأن معلومة FM محمولة بالتردد لا بالسعة، والتشويش الجوي يغيّر السعة أساساً — التشويش كالبرق يؤثر أساساً بسعة الإشارة الملتقطة. بما أن معلومة FM محمولة بالتردد لا بالسعة، فلا يكاد التشويش يؤثر بها، بعكس AM.","type":"سؤال","ministerial":false},{"question":"ما ميزة التضمين الرقمي على التماثلي؟","answer":"يحوّل المعلومة إلى نبضات فيقلّل تأثير التشويش الخارجي ويرفع دقّة الإرسال والتسلم — التضمين الرقمي يحوّل المعلومة لنبضات منفصلة، فيقلّل تأثير التشويش الخارجي مقارنة بالإشارة التماثلية المستمرة.","type":"سؤال","ministerial":false},{"question":"أي منطقة ترددية (رمزها) تُستعمل بالبث الإذاعي المتوسط AM؟","answer":"MF (300kHz–3MHz) — منطقة MF (300kHz–3MHz) هي المخصصة للبث الإذاعي المتوسط AM.","type":"سؤال","ministerial":false},{"question":"أي منطقة ترددية تُستعمل بإرسال FM والتلفاز وأنظمة الشرطة؟","answer":"VHF (30–300MHz) — منطقة VHF (30–300MHz) هي المخصصة للتلفاز وإرسال FM وأنظمة الشرطة.","type":"سؤال","ministerial":false},{"question":"علامَ يعتمد مقدار سرعة انتشار الموجة الكهرومغناطيسية بوسط مادي؟","answer":"على السماحية الكهربائية ε والنفاذية المغناطيسية μ للوسط (v=1/√(εμ)) — v=1/√(εμ). كلما كبرت εμ للوسط قلّت سرعة الموجة فيه، وتبلغ أعظمها c بالفراغ.","type":"سؤال","ministerial":false},{"question":"ما قيمة سرعة الضوء بالفراغ التي ينتج عنها التعويض c=1/√(μ₀ε₀)؟","answer":"3×10⁸ m/s — بالتعويض بثوابت الفراغ ε₀ وμ₀ بالعلاقة c=1/√(μ₀ε₀) ينتج c=3×10⁸ m/s بالضبط.","type":"سؤال","ministerial":false},{"question":"ما الذي يميّز الموجة الأرضية عن غيرها من طرائق الانتشار؟","answer":"تنتقل قريباً من سطح الأرض وتنحني مع انحنائه، فمداها محدود نسبياً — الموجة الأرضية (530kHz–2MHz) تتبع انحناء سطح الأرض، لكن هذا الانحناء نفسه يحدّ من مداها بعد مسافة معيّنة.","type":"سؤال","ministerial":false},{"question":"ما الذي يميّز الموجة السماوية؟","answer":"تنعكس عن طبقات الأيونوسفير فتصل مسافات بعيدة، وترددها 3–30MHz — الموجة السماوية (3–30MHz) تنعكس عن طبقات الأيونوسفير، فتصل مسافات بعيدة جداً، ويتّسع مداها ليلاً بغياب الطبقة الماصّة D.","type":"سؤال","ministerial":false},{"question":"ما الذي يميّز الموجة الفضائية، ولماذا تحتاج أقماراً صناعية؟","answer":"ترددها أكبر من 30MHz، تنتشر بخط مستقيم وتخترق الأيونوسفير بدل الانعكاس عنه، فتحتاج أقماراً كمعيدات للاتصال بمسافات بعيدة — الموجة الفضائية (>30MHz) تخترق الأيونوسفير بدل الانعكاس عنه وتنتشر بخط بصري مستقيم، فتحتاج أقماراً صناعية تُعيد بثّها لمسافات بعيدة (بين القارّات مثلاً).","type":"سؤال","ministerial":false},{"question":"لماذا يتّسع مدى استقبال محطات AM البعيدة ليلاً مقارنة بالنهار؟","answer":"لأن الطبقة الواطئة الماصّة (D) بالأيونوسفير تختفي ليلاً، فتنعكس الموجات عن الطبقة العليا (F) وتصل مسافات أبعد — نهاراً تمتصّ طبقة D الموجات السماوية فيقلّ مداها؛ ليلاً تختفي هذه الطبقة فتنعكس الموجات عن طبقة F الأعلى وترتدّ لمسافات أبعد بكثير — أحياناً عبر قارّات.","type":"سؤال","ministerial":false},{"question":"ماذا يعني اختصار RADAR؟","answer":"Radio Detection And Ranging — الكشف وتحديد البُعد بوساطة الموجات الراديوية — RADAR اختصار Radio Detection And Ranging: الكشف وتحديد البُعد بوساطة الموجات الراديوية.","type":"سؤال","ministerial":false},{"question":"رادار أرسل نبضة استغرقت 600 μs لترتدّ عن هدف وتعود. جد بُعد الهدف (c=3×10⁸ m/s).","answer":"90 km — d = c×t/2 = (3×10⁸ × 600×10⁻⁶)/2 = 180000/2 = 90000 m = 90 km.","type":"سؤال","ministerial":false},{"question":"هدفٌ يبعد 45 km عن رادار. كم يستغرق الزمن الكلي (ذهاباً وإياباً) لنبضة الرادار لترتدّ عنه وتعود؟","answer":"300 μs — t = 2d/c = (2×45000)/(3×10⁸) = 90000/(3×10⁸) = 3×10⁻⁴ s = 300 μs.","type":"سؤال","ministerial":false},{"question":"ما الفرق الجوهري بين الصور النشطة وغير النشطة بالاستشعار عن بُعد؟","answer":"النشطة: القمر مصدر الإشعاع نفسه (يرسل الموجة ويحلّل ارتدادها)؛ غير النشطة: تعتمد على إشعاع صادر أو منعكس من الهدف نفسه فقط — بالصور النشطة يُصدر القمر موجته الخاصة ويحلّل ارتدادها (كالرادار)؛ بغير النشطة يعتمد على إشعاع الهدف نفسه (كضوء الشمس المنعكس) دون أن يُصدر القمر شيئاً.","type":"سؤال","ministerial":false},{"question":"أي المجالات التالية تستفيد من الاستشعار عن بُعد؟","answer":"المساحة، الجيولوجيا، الزراعة، الأرصاد الجوية، والتطبيقات العسكرية — يُستعمل الاستشعار عن بُعد بالمساحة والجيولوجيا والزراعة (رصد صحة المحاصيل) والأرصاد الجوية والتطبيقات العسكرية.","type":"سؤال","ministerial":false},{"question":"لماذا يكفي قياس زمن قصير جداً (بالميكروثانية) ليحسب الرادار مسافات كبيرة (بالكيلومترات)؟","answer":"لأن سرعة الضوء c هائلة (3×10⁸ m/s)، فمسافات كبيرة جداً تقابلها أزمنة قصيرة جداً فقط — بما أن d=ct/2 وc كبيرة جداً (3×10⁸ m/s)، فحتى أزمنة قصيرة جداً (ميكروثانية) تقابل مسافات كبيرة بالكيلومترات — هذا سرّ دقة الرادار العملية.","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":1,"lesson_title":"مقدمة في البصريات الفيزيائية","order_index":1,"hook":"أثبتّ بفصل الموجات الكهرومغناطيسية أن الضوء موجة كهرومغناطيسية مستعرضة. في هذا الفصل ستشاهد الدليل التجريبي المباشر على ذلك: أربع ظواهر لا تحدث إلا للموجات ولا يمكن لأي نموذج جسيمي أن يفسّرها.","concepts":[{"term":"🌊 التداخل (Interference)","text":"تراكب موجتين ضوئيتين متشاكهتين فينتج تقوية (بناء) أو إلغاء (إتلاف) — يظهر في تجربة يونك والأغشية الرقيقة.","ministerial":false},{"term":"🔦 الحيود (Diffraction)","text":"انحراف الضوء عن مساره المستقيم عند مروره بحافة أو شق ضيق — أساس عمل محزز الحيود.","ministerial":false},{"term":"🕶️ الاستقطاب (Polarization)","text":"تقييد اهتزاز المجال الكهربائي باتجاه واحد — دليل قاطع أن الضوء موجة مستعرضة لا طولية.","ministerial":false},{"term":"🌇 الاستطارة (Scattering)","text":"إعادة بثّ الضوء بكل الاتجاهات من دقائق صغيرة — تفسّر لماذا السماء زرقاء والغروب أحمر.","ministerial":false}],"laws":[],"notes":[{"heading":"لماذا هذا الترتيب؟","items":["التداخل والحيود ظاهرتان تثبتان أن الضوء موجة بشكل عام (يمكن لأي موجة، طولية أو مستعرضة، أن تتداخل وتحيد).","أما الاستقطاب فيثبت أمراً أدق: أن الضوء موجة مستعرضة تحديداً (كموجات الماء والحبل، لا كالصوت).","والاستطارة تطبيق عملي جميل يفسّر مشهداً تراه كل يوم: لون السماء."],"ministerial":false}],"tables":[],"examples":[],"qa":[],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":2,"lesson_title":"تداخل الموجات الضوئية","order_index":2,"hook":"ألوان فقاعة الصابون، وبريق قرص الـCD، وأنماط الضوء خلف ستارة رقيقة — كلها من تراكب موجات الضوء. لكن لماذا لا نرى هذه الأنماط من مصباحَي غرفتنا؟ السرّ كله في كلمة واحدة: التشاكه. افهمها أولاً، وسيصبح الفصل كله تحصيل حاصل.","concepts":[{"term":"➕ تداخل بناء","text":"الموجتان بالطور نفسه: قمة تركب قمة، فتتقوّى كلٌّ منهما بالأخرى — سعة الناتج = ضعف سعة أيٍّ منهما.","ministerial":false},{"term":"➖ تداخل إتلاف","text":"الموجتان بطورين متعاكسين: قمة تركب قعراً فيمحو أحدهما الآخر — سعة الناتج = صفر.","ministerial":false}],"laws":[{"name":"شرط التداخل البناء","formula":"Δℓ = mλ","variables_note":"m = 0, 1, 2, 3, …"},{"name":"شرط التداخل الإتلافي","formula":"Δℓ = (m + ½)λ","variables_note":"m = 0, 1, 2, …"}],"notes":[{"heading":"شروط التداخل المستديم (الدائم على الشاشة):","items":["أن تكون الموجتان متشاكهتين — أي ① متساويتين بالتردد ② متساويتين أو متقاربتين بالسعة ③ فرق الطور بينهما ثابت لا يتغيّر بالزمن — وأن يهتزّا بمستوٍ واحد ووسط واحد ويتجها نحو نقطة واحدة في آنٍ واحد."],"ministerial":false},{"heading":"احفظ المنطق لا الصيغة:","items":["فرق مسار = أعداد صحيحة من λ (0, λ, 2λ, …) ⟸ وصول متوافق الطور ⟸ بناء.","وفرق مسار = أعداد فردية من أنصاف λ (λ/2, 3λ/2, …) ⟸ وصول متعاكس الطور ⟸ إتلاف."],"ministerial":false}],"tables":[],"examples":[{"problem":"مصدران متشاكهان يبعثان موجات λ = 0.1 m، وتتداخل عند نقطة P. ما نوع التداخل عندما تقطع إحدى الموجتين مساراً 3.2 m والأخرى: ① 3 m ② 3.05 m ③ 2.95 m؟","givens":"","solution_steps":["① Δℓ = 3.2 − 3 = 0.2 m = 2λ ⟹ عدد صحيح من λ ⟹ تداخل بناء (m = 2).","② Δℓ = 3.2 − 3.05 = 0.15 m = 1.5λ = (1+½)λ ⟹ تداخل إتلاف.","③ Δℓ = 3.2 − 2.95 = 0.25 m = 2.5λ = (2+½)λ ⟹ تداخل إتلاف. 💡 هذا النمط نفسه ورد وزارياً (الدور الأول 2022) بمعطيات مسارين 3.2 m و2.5 m ⟹ Δℓ = 0.7 m = 7λ ⟹ تداخل بناء."],"ministerial":true}],"qa":[{"question":"مصدران ضوئيان غير متشاكهين لا يعطيان نمط تداخل مستقراً على الشاشة.","answer":"لأن كل مصدر يبعث موجات بأطوار عشوائية متغيّرة بسرعة فائقة، فلا يمكن الحصول على فرق طور ثابت بين الموجتين عند أي نقطة. يحصل التداخل البناء والإتلاف فعلاً، لكن بالتعاقب وبسرعة كبيرة لا تدركها العين، فتشاهد العين إضاءة مستديمة (بسبب دوام الإبصار) ولا يظهر نمط تداخل ثابت.","type":"علل","ministerial":true},{"question":"ما المقصود بتداخل الضوء؟ وما شروط الحصول على تداخل مستديم؟","answer":"تداخل الضوء: ظاهرة إعادة توزيع الطاقة الضوئية الناشئة عن تراكب موجات ضوئية متشاكهة. شروط التداخل المستديم: ① تساوي الموجتين بالتردد، وتساويهما أو تقاربهما بالسعة، وثبوت فرق الطور بينهما ② اهتزازهما بمستوٍ واحد ووسط واحد واتجاههما نحو نقطة واحدة بآنٍ واحد.","type":"وزاري","ministerial":true},{"question":"اختيارات وزارية متكررة عن شروط التداخل.","answer":"① فرق مسار بصري = أعداد فردية من أنصاف λ ⟸ تداخل إتلاف. ② لحصول تداخل مستديم يجب أن يكون المصدران متشاكهين. ③ نمط التداخل بشكل عام يتولّد نتيجة حيود وتداخل موجات الضوء معاً عند مرورها بفتحات ضيقة.","type":"وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":3,"lesson_title":"تجربة شقي يونك","order_index":3,"hook":"","concepts":[],"laws":[{"name":"هُدب مضيئة (بناء)","formula":"d sinθ = mλ","variables_note":""},{"name":"هُدب معتمة (إتلاف)","formula":"d sinθ = (m+½)λ","variables_note":""},{"name":"فاصلة الهُدب (البعد بين مركزي هدبين متتاليين من النوع نفسه)","formula":"Δy = λL/d","variables_note":""}],"notes":[{"heading":"تذكّر (وزاري متكرر):","items":["تزداد فاصلة الهدب Δy: ① بازدياد بعد الشاشة L (طردية) ② بنقصان البعد بين الشقين d (عكسية) ③ بازدياد الطول الموجي λ (طردية).","والهداب المركزي بالضوء الأبيض أبيض (فرق المسار = صفر لكل الألوان)، وعلى جانبيه أطياف يتدرّج كلٌّ منها من البنفسجي (الأقرب للمركز) إلى الأحمر."],"ministerial":true},{"heading":"","items":["كل مسائل يونك الوزارية تدور على قانونين: موقع هدب y_m = (λL/d)m وفاصلة الهدب Δy = λL/d.","اقرأ السؤال وحدّد: هل المعطى بُعد هدب ذي مرتبة (y_m) أم بُعد بين هدبين متتاليين (Δy)؟","ثم اعزل المجهول.","وانتبه للوحدات: mm ⟵ 10⁻³ m، وnm ⟵ 10⁻⁹ m."],"ministerial":true}],"tables":[],"examples":[{"problem":"البعد بين شقي يونك 0.2 mm وبعد الشاشة عنهما 1 m، وبعد الهدب الثالث المضيء عن المركزي 9.49 mm. احسب طول موجة الضوء. (ورد وزارياً حرفياً — تمهيدي 2020)","givens":"","solution_steps":["القانون: y_m = (λL/d)m ⟹ λ = y_m·d/(mL)","التعويض: λ = (9.49×10⁻³ × 0.2×10⁻³)/(3×1) = 633×10⁻⁹ m = 633 nm (ضوء ليزر الهيليوم-نيون الأحمر الشهير). 💡 نظير وزاري (الدور الثالث 2023): d=4×10⁻⁴m، L=2m، y₃=6mm ⟹ λ = 400 nm."],"ministerial":true},{"problem":"شاشة على بُعد 4.5 m من حاجز ذي شقين تباعدهما 0.1 mm، وكانت الفاصلة بين الهداب المركزي والهدب ذي المرتبة m=2 تساوي 4.5 cm. احسب λ، وكم تصبح فاصلة الهدب عند استخدام ضوء 625 nm؟ (د2 2020 ومثله د1 2023)","givens":"","solution_steps":["الخطوة 1: المعطى هنا موقع هدب ذي مرتبة: y₂=(λL/d)×2 ⟹ λ = y₂d/(2L) = (4.5×10⁻²×0.1×10⁻³)/(2×4.5) = 5×10⁻⁷ m = 500 nm.","الخطوة 2: عند λ′=625nm: Δy′ = λ′L/d = (625×10⁻⁹×4.5)/(0.1×10⁻³) ≈ 2.81 cm. 💡 الفاصلة كبرت لأن الطول الموجي أكبر — تتناسب معه طردياً."],"ministerial":false}],"qa":[{"question":"سبب ظهور هُدب مضيئة وهُدب مظلمة بتجربة شقي يونك.","answer":"حيود وتداخل موجات الضوء معاً: تحيد الموجات عند مرورها بالشقين الضيقين (فيصيران مصدرين متشاكهين)، ثم تتداخل الموجتان المنبعثتان: بناءً حيث فرق المسار أعداد صحيحة من λ (هدب مضيء)، وإتلافاً حيث أعداد فردية من أنصافها (هدب مظلم). ملاحظة: عبارة «حيود موجات الضوء فقط» الشائعة بصيغة صح/خطأ (2020د2) خاطئة — الصحيح: حيود وتداخل معاً.","type":"وزاري","ministerial":true},{"question":"لو أُجريت تجربة يونك تحت سطح الماء، كيف يتأثر طراز التداخل؟","answer":"يقلّ الطول الموجي داخل الماء (λ_n = λ/n، ومعامل انكسار الماء n أكبر من 1)، وبما أن فاصلة الهدب Δy = λ_nL/d تتناسب طردياً مع الطول الموجي، فإن فاصلة الهدب تقلّ وتتقارب الهدب من بعضها (يبقى الترتيب نفسه لكن النمط ينكمش).","type":"وزاري — الأكثر تكراراً","ministerial":true},{"question":"أثبت أن فاصلة الهدب تُعطى بالعلاقة Δy = λL/d.","answer":"موقع الهدب المضيء ذي المرتبة m: y_m = (λL/d)m، وموقع التالي: y_(m+1) = (λL/d)(m+1). وفاصلة الهدب: Δy = y_(m+1) − y_m = (λL/d)(m+1) − (λL/d)m = (λL/d)(m+1−m) ⟹ Δy = λL/d.","type":"وزاري","ministerial":true},{"question":"كيف تتغيّر فاصلة الهدب بتغيّر L، d، λ كلٍّ على حدة؟","answer":"من Δy = λL/d: ① تزداد الفاصلة بازدياد L (تناسب طردي) ② تقلّ بازدياد d (تناسب عكسي) ③ تزداد بازدياد λ (تناسب طردي).","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌈 مختبر تجربة يونك لشقّي التداخل"},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":4,"lesson_title":"التداخل في الأغشية الرقيقة","order_index":4,"hook":"بقعة الزيت وفقاعة الصابون شفافتان بلا لون، ومع ذلك تتوهجان بألوان الطيف! السبب تداخل بين موجتي ضوء انعكستا عن سطحَي غشاء رقيق.","concepts":[{"term":"① سمك الغشاء","text":"الموجة المنعكسة عن الخلفي تقطع زيادة على المنعكسة عن الأمامي مساراً بصرياً = ضعف السمك البصري (2nt).","ministerial":false},{"term":"② انقلاب الطور","text":"الموجة المنعكسة عن الأمامي يحصل لها انقلاب طور مقداره π rad (180°)، أما المنعكسة عن الخلفي فلا تنقلب.","ministerial":false}],"laws":[{"name":"تداخل بناء (غشاء مضيء)","formula":"nt = 1·λ/4, 3·λ/4, 5·λ/4, …","variables_note":"أرباع فردية من λ"},{"name":"تداخل إتلاف (غشاء مظلم)","formula":"nt = 0, 2·λ/4, 4·λ/4, …","variables_note":"أرباع زوجية من λ"}],"notes":[{"heading":"","items":["تذكّر: طول موجة الضوء داخل وسط معامل انكساره n هو λ_n = λ/n."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"الموجات المنعكسة عن السطح الأمامي للغشاء الرقيق يحصل لها انقلاب طور مقداره π rad.","answer":"لأن كل موجة تنعكس عن وسط معامل انكساره أكبر من معامل انكسار الوسط الذي قدمت منه يحصل لها انقلاب طور مقداره 180° (π rad) — والموجة الساقطة من الهواء تنعكس عن الغشاء الذي معامل انكساره أكبر من الهواء.","type":"علل","ministerial":true},{"question":"علامَ يعتمد نوع التداخل بالأغشية الرقيقة؟ وكم السمك البصري اللازم للبناء وللإتلاف؟","answer":"يعتمد على: ① سمك الغشاء (تقطع المنعكسة عن الخلفي زيادة 2nt) ② انقلاب الطور (تنقلب المنعكسة عن الأمامي بمقدار π). للبناء: nt = أعداد فردية من λ/4 (1×λ/4, 3×λ/4, …). للإتلاف: nt = أعداد زوجية من λ/4 (0, 2×λ/4, …).","type":"وزاري","ministerial":true},{"question":"تُعزى ألوان فقاعات الصابون وأغشية الزيت الرقيقة إلى ظاهرة:","answer":"التداخل: يختلف سمك الغشاء من موضع لآخر، فيتحقق شرط البناء لطول موجي (لون) مختلف عند كل موضع، فنرى ألوان الطيف الشمسي متوزّعة على الغشاء.","type":"وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":5,"lesson_title":"حيود موجات الضوء","order_index":5,"hook":"","concepts":[],"laws":[{"name":"هُدب معتمة (شق واحد)","formula":"ℓ sinθ = mλ","variables_note":"m = ±1, ±2, …"},{"name":"هُدب مضيئة (شق واحد)","formula":"ℓ sinθ = (m+½)λ","variables_note":""}],"notes":[{"heading":"","items":["ℓ هنا عرض الشق (لا تخلطه مع d بُعد الشقين بيونك!).","لاحظ الانعكاس الطريف: بالشق الواحد شرط mλ يعطي معتماً، بعكس يونك حيث يعطي مضيئاً."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ما التغيّر بعرض المنطقة المركزية المضيئة لنمط حيود شق واحد عندما يضيق الشق أكثر؟","answer":"من شرط أول معتم ℓ sinθ=λ: كلما ضاق عرض الشق ℓ كبر sinθ فكبرت زاوية الحيود θ التي يقع عندها أول معتم — أي يزداد عرض المنطقة المركزية المضيئة (ينتشر النمط ويتوسّع).","type":"وزاري","ministerial":true},{"question":"شرط تكوّن الهدب المضيء الأول (غير المركزي) لشق واحد يكون عندما يساوي عرض الشق:","answer":"شرط الهدب المضيء: ℓ sinθ=(m+½)λ، وللأول (m=1): ℓ sinθ = (3/2)λ ⟹ ℓ = 3λ/(2sinθ).","type":"وزاري","ministerial":true},{"question":"اشرح نشاطاً يوضّح حيود الضوء.","answer":"الأدوات: لوح زجاج مطلي بدهان أسود، دبوس (لعمل شق دقيق برأسه)، مصدر ضوئي أحادي اللون. الخطوات: نعمل شقاً رفيعاً بالدهان الأسود، وننظر من خلاله إلى المصدر. المشاهدة: منطقة وسطى عريضة شديدة الإضاءة تتخللها مناطق معتمة، وهُدب مضيئة تقلّ شدّتها بالابتعاد عن المركز. الاستنتاج: ظهور هذه المناطق يدلّ أن الضوء يحيد عن مساره المستقيم عند مروره بالشق الضيق.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌈 مختبر حيود الشق المفرد"},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":6,"lesson_title":"مُحزّز الحيود","order_index":6,"hook":"","concepts":[],"laws":[{"name":"ثابت المحزز (المسافة بين حزّين متتاليين)","formula":"d = W/N","variables_note":"W: عرض المحزز، N: عدد الحزوز"},{"name":"شرط الهُدب المضيئة للمحزز","formula":"d sinθ = mλ","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"ضوء ليزر هيليوم-نيون λ=632.8nm يسقط عمودياً على محزز حيود يحوي السنتمتر منه 6000 خط. جد زاويتَي الحيود للمرتبتين الأولى والثانية (sin21.3°=0.3796، sin49°=0.7592).","givens":"","solution_steps":["ثابت المحزز: d = W/N = 1cm/6000 = 1.667×10⁻⁴ cm","المرتبة الأولى (m=1): sinθ₁ = λ/d = 632.8×10⁻⁷/1.667×10⁻⁴ = 0.3796 ⟹ θ₁ = 21.3°","المرتبة الثانية (m=2): sinθ₂ = 2λ/d = 0.7592 ⟹ θ₂ = 49° 💡 لاحظ: sinθ₂ = 2×sinθ₁ دوماً بالمحزز (الزوايا لا تتضاعف، لكن جيوبها تتضاعف) — هذه الفكرة وحدها حلّت وزاري 2020د1."],"ministerial":true}],"qa":[{"question":"فائدة محزز الحيود، وهل الهدب المركزي بالضوء الأبيض طيف مستمر؟","answer":"① فائدته: دراسة الأطياف وتحليل مصادر الضوء وقياس الطول الموجي (بجهاز المطياف). ② العبارة (الهدب المركزي طيف مستمر بالضوء الأبيض) خاطئة — الصحيح: الهدب المركزي أبيض (كل الألوان تصله بفرق مسار صفر)، والأطياف المستمرة تظهر بالمراتب الجانبية. (لو سقط ضوء أخضر لظهر الهدب المركزي أخضر.)","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌈 مختبر محزز الحيود"},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":7,"lesson_title":"استقطاب الضوء","order_index":7,"hook":"الموجة الطولية (كالصوت) تهتزّ باتجاه انتشارها نفسه، فلا معنى «لتصفية» اتجاه اهتزازها. أما المستعرضة فتهتزّ عمودياً على الانتشار في اتجاهات كثيرة ممكنة — ويمكن حجب بعضها وإنفاذ بعض. فإذا نجحنا في «تصفية» الضوء فهو مستعرض حتماً.","concepts":[{"term":"🌟 ضوء غير مستقطب","text":"يهتزّ مجاله الكهربائي بالاتجاهات جميعها (عشوائياً)، بمستويات متوازية عمودية على خط الانتشار.","ministerial":false},{"term":"⬆️ ضوء مستقطب","text":"يتذبذب مجاله الكهربائي باتجاه واحد فقط عمودي على خط الانتشار. الشريحة المُنجزة لذلك: المستقطب، والفاحصة الثانية: المحلّل.","ministerial":false},{"term":"① الامتصاص الانتقائي","text":"موادّ قطبية (كالبولارويد) تُصنع بسلاسل هيدروكاربونية متراصفة تكوّن محوراً بصرياً: تُنفذ الموجات التي يهتزّ مجالها عمودياً على المحور، وتمتصّ الباقي. وثمة موادّ نشطة بصرياً (بلورة الكوارتز، سائل التربنتين، محلول السكر) تُدوّر مستوى الاستقطاب بزاوية تسمى زاوية الدوران البصري — تعتمد على نوع المادة وسمكها وتركيزها وطول موجة الضوء.","ministerial":false},{"term":"② الاستقطاب بالانعكاس","text":"اكتشف العالِم مالوس أن الضوء المنعكس عن سطوح عاكسة (مرآة، ماء، زجاج) يكون مستقطباً جزئياً بمستوٍ موازٍ للسطح. تزداد درجة الاستقطاب بزيادة زاوية السقوط حتى تصل استقطاباً كلياً عند زاوية بروستر θp، حيث يتعامد الشعاعان المنعكس والمنكسر (90°).","ministerial":false}],"laws":[{"name":"قانون بروستر","formula":"tan θp = n","variables_note":""}],"notes":[{"heading":"","items":["بلورة التورمالين تترتّب جزيئاتها بسلاسل طويلة، فلا تُنفذ إلا الموجات التي يهتزّ مجالها الكهربائي عمودياً على خط السلسلة (موازياً محور النفاذ)، وتمتصّ الباقي."],"ministerial":false}],"tables":[],"examples":[{"problem":"سقطت حزمة ضوئية على سطح عاكس بزوايا سقوط مختلفة، وتبيّن أن الشعاع المنعكس صار مستقطباً كلياً عند زاوية سقوط 48°. احسب معامل انكسار الوسط (tan48°=1.110). (مسألة الكتاب س٣)","givens":"","solution_steps":["استقطاب كلي بالانعكاس ⟹ زاوية السقوط = زاوية بروستر: θp = 48°.","من قانون بروستر: n = tan θp = tan 48° = 1.110."],"ministerial":false}],"qa":[{"question":"اشرح نشاطاً يوضّح استقطاب موجات الضوء.","answer":"الأدوات: شريحتا تورمالين، مصدر ضوئي. الخطوات: ① نضع شريحة تورمالين بطريق الضوء وندوّرها حول محورها — لا يتغيّر مقدار الضوء النافذ. ② نضع شريحتين، نثبّت إحداهما وندوّر الأخرى ببطء — تتناقص شدة الضوء النافذ حتى تنعدم تماماً (تعامد المحورين) ثم تعود. الاستنتاج: الضوء النافذ من الشريحة الأولى استُقطب (صار اهتزاز مجاله الكهربائي باتجاه واحد)، وهذا يثبت أن موجات الضوء مستعرضة.","type":"وزاري","ministerial":true},{"question":"الموجات الطولية لا يمكنها إظهار:","answer":"الاستقطاب — لأن اهتزاز الموجة الطولية باتجاه انتشارها نفسه، فليس لها مستويات اهتزاز متعددة يمكن حجب بعضها وإنفاذ بعض. الاستقطاب خاصية حصرية للموجات المستعرضة.","type":"وزاري","ministerial":true},{"question":"كيف نحصل على ضوء مستقطب من ضوء غير مستقطب؟ وكيف يحصل الاستقطاب بالانعكاس؟","answer":"بإزالة معظم الموجات ما عدا التي يتذبذب مجالها بمستوٍ واحد، بطريقتين: ① الامتصاص الانتقائي (بولارويد/تورمالين): تُنفذ الموجات الموازية لمحورها البصري وتمتصّ الباقي. ② الانعكاس: إسقاط الضوء على سطح عاكس بزاوية بروستر θp (يتعامد عندها المنعكس والمنكسر)، فيكون المنعكس مستقطباً كلياً بمستوٍ موازٍ للسطح.","type":"وزاري","ministerial":true},{"question":"ما المقصود بـ«المواد النشطة بصرياً»؟ وعلامَ تعتمد زاوية الدوران البصري؟","answer":"موادّ (كبلورة الكوارتز وسائل التربنتين ومحلول السكر) لها القابلية على تدوير مستوى استقطاب الضوء المارّ خلالها بزاوية تسمى زاوية الدوران البصري، وتعتمد هذه الزاوية على: ① نوع المادة ② سمكها ③ تركيز المحلول ④ طول موجة الضوء.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🕶️ مختبر الاستقطاب (قانون مالوس)"},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":8,"lesson_title":"استطارة الضوء","order_index":8,"hook":"","concepts":[],"laws":[{"name":"شدة الضوء المستطار","formula":"شدة الاستطارة ∝ 1/λ⁴","variables_note":""}],"notes":[{"heading":"","items":["الأطوال الموجية القصيرة (البنفسجي والأزرق) تُستطار أكثر بكثير من الطويلة (الأحمر) — البنفسجي يُستطار نحو عشرة أضعاف الأحمر تقريباً.","لذا نرى السماء نهاراً زرقاء (استطارة الأزرق)، وعند الشروق والغروب نرى الأحمر والبرتقالي (الأقل استطارة، يصلنا مباشرة بعد أن يتشتّت الأزرق بالطريق الطويل عبر الغلاف الجوي)."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ظهور قرص الشمس بلون أحمر عند شروقها وغروبها.","answer":"ضوء الشمس عند الشروق والغروب يقطع مسافة أطول بالغلاف الجوي، فتُستطار الأطوال القصيرة (الأزرق والبنفسجي) بنسبة كبيرة وتتشتّت بعيداً عن خط النظر، بينما الأطوال الطويلة (الأحمر والبرتقالي) أقل استطارة (الشدة ∝ 1/λ⁴) فتصل العين مباشرة.","type":"علل","ministerial":true},{"question":"نهاراً يرى رائد الفضاء على سطح القمر السماء سوداء والنجوم بوضوح، بينما على الأرض تُرى السماء زرقاء بلا نجوم.","answer":"القمر لا غلاف جوي له، فلا توجد جزيئات تستطير ضوء الشمس، فلا يصل عين الرائد ضوء مستطار فتبدو السماء سوداء وتُرى النجوم بوضوح. أما على الأرض فجزيئات الغلاف الجوي تستطير الأطوال القصيرة (الزرقاء) بكل الاتجاهات فتبدو السماء زرقاء، وهذا الضوء الساطع يطغى على ضوء النجوم الخافت فلا تُرى نهاراً.","type":"علل","ministerial":true},{"question":"أي أطوال الضوء الأبيض يُستطار أكثر وأيها أقل؟ ولماذا؟","answer":"تعتمد شدة الاستطارة عكسياً على الأس الرابع للطول الموجي (1/λ⁴). لذا يُستطار البنفسجي (أقصر الأطوال) بالنسبة الأكبر، بينما يُستطار الأحمر (أطولها) بالنسبة الأقل.","type":"وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c5","chapter_title":"البصريات الفيزيائية","lesson_number":9,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":9,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"ما تعريف تداخل الضوء؟","answer":"إعادة توزيع الطاقة الضوئية الناشئة عن تراكب موجات ضوئية متشاكهة — تداخل الضوء: إعادة توزيع الطاقة الضوئية الناشئة عن تراكب سلسلتين أو أكثر من الموجات الضوئية المتشاكهة. (تمهيدي 2019 · تمهيدي 2021)","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، الأكثر تكراراً) لو أُجريت تجربة يونك تحت سطح الماء بدل الهواء، ماذا يحدث لفاصلة الهدب؟","answer":"تقلّ فتتقارب الهدب من بعضها — λ_n=λ/n أصغر داخل الماء، وΔy=λ_nL/d تتناسب طردياً مع λ، فتقلّ فاصلة الهدب. (2017د1 · 2018ت · 2019د3 · 2021ت وغيرها)","type":"سؤال","ministerial":true},{"question":"مصدران ضوئيان غير متشاكهين يُسقطان موجاتهما على شاشة. لماذا لا يظهر نمط تداخل مستقر؟","answer":"فرق الطور بينهما يتغيّر عشوائياً بسرعة فائقة فلا يثبت — المصدران غير المتشاكهين يبعثان أطواراً عشوائية متغيّرة بسرعة، فلا يتحقق شرط ثبات فرق الطور اللازم لتداخل مستديم. (تمهيدي 2017 · د1 2020 وغيرها)","type":"سؤال","ministerial":false},{"question":"(اختيار وزاري) فرق المسار البصري بين موجتين متشاكهتين متراكبتين يساوي أعداداً فردية من أنصاف الأطوال الموجية. أي تداخل يحصل؟","answer":"تداخل إتلاف — Δℓ=(m+½)λ شرط التداخل الإتلافي. (2020د1 · 2021ت)","type":"سؤال","ministerial":true},{"question":"سبب ظهور هدب مضيئة ومظلمة بتجربة شقي يونك هو:","answer":"حيود وتداخل موجات الضوء معاً — تحيد الموجات بالشقين فتصير مصدرين متشاكهين، ثم تتداخل بناءً وإتلافاً. عبارة «الحيود فقط» وردت بصح/خطأ (2020د2) وهي خاطئة.","type":"سؤال","ministerial":false},{"question":"أثبت أن فاصلة الهدب في تجربة يونك تُعطى بالعلاقة Δy=λL/d — ما الخطوة الأخيرة بهذا الإثبات؟","answer":"Δy = y_(m+1) − y_m = (λL/d)(m+1) − (λL/d)m = λL/d — طرح موقعي هدبين متتاليين ذوي مرتبتين m وm+1 يحذف m ويبقي λL/d. (د1 2022)","type":"سؤال","ministerial":false},{"question":"بتجربة يونك، البعد بين الشقين 0.2mm وبعد الشاشة 1m، وبعد الهدب الثالث المضيء عن المركزي 9.49mm. جد λ.","answer":"≈633 nm — λ=y₃d/(3L)=(9.49×10⁻³×0.2×10⁻³)/3=633×10⁻⁹m. (تمهيدي 2020 — ورد وزارياً حرفياً)","type":"سؤال","ministerial":false},{"question":"بضوء أخضر λ=5×10⁻⁷m، وتباعد شقين 1mm، وبعد شاشة 2m، فإن فاصلة الهدب:","answer":"1 mm — Δy=λL/d=(5×10⁻⁷×2)/(10⁻³)=10⁻³m=1mm. (تمهيدي 2022 — سؤال الكتاب س١/١٥)","type":"سؤال","ministerial":false},{"question":"كيف تتغيّر فاصلة الهدب بازدياد بعد الشاشة L مع ثبوت d وλ؟","answer":"تزداد طردياً — Δy=λL/d تتناسب طردياً مع L. (د2 2018 · تمهيدي 2020 · د1 2021 · تمهيدي 2022)","type":"سؤال","ministerial":false},{"question":"لماذا يحصل انقلاب طور مقداره π rad للموجة المنعكسة عن السطح الأمامي لغشاء رقيق؟","answer":"لأنها تنعكس عن وسط معامل انكساره أكبر من الوسط القادمة منه — الانعكاس عن وسط أعلى معامل انكسار يسبّب دوماً انقلاب طور 180°. (د1 2018 · د1 2024 · تمهيدي 2024)","type":"سؤال","ministerial":false},{"question":"للحصول على تداخل بناء (غشاء مضيء) بغشاء رقيق سمكه البصري nt، يجب أن يكون nt مساوياً:","answer":"أعداداً فردية من λ/4 — nt=1×λ/4, 3×λ/4, 5×λ/4… (أرباع فردية) يعطي تداخلاً بناءً. (تمهيدي 2018 · د1 2019 · د1 2020)","type":"سؤال","ministerial":false},{"question":"ألوان فقاعات الصابون وأغشية الزيت الرقيقة تُعزى إلى ظاهرة:","answer":"التداخل — تداخل موجات الضوء المنعكسة عن السطحين الأمامي والخلفي للغشاء، ويختلف السمك من موضع لآخر فتظهر ألوان مختلفة. (د1 2017 · تمهيدي 2020 · د2 2019)","type":"سؤال","ministerial":false},{"question":"ماذا يحدث لعرض المنطقة المركزية المضيئة بنمط حيود شق واحد عندما يضيق الشق أكثر؟","answer":"يزداد عرضها — من ℓsinθ=λ: كلما ضاق ℓ كبرت θ التي يقع عندها أول معتم، فيتوسّع النمط. (د1 2017 · تمهيدي 2019)","type":"سؤال","ministerial":false},{"question":"شرط تكوّن الهدب المضيء الأول (غير المركزي) بحيود شق واحد هو أن يساوي عرض الشق:","answer":"3λ/(2sinθ) — ℓsinθ=(m+½)λ وللأول m=1: ℓsinθ=(3/2)λ ⟹ ℓ=3λ/(2sinθ). (د2 2017 — سؤال الكتاب س١/١)","type":"سؤال","ministerial":false},{"question":"في حيود الضوء من شق واحد، شرط الهُدب المعتمة هو:","answer":"ℓ sinθ = mλ — لاحظ الانعكاس عن يونك: بالشق الواحد mλ يعطي معتماً لا مضيئاً.","type":"سؤال","ministerial":false},{"question":"ثابت المحزز d يُحسب من العلاقة:","answer":"d = W/N (عرض المحزز÷عدد الحزوز) — ثابت المحزز = عرض المحزز الكلي مقسوماً على عدد حزوزه.","type":"سؤال","ministerial":false},{"question":"ليزر هيليوم-نيون λ=632.8nm على محزز 6000 خط/سم. جد زاوية حيود المرتبة الأولى (sin21.3°=0.3796).","answer":"≈21.3° — d=1/6000cm=1.667×10⁻⁴cm. sinθ₁=λ/d=0.3796 ⟹ θ₁=21.3°. (مثال الكتاب)","type":"سؤال","ministerial":false},{"question":"محزز 2000 line/cm، جد زاوية حيود المرتبة الأولى للأحمر λ=640nm (sin7.5°=0.128).","answer":"7.5° — d=5×10⁻⁴cm. sinθ=λ/d=0.128 ⟹ θ=7.5°. (د2 2018 — مسألة الكتاب س٢)","type":"سؤال","ministerial":false},{"question":"الهدب المركزي بمحزز الحيود عند إضاءته بضوء أبيض يكون:","answer":"أبيض — كل الألوان تصل الهدب المركزي بفرق مسار صفر فيظهر أبيض؛ الأطياف المستمرة تظهر بالمراتب الجانبية فقط. (د2 2020 · تمهيدي 2020)","type":"سؤال","ministerial":false},{"question":"اشرح نشاطاً يوضّح استقطاب الضوء بشريحتي تورمالين — ماذا يحدث عند تعامد محوريهما؟","answer":"تنعدم شدة الضوء النافذ تقريباً — عند تعامد المحورين تمتصّ الشريحة الثانية كل الضوء النافذ من الأولى تقريباً، فتنعدم الشدة. (د1 2018 · د1 2024)","type":"سؤال","ministerial":false},{"question":"الموجات الطولية (كالصوت) لا يمكنها إظهار خاصية:","answer":"الاستقطاب — اهتزاز الموجة الطولية باتجاه انتشارها نفسه فلا مستويات اهتزاز متعددة تُحجب أو تُنفذ انتقائياً. (تمهيدي 2017 — سؤال الكتاب س١/١٣)","type":"سؤال","ministerial":false},{"question":"قانون بروستر لزاوية الاستقطاب الكلي بالانعكاس هو:","answer":"tan θp = n — عند زاوية بروستر يتعامد المنعكس والمنكسر، وينتج عن ذلك tanθp=n.","type":"سؤال","ministerial":false},{"question":"زاوية سقوط جعلت الشعاع المنعكس عن سطح مستقطباً كلياً كانت 48° (tan48°=1.110). جد معامل انكسار الوسط.","answer":"1.110 — n = tanθp = tan48° = 1.110. (مسألة الكتاب س٣)","type":"سؤال","ministerial":false},{"question":"زاوية الدوران البصري لمادة نشطة بصرياً (كمحلول السكر) تعتمد على:","answer":"نوع المادة وسمكها وتركيزها وطول موجة الضوء — أربعة عوامل معاً: نوع المادة، سمكها، تركيز المحلول، وطول موجة الضوء المارّ خلالها. (تمهيدي 2020 · د3 2020)","type":"سؤال","ministerial":false},{"question":"علّل: يظهر قرص الشمس أحمر عند الشروق والغروب.","answer":"الأطوال القصيرة تُستطار بعيداً عن خط النظر بعد مسار طويل بالغلاف الجوي، فيصل الأحمر (الأقل استطارة) مباشرة — الشدة∝1/λ⁴؛ فالأزرق والبنفسجي (أقصر طولاً) يُستطاران بنسبة أكبر بكثير على المسار الطويل عند الشروق/الغروب. (تمهيدي 2017 · د3 2017)","type":"سؤال","ministerial":false},{"question":"لماذا تبدو سماء القمر سوداء نهاراً بينما سماء الأرض زرقاء؟","answer":"القمر بلا غلاف جوي فلا استطارة، بينما غلاف الأرض يستطير الأزرق بكل الاتجاهات — بلا جزيئات هواء لا تحدث استطارة، فلا ضوء مستطار يصل عين الراصد على القمر — بعكس الأرض حيث الاستطارة الجوية تصبغ السماء زرقاء وتحجب ضوء النجوم الخافت. (د1 2018 · د3 2023 · د2 2018)","type":"سؤال","ministerial":false},{"question":"أي أطوال الضوء الأبيض يُستطار بأكبر نسبة؟","answer":"البنفسجي (أقصر الأطوال) — الشدة∝1/λ⁴، وλ البنفسجي أصغر أطوال الضوء المرئي فيُستطار أكثرها. (د2 2020 · د2 2023 · د2 2022)","type":"سؤال","ministerial":false},{"question":"الزاوية الحرجة لمادة معينة 34.4° (sin34.4°=0.565). جد زاوية بروستر لهذه المادة (tan60.5°=1.77).","answer":"60.5° — n=1/sinθc=1/0.565=1.77، ثم tanθp=n=1.77 ⟹ θp=60.5°.","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":1,"lesson_title":"مقدمة","order_index":1,"hook":"نهاية القرن التاسع عشر، اعتقد كثير من الفيزيائيين أن مهمة الفيزياء اقتربت من الاكتمال — لم يبقَ سوى تفاصيل صغيرة لضبطها. لكن مسألتين صغيرتين ظلّتا عالقتين: لماذا يتغيّر لون أي جسم ساخن بطريقة محددة مع درجة حرارته؟ ولماذا تقيس كل التجارب سرعة الضوء نفسها تماماً، مهما تحرّك من يقيسها؟ الإجابتان قلبتا الفيزياء رأساً على عقب.","concepts":[{"term":"هل تعلم؟","text":"عام ١٩٠٥ — الذي يُسمّى \"عام آينشتاين المعجزة\" — نشر آينشتاين بحثين ثوريين بالوقت نفسه تقريباً: تفسيره الكمّي للظاهرة الكهروضوئية (سينال عليه جائزة نوبل)، والنظرية النسبية الخاصة. عالِمٌ واحد، عامٌ واحد، وثورتان منفصلتان كلياً غيّرتا الفيزياء للأبد.","ministerial":false}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[],"has_simulation":true,"simulation_title":"🗺️ الخط الزمني: من بلانك إلى هايزنبرغ"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":2,"lesson_title":"نظرية الكم — إشعاع الجسم الأسود وفرضية بلانك","order_index":2,"hook":"نهاية القرن التاسع عشر، بدت الفيزياء الكلاسيكية (نيوتن وماكسويل) شبه مكتملة — تفسّر حركة الكواكب والضوء والكهرباء والمغناطيسية بدقة مذهلة. لكن مسألة صغيرة ظلّت عالقة: لماذا يتغيّر لون أي جسم ساخن بطريقة محددة جداً مع درجة حرارته، ولا تنجح معادلات الفيزياء الكلاسيكية بتفسيرها؟ الإجابة قلبت الفيزياء رأساً على عقب خلال ٣٠ سنة فقط.","concepts":[{"term":"تقريب عملي للجسم الأسود:","text":"فتحة صغيرة بجدار تجويف مغلق (كفرن). أي إشعاع يدخل من الفتحة ينعكس داخلياً مراراً حتى يُمتص بالكامل تقريباً قبل أن يخرج ثانية — فتتصرف الفتحة كجسم أسود شبه مثالي. النجوم (ومنها الشمس) تقارِب أيضاً سلوك الجسم الأسود، ولهذا يستطيع الفلكيون تقدير درجة حرارة سطح أي نجم من لون ضوئه فقط!","ministerial":false},{"term":"قانون ستيفان-بولتزمان:","text":"المعدل الزمني للطاقة المشعّة من وحدة مساحة الجسم الأسود (شدة الإشعاع I) يتناسب طردياً مع الأس الرابع لدرجة حرارته المطلقة — أي يعتمد على درجة الحرارة فقط، لا نوع المادة.","ministerial":false},{"term":"قانون الإزاحة لِفِن:","text":"الطول الموجي عند ذروة التوزيع الطيفي λ_m يتناسب عكسياً مع درجة الحرارة المطلقة — كلما سخُن الجسم أكثر، اتجهت ذروة إشعاعه نحو الأطوال الموجية الأقصر (الأزرق). هذا بالضبط سبب تحوّل توهج الحديد من أحمر إلى أبيض مزرقّ كلما سخّنته أكثر.","ministerial":false}],"laws":[{"name":"ستيفان-بولتزمان","formula":"I = σT⁴","variables_note":"σ = 5.67×10⁻⁸ W/m²K⁴"},{"name":"إزاحة فِن","formula":"λ_m T = 2.898×10⁻³ m·K","variables_note":""},{"name":"فرضية بلانك: طاقة الكمّ الإشعاعي (الفوتون)","formula":"E = hf","variables_note":""}],"notes":[{"heading":"⚡ الكارثة فوق البنفسجية (Ultraviolet Catastrophe)","items":["سُمّي هذا الفشل الصارخ بهذا الاسم لأن التناقض بين التنبؤ الكلاسيكي والتجربة كان الأوضح عند الأطوال الموجية القصيرة القريبة من فوق البنفسجي وما بعدها. كان هذا أحد أكبر الألغاز العالقة بالفيزياء عام ١٩٠٠."],"ministerial":false},{"heading":"⭐ القاعدة الذهبية: ثابت بلانك","items":["h = 6.63 × 10⁻³⁴ J.s — أحد أهم الثوابت الأساسية بالكون، ويظهر بكل معادلات هذا الفصل تقريباً. صِغَره الشديد هو بالضبط سبب أن تأثيرات الكم غير محسوسة إطلاقاً بحياتنا اليومية (أجسام كبيرة)، لكنها تهيمن كلياً على عالم الذرات والإلكترونات."],"ministerial":false}],"tables":[],"examples":[{"problem":"جد الطول الموجي المقابل لذروة الإشعاع المنبعث من جسم الإنسان إذا كانت درجة حرارة جلده 35°C.","givens":"المعطيات: T=35°C — قانون فِن: λ_mT=2.898×10⁻³ m·K","solution_steps":["الخطوة ١: نحوّل الحرارة إلى كلفن: T = 35 + 273 = 308 K","الخطوة ٢: نطبّق قانون فِن: λ_m = 2.898×10⁻³ / T = 2.898×10⁻³ / 308 ≈ 9.41×10⁻⁶ m 💡 هذا الطول يقع في مدى الأشعة تحت الحمراء — وهذا بالضبط ما تلتقطه كاميرات التصوير الحراري لجسم الإنسان في الظلام!"],"ministerial":true},{"problem":"مصباح يصدر ضوءاً أصفر طوله الموجي λ=590nm. أوجد: ① تردد هذا الضوء f. ② طاقة الكمّ الضوئي الواحد (الفوتون) بالجول وبالإلكترون فولت.","givens":"المعطيات: λ=590nm=590×10⁻⁹m — h=6.63×10⁻³⁴J.s — c=3×10⁸m/s — 1eV=1.6×10⁻¹⁹J","solution_steps":["الخطوة ١: نوجد التردد من العلاقة c=fλ: f = c/λ = (3×10⁸)/(590×10⁻⁹) ≈ 5.08×10¹⁴ Hz","الخطوة ٢: نوجد طاقة الكمّ بالجول: E = hf = 6.63×10⁻³⁴ × 5.08×10¹⁴ ≈ 3.37×10⁻¹⁹ J","الخطوة ٣: نحوّلها إلى إلكترون فولت: E = (3.37×10⁻¹⁹)/(1.6×10⁻¹⁹) ≈ 2.11 eV 💡 لاحظ صغر هذه الطاقة بوحدة الجول — لهذا يُفضَّل فيزيائيو الكم استعمال وحدة الإلكترون فولت (eV) بدلاً منها. سنستعمل هذه العلاقة نفسها (E=hf=hc/λ) كثيراً بالدرس القادم."],"ministerial":false}],"qa":[{"question":"يُعدّ الجسم الأسود المثالي أفضل ماص وأفضل مُشع للإشعاع الحراري في آنٍ واحد.","answer":"لأنه يمتص كل الإشعاع الساقط عليه بجميع الأطوال الموجية دون عكس أو نفاذ (أفضل ماص). وبحكم الاتزان الحراري (كل ما يُمتص يجب أن يُعاد إشعاعه كي لا ترتفع حرارته إلى ما لا نهاية)، فإن الجسم الذي يمتص كل الإشعاع الساقط هو بالضرورة نفسه أفضل جسم يعيد إشعاعه — أي أفضل مُشع أيضاً.","type":"علل","ministerial":true},{"question":"على ماذا ينصّ قانون ستيفان-بولتزمان؟ وعلامَ يعتمد المعدل الزمني للطاقة التي يُشعّها الجسم الأسود من وحدة مساحته؟","answer":"ينصّ قانون ستيفان-بولتزمان على أن شدة الإشعاع I (المعدل الزمني للطاقة المُشعّة من وحدة مساحة الجسم الأسود) تتناسب طردياً مع الأس الرابع لدرجة حرارته المطلقة: I=σT⁴. إذن تعتمد شدة الإشعاع على درجة الحرارة المطلقة للجسم فقط، ولا تعتمد على نوع مادة الجسم.","type":"وزاري","ministerial":true},{"question":"ما المقصود بـ: قانون الإزاحة لِفِن (Wien)؟","answer":"قانون ينصّ على أن حاصل ضرب الطول الموجي المقابل لذروة توزيع الطاقة الإشعاعية للجسم الأسود λ_m في درجة حرارته المطلقة T يساوي مقداراً ثابتاً: λ_mT = 2.898×10⁻³ m·K. أي أنه كلما ارتفعت درجة حرارة الجسم، «انزاحت» ذروة إشعاعه نحو أطوال موجية أقصر.","type":"وزاري","ministerial":true},{"question":"لماذا فشلت المحاولات العديدة لتفسير الطيف الكهرومغناطيسي المنبعث من الجسم الأسود كدالة للطول الموجي عند درجة حرارة معينة وفقاً لقوانين الفيزياء الكلاسيكية؟","answer":"لأن الفيزياء الكلاسيكية افترضت أن ذرّات الجسم الأسود المهتزّة تمتصّ وتُشعّ الطاقة الكهرومغناطيسية بكميات مستمرة (أي أن أي مقدار طاقة ممكن)، وهذا الافتراض توقّع طاقة غير منتهية عند الأطوال الموجية القصيرة (فوق البنفسجية) — وهو ما يخالف التجربة كلياً. ولم يُحلّ الإشكال إلا بفرضية بلانك: أن الطاقة تُصدَر وتُمتصّ في حزم منفصلة (كمّات) طاقة كلٍّ منها E=hf، لا بمقادير مستمرة.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌡️ مختبر منحني إشعاع الجسم الأسود"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":3,"lesson_title":"الظاهرة الكهروضوئية","order_index":3,"hook":"تخيّل تسلّط ضوءاً أزرق ضعيف الشدة جداً على صفيحة فلزية، فتتحرر إلكترونات فوراً بلا أي تأخير. ثم تُطفئه وتسلّط بدلاً عنه ضوءاً أحمر قوياً جداً (أقوى بآلاف المرات) على الصفيحة نفسها — فلا يتحرر ولو إلكترون واحد، مهما طال انتظارك! كيف يُعقل أن الضوء \"الأضعف\" ينجح والضوء \"الأقوى\" يفشل بالكامل؟ هذا بالضبط ما عجزت الفيزياء الكلاسيكية عن تفسيره.","concepts":[{"term":"جهد القطع (فولطية الإيقاف) V_s:","text":"إذا عكسنا الجهد بين القطبين تدريجياً، عند قيمة معيّنة V_s يتوقف حتى أسرع الإلكترونات (الأعلى طاقة حركية) عن بلوغ المصعد فيصبح التيار صفراً بالضبط. من مبدأ حفظ الطاقة: KE_max = eV_s.","ministerial":false}],"laws":[{"name":"معادلة أينشتاين الكهروضوئية","formula":"hf = W₀ + KE_max","variables_note":""},{"name":"دالة الشغل من تردد العتبة","formula":"W₀ = hf₀","variables_note":""},{"name":"طول موجة العتبة","formula":"λ₀ = c/f₀ = hc/W₀","variables_note":""}],"notes":[{"heading":"⭐ القاعدة الذهبية: لماذا فوتون واحد ↔ إلكترون واحد","items":["بما أن الفوتون لا ينقسم، ولا يستطيع الإلكترون تجميع طاقة عدة فوتونات ضعيفة معاً — فإما أن يملك الفوتون الواحد طاقة كافية لتحرير الإلكترون فوراً (وهذا يفسّر الانبعاث الفوري بلا تأخير)، أو لا يحدث شيء إطلاقاً بغض النظر عن عدد الفوتونات الساقطة (الشدة). هذا وحده يفسّر الملاحظات الأربع كلها بأناقة."],"ministerial":false}],"tables":[],"examples":[{"problem":"يتوقّف تحرير الإلكترونات الضوئية من سطح معدن عندما يزيد طول موجة الضوء الساقط عليه عن 600nm. فإذا أُضيء سطح المعدن نفسه بضوء طول موجته 300nm، فما مقدار الطاقة الحركية العظمى للإلكترونات الضوئية المنبعثة؟ وزاري: الدور الثالث 2017 · الدور الثاني 2019 · الدور الثاني 2023 · الدور الأول 2023","givens":"المعطيات: λ₀=600nm (طول موجة العتبة، حيث يتوقف الانبعاث) — λ=300nm — h=6.63×10⁻³⁴J.s — c=3×10⁸m/s","solution_steps":["الخطوة ١: نوجد دالة الشغل من طول موجة العتبة: W₀ = hc/λ₀ = (6.63×10⁻³⁴×3×10⁸)/(600×10⁻⁹) = 3.315×10⁻¹⁹ J","الخطوة ٢: نطبّق معادلة أينشتاين عند λ=300nm: KE_max = hc/λ − W₀ = (6.63×10⁻³⁴×3×10⁸)/(300×10⁻⁹) − 3.315×10⁻¹⁹ KE_max = 6.63×10⁻¹⁹ − 3.315×10⁻¹⁹ = 3.315×10⁻¹⁹ J ≈ 2.07 eV 💡 لاحظ الحيلة: مضاعفة التردد هنا (بتنصيف الطول الموجي) ضاعفت طاقة الفوتون، فجاءت النتيجة أنيقة = دالة الشغل نفسها بالضبط."],"ministerial":true}],"qa":[{"question":"لا تنبعث أي إلكترونات من سطح فلز مهما زادت شدة الضوء الساقط عليه، إن كان تردد هذا الضوء أقل من التردد الحرج لذلك الفلز.","answer":"لأن الفوتون الواحد يتفاعل مع إلكترون واحد فقط (تصادم لحظي)، فلا يستطيع الإلكترون تجميع طاقة عدة فوتونات ضعيفة معاً ليحرر نفسه. وبما أن طاقة الفوتون الواحد hf أقل من دالة الشغل W₀ اللازمة للتحرير، يبقى الإلكترون مرتبطاً بالفلز مهما زاد عدد الفوتونات الساقطة (أي الشدة).","type":"علل","ministerial":false},{"question":"عند مضاعفة شدة الضوء الساقط بتردد معيّن مؤثر على سطح معدن معيّن، يتضاعف مقدار: (الطاقة الحركية العظمى، جهد الإيقاف، زخم الفوتون، تيار الإشباع)؟","answer":"الجواب: تيار الإشباع. فمضاعفة شدة الضوء تضاعف عدد الفوتونات الساقطة بالثانية، وبالتالي عدد الإلكترونات المنبعثة (تيار الإشباع)، لكنها لا تغيّر طاقة كل فوتون على حدة (تحدّدها العلاقة E=hf فقط)، فتبقى الطاقة الحركية العظمى وجهد الإيقاف ثابتين.","type":"اختيار وزاري متكرر","ministerial":true}],"has_simulation":true,"simulation_title":"💥 مختبر الظاهرة الكهروضوئية"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":4,"lesson_title":"الجسيمات (الدقائق) والموجات","order_index":4,"hook":"الفوتون غريب الأطوار: لا كتلة سكون له إطلاقاً، لكنه يحمل طاقة ويتحرّك بسرعة الضوء دائماً. ورغم ذلك، حين يصطدم بإلكترون (كما بالظاهرة الكهروضوئية) يتصرّف تماماً كجسيم له زخم محدد يمكن حسابه ومقارنته بأي تصادم ميكانيكي عادي. كيف نوفّق بين \"بلا كتلة\" و\"له زخم\" بمعادلة واحدة رياضية أنيقة؟","concepts":[{"term":"قراءة المعادلة:","text":"طرفها الأيسر p (الزخم) صفة جسيمية بحتة، وطرفها الأيمن h/λ يحوي الطول الموجي λ وهو صفة موجية بحتة — فالمعادلة الواحدة p=h/λ تصف الوجهين معاً. هذا هو التفسير الرياضي المباشر للسلوك المزدوج (موجي-جسيمي) للضوء.","ministerial":false}],"laws":[{"name":"كتلة الفوتون الحركية","formula":"m = hf/c²","variables_note":""},{"name":"زخم الفوتون","formula":"p = mc = hf/c = h/λ","variables_note":""}],"notes":[],"tables":[],"examples":[{"problem":"فوتون طوله الموجي λ=3nm سقط على سطح فلز. جد: ① زخم هذا الفوتون. ② طاقته بوحدة الجول.","givens":"المعطيات: λ=3nm=3×10⁻⁹m — h=6.63×10⁻³⁴J.s — c=3×10⁸m/s","solution_steps":["الخطوة ①: p = h/λ = (6.63×10⁻³⁴)/(3×10⁻⁹) ≈ 2.21×10⁻²⁵ kg·m/s","الخطوة ②: E = pc = 2.21×10⁻²⁵ × 3×10⁸ ≈ 6.63×10⁻¹⁷ J 💡 يمكن التحقق مباشرة: E=hc/λ تعطي النتيجة نفسها بالضبط."],"ministerial":false}],"qa":[{"question":"ما النظرة الحديثة لطبيعة الضوء؟","answer":"النظرة الحديثة: الضوء له طبيعة مزدوجة (ثنائية) — يسلك سلوك الموجات في ظواهر التداخل والحيود والاستقطاب، ويسلك سلوك الجسيمات (الفوتونات) في الظاهرة الكهروضوئية وتفاعله مع المادة. فلا يمكن وصف الضوء بأنه موجة بحتة أو جسيم بحت، بل الاثنان معاً بحسب الظاهرة المدروسة.","type":"سؤال وزاري متكرر جداً","ministerial":true},{"question":"كيف يمكن رياضياً تفسير السلوك المزدوج للفوتون؟","answer":"بمعادلة زخم الفوتون p=h/λ: طرفها الأيسر p (الزخم) يصف الصفة الجسيمية للفوتون، وطرفها الأيمن يحوي λ (الطول الموجي) الذي يصف الصفة الموجية. اجتماع الكمّيتين بمعادلة واحدة هو التفسير الرياضي للسلوك المزدوج.","type":"سؤال وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":5,"lesson_title":"الموجات المادية","order_index":5,"hook":"عام ١٩٢٣، طرح طالب دكتوراه فرنسي شاب اسمه لويس دي برولي فكرة بدت خيالية وقتها برسالته الجامعية: بما أن الطبيعة \"متناظرة\"، وبما أن الضوء (موجة) أثبت خواصاً جسيمية مؤكدة (الفوتون)، فلا بد أن الجسيمات المادية — كالإلكترون — تملك خواصاً موجية أيضاً! تردّدت لجنة المناقشة بقبول الفكرة لغرابتها، حتى استشارت آينشتاين الذي كتب: «لقد رفع طرف حجاب عظيم». وخلال ٣ سنوات فقط أثبتت التجربة صحتها، فنال دي برولي نوبل عام ١٩٢٩.","concepts":[{"term":"حزمة الموجة (Wave Packet):","text":"يُمثَّل الجسيم المتحرك بالصورة الموجية بحزمة موجية — تراكب عدد كبير من الموجات المتقاربة الأطوال الموجية، يتركّز تراكبها البنّاء في منطقة محدودة من الفراغ تمثّل موضع الجسيم التقريبي.","ministerial":false},{"term":"عام ١٩٢٧:","text":"قذف العالمان كلينتون ديفيسون ولستر جيرمر حزمة إلكترونات على بلورة نيكل، ورصدا نمط حيود للإلكترونات المرتدة — تماماً كما يحدث بحيود الأشعة السينية عبر البلورات الذرية. هذا أثبت عملياً أن للإلكترون طبيعة موجية حقيقية، مؤكداً فرضية دي برولي بالكامل.","ministerial":false}],"laws":[{"name":"فرضية دي برولي: الطول الموجي المرافق لجسيم","formula":"λ = h/p = h/(mv)","variables_note":""}],"notes":[{"heading":"🔑 اختصار مفيد لمسائل \"التعجيل بفرق جهد\"","items":["بدمج الخطوتين بعلاقة واحدة: λ = h/√(2meV). احفظ الفكرة لا الصيغة الجاهزة: أي مسألة تُعطيك فرق جهد معجِّل لإلكترون وتطلب طول موجة دي برولي تُحَل بثلاث خطوات ثابتة: الطاقة الحركية من الشغل الكهربائي ⟵ السرعة ⟵ الطول الموجي."],"ministerial":false}],"tables":[],"examples":[{"problem":"أوجد طول موجة دي برولي المرافقة لإلكترون عُجِّل من السكون بفرق جهد مقداره V=100V. وزاري — نمط متكرر","givens":"المعطيات: V=100V — e=1.6×10⁻¹⁹C — m=9.11×10⁻³¹kg — h=6.63×10⁻³⁴J.s","solution_steps":["الخطوة ١: نوجد سرعة الإلكترون من eV=½mv²: v = √(2eV/m) = √[(2×1.6×10⁻¹⁹×100)/(9.11×10⁻³¹)] ≈ 5.93×10⁶ m/s","الخطوة ٢: نعوّض بقانون دي برولي: λ = h/(mv) = (6.63×10⁻³⁴)/(9.11×10⁻³¹ × 5.93×10⁶) ≈ 1.23×10⁻¹⁰ m = 0.123 nm 💡 هذا الطول قريب جداً من أبعاد الذرة نفسها — بالضبط سبب استعمال إلكترونات مُعجَّلة بجهود مشابهة لدراسة تركيب البلورات، تماماً كما تُستعمل الأشعة السينية."],"ministerial":true}],"qa":[{"question":"لا نلاحظ أي سلوك موجي محسوس (كحيود أو تداخل) للأجسام الكبيرة اليومية كالكرة المتحركة، رغم أن فرضية دي برولي تنطبق عليها نظرياً أيضاً.","answer":"لأن طول موجة دي برولي λ=h/(mv) يتناسب عكسياً مع الزخم mv، وكتلة الأجسام الكبيرة هائلة جداً مقارنة بصِغر ثابت بلانك h، فيكون λ الناتج ضئيلاً جداً (أصغر من نواة الذرة بمراحل عديدة) — أصغر بكثير من أن يرصده أي جهاز قياس عملي، فيبدو الجسم \"جسيمياً\" خالصاً بلا أي أثر موجي محسوس.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"📏 مختبر طول موجة دي برولي (مقياس لوغاريتمي)"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":6,"lesson_title":"مدخل إلى مفهوم ميكانيك الكم ودالة الموجة","order_index":6,"hook":"بميكانيك نيوتن، إن عرفتَ موضع وسرعة كرة الآن، تقدر تتنبأ بموضعها بأي لحظة مستقبلية بدقة تامة. لكن بعالم الإلكترون، لا يوجد \"موضع محدد\" أصلاً قبل القياس — فقط احتمالات. هذا ليس قصوراً بمعرفتنا، بل خاصية أساسية بالطبيعة نفسها عند هذا المقياس.","concepts":[{"term":"مثال توضيحي — ذرة الهيدروجين:","text":"النموذج الكلاسيكي (بور) يصوّر الإلكترون يدور بمدار دائري نصف قطره ثابت تماماً (0.0529nm). أما الوصف الكمّي الحديث فيستبدل هذا المدار الحاد بـ«سحابة احتمال»: منطقة ضبابية حول النواة تمثّل توزيع |ψ|²، كثافتها أعلى ما يمكن قرب نصف قطر بور الكلاسيكي — لكن للإلكترون احتمال (ضئيل) للتواجد بمناطق أخرى أيضاً.","ministerial":false}],"laws":[],"notes":[{"heading":"⭐ القاعدة الذهبية: تفسير بورن الاحتمالي (1927)","items":["كثافة الاحتمال |ψ|² لجسيم بموضع وزمان معيّنين تتناسب طردياً مع احتمالية العثور على الجسيم بتلك المنطقة من الفراغ عند تلك اللحظة. حيث تكون |ψ|² كبيرة، يكبر احتمال وجود الجسيم هناك؛ وحيث تكون صغيرة (أو صفراً) يقلّ احتمال وجوده (أو ينعدم)."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"علامَ تدل قيمة كبيرة لـ|ψ|² لجسيم بمكان وزمان معيّنين؟","answer":"تدلّ القيمة الكبيرة لـ|ψ|² على أن احتمالية العثور على الجسيم في ذلك المكان وتلك اللحظة كبيرة (مرتفعة) — أي أن كثافة الاحتمال تتناسب طردياً مع مقدار |ψ|².","type":"سؤال وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"⚛️ مقارنة: مدار بور مقابل سحابة الاحتمال"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":7,"lesson_title":"مبدأ اللادقة (اللاتحديد) لهايزنبرغ","order_index":7,"hook":"تخيّل مجهراً خيالياً فائق الدقة تريد به تحديد موقع إلكترون بدقة متناهية. لرؤيته بدقة تحتاج ضوءاً بطول موجي قصير جداً — أي فوتونات عالية الطاقة والزخم. لكن حين يصطدم هذا الفوتون بالإلكترون ليصوّره، فإنه يدفعه بقوة ويغيّر زخمه بمقدار لا يمكن التنبؤ به! كلما حسّنت دقة تحديد الموضع، اضطربت معرفتك بالزخم أكثر. هذه ليست مشكلة تقنية يمكن حلّها بجهاز أفضل مستقبلاً — إنها خاصية جوهرية بطبيعة المادة نفسها.","concepts":[{"term":"حالة خاصة مهمة: Δx=0","text":"إذا قيس موضع الجسيم بدقة تامة (Δx=0)، يبقى الطرف الأيمن للمتراجحة ثابتاً (h/4π) بينما حاصل الضرب بالطرف الأيسر يحوي صفراً × Δp — وهذا لا يتحقق إلا إذا كان Δp يؤول إلى ما لا نهاية. أي: لا توجد أي دقة إطلاقاً لمعرفة الزخم عندئذٍ.","ministerial":false}],"laws":[{"name":"مبدأ اللادقة (اللاتحديد) لهايزنبرغ","formula":"Δx · Δp ≥ h/4π","variables_note":""}],"notes":[{"heading":"⭐ القاعدة الذهبية: علاقة عكسية بين اللادقتين","items":["كلما صغّرت اللادقة بأحد المقدارين (ضيّقت Δx مثلاً بحصر الجسيم بمنطقة أدق)، وجب أن تكبر اللادقة بالآخر (Δp) تلقائياً، بحيث يبقى حاصل ضربهما محقِّقاً للشرط أعلاه دائماً. وبما أن p=mv، يمكن كتابتها أيضاً: Δx · mΔv ≥ h/4π (بافتراض كتلة m ثابتة معروفة بدقة)."],"ministerial":false}],"tables":[],"examples":[{"problem":"قارن أدنى لادقة ممكنة بالسرعة (Δv_min) لكل من: ① إلكترون محصور بمنطقة عرضها Δx=1×10⁻¹⁰m (بحجم الذرة تقريباً). ② كرة صغيرة كتلتها m=0.02kg محصورة (افتراضاً) بالمنطقة نفسها Δx=1×10⁻¹⁰m.","givens":"المعطيات: Δx=1×10⁻¹⁰m — m_e=9.11×10⁻³¹kg — m_كرة=0.02kg — h=6.63×10⁻³⁴J.s","solution_steps":["الخطوة ١: من شرط الحد الأدنى Δx·mΔv=h/4π، نستخرج Δv_min=h/(4πmΔx). للإلكترون: Δv_min = (6.63×10⁻³⁴)/(4π × 9.11×10⁻³¹ × 1×10⁻¹⁰) ≈ 5.8×10⁵ m/s لادقة ضخمة فعلياً — قريبة من رتبة سرعات الإلكترونات نفسها! لا يمكن إهمالها إطلاقاً.","الخطوة ٢: نكرر الحساب لنفس الحصر لكن بكتلة الكرة: Δv_min = (6.63×10⁻³⁴)/(4π × 0.02 × 1×10⁻¹⁰) ≈ 2.6×10⁻²³ m/s 💡 لادقة مهملة تماماً بلا أي معنى عملي — أصغر من أن يرصدها أي جهاز قياس موجود أو متخيَّل. هذا بالضبط الفارق بين عالم الكم وعالمنا اليومي: نفس القانون، لكن الكتلة الكبيرة تجعل أثره غير محسوس كلياً."],"ministerial":false}],"qa":[{"question":"ما المقصود بـ: مبدأ اللادقة لهايزنبرك؟","answer":"مبدأ ينصّ على استحالة تحديد موضع الجسيم وزخمه (أو طاقته وزمن قياسها) بدقة تامة في الوقت نفسه؛ إذ يتحقق دوماً أن حاصل ضرب مقداري اللادقة بالكمّيتين المترافقتين لا يقلّ عن h/4π. فكلما ازدادت دقة إحدى الكمّيتين، تناقصت بالضرورة دقة الأخرى.","type":"سؤال وزاري","ministerial":true},{"question":"عدم التحديد بمبدأ هايزنبرغ ليس ناتجاً عن قصور تقني بدقة أجهزة القياس، بل هو خاصية أساسية بالطبيعة نفسها.","answer":"لأنه ناتج مباشرة عن الطبيعة الموجية للجسيمات (فرضية دي برولي)؛ فالموجة بطبيعتها الرياضية ممتدة بالفضاء ولا يمكن حصرها بنقطة واحدة محددة بدقة تامة مع تحديد طول موجتها (المرتبط بالزخم) بدقة تامة أيضاً في آنٍ واحد. هذا تناقض جوهري بطبيعة الموجات ذاتها، مستقل تماماً عن جودة أي جهاز قياس مهما تطوّر مستقبلاً.","type":"علل","ministerial":false},{"question":"لا يظهر تأثير مبدأ اللادقة بشكل محسوس على حركة الأجسام الكبيرة بحياتنا اليومية كالسيارة أو الكرة.","answer":"لأن اللادقة الدنيا بالموضع والزخم مقيّدة بثابت بلانك h الصغير جداً، وبما أن Δp=mΔv، فكلما كبرت كتلة الجسم m (كالسيارة) صغرت اللادقة الناتجة بسرعته Δv بشكل كبير جداً لنفس اللادقة بالزخم — فتصبح مهملة تماماً وغير محسوسة عملياً، بعكس الإلكترون الذي تجعل كتلته الصغيرة جداً هذه اللادقة كبيرة وملموسة فيزيائياً.","type":"علل","ministerial":true}],"has_simulation":true,"simulation_title":"🌫️ مختبر اللادقة: صندوق الحصر"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":8,"lesson_title":"النظرية النسبية","order_index":8,"hook":"عند نيوتن، الزمن مطلقٌ يتدفّق بالمعدّل نفسه لكل المراقبين مهما اختلفت سرعتهم. لكن آينشتاين أثبت عام ١٩٠٥ أن هذا خطأ: بافتراضٍ واحد يبدو بسيطاً — سرعة الضوء ثابتة للجميع مهما تحرّكوا — تنهار فكرة الزمان والمكان المطلقين، وتولد نتائج تُقاس اليوم بدقّة بالمختبرات ومحطات الفضاء.","concepts":[],"laws":[],"notes":[{"heading":"🔬 لماذا اضطر آينشتاين للتخلي عن الزمن المطلق؟","items":["عام ١٨٨٧، أراد العالِمان مايكلسون ومورلي قياس \"رياح الأثير\" التي ظنّا أن الأرض تسبح خلالها وهي تدور حول الشمس. قاسا سرعة الضوء باتجاهين متعامدين، متوقّعَين فرقاً بسبب حركة الأرض — لكن النتيجة جاءت صفراً تماماً: لا فرق إطلاقاً، مهما تغيّر اتجاه القياس أو فصل السنة. هذه النتيجة \"الفاشلة\" بظاهرها دحضت فكرة الأثير كلياً، ومهّدت الطريق بعد ١٨ عاماً فقط لآينشتاين ليبني عليها نظريته — كما ستكتشف بالدرس القادم."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ما الذي أضافته النظرية النسبية للمفاهيم الكلاسيكية؟","answer":"أضافت النظرية النسبية الزمن كبُعدٍ رابع يتشابك مع الأبعاد المكانية الثلاثة، بدلاً من معاملته كمّية مطلقة منفصلة كما بالفيزياء الكلاسيكية. فأصبح وصف أي حدث يتطلّب أربعة إحداثيات (x,y,z,t) لا ثلاثة فقط، وصار الزمن نسبياً يعتمد على حركة المراقب (إطاره المرجعي) لا كمّية ثابتة للجميع.","type":"سؤال وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":9,"lesson_title":"فرضيتا آينشتاين للنسبية الخاصة","order_index":9,"hook":"لو ركضتَ باتجاه سيارة، تقترب منك بسرعة أكبر من سرعتها الحقيقية — هذا جمع السرعات الكلاسيكي المألوف. فلماذا لا يحدث الأمر نفسه مع الضوء؟ لماذا يقيس كل مراقب سرعة الضوء نفسها بالضبط 3×10⁸ m/s، بصرف النظر عن سرعته هو أو سرعة مصدر الضوء؟ إجابة آينشتاين: لأن هذا ببساطة قانون أساسي بالطبيعة، لا استثناءً يحتاج تفسيراً إضافياً.","concepts":[{"term":"لماذا هذا صادم؟","text":"تخيّل مركبة فضائية تتحرك بسرعة 0.5c تجاهك وتُطلق شعاع ليزر نحوك. كلاسيكياً تتوقّع أن يصلك الضوء بسرعة c+0.5c. لكن الفرضية الثانية تقول: سيصلك بالضبط بسرعة c — لا أكثر ولا أقل! هذا التناقض الظاهري مع الحدس اليومي هو بالضبط ما يجبر الزمان والمكان أنفسهما على التغيّر (كما سترى بدرسَي القادمين) ليبقى قانون ثبات سرعة الضوء صحيحاً دوماً.","ministerial":false}],"laws":[],"notes":[{"heading":"🔬 الدليل التجريبي","items":["نتيجة تجربة مايكلسون-مورلي (الدرس السابق) — لا فرق إطلاقاً بسرعة الضوء بأي اتجاه قياس — هي الدليل التجريبي المباشر الذي بُنيت عليه الفرضية الثانية، وقد دحضت نظرية الأثير كلياً."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ما هما فرضيتا آينشتاين في النظرية النسبية الخاصة؟","answer":"الفرضية الأولى (مبدأ النسبية): قوانين الفيزياء واحدة بجميع الأطر المرجعية العطالية. الفرضية الثانية (ثبات سرعة الضوء): سرعة الضوء بالفراغ ثابتة ومقدارها 3×10⁸ m/s لجميع المراقبين، بصرف النظر عن حركة مصدر الضوء أو حركة المراقب.","type":"سؤال وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":10,"lesson_title":"تحويلات لورنتز","order_index":10,"hook":"تحويلات غاليليو الكلاسيكية بسيطة وبديهية: لو تحركتَ بسرعة v بالنسبة لي، فإن موقعك وزمنك يُحسبان بجمع أو طرح بسيط. لكنها تفترض ضمنياً أن الزمن مطلق ثابت للجميع — وهذا بالضبط ما تناقضه فرضية آينشتاين الثانية. الحل: معادلات جديدة تتضمّن مقداراً واحداً محورياً يظهر بكل حساب نسبي تقريباً.","concepts":[],"laws":[{"name":"عامل لورنتز","formula":"γ = 1 / √(1 − v²/c²)","variables_note":""}],"notes":[{"heading":"⭐ كيف يتصرف γ؟","items":["عند سرعات صغيرة مقارنة بسرعة الضوء (v≪c) يكون γ≈1 فلا تظهر أي تأثيرات نسبية محسوسة — عالمنا اليومي بأكمله هنا. أما عند اقتراب v من c فإن γ يتزايد بسرعة هائلة ويؤول إلى ما لا نهاية — ولهذا يستحيل على أي جسم له كتلة أن يبلغ سرعة الضوء فعلياً."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ما المقصود بتحويلات لورنتز؟","answer":"مجموعة من المعادلات الرياضية التي تربط إحداثيات الحدث (الموقع والزمن) كما يقيسها مراقب بإطار مرجعي عطالي، بإحداثيات الحدث نفسه كما يقيسها مراقب آخر بإطار عطالي يتحرك بالنسبة للأول بسرعة نسبية v — وتحلّ محلّ تحويلات غاليليو الكلاسيكية لتتوافق مع ثبات سرعة الضوء.","type":"سؤال وزاري","ministerial":true},{"question":"ما الفرق الأساسي بين تحويلات غاليليو والتحويلات النسبية (لورنتز)؟","answer":"الفرق الأساسي هو المقدار γ (عامل لورنتز) وتأثيره: تحويلات غاليليو الكلاسيكية لا تتضمّنه إطلاقاً (تفترض زمناً وطولاً وكتلة مطلقة ثابتة لكل المراقبين)، بينما تحويلات لورنتز النسبية تُدخل γ فيؤثر مباشرة على زخم الجسم وطوله وكتلته والزمن المقاس له كلما اقتربت سرعته من سرعة الضوء.","type":"سؤال وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🚀 مختبر النسبية: عامل لورنتز وتأثيراته"},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":11,"lesson_title":"أهم النتائج المترتبة على النظرية النسبية الخاصة","order_index":11,"hook":"لو ركب رائد فضاء مركبةً تسير بسرعة قريبة جداً من سرعة الضوء لسنواتٍ (بساعته هو)، ثم عاد إلى الأرض — سيجد أن أهله قد كبروا في العمر أكثر منه بكثير! هذه ليست خيالاً علمياً: قِيست هذه الظاهرة فعلياً بساعاتٍ ذرّية دقيقة جداً على متن طائرات وأقمار صناعية، وتطابقت النتائج تماماً مع تنبؤات آينشتاين.","concepts":[{"term":"⚖ ازدياد الكتلة النسبية:","text":"كتلة الجسم المتحرك تزداد كما يقيسها مراقب ساكن كلما اقتربت سرعته من سرعة الضوء: m = m₀/√(1−v²/c²) = m₀γ، حيث m₀ كتلة السكون. ولهذا يحتاج تسريع أي جسم إلى سرعة الضوء طاقة غير منتهية — فيستحيل عملياً بلوغها.","ministerial":false}],"laws":[{"name":"تقلّص الطول","formula":"L = L₀ √(1 − v²/c²) = L₀/γ","variables_note":""}],"notes":[{"heading":"⭐ القاسم المشترك للنتائج الثلاث","items":["كلها تتضمّن عامل لورنتز γ. الزمن والكتلة يُضربان بـγ (يكبران)، بينما الطول يُقسَم على γ (يصغر) — وعند السرعات اليومية (γ≈1) تختفي كل هذه الفروق عملياً."],"ministerial":false}],"tables":[],"examples":[{"problem":"(سؤال وزاري — اختيار من متعدد) سفينة فضائية طولها على الأرض (طول السكون) L₀=40 m. كم يصبح طولها عندما تتحرك بسرعة 0.8c كما يقيسه مراقب ساكن على الأرض؟ الخيارات: (18 m، 20 m، 24 m، 40 m)","givens":"المعطيات: L₀=40 m — v=0.8c","solution_steps":["الخطوة ١: نعوّض مباشرة بقانون تقلّص الطول: L = L₀√(1 − v²/c²) = 40×√(1 − 0.8²)","الخطوة ٢: L = 40×√(1 − 0.64) = 40×√0.36 = 40×0.6","الخطوة ٣: L = 24 m 💡 الجواب: 24 m. لاحظ أن الطول قلّ لأن السفينة تتحرك بالنسبة للمراقب الأرضي — بينما رائد السفينة نفسه يقيس طولها 40m دائماً (طول سكونه الخاص)."],"ministerial":true}],"qa":[],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":12,"lesson_title":"تكافؤ الكتلة والطاقة","order_index":12,"hook":"الطاقة التي تشعّها الشمس ناتجة عن تحوّل جزءٍ ضئيل من كتلتها إلى طاقة عبر الاندماج النووي — الشمس تفقد نحو ٤ ملايين طنٍّ من كتلتها كل ثانية، وهذا مستمر منذ نحو ٤.٦ مليار سنة! معادلة واحدة بسيطة تفسّر كل هذه الطاقة الهائلة.","concepts":[],"laws":[{"name":"تكافؤ الكتلة والطاقة","formula":"E = mc²","variables_note":""}],"notes":[{"heading":"","items":["بما أن c² مقدار هائل (9×10¹⁶ m²/s²)، فإن كمّية صغيرة جداً من الكتلة تكافئ طاقة ضخمة — وهذا أساس عمل المفاعلات والقنابل النووية، حيث يتحوّل جزء ضئيل جداً من كتلة النواة إلى طاقة هائلة أثناء التفاعلات النووية. وهو أيضاً أساس إشعاع الشمس نفسها: تفقد الشمس نحو ٤ ملايين طنٍّ من كتلتها كل ثانية عبر الاندماج النووي، وهذا مستمر منذ نحو ٤.٦ مليار سنة!"],"ministerial":false}],"tables":[],"examples":[{"problem":"إذا تحوّلت كتلة مقدارها 1 gram بالكامل إلى طاقة، فما مقدار هذه الطاقة؟ وكم شهراً من استهلاك بيتٍ عراقي للكهرباء (~1000 kWh/شهر) تكافئها؟","givens":"المعطيات: m=1 g=1×10⁻³ kg — c=3×10⁸ m/s — استهلاك البيت الشهري ≈3.6×10⁹ J","solution_steps":["الخطوة ١: نطبّق معادلة آينشتاين مباشرة: E = mc² = 1×10⁻³ × (3×10⁸)² = 1×10⁻³ × 9×10¹⁶ E = 9×10¹³ J","الخطوة ٢: نقارن باستهلاك البيت الشهري: عدد الأشهر = (9×10¹³) / (3.6×10⁹) ≈ 25000 شهر ≈ 2083 سنة 💡 من غرامٍ واحد فقط! هذا يوضّح ضخامة الطاقة الكامنة بالكتلة."],"ministerial":false}],"qa":[],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c6","chapter_title":"الفيزياء الحديثة","lesson_number":13,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":13,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"ما تعريف الجسم الأسود المثالي؟","answer":"جسم يمتص كل الإشعاع الساقط عليه بجميع الأطوال الموجية دون عكس أو نفاذ — الجسم الأسود المثالي يمتص الإشعاع الساقط عليه بالكامل بجميع الأطوال الموجية، دون أي عكس أو نفاذ.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، الدور الثالث 2019 · الدور الثالث 2023) على ماذا ينصّ قانون ستيفان-بولتزمان؟","answer":"شدة إشعاع الجسم الأسود I تتناسب طردياً مع الأس الرابع لدرجة حرارته المطلقة (I=σT⁴) — I=σT⁴ — شدة إشعاع الجسم الأسود تتناسب طردياً مع الأس الرابع لدرجة حرارته المطلقة، وتعتمد على درجة الحرارة فقط لا نوع المادة.","type":"سؤال","ministerial":true},{"question":"جسم أسود درجة حرارته 500K. جد الطول الموجي المقابل لذروة إشعاعه (قانون فِن: λ_mT=2.898×10⁻³m·K).","answer":"≈5.8×10⁻⁶ m — λ_m = 2.898×10⁻³/500 ≈ 5.8×10⁻⁶ m.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، الدور الثاني 2023) لماذا فشلت المحاولات العديدة لتفسير طيف الجسم الأسود وفق قوانين الفيزياء الكلاسيكية؟","answer":"لأنها افترضت أن الطاقة تُصدر وتُمتص بكميات مستمرة، فتنبأت بطاقة لا نهائية عند الأطوال الموجية القصيرة — الفيزياء الكلاسيكية افترضت طاقة إشعاعية مستمرة (بلا تكميم)، فتنبأت بطاقة لا نهائية عند الأطوال الموجية القصيرة (الكارثة فوق البنفسجية) — يخالف التجربة تماماً.","type":"سؤال","ministerial":true},{"question":"ما نص فرضية بلانك الأساسية؟","answer":"الطاقة الإشعاعية تُصدر وتُمتص على شكل حزم منفصلة (كمّات) طاقة كل منها E=hf — فرضية بلانك: الطاقة تُصدر أو تُمتص بحزم منفصلة (كمّات) طاقة كل منها E=hf.","type":"سؤال","ministerial":false},{"question":"كمّ إشعاعي (فوتون) تردده f=5×10¹⁴ Hz. جد طاقته تقريباً (h=6.63×10⁻³⁴J.s).","answer":"≈3.32×10⁻¹⁹ J — E = hf = 6.63×10⁻³⁴ × 5×10¹⁴ ≈ 3.32×10⁻¹⁹ J.","type":"سؤال","ministerial":false},{"question":"كلما ارتفعت درجة حرارة الجسم الأسود، ماذا يحدث لموقع قمة منحني إشعاعه ولشدته الكلية؟","answer":"تنزاح القمة نحو أطوال موجية أقصر، وتزداد الشدة الكلية بقوة — قانون فِن: القمة تنزاح لأطوال موجية أقصر مع ارتفاع T. قانون ستيفان-بولتزمان: الشدة الكلية تزداد بقوة (∝T⁴).","type":"سؤال","ministerial":false},{"question":"ما ملاحظتان تجريبيتان من ملاحظات الظاهرة الكهروضوئية الأربع تناقضان توقعات النظرية الموجية الكلاسيكية؟","answer":"الانبعاث الفوري بلا تأخير، ووجود تردد عتبة أدنى لا ينبعث دونه أي إلكترون — النموذج الكلاسيكي يتوقع تأخيراً زمنياً لتجميع الطاقة، وعدم وجود تردد عتبة (أي تردد يحرر إلكتروناً لو انتظرنا كفاية) — كلا الأمرين يخالف التجربة.","type":"سؤال","ministerial":false},{"question":"(اختيار وزاري متكرر، الدور الأول 2024 · 2022 · 2019) عند مضاعفة شدة الضوء الساقط بتردد ثابت أعلى من f₀، أي مقدار يتضاعف؟","answer":"تيار الإشباع (عدد الإلكترونات المنبعثة بالثانية) — مضاعفة الشدة تضاعف عدد الفوتونات فقط، فيتضاعف تيار الإشباع، بينما KE_max وV_s ثابتتان لاعتمادهما على التردد فقط.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثالث 2017 · الدور الثاني 2019 وغيرها — الأكثر تكراراً) يتوقّف تحرير الإلكترونات من سطح معدن عند λ₀=600nm. أُضيء المعدن نفسه بضوء λ=300nm. جد KE_max.","answer":"≈3.315×10⁻¹⁹ J (≈2.07eV) — W₀=hc/600nm=3.315×10⁻¹⁹J. عند 300nm: hf=hc/300nm=6.63×10⁻¹⁹J. KE_max=6.63×10⁻¹⁹−3.315×10⁻¹⁹=3.315×10⁻¹⁹J≈2.07eV.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الثاني 2023) سقط ضوء λ=3×10⁻⁷m على معدن، وكان جهد القطع اللازم لإيقاف الإلكترونات 1.658V. جد طول موجة العتبة لهذا المعدن.","answer":"≈500 nm — KE_max=eV_s=1.6×10⁻¹⁹×1.658=2.653×10⁻¹⁹J. W₀=hc/λ−KE_max=6.63×10⁻¹⁹−2.653×10⁻¹⁹=3.977×10⁻¹⁹J. λ₀=hc/W₀≈5×10⁻⁷m=500nm.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2022–2023 · 2023–2024) سقط ضوء λ=300nm على معدن دالة شغله 3.978×10⁻¹⁹J. جد KE_max بوحدة الجول.","answer":"≈2.652×10⁻¹⁹ J — hf=hc/λ=6.63×10⁻¹⁹J. KE_max=6.63×10⁻¹⁹−3.978×10⁻¹⁹=2.652×10⁻¹⁹J.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، الدور الأول 2021) سقط ضوء λ=400nm على الصوديوم، فانبعثت إلكترونات طاقتها الحركية العظمى 0.8eV. جد دالة الشغل للصوديوم بوحدة eV.","answer":"≈2.31 eV — hf=hc/λ=4.9725×10⁻¹⁹J≈3.108eV. W₀=hf−KE_max=3.108−0.8≈2.31eV.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2021) سقط ضوء λ=100nm على معدن دالة شغله 1.67×10⁻¹⁹J. جد الانطلاق الأعظم للإلكترونات المنبعثة تقريباً.","answer":"≈2×10⁶ m/s — KE_max=hc/λ−W₀=1.989×10⁻¹⁸−0.167×10⁻¹⁸=1.822×10⁻¹⁸J. من KE_max=½mv²: v=√(2×KE_max/m)≈2×10⁶m/s.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2019 — نمط بالتردد) سقط ضوء تردده 0.75×10¹⁵Hz على معدن، وجهد القطع اللازم 0.3V. جد التردد الحرج لهذا المعدن.","answer":"≈0.678×10¹⁵ Hz — KE_max=eV_s=4.8×10⁻²⁰J. f₀=f−KE_max/h=0.75×10¹⁵−0.0724×10¹⁵≈0.678×10¹⁵Hz.","type":"سؤال","ministerial":true},{"question":"برسم بياني، يمر خط KE_max−f لفلز بنقطتين: (f=5×10¹⁴Hz, KE_max=0) و(f=10×10¹⁴Hz, KE_max≈2.07eV). جد ثابت بلانك h التقريبي (بوحدة eV.s).","answer":"≈4.14×10⁻¹⁵ eV.s — h = ΔKE_max/Δf = 2.07/(5×10¹⁴) ≈ 4.14×10⁻¹⁵ eV.s — القيمة المعروفة لثابت بلانك بوحدة eV.s.","type":"سؤال","ministerial":false},{"question":"أي مما يلي تطبيق عملي شائع للظاهرة الكهروضوئية؟","answer":"الألواح الشمسية وأجهزة الإنذار الضوئية والكاميرات الرقمية (CCD) — هذه التطبيقات الثلاثة كلها تعتمد على تحويل الفوتونات الساقطة إلى تيار كهربائي عبر الظاهرة الكهروضوئية.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري متكرر جداً، الدور الثالث 2023 · الدور الثاني 2018 وغيرها) ما النظرة الحديثة لطبيعة الضوء؟","answer":"طبيعة مزدوجة: موجة بالتداخل والحيود، وجسيم (فوتون) بالظاهرة الكهروضوئية — الضوء له طبيعة مزدوجة (ثنائية): يسلك سلوك الموجات بالتداخل والحيود والاستقطاب، وسلوك الجسيمات (الفوتونات) بالظاهرة الكهروضوئية.","type":"سؤال","ministerial":true},{"question":"ما زخم فوتون طاقته E؟","answer":"p = E/c — من p=h/λ وE=hc/λ، نستنتج p=E/c مباشرة.","type":"سؤال","ministerial":false},{"question":"فوتون طوله الموجي λ=2nm. جد زخمه تقريباً (h=6.63×10⁻³⁴J.s).","answer":"≈3.32×10⁻²⁵ kg·m/s — p = h/λ = (6.63×10⁻³⁴)/(2×10⁻⁹) ≈ 3.32×10⁻²⁵ kg·m/s.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري مركّب — زخم الفوتون + الكهروضوئية) سقط ضوء زخم فوتونه 3.32×10⁻²⁷kg·m/s على الصوديوم، فكانت KE_max=2.75×10⁻¹⁹J. جد دالة الشغل للصوديوم.","answer":"≈7.21×10⁻¹⁹ J — E=pc=3.32×10⁻²⁷×3×10⁸=9.96×10⁻¹⁹J. W₀=E−KE_max=9.96×10⁻¹⁹−2.75×10⁻¹⁹=7.21×10⁻¹⁹J.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2018) ما المقصود بـ: فرضية دي برولي؟","answer":"لكل جسيم مادي متحرك سلوك موجي مرافق، طوله الموجي λ=h/mv — فرضية دي برولي: لكل جسيم مادي متحرك (كتلته m وسرعته v) سلوك موجي مرافق طوله λ=h/mv=h/p.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2017) إلكترون يتحرك بانطلاق 6×10⁶m/s. جد طول موجة دي برولي المرافقة له تقريباً.","answer":"≈1.21×10⁻¹⁰ m — λ=h/mv=(6.63×10⁻³⁴)/(9.11×10⁻³¹×6×10⁶)≈1.21×10⁻¹⁰m — نحو نصف قطر ذرة الهيدروجين تقريباً.","type":"سؤال","ministerial":true},{"question":"إلكترون عُجِّل من السكون بفرق جهد V=100V. جد طول موجة دي برولي المرافقة له تقريباً.","answer":"≈0.123 nm — v=√(2eV/m)≈5.93×10⁶m/s، ثم λ=h/(mv)≈1.23×10⁻¹⁰m=0.123nm.","type":"سؤال","ministerial":false},{"question":"لماذا لا نلاحظ أي سلوك موجي محسوس لكرة متحركة رغم انطباق فرضية دي برولي عليها نظرياً؟","answer":"كتلتها كبيرة جداً مقارنة بثابت بلانك، فطول موجتها المرافق ضئيل جداً يستحيل رصده — λ=h/mv يتناسب عكسياً مع الكتلة؛ كتلة الكرة الكبيرة تجعل λ أصغر من نواة الذرة بمراحل، فلا يمكن رصده.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، الدور الأول 2019) علامَ تدل قيمة كبيرة لـ|ψ|² لجسيم بمكان وزمان معيّنين؟","answer":"على احتمالية كبيرة للعثور على الجسيم في ذلك المكان وتلك اللحظة — تفسير بورن الاحتمالي: كثافة الاحتمال |ψ|² تتناسب طردياً مع احتمالية العثور على الجسيم في تلك المنطقة وتلك اللحظة.","type":"سؤال","ministerial":true},{"question":"بالوصف الكمّي الحديث لذرة الهيدروجين (بعكس نموذج بور)، كيف يوصف موضع الإلكترون؟","answer":"بسحابة احتمال |ψ|² حول النواة، لا بمدار دائري محدد الشكل بدقة تامة — الوصف الكمي يستبدل مدار بور الحاد بسحابة احتمال ضبابية |ψ|²، أعلى كثافة قرب نصف قطر بور الكلاسيكي لكن مع احتمال ضئيل بمناطق أخرى.","type":"سؤال","ministerial":false},{"question":"ما الصيغة الرياضية الصحيحة لمبدأ هايزنبرغ للادقة؟","answer":"Δx · Δp ≥ h/4π — حاصل ضرب اللادقة بالموضع Δx واللادقة بالزخم Δp لا يقل أبداً عن h/4π.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، التمهيدي 2018 · الدور الثالث 2019) ما المقصود بـ: مبدأ اللادقة لهايزنبرك؟","answer":"استحالة تحديد موضع الجسيم وزخمه بدقة تامة في الوقت نفسه — مبدأ اللادقة: يستحيل تحديد موضع الجسيم وزخمه بدقة تامة بآنٍ واحد؛ حاصل ضرب اللادقتين لا يقل عن h/4π.","type":"سؤال","ministerial":true},{"question":"(اختيار وزاري، التمهيدي 2019) إذا قيس موضع جسيم بدقة تامة (Δx=0)، فإن أقل دقة لزخمه تساوي:","answer":"ما لا نهاية — من Δx·Δp≥h/4π، إذا Δx=0 فلا بد أن يؤول Δp إلى ما لا نهاية — أي انعدام الدقة كلياً بمعرفة الزخم.","type":"سؤال","ministerial":true},{"question":"بروتون محصور بمنطقة عرضها Δx=5×10⁻¹⁵m (بحجم النواة). جد أدنى لادقة ممكنة بزخمه Δp تقريباً.","answer":"≈1.05×10⁻²⁰ kg·m/s — Δp_min = h/(4πΔx) = (6.63×10⁻³⁴)/(4π×5×10⁻¹⁵) ≈ 1.05×10⁻²⁰ kg·m/s.","type":"سؤال","ministerial":false},{"question":"بنفس المسألة أعلاه (Δp_min≈1.05×10⁻²⁰kg·m/s) وكتلة البروتون 1.67×10⁻²⁷kg، جد أدنى لادقة ممكنة بسرعته.","answer":"≈6.3×10⁶ m/s — Δv_min = Δp_min/m = (1.05×10⁻²⁰)/(1.67×10⁻²⁷) ≈ 6.3×10⁶ m/s — كبيرة رغم أن البروتون أثقل من الإلكترون بـ1836 مرة، لأن الحصر هنا بمقياس نووي دقيق جداً.","type":"سؤال","ministerial":false},{"question":"ماذا تعني الصيغة المرافقة لمبدأ اللادقة: ΔE·Δt≥h/4π؟","answer":"كلما قصرت مدة قياس طاقة نظام ما، كبرت اللادقة بقيمة تلك الطاقة بالضرورة — علاقة اللادقة بين الطاقة والزمن: قياس طاقة نظام خلال فترة قصيرة جداً يترافق حتماً بلادقة كبيرة بقيمة تلك الطاقة.","type":"سؤال","ministerial":false},{"question":"لماذا لا يُعدّ مبدأ اللادقة لهايزنبرغ قصوراً تقنياً يمكن حله بجهاز قياس أدق مستقبلاً؟","answer":"لأنه نتيجة حتمية للطبيعة الموجية الأساسية للجسيمات نفسها، لا لعيب بأي جهاز قياس — اللادقة نابعة من كون الجسيم موجة ممتدة بالفضاء أصلاً (فرضية دي برولي)، فلا يمكن لأي جهاز — مهما تطوّر — أن يتجاوز هذا القيد الطبيعي الأساسي.","type":"سؤال","ministerial":false},{"question":"رتّب هذه الاكتشافات حسب تسلسلها الزمني الصحيح: فرضية بلانك، تفسير أينشتاين الكهروضوئي، فرضية دي برولي، مبدأ هايزنبرغ.","answer":"بلانك (1900) ← أينشتاين (1905) ← دي برولي (1923) ← هايزنبرغ (1927) — التسلسل التاريخي الصحيح: بلانك 1900 (فرضية الكم) ← أينشتاين 1905 (الظاهرة الكهروضوئية) ← دي برولي 1923 (الموجات المادية) ← هايزنبرغ 1927 (مبدأ اللادقة).","type":"سؤال","ministerial":false},{"question":"ما القاسم المشترك بين القوانين الرئيسية بهذا الفصل: E=hf، hf=W₀+KE_max، p=h/λ، λ=h/mv، وΔx·Δp≥h/4π؟","answer":"تحتوي جميعها على ثابت بلانك h، مؤكدة أنه المفتاح الأساسي للفيزياء الحديثة — ثابت بلانك h يظهر بكل قوانين هذا الفصل — من تكميم الطاقة، إلى الظاهرة الكهروضوئية، إلى زخم الفوتون والموجات المادية، إلى مبدأ اللادقة.","type":"سؤال","ministerial":false},{"question":"الفوتون والإلكترون كلاهما يُظهران ثنائية موجة-جسيم. ما وجه الشبه المفاهيمي الدقيق بينهما بهذا الفصل؟","answer":"كل منهما يملك خاصية جسيمية (طاقة أو زخم) مرتبطة بخاصية موجية (تردد أو طول موجي) عبر ثابت بلانك h نفسه — للفوتون: E=hf وp=h/λ. للإلكترون (وأي جسيم مادي): λ=h/p. نفس ثابت بلانك h يربط الصفتين الجسيمية والموجية بكلا الحالتين.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، الدور الأول 2021 · التمهيدي 2018) ما الذي أضافته النظرية النسبية للمفاهيم الكلاسيكية؟","answer":"الزمن كبُعدٍ رابع يتشابك مع الأبعاد المكانية الثلاثة، بدلاً من كونه كمّية مطلقة منفصلة — أضافت النظرية النسبية الزمن كبُعد رابع (x,y,z,t) متشابك مع المكان — لا كمّية مطلقة منفصلة كما بالفيزياء الكلاسيكية.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2022–2023 · الدور الأول 2020 · الدور الثاني التكميلي 2021) ما هما فرضيتا آينشتاين في النظرية النسبية الخاصة؟","answer":"مبدأ النسبية (قوانين الفيزياء واحدة بكل الأطر العطالية) وثبات سرعة الضوء لكل المراقبين — الفرضية الأولى: قوانين الفيزياء واحدة بجميع الأطر العطالية. الفرضية الثانية: سرعة الضوء بالفراغ (3×10⁸m/s) ثابتة لجميع المراقبين.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري، التمهيدي 2022) ما المقصود بتحويلات لورنتز؟","answer":"معادلات تربط إحداثيات الحدث (الموقع والزمن) بين إطارين عطاليين يتحرك أحدهما بالنسبة للآخر بسرعة v — تحويلات لورنتز تربط إحداثيات الحدث كما يقيسها مراقبان بإطارين عطاليين مختلفين، وتحلّ محلّ تحويلات غاليليو الكلاسيكية.","type":"سؤال","ministerial":true},{"question":"ما الصيغة الرياضية الصحيحة لعامل لورنتز γ؟","answer":"γ = 1/√(1 − v²/c²) — γ = 1/√(1−v²/c²) — يساوي 1 عند السكون تقريباً، ويكبر بلا حدود كلما اقتربت v من c.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري، 2013 · 2016 و2017 خارج القطر · التطبيقي 2019) ما الفرق الأساسي بين تحويلات غاليليو والتحويلات النسبية (لورنتز)؟","answer":"المقدار γ (عامل لورنتز)، الذي يؤثر بزخم الجسم وطوله وكتلته والزمن المقاس له — تحويلات غاليليو لا تتضمّن γ إطلاقاً (تفترض زمناً وطولاً وكتلة مطلقة)، بينما تحويلات لورنتز تُدخله فيؤثر على هذه المقادير عند السرعات القريبة من سرعة الضوء.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — اختيار من متعدد) سفينة فضائية طولها بالسكون 40m تتحرك بسرعة 0.8c. كم يصبح طولها كما يقيسه مراقب ساكن على الأرض؟","answer":"24 m — L=L₀√(1−v²/c²)=40×√(1−0.64)=40×0.6=24 m.","type":"سؤال","ministerial":true},{"question":"جسيم كتلته بالسكون m₀=2kg يتحرك بسرعة v=0.6c. جد كتلته النسبية كما يقيسها مراقب ساكن.","answer":"2.5 kg — γ=1/√(1−0.36)=1/0.8=1.25. m=m₀γ=2×1.25=2.5 kg.","type":"سؤال","ministerial":false},{"question":"إذا تحوّلت كتلة مقدارها 1 gram بالكامل إلى طاقة وفق E=mc²، فما مقدار هذه الطاقة تقريباً؟","answer":"≈9×10¹³ J — E=mc²=1×10⁻³×(3×10⁸)²=1×10⁻³×9×10¹⁶=9×10¹³ J — طاقة تكفي بيتاً عراقياً نحو ألفي سنة!","type":"سؤال","ministerial":false},{"question":"لماذا يستحيل عملياً أن يبلغ جسمٌ له كتلة سكون سرعة الضوء؟","answer":"لأن عامل لورنتز γ يؤول إلى ما لا نهاية عند v→c، فتزداد كتلته النسبية بلا حدود وتحتاج طاقة غير منتهية لتسريعه أكثر — بما أن m=m₀γ وγ يكبر بلا حدود عند v→c، تحتاج زيادة سرعة الجسم أكثر إلى طاقة غير منتهية — مستحيل عملياً بأي مصدر طاقة محدود.","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":1,"lesson_title":"مقدمة ومستويات الطاقة في الذرة","order_index":1,"hook":"هذا الفصل هو الجسر بين فيزياء الذرة (الفصل السادس) وبين كل جهاز إلكتروني تستعمله يومياً. ستكتشف كيف تتحوّل بلورة سيليكون عادية — أحد أكثر العناصر توفراً على الأرض — إلى \"دماغ\" كل حاسوب وهاتف ذكي، فقط بالتحكّم الدقيق بحركة الإلكترونات داخلها.","concepts":[{"term":"المستوى الأرضي والمستوى المثار:","text":"في حالتها الطبيعية المستقرة، تشغل إلكترونات الذرة أخفض مستويات الطاقة المتاحة (المستوى الأرضي). إذا اكتسبت الذرة طاقة كافية (من فوتون أو تصادم)، يمكن لإلكترون أن \"يقفز\" إلى مستوى أعلى (مستوى مثار) — بشرط أن تساوي الطاقة الممتصة بالضبط الفرق بين المستويين، لا أقل ولا أكثر.","ministerial":false},{"term":"غلاف التكافؤ وإلكترونات التكافؤ:","text":"يُسمى الغلاف الخارجي الأبعد عن النواة غلاف التكافؤ (Valence shell)، وإلكتروناته إلكترونات التكافؤ (Valence electrons). ولأنها الأعلى طاقةً والأضعف ارتباطاً، فهي التي تُسهم في التفاعلات الكيميائية وتحدّد الخواص الكهربائية والإلكترونية للمادة — وهي بالضبط ما سيهمّنا طوال هذا الفصل.","ministerial":false},{"term":"انشطار مستويات الطاقة:","text":"وفق مبدأ باولي للاستبعاد، لا يمكن لإلكترونين متطابقين تماماً بنفس البلورة أن يشغلا نفس مستوى الطاقة بالضبط. لذلك، حين تتقارب N ذرة، ينشطر كل مستوى طاقة أصلي (كان مشتركاً بين الذرات المنفصلة) إلى N مستوى متقارب جداً بدلاً منه — لكل ذرة \"نسختها\" الخاصة المزاحة بمقدار طفيف جداً.","ministerial":false}],"laws":[],"notes":[{"heading":"🏆 لماذا غيّر الترانزستور العالم؟","items":["أصغر حجماً، أخف وزناً، يستهلك طاقة أقل بكثير، لا يحتاج وقت إحماء، عمره الافتراضي أطول جداً (لا فتيل يحترق)، وقابل للتصنيع بأعداد هائلة وبتكلفة منخفضة جداً على شريحة واحدة (الدارة المتكاملة).","هذا بالضبط ما سمح بتقليص حاسوب بحجم غرفة إلى معالج أصغر من ظفر إصبعك."],"ministerial":false},{"heading":"📏 اصطلاح قياس الطاقة: لماذا سالبة؟","items":["نقيس طاقة الإلكترون بالإلكترون-فولت (eV) نسبةً إلى مستوى الطاقة الصفري (E=0)، وهو أعلى مستوى ممكن — عنده يكون الإلكترون قد تحرّر تماماً من جذب النواة.","لذلك تكون طاقة أي إلكترون مقيّد داخل الذرة سالبة دوماً.","مثال: أقل طاقة ممكنة لإلكترون ذرة الهيدروجين (مستواها الأرضي) تساوي −13.6 eV — أي يحتاج اكتساب +13.6 eV بالضبط ليتحرر كلياً من الذرة."],"ministerial":false}],"tables":[],"examples":[{"problem":"الفرق بين مستويي طاقة في ذرة معيّنة يساوي 2eV. جد الطول الموجي للفوتون اللازم بالضبط لنقل إلكترون من المستوى الأدنى إلى المستوى الأعلى.","givens":"المعطيات: ΔE=2eV=2×1.6×10⁻¹⁹J — h=6.63×10⁻³⁴J.s — c=3×10⁸m/s","solution_steps":["الخطوة ١: نحوّل الطاقة إلى الجول: ΔE = 2 × 1.6×10⁻¹⁹ = 3.2×10⁻¹⁹ J","الخطوة ٢: نطبّق العلاقة E=hc/λ ونحل لإيجاد λ: λ = hc/ΔE = (6.63×10⁻³⁴ × 3×10⁸) / (3.2×10⁻¹⁹) ≈ 6.22×10⁻⁷ m = 622 nm 💡 هذا الطول الموجي يقع في مدى الضوء الأحمر المرئي — نفس المبدأ (E=hf=hc/λ) الذي درسته بالفصل السادس يحكم أيضاً كل قفزة إلكترون بين مستويي طاقة، سواء داخل ذرة مفردة أو — كما سترى بالدرس القادم — داخل بلورة كاملة."],"ministerial":false}],"qa":[{"question":"استُبدلت الصمامات المفرغة بالترانزستورات في تصنيع الأجهزة الإلكترونية الحديثة.","answer":"لأن الترانزستور (نبيطة الحالة الصلبة) أصغر حجماً بكثير، أقل استهلاكاً للطاقة، لا يحتاج فتيلاً ساخناً ولا وقت إحماء، أطول عمراً وأكثر متانة، وقابل للتصنيع الكثيف على شريحة واحدة (دارة متكاملة) — بعكس الصمام المفرغ الكبير الحجم، عالي استهلاك الطاقة، سريع الاحتراق.","type":"علل","ministerial":false},{"question":"ما الفرق بين مستويات الطاقة في الذرة المفردة ومستويات الطاقة في البلورة الصلبة؟","answer":"في الذرة المفردة المعزولة: مستويات طاقة منفصلة وحادّة، متباعدة بوضوح عن بعضها. في البلورة الصلبة (عدد هائل من الذرات المتقاربة): ينشطر كل مستوى أصلي إلى عدد هائل من المستويات شديدة التقارب، تندمج بصرياً معاً لتُكوّن ما يُسمى \"حزمة طاقة\" (Energy Band) تقريباً مستمرة، بدلاً من مستوى واحد حاد.","type":"قارن","ministerial":false}],"has_simulation":true,"simulation_title":"🔬 مختبر: من مستوى طاقة إلى حزمة طاقة"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":2,"lesson_title":"حزم الطاقة — الموصلات والعوازل وأشباه الموصلات","order_index":2,"hook":"بالدرس السابق رأيت كيف تنشطر مستويات الطاقة إلى \"حزم\" عند تقارب عدد هائل من الذرات. اليوم ستستعمل هذه الفكرة بالضبط لتفسّر أحد أهم تصنيفات المواد في الفيزياء والهندسة كلها: لماذا هذه المادة موصل، وتلك عازل، وثالثة \"شبه\" موصل؟","concepts":[{"term":"حزمة التكافؤ (Valence Band):","text":"حزمة الطاقة التي تشغلها إلكترونات التكافؤ (الإلكترونات الخارجية) للذرات وهي مرتبطة بأماكنها ضمن الروابط بين الذرات. إلكترونات هذه الحزمة عادة لا تساهم في التوصيل الكهربائي طالما بقيت فيها.","ministerial":false},{"term":"حزمة التوصيل (Conduction Band):","text":"حزمة الطاقة الأعلى من حزمة التكافؤ. أي إلكترون يصل إلى هذه الحزمة يصبح حراً تماماً من قيد أي ذرة معيّنة، وينتقل بسهولة عبر البلورة تحت تأثير مجال كهربائي — أي يُسهم في التيار الكهربائي.","ministerial":false},{"term":"الفجوة الطاقية المحرمة (Forbidden Energy Gap, Eg):","text":"المدى من الطاقة الواقع بين أعلى حزمة التكافؤ وأسفل حزمة التوصيل، حيث لا يوجد أي مستوى طاقة مسموح للإلكترون أن يشغله إطلاقاً. لكي \"يقفز\" إلكترون من حزمة التكافؤ إلى حزمة التوصيل، يجب أن يكتسب طاقة لا تقل عن Eg بالضبط.","ministerial":false}],"laws":[],"notes":[],"tables":[{"caption":"🔷 أشباه الموصلات (Semiconductors)","ministerial":false,"headers":["الخاصية","موصل","شبه موصل","عازل"],"rows":[["الفجوة الطاقية Eg","≈ صفر (تراكب الحزمتين)","صغيرة (~0.1–3eV تقريباً)","كبيرة (>3eV غالباً)"],["مثال حقيقي","نحاس، فضة، ألمنيوم","سيليكون (1.12eV)، جرمانيوم (0.67eV)","مطاط، زجاج، ماس (~5.5eV)"],["التوصيلية الكهربائية","عالية جداً","متوسطة، قابلة للتحكم","شبه معدومة"],["المقاومة النوعية (Ω·m)","10⁻⁸ – 10⁻⁵","10⁻⁵ – 10⁸","10¹⁰ – 10¹⁶"]]}],"examples":[{"problem":"فجوة الطاقة المحرمة للسيليكون Eg=1.12eV. جد أطول طول موجي لفوتون ضوئي قادر على نقل إلكترون من حزمة التكافؤ إلى حزمة التوصيل في السيليكون.","givens":"المعطيات: Eg=1.12eV=1.12×1.6×10⁻¹⁹J — h=6.63×10⁻³⁴J.s — c=3×10⁸m/s","solution_steps":["الخطوة ١: نحوّل الفجوة إلى الجول: Eg = 1.12 × 1.6×10⁻¹⁹ ≈ 1.79×10⁻¹⁹ J","الخطوة ٢: نطبّق العلاقة λ_max=hc/Eg (أقل طاقة ممكنة = أطول طول موجي ممكن): λ_max = (6.63×10⁻³⁴ × 3×10⁸) / (1.79×10⁻¹⁹) ≈ 1.11×10⁻⁶ m = 1110 nm 💡 هذا يقع في مدى تحت الأحمر القريب — أي طول موجي أطول من هذا (طاقة أقل من Eg) لن يستطيع \"قفز\" الفجوة إطلاقاً، مهما طالت مدة سقوط الضوء. هذا يفسّر أيضاً لماذا تُصمَّم الخلايا الشمسية بمواد فجوتها الطاقية قريبة من ذروة طيف الشمس المرئي."],"ministerial":false}],"qa":[{"question":"ما الفرق بين حزمة التكافؤ وحزمة التوصيل في المواد الصلبة؟","answer":"حزمة التكافؤ: حزمة الطاقة الواطئة، مملوءة كلياً أو جزئياً بالإلكترونات (إلكترونات التكافؤ)، وهذه الإلكترونات مرتبطة بقوى كبيرة نسبياً بالنواة. حزمة التوصيل: حزمة الطاقة العالية الأعلى من حزمة التكافؤ، وإلكتروناتها (إلكترونات التوصيل) تتمكّن من الانتقال بسهولة لتشارك في عملية التوصيل الكهربائي.","type":"وزاري","ministerial":true},{"question":"علّل: تقلّ قابلية التوصيل الكهربائي في المواد الموصلة (المعادن) بارتفاع درجة حرارتها.","answer":"لأن ارتفاع درجة الحرارة يزيد المعدّل الزمني للطاقة الاهتزازية لذرّات المعدن، فتزداد اهتزازات الشبيكة البلورية وتعترض حركة الإلكترونات الحرة وتعيقها، مما يؤدّي إلى ازدياد مقاومتها الكهربائية ومن ثمّ نقصان قابلية التوصيل الكهربائي.","type":"وزاري","ministerial":true},{"question":"بماذا تتصف (تتميّز) حزم الطاقة في المواد العازلة؟","answer":"تتّصف حزم الطاقة في المواد العازلة بأن: ① حزمة التكافؤ مملوءة بالإلكترونات (إلكترونات التكافؤ). ② حزمة التوصيل خالية من الإلكترونات. ③ ثغرة الطاقة المحظورة بينهما واسعة نسبياً (حوالي 5eV أو أكثر)، لذا لا تتمكّن إلكترونات التكافؤ من عبورها والانتقال إلى حزمة التوصيل، فلا تمتلك المادة العازلة قابلية توصيل كهربائي.","type":"وزاري","ministerial":true},{"question":"يزداد التيار المار بقطعة من السيليكون النقي عند تسخينها، بعكس السلك النحاسي الذي تقل قابليته للتوصيل عند تسخينه.","answer":"في السيليكون (شبه موصل)، ترفع الحرارة الزائدة عدد الإلكترونات القادرة على قفز الفجوة الطاقية Eg الصغيرة نسبياً إلى حزمة التوصيل، فيزداد عدد حاملات الشحنة الحرة ويزداد التيار. أما في النحاس (موصل)، فعدد الإلكترونات الحرة كبير أصلاً وثابت تقريباً؛ ترفع الحرارة فقط اهتزاز الأيونات بالبلورة، فتزيد تصادم الإلكترونات معها وتُعيق حركتها — أي تزداد المقاومة ويقل التيار. سنعود لهذا التفصيل بعمق أكبر بالدرس القادم.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 مختبر: مصنّف المواد بحسب فجوتها الطاقية"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":3,"lesson_title":"أشباه الموصلات النقية","order_index":3,"hook":"هذا الدرس يشرح \"الحالة الافتراضية\" لبلورة شبه موصل نقي 100% (بلا أي إضافات)، تمهيداً للدرس القادم حيث نتعمّد \"تلويث\" هذه البلورة بعناصر أخرى للتحكم بتوصيليتها بدقة متناهية.","concepts":[{"term":"الفجوة (Hole):","text":"ليست جسيماً حقيقياً، بل مكان شاغر في رابطة تساهمية بعد هروب إلكترونها. لكنها تتصرف عملياً وكأنها جسيم موجب الشحنة: فحين \"يقفز\" إلكترون من رابطة مجاورة سليمة ليملأ هذه الفجوة، يترك بدوره فجوة جديدة مكانه — وكأن الفجوة \"تحركت\" بالاتجاه المعاكس لحركة الإلكترونات! هذه الحركة الظاهرية للفجوات تُسهم فعلياً بالتيار الكهربائي، تماماً كحركة الإلكترونات الحرة.","ministerial":false},{"term":"تيار الإلكترونات:","text":"الإلكترونات الحرة بحزمة التوصيل تُجذَب نحو الطرف الموجب للمجال (بعكس اتجاه المجال).","ministerial":false},{"term":"تيار الفجوات:","text":"الفجوات الموجبة بحزمة التكافؤ تتحرك باتجاه المجال المسلّط نفسه (عكس حركة الإلكترونات).","ministerial":false},{"term":"مستوى فيرمي (Fermi Level):","text":"أعلى مستوى طاقة مسموح به يمكن أن يشغله الإلكترون عند درجة حرارة الصفر المطلق (0K).","ministerial":false},{"term":"في الموصلات:","text":"يقع مستوى فيرمي عند 0K فوق المنطقة المملوءة بالإلكترونات من حزمة التوصيل مباشرة.","ministerial":false},{"term":"في أشباه الموصلات النقية:","text":"يقع مستوى فيرمي في منتصف ثغرة الطاقة المحظورة، بين حزمة التوصيل وحزمة التكافؤ بالضبط.","ministerial":false}],"laws":[{"name":"في شبه الموصل النقي (الذاتي): ينتج كل رابطة منكسرة إلكتروناً حراً واحداً وفجوة واحدة معاً","formula":"n (تركيز الإلكترونات الحرة) = p (تركيز الفجوات) = nᵢ","variables_note":""},{"name":"التيار الكلي المنساب خلال شبه الموصل النقي = مجموع تيار الإلكترونات وتيار الفجوات معاً — وتُسمى كل من الإلكترونات والفجوات حوامل الشحنة (Charge Carriers).","formula":"","variables_note":""}],"notes":[{"heading":"🥶 عند الصفر المطلق (0K):","items":["كل الإلكترونات محبوسة تماماً داخل روابطها التساهمية، ولا يوجد إلكترون حر واحد.","لذلك تتصرف بلورة شبه الموصل النقي عند هذه الدرجة كعازل تقريباً تام — بلا أي توصيل كهربائي يُذكر."],"ministerial":false},{"heading":"📉 ملاحظة:","items":["يقلّ مقدار الفجوة الطاقية المحرمة في شبه الموصل النقي بارتفاع درجة حرارته فوق الصفر المطلق حتى درجة حرارة الغرفة — لاحظ من الجدول أن فجوة كلٍّ من السيليكون والجرمانيوم أصغر قليلاً عند 300K مقارنةً بـ0K."],"ministerial":false},{"heading":"👀 لاحقاً:","items":["عند تطعيم شبه الموصل النقي بشوائب (الدرس القادم)، ينزاح موقع مستوى فيرمي نحو الأعلى أو الأسفل تبعاً لنوع الشائبة المضافة."],"ministerial":false}],"tables":[{"caption":"🌡️ التوليد الحراري لزوج إلكترون-فجوة","ministerial":false,"headers":["المادة","الفجوة الطاقية عند 0K","الفجوة الطاقية عند 300K (الغرفة)"],"rows":[["السيليكون النقي (Si)","1.2 eV","1.1 eV"],["الجرمانيوم النقي (Ge)","0.78 eV","0.72 eV"]]}],"examples":[{"problem":"قِيس تركيز الإلكترونات الحرة في بلورة سيليكون نقي عند درجة حرارة الغرفة فوُجد 1.5×10¹⁶ إلكترون/m³. جد تركيز الفجوات في نفس البلورة، ووضّح السبب.","givens":"المعطيات: n=1.5×10¹⁶ إلكترون/m³ (بلورة نقية/ذاتية)","solution_steps":["الخطوة ١: نتذكر خاصية شبه الموصل النقي: كل رابطة تساهمية منكسرة تولّد إلكتروناً حراً وفجوة معاً، بالتساوي دوماً: p = n","الخطوة ٢: إذن: p = 1.5×10¹⁶ فجوة/m³ 💡 هذا التساوي (n=p=nᵢ) هو بالضبط التعريف العملي لـ\"النقاء\" أو الذاتية (Intrinsic) — وسيختل هذا التوازن عمداً بالدرس القادم عندما \"نطعّم\" البلورة."],"ministerial":false}],"qa":[{"question":"هل يمكن جعل شبه الموصل النقي (السيليكون مثلاً) يمتلك قابلية توصيل كهربائي بوساطة التأثير الحراري؟ وضّح ذلك.","answer":"نعم يمكن. عند رفع درجة حرارة السيليكون النقي إلى درجة حرارة الغرفة (300K)، تكتسب إلكترونات التكافؤ طاقة حرارية كافية لكسر بعض الأواصر التساهمية والانتقال من حزمة التكافؤ إلى حزمة التوصيل عبر ثغرة الطاقة المحظورة، فتتولّد أزواج (إلكترون–فجوة) تعمل حواملَ شحنة، فيمتلك السيليكون قابلية توصيل كهربائي.","type":"وزاري","ministerial":true},{"question":"علامَ يعتمد المعدّل الزمني لتوليد الأزواج (إلكترون–فجوة) في شبه الموصل النقي؟","answer":"يعتمد على: ① درجة حرارة شبه الموصل (كلّما ارتفعت، ازداد معدّل التوليد). ② نوع مادة شبه الموصل (سيليكون أم جرمانيوم — لاختلاف ثغرة الطاقة المحظورة بينهما).","type":"وزاري متكرر","ministerial":true},{"question":"ما المقصود بمستوى فيرمي؟ وما موقعه في الموصلات وفي شبه الموصل النقي؟","answer":"مستوى فيرمي: أعلى مستوى طاقة مسموح به يمكن أن يشغله الإلكترون عند درجة حرارة الصفر المطلق (0K). موقعه: في الموصلات يقع فوق المنطقة المملوءة بالإلكترونات (ضمن حزمة التوصيل). وفي شبه الموصل النقي يقع في منتصف ثغرة الطاقة المحظورة بين حزمة التوصيل وحزمة التكافؤ.","type":"وزاري متكرر","ministerial":true},{"question":"«في الموصلات وعند درجة (0K) تكون مستويات الطاقة التي تقع تحت مستوى فيرمي مشغولة بالإلكترونات».","answer":"العبارة صحيحة. فمستوى فيرمي هو أعلى مستوى يشغله الإلكترون عند 0K، لذا كل المستويات التي تقع تحته تكون مشغولة بالإلكترونات، والتي فوقه تكون خالية.","type":"صح أو خطأ · وزاري","ministerial":true},{"question":"تزداد التوصيلية الكهربائية لشبه الموصل النقي بارتفاع درجة الحرارة.","answer":"لأن ارتفاع درجة الحرارة يزوّد ذرات البلورة بطاقة اهتزازية أكبر، فتنكسر روابط تساهمية أكثر، وينتج عدد أكبر من أزواج الإلكترونات الحرة والفجوات معاً. زيادة عدد حاملات الشحنة الحرة (من النوعين) تعني مروراً أسهل للتيار — أي توصيلية أعلى.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🌡️ مختبر: التوليد الحراري في بلورة نقية"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":4,"lesson_title":"أشباه الموصلات المطعّمة","order_index":4,"hook":"بإضافة ذرة شائبة واحدة فقط لكل نحو 10⁸ (مئة مليون) ذرة سيليكون، يمكن رفع توصيلية البلورة آلاف المرات، والتحكم بنوع حامل الشحنة السائد فيها بدقة تامة. هذا بالضبط ما يجعل شبه الموصل \"قابلاً للهندسة\" — على عكس الموصل والعازل الثابتين.","concepts":[{"term":"النوع n (Donor / مانح):","text":"نطعّم السيليكون بعنصر خماسي التكافؤ (٥ إلكترونات تكافؤ، كالزرنيخ As أو الفوسفور P). تكوّن ٤ من إلكتروناته الخمسة روابط تساهمية طبيعية مع ٤ ذرات سيليكون مجاورة، بينما يبقى الإلكترون الخامس زائداً — مرتبط بذرة الشائبة بضعف شديد فقط، فيتحرر بسهولة فائقة ليصبح إلكتروناً حراً حتى بحرارة الغرفة العادية. تُسمى ذرة الشائبة هنا ذرة مانحة لأنها \"تمنح\" إلكتروناً حراً إضافياً للبلورة، من دون أن تترك فجوة مقابلة له.","ministerial":false},{"term":"النوع p (Acceptor / مستقبِل):","text":"نطعّم السيليكون بعنصر ثلاثي التكافؤ (٣ إلكترونات تكافؤ فقط، كالبورون B أو الغاليوم Ga). يكوّن إلكتروناته الثلاثة روابط تساهمية طبيعية مع ٣ ذرات سيليكون مجاورة فقط، بينما تبقى الرابطة الرابعة ناقصة إلكتروناً — أي فجوة جاهزة منذ البداية، بلا حاجة لأي طاقة حرارية لتوليدها! تُسمى ذرة الشائبة هنا ذرة مستقبِلة لأنها جاهزة \"لاستقبال\" إلكترون من رابطة مجاورة لتملأ هذه الفجوة.","ministerial":false},{"term":"المستوى المانح (Donor Level) — النوع n:","text":"مستوى طاقة جديد يقع ضمن الفجوة المحظورة، تحت حزمة التوصيل مباشرة. يرتفع مستوى فيرمي نحو الأعلى ويقترب من حزمة التوصيل.","ministerial":false},{"term":"المستوى القابل (Acceptor Level) — النوع p:","text":"مستوى طاقة جديد يقع ضمن الفجوة المحظورة، فوق حزمة التكافؤ مباشرة. ينخفض مستوى فيرمي نحو الأسفل ويقترب من حزمة التكافؤ.","ministerial":false}],"laws":[],"notes":[{"heading":"⚖️ نقطة دقيقة مهمة جداً","items":["رغم أن النوع n يحوي فائضاً من الإلكترونات الحرة والنوع p يحوي فائضاً من الفجوات، تبقى كل قطعة مطعّمة (n أو p) متعادلة كهربائياً تماماً ككل!","فذرة الشائبة نفسها (سواء مانحة أو مستقبِلة) ذرة متعادلة الشحنة أصلاً — لم \"نُضِف\" أي شحنة صافية للبلورة، بل غيّرنا فقط توزيع الإلكترونات والفجوات المتاحة للحركة الحرة داخلها."],"ministerial":false}],"tables":[{"caption":"⚗️ التطعيم: لماذا ولماذا نوعان فقط؟","ministerial":false,"headers":["الخاصية","النوع n","النوع p"],"rows":[["عنصر التطعيم","خماسي التكافؤ (As, P, Sb)","ثلاثي التكافؤ (B, Ga, In)"],["نوع ذرة الشائبة","مانحة (Donor)","مستقبِلة (Acceptor)"],["حاملات الشحنة الأغلبية","إلكترونات حرة (سالبة)","فجوات (موجبة)"],["حاملات الشحنة الأقلية","فجوات (قليلة جداً، حرارية المنشأ)","إلكترونات حرة (قليلة جداً، حرارية المنشأ)"]]}],"examples":[],"qa":[{"question":"علّل: إذا كان التأثير الحراري في شبه الموصل النقي يزيد قابليته على التوصيل، فلماذا نلجأ إلى تطعيمه بشوائب خماسية أو ثلاثية التكافؤ؟","answer":"لأنه لا يمكن السيطرة على قابلية التوصيل الكهربائي لمادة شبه الموصل النقي بطريقة التأثير الحراري. أما التطعيم فيتيح طريقة عملية أفضل للتحكم في التوصيلية وزيادتها بنسبة كبيرة (وبمعدّل مسيطَر عليه) نتيجة ازدياد حاملات الشحنة بصورة محدّدة.","type":"وزاري","ministerial":true},{"question":"تبقى قطعة السيليكون المطعّمة بالنوع n متعادلة كهربائياً، رغم احتوائها فائضاً كبيراً من الإلكترونات الحرة.","answer":"لأن ذرة الشائبة المانحة (خماسية التكافؤ) نفسها متعادلة الشحنة قبل التطعيم وبعده — عدد بروتونات نواتها يساوي عدد إلكتروناتها دوماً. تحرر الإلكترون الخامس الزائد لا \"يخلق\" شحنة سالبة صافية، بل يجعل هذا الإلكترون حراً بالحركة فقط، بينما تبقى ذرة الشائبة (بعد فقدها هذا الإلكترون) أيوناً موجباً ثابتاً مكانه ضمن البلورة — فيتوازن الصافي الكلي للشحنة عند الصفر.","type":"علل","ministerial":false},{"question":"علّل: الأيون الموجب المتولّد عند إضافة شائبة من نوع المانح لا يُعدّ من حاملات الشحنة.","answer":"لأن الأيون الموجب (الذرّة المانحة بعد أن منحت إلكترونها) يرتبط بالهيكل البلوري ارتباطاً وثيقاً وثابتاً في موقعه، فلا يستطيع الحركة، ومن ثمّ لا يشارك في عملية التوصيل الكهربائي — لذا لا يُعدّ من حاملات الشحنة.","type":"وزاري","ministerial":true},{"question":"هل يمكن أن توجد فجوات في بلورة السيليكون نوع n؟ ولماذا؟","answer":"نعم توجد فجوات، لكنها قليلة وتُعدّ من حاملات الشحنة الأقلية. والسبب أنها تتولّد نتيجة التأثير الحراري (كسر بعض الأواصر التساهمية بالحرارة)، لا من عملية التطعيم — إذ التطعيم بخماسية التكافؤ يزيد الإلكترونات (الأغلبية) فقط.","type":"وزاري","ministerial":true},{"question":"ما المقصود بالمستوى المانح؟ وكيف يتولّد؟","answer":"المستوى المانح: مستوى طاقة جديد يقع ضمن ثغرة الطاقة المحظورة وتحت حزمة التوصيل مباشرة. يتولّد عند تطعيم شبه الموصل النقي بشوائب خماسية التكافؤ (الذرّات المانحة)، وهو المستوى الذي تشغله الإلكترونات (الخامسة) التي حرّرتها الذرّات المانحة قبل انتقالها إلى حزمة التوصيل.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🔵 شبه موصل النوع n"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":5,"lesson_title":"الثنائي pn","order_index":5,"hook":"هذا الدرس يشرح ما يحدث لحظة \"التقاء\" النوعين p وn داخل بلورة واحدة متصلة (لا بلورتين منفصلتين متلامستين). الدرس القادم يشرح ماذا يحدث لهذه الوصلة عند توصيلها ببطارية خارجية.","concepts":[{"term":"منطقة الاستنزاف (Depletion Region):","text":"بعد أن \"تُلغي\" عمليات الانتشار وإعادة الاتحاد حاملات الشحنة الحرة القريبة من الوصلة، تبقى في هذه المنطقة الضيقة فقط أيونات ثابتة (لا تتحرك، لأنها جزء من البلورة نفسها): أيونات مانحة موجبة بجهة n (بعد فقدانها إلكترونها الزائد)، وأيونات مستقبِلة سالبة بجهة p (بعد اكتسابها إلكتروناً). هذه المنطقة خالية عملياً من حاملات الشحنة الحرة — ومن هنا اسمها.","ministerial":false},{"term":"جهد الحاجز (Barrier Potential):","text":"الأيونات الثابتة بمنطقة الاستنزاف تُنشئ مجالاً كهربائياً داخلياً موجّهاً من n نحو p، يُعادل فرق جهد صغيراً يمنع أي انتشار إضافي بمجرد الوصول إلى التوازن. لهذا الجهد قيمة نموذجية معروفة تعتمد على نوع المادة:","ministerial":false}],"laws":[{"name":"ثنائي السيليكون (Si)","formula":"V₀ ≈ 0.7 V","variables_note":""},{"name":"ثنائي الجرمانيوم (Ge)","formula":"V₀ ≈ 0.3 V","variables_note":""}],"notes":[{"heading":"🔌 رمز الثنائي بالدارات","items":["يُرمز للثنائي بسهم مثلث يشير من جهة p (الأنود، Anode) إلى جهة n (الكاثود، Cathode)؛ اتجاه السهم نفسه هو الاتجاه الذي يسمح الثنائي بمرور التيار التقليدي خلاله بسهولة — كما سترى بالدرس القادم."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"علّل: سبب تولّد منطقة الاستنزاف في الثنائي البلوري pn.","answer":"لأن حوامل الأغلبية تنتشر عبر الملتقى: الإلكترونات الحرة من المنطقة N تنتشر إلى المنطقة P، والفجوات من P إلى N، فتلتحم الإلكترونات مع الفجوات القريبة من الملتقى، تاركةً على جانبيه منطقة رقيقة تحتوي أيونات موجبة (في N) وأيونات سالبة (في P) خالية من حاملات الشحنة — هي منطقة الاستنزاف.","type":"وزاري متكرر","ministerial":true},{"question":"علامَ يعتمد مقدار حاجز الجهد الكهربائي في الثنائي البلوري pn؟","answer":"يعتمد على: ① نوع مادة شبه الموصل المستعملة (سيليكون أم جرمانيوم). ② نسبة الشوائب المطعّمة بها. ③ درجة حرارة المادة.","type":"وزاري متكرر","ministerial":true},{"question":"لماذا تُصنَّع الوصلة pn من بلورة واحدة متصلة، لا من قطعتين منفصلتين لـn وp يتم لصقهما ميكانيكياً؟","answer":"لأن تكوّن منطقة الاستنزاف وجهد الحاجز يتطلب استمرارية حقيقية بالبنية البلورية عبر الوصلة (شبكة ذرية متصلة بلا فجوات أو تشوهات بينية)، بحيث تنتشر حاملات الشحنة وتتحد فعلياً عبر حدود دقيقة جداً (أجزاء من الميكرومتر). أي وصلة ميكانيكية بلصق قطعتين منفصلتين تترك سطوحاً غير منتظمة وشوائب تمنع هذا السلوك الدقيق، فلا تُعطي خواص ثنائي عملي.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🧲 مختبر: تكوّن منطقة الاستنزاف"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":6,"lesson_title":"فولطية الانحياز للثنائي pn","order_index":6,"hook":"الانحياز (Biasing) يعني ببساطة: توصيل الثنائي بمصدر جهد خارجي (بطارية). النتيجة تعتمد كلياً على قطبية هذا التوصيل — وجهان لعملة واحدة، بنتيجتين متعاكستين تماماً.","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"🚫 الانحياز العكسي (Reverse Bias)","ministerial":false,"headers":["الخاصية","الانحياز الأمامي","الانحياز العكسي"],"rows":[["توصيل البطارية","+ لجهة p، − لجهة n","+ لجهة n، − لجهة p"],["عرض منطقة الاستنزاف","يضيق تدريجياً","يتّسع تدريجياً"],["المقاومة الفعلية","منخفضة جداً (بعد تجاوز ~0.7V)","عالية جداً"],["التيار","كبير، يزداد بسرعة مع V","شبه معدوم (تيار تسرب ضئيل فقط)"]]}],"examples":[{"problem":"دائرة فيها بطارية 6V موصولة على التوالي مع ثنائي سيليكون (منحاز أمامياً، جهد عتبته V₀=0.7V) ومقاومة R=470Ω. جد التيار المار بالدائرة.","givens":"المعطيات: EMF=6V — V₀=0.7V — R=470Ω","solution_steps":["الخطوة ١: بعد تجاوز العتبة، يُنمذَج الثنائي المنحاز أمامياً بمصدر هبوط جهد ثابت تقريباً V₀. نطبّق قانون فولط على الدارة: EMF = V₀ + IR","الخطوة ٢: نحل لإيجاد التيار: I = (EMF − V₀) / R = (6 − 0.7) / 470 = 5.3 / 470 ≈ 0.0113 A ≈ 11.3 mA 💡 لاحظ أن هبوط الجهد على الثنائي نفسه يبقى ثابتاً تقريباً عند 0.7V بغض النظر عن قيمة التيار (طالما موصولاً أمامياً)؛ كل الفولطية \"الزائدة\" عن هذه العتبة تهبط على المقاومة R وحدها."],"ministerial":false}],"qa":[{"question":"يكاد التيار ينعدم في الثنائي المنحاز عكسياً، رغم وجود حاملات شحنة (أقلية) فيه فعلاً.","answer":"لأن الانحياز العكسي يوسّع منطقة الاستنزاف ويسحب حاملات الشحنة الأغلبية (الكثيرة جداً) بعيداً عن الوصلة تماماً، فلا تسهم في أي تيار. أما حاملات الأقلية (قليلة جداً أصلاً، منشؤها حراري بحت) فهي الوحيدة القادرة على عبور الوصلة بهذا الاتجاه، فينتج عنها تيار تسرب عكسي ضئيل جداً فقط — لا معدوم تماماً، لكنه مهمَل عملياً مقارنة بتيار الانحياز الأمامي.","type":"علل","ministerial":false},{"question":"علّل: انسياب تيار كبير في دائرة الثنائي البلوري pn عندما تزداد فولطية الانحياز بالاتجاه الأمامي.","answer":"لأن اتجاه المجال الكهربائي المسلّط (بالانحياز الأمامي) يكون معاكساً لاتجاه مجال حاجز الجهد وأكبر منه، فتضيق منطقة الاستنزاف ويقلّ حاجز الجهد، وتقلّ مقاومة الملتقى، فتتمكّن حوامل الأغلبية من التغلّب على حاجز الجهد وعبور الملتقى، فينساب تيار كبير.","type":"وزاري","ministerial":true},{"question":"«يزداد مقدار حاجز الجهد في الثنائي البلوري عندما يكون محيّزاً بالاتجاه الأمامي».","answer":"خطأ. التصحيح: يقلّ مقدار حاجز الجهد في الثنائي البلوري عندما يكون محيّزاً بالاتجاه الأمامي (ويزداد في الانحياز العكسي).","type":"صح أو خطأ · وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🔋 مختبر: انحياز الثنائي"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":7,"lesson_title":"بعض أنواع الثنائيات","order_index":7,"hook":"كل نوع أدناه هو ثنائي pn عادي، لكن مصمَّم أو مستعمَل بطريقة خاصة لاستثمار جانب معيّن من سلوكه الذي تعلّمته بالدرس السابق.","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"☀️ ثنائي الخلية الشمسية (Solar Cell)","ministerial":false,"headers":["النوع","الانحياز المستعمَل","أبرز استعمال"],"rows":[["الثنائي المقوّم","أمامي وعكسي بالتناوب (يتبع AC)","تحويل AC إلى DC"],["الثنائي الباعث للضوء LED","أمامي","الإضاءة ومؤشرات الأجهزة الرقمية"],["الثنائي المتحسّس للضوء (Photodiode)","عكسي","كاشفات الضوء وقياس شدته"],["ثنائي الخلية الشمسية (Solar Cell)","عكسي (بلا مصدر جهد خارجي)","تحويل الضوء إلى طاقة كهربائية"]]}],"examples":[{"problem":"ثنائي LED مصنوع من مادة فجوتها الطاقية Eg=1.9eV. جد الطول الموجي التقريبي للضوء المنبعث منه، وحدّد لونه تقريباً.","givens":"المعطيات: Eg=1.9eV=1.9×1.6×10⁻¹⁹J — h=6.63×10⁻³⁴J.s — c=3×10⁸m/s","solution_steps":["الخطوة ١: نحوّل الفجوة إلى الجول: Eg = 1.9 × 1.6×10⁻¹⁹ ≈ 3.04×10⁻¹⁹ J","الخطوة ٢: نطبّق λ=hc/Eg: λ = (6.63×10⁻³⁴ × 3×10⁸) / (3.04×10⁻¹⁹) ≈ 6.54×10⁻⁷ m = 654 nm 💡 طول موجي 654nm يقع بمدى الضوء الأحمر — وهذا فعلاً قريب من فجوة موادّ الـ LED الحمراء الشائعة تجارياً. كلما كبرت Eg، قصر λ، واقترب اللون من الأزرق والبنفسجي؛ وكلما صغرت، طال λ واقترب من الأحمر وتحت الأحمر."],"ministerial":false}],"qa":[{"question":"ما الفرق بين الثنائي الباعث للضوء (LED) والثنائي المتحسّس للضوء (Photodiode)؟","answer":"الثنائي الباعث للضوء (LED): يُربَط بالانحياز الأمامي، ويحوّل الطاقة الكهربائية إلى ضوئية (يبعث ضوءاً عند مرور التيار). الثنائي المتحسّس للضوء (Photodiode): يُربَط بالانحياز العكسي، ويحوّل الطاقة الضوئية إلى كهربائية (يزداد تياره بازدياد شدة الضوء الساقط عليه).","type":"وزاري متكرر","ministerial":true},{"question":"ما الفائدة من: ① الثنائي المتحسّس للضوء؟ ② الثنائي الباعث للضوء؟","answer":"① الثنائي المتحسّس للضوء: يُستعمل في كاشفات الضوء وكمقياس لشدة الضوء (تحويل الطاقة الضوئية إلى كهربائية). ② الثنائي الباعث للضوء (LED): يُستعمل في الشاشات الرقمية والساعات والحاسبات لإظهار الأرقام (تحويل الطاقة الكهربائية إلى ضوئية).","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌈 مختبر: من الفجوة الطاقية إلى لون الـ LED"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":8,"lesson_title":"الترانزستور","order_index":8,"hook":"هذا آخر درس بالفصل — وهو أيضاً القمة التي بُنيت عليها كل الدروس السابقة: مستويات الطاقة، الحزم، أشباه الموصلات النقية والمطعّمة، ووصلة pn وانحيازها، كلها تتضافر هنا لتُفسّر كيف يعمل العنصر الذي بُني عليه العصر الرقمي بأكمله.","concepts":[{"term":"الأطراف الثلاثة:","text":"• الباعث (Emitter, E): المنطقة الطرفية الأولى، مطعّمة تطعيماً كثيفاً — \"يبعث\" حاملات الشحنة الأغلبية بغزارة نحو القاعدة. • القاعدة (Base, B): المنطقة الوسطى، رقيقة جداً ومطعّمة تطعيماً خفيفاً جداً — تسمح لمعظم الحاملات القادمة من الباعث بعبورها دون إعادة اتحاد تُذكر. • المجمع (Collector, C): المنطقة الطرفية الثانية، الأكبر مساحة عادة — \"يجمع\" الحاملات العابرة من الباعث خلال القاعدة.","ministerial":false},{"term":"القاعدة المشتركة (Common Base):","text":"α = I_C / I_E قيمته دائماً أقل من الواحد (لأن I_C<I_E)، والإشارة الخارجة بالطور نفسه للداخلة (فرق طور = صفر).","ministerial":false},{"term":"الباعث المشترك (Common Emitter):","text":"α = I_C / I_B قيمته كبيرة (عالية) عادة، والإشارة الخارجة معاكسة بالطور للداخلة (فرق طور = 180°).","ministerial":false}],"laws":[{"name":"قانون التيارات بالترانزستور (تحفظ الشحنة عند العقدة)","formula":"I_E = I_B + I_C","variables_note":""},{"name":"ربح الفولطية والقدرة (لمضخّم القاعدة المشتركة)","formula":"A_v = V_out / V_in | G = α × A_v","variables_note":"حيث V_in=I_E·R_in وV_out=I_C·R_out (R_in وR_out مقاومتا دخول وخروج دائرة المضخّم)."}],"notes":[{"heading":"💡 لنُبسّط الفكرة أولاً بنسبة تقريبية:","items":["إذا كان تيار القاعدة I_B مثلاً 1% فقط من تيار الباعث I_E، فإن تيار المجمع I_C يكون تقريباً 99% من I_E — أي أن نسبة (تيار المجمع ÷ تيار القاعدة) تكون كبيرة جداً (بعشرات أو مئات المرات).","هذه بالضبط الفكرة التي تُصاغ رسمياً بمفهوم ربح التيار في الفقرة التالية."],"ministerial":false},{"heading":"🔁 من غرفة كاملة إلى ظفر إصبع","items":["تذكّر بداية هذا الفصل: أول حاسوب إلكتروني كان بحجم غرفة، يعمل بآلاف الصمامات المفرغة الهشّة.","اليوم، معالج واحد بحجم ظفر إصبعك يحوي أكثر من عشرة مليارات ترانزستور، كل واحد منها أصغر من فيروس — وكلها تعمل بنفس المبدأ البسيط الذي درسته للتو: باعث، وقاعدة رقيقة، ومجمع."],"ministerial":false}],"tables":[],"examples":[{"problem":"في دائرة ترانزستور كمضخّم ذي القاعدة المشتركة، إذا كان تيار الباعث I_E=3mA وتيار المجمع I_C=2.94mA ومقاومة الدخول R_in=500Ω ومقاومة الخروج R_out=400kΩ، احسب: ① ربح التيار α ② ربح الفولطية A_v.","givens":"المعطيات: I_E=3mA — I_C=2.94mA — R_in=500Ω — R_out=400kΩ=400000Ω","solution_steps":["الخطوة ١: ربح التيار: α = I_C/I_E = 2.94×10⁻³ / 3×10⁻³ = 0.98 (أقل من الواحد كما هو متوقّع بالقاعدة المشتركة)","الخطوة ٢: فولطية الدخول والخروج: V_in = I_E×R_in = 3×10⁻³ × 500 = 1.5 V V_out = I_C×R_out = 2.94×10⁻³ × 400000 = 1176 V","الخطوة ٣: ربح الفولطية: A_v = V_out/V_in = 1176/1.5 = 784 💡 لاحظ كيف تنتج مقاومة الخروج الكبيرة جداً (400kΩ) ربح فولطية هائلاً (784 مرة) رغم أن ربح التيار نفسه أقل من الواحد — سرّ التكبير هنا بفرق المقاومتين، لا بربح التيار."],"ministerial":true}],"qa":[{"question":"ما الفرق بين الباعث والجامع (المجمع) في الترانزستور من حيث طريقة الانحياز ونسبة الشوائب؟","answer":"الباعث: يُحيَّز انحيازاً أمامياً، ويُطعَّم بنسبة عالية من الشوائب. المجمع: يُحيَّز انحيازاً عكسياً، ويُطعَّم بنسبة متوسطة من الشوائب.","type":"وزاري","ministerial":true},{"question":"علّل: ممانعة ملتقى (المجمع-قاعدة) في الترانزستور عالية، بينما ممانعة ملتقى (الباعث-قاعدة) واطئة.","answer":"لأن ملتقى (الباعث-قاعدة) محيّز بالاتجاه الأمامي فتقلّ منطقة استنزافه ومقاومته → ممانعته واطئة. أما ملتقى (المجمع-قاعدة) فمحيّز بالاتجاه العكسي فتتّسع منطقة استنزافه وتزداد مقاومته → ممانعته عالية.","type":"وزاري","ministerial":true},{"question":"«تيار الباعث I_E في دائرة الترانزستور يكون دائماً أكبر من تيار القاعدة وأكبر من تيار المجمع».","answer":"العبارة صحيحة. لأن I_E=I_C+I_B، فتيار الباعث هو الأكبر دائماً بين التيارات الثلاثة.","type":"صح أو خطأ · وزاري","ministerial":true},{"question":"يجب أن تكون منطقة القاعدة بالترانزستور رقيقة جداً ومطعّمة تطعيماً خفيفاً جداً.","answer":"لأن وظيفة القاعدة أن \"تمرّر\" معظم حاملات الشحنة القادمة من الباعث إلى المجمع، لا أن تعيد اتحادها. لو كانت القاعدة سميكة أو مطعّمة تطعيماً كثيفاً، لأعادت اتحاد نسبة كبيرة من هذه الحاملات داخلها، فيكبر تيار القاعدة I_B على حساب تيار المجمع I_C، وينخفض معامل التكبير β كثيراً — عكس الهدف المطلوب من الترانزستور.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"📈 مختبر: تكبير التيار بالترانزستور"},{"chapter_number":"g6c7","chapter_title":"إلكترونيات الحالة الصلبة","lesson_number":9,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":9,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"لماذا استُبدلت الصمامات المفرغة بالترانزستورات في تصنيع الأجهزة الإلكترونية الحديثة؟","answer":"لأن الترانزستور أصغر حجماً، أقل استهلاكاً للطاقة، وأطول عمراً وأكثر متانة — الترانزستور (نبيطة الحالة الصلبة) أصغر، أقل استهلاكاً للطاقة، لا يحتاج فتيلاً ساخناً، وأطول عمراً من الصمام المفرغ.","type":"سؤال","ministerial":false},{"question":"طاقة الإلكترون بمستواه الأرضي في ذرة الهيدروجين تساوي −13.6eV. كم مقدار الطاقة اللازمة لتحريره تماماً من الذرة؟","answer":"+13.6 eV — التحرر الكامل يعني الانتقال إلى المستوى الصفري E=0؛ الطاقة اللازمة = 0−(−13.6) = +13.6eV.","type":"سؤال","ministerial":false},{"question":"ما الذي يحدد ما إذا كانت المادة موصلاً أم عازلاً أم شبه موصل؟","answer":"حجم الفجوة الطاقية المحرمة Eg بين حزمتي التكافؤ والتوصيل — حجم الفجوة الطاقية Eg هو الفيصل: صفر تقريباً (موصل)، صغيرة (شبه موصل)، كبيرة (عازل).","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) ما الفرق بين حزمة التكافؤ وحزمة التوصيل في المواد الصلبة؟","answer":"حزمة التكافؤ واطئة الطاقة وممتلئة كلياً أو جزئياً بإلكترونات مرتبطة بالنواة، وحزمة التوصيل أعلى منها وإلكتروناتها حرة الانتقال — حزمة التكافؤ واطئة الطاقة (ممتلئة كلياً أو جزئياً، إلكتروناتها مرتبطة بالنواة)؛ حزمة التوصيل أعلى منها، وإلكتروناتها حرة تساهم بالتيار.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) بماذا تتصف (تتميّز) حزم الطاقة في المواد العازلة؟","answer":"حزمة التكافؤ ممتلئة، حزمة التوصيل خالية، والفجوة بينهما واسعة (~5eV أو أكثر) — بالعوازل: حزمة التكافؤ مملوءة، حزمة التوصيل خالية تماماً، والفجوة المحرمة بينهما واسعة (~5eV فأكثر) فتمنع أي عبور.","type":"سؤال","ministerial":true},{"question":"فجوة طاقية Eg=1.5eV. جد أطول طول موجي لفوتون قادر على نقل إلكترون عبر هذه الفجوة تقريباً.","answer":"≈829 nm — λ_max=hc/Eg=(6.63×10⁻³⁴×3×10⁸)/(1.5×1.6×10⁻¹⁹)≈8.29×10⁻⁷m=829nm.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) علّل: تقلّ قابلية التوصيل الكهربائي في المواد الموصلة (المعادن) بارتفاع درجة حرارتها.","answer":"لأن ارتفاع الحرارة يزيد اهتزاز الشبيكة البلورية فيعيق حركة الإلكترونات الحرة وتزداد المقاومة — ارتفاع الحرارة يزيد الطاقة الاهتزازية لذرات المعدن، فتعيق اهتزازات الشبيكة حركة الإلكترونات الحرة وتزداد المقاومة، فتقلّ التوصيلية.","type":"سؤال","ministerial":true},{"question":"كم إلكترون تكافؤ تملكه ذرة السيليكون، وكم رابطة تساهمية تكوّنها مع جاراتها بالبلورة؟","answer":"٤ إلكترونات تكافؤ، و٤ روابط تساهمية — السيليكون من المجموعة الرابعة، فله ٤ إلكترونات تكافؤ يكوّن بها ٤ روابط تساهمية مع ٤ ذرات مجاورة.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) هل يمكن جعل شبه الموصل النقي (السيليكون) يمتلك قابلية توصيل كهربائي بوساطة التأثير الحراري؟","answer":"نعم، لأن الحرارة تكسر أواصر تساهمية وتحرر إلكترونات لحزمة التوصيل، مولّدة أزواج إلكترون-فجوة — عند رفع الحرارة لدرجة الغرفة، تكتسب إلكترونات التكافؤ طاقة كافية لكسر أواصر تساهمية والانتقال لحزمة التوصيل، مولّدة أزواج (إلكترون-فجوة) تعمل حوامل شحنة.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري متكرر) علامَ يعتمد المعدّل الزمني لتوليد الأزواج (إلكترون–فجوة) في شبه الموصل النقي؟","answer":"على درجة حرارة شبه الموصل فقط ونوع مادته — يعتمد على: درجة حرارة شبه الموصل (كلما ارتفعت، ازداد معدل التوليد)، ونوع مادته (سيليكون أم جرمانيوم، لاختلاف الفجوة الطاقية).","type":"سؤال","ministerial":true},{"question":"(اختيار وزاري متكرر) تتولّد الأزواج (إلكترون–فجوة) في شبه الموصل النقي بوساطة:","answer":"التأثير الحراري — الطاقة الحرارية عند درجة حرارة الغرفة هي التي تكسر أواصر تساهمية وتحرر إلكترونات مولّدة الأزواج.","type":"سؤال","ministerial":true},{"question":"(اختيار وزاري متكرر) يزداد المعدّل الزمني لتوليد الأزواج (إلكترون–فجوة) في شبه الموصل بـ:","answer":"ارتفاع درجة الحرارة — التطعيم يزيد حاملات الشحنة لكنه ليس توليداً لأزواج (إلكترون-فجوة)؛ ارتفاع الحرارة وحده هو ما يزيد معدل توليد الأزواج.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري متكرر) ما المقصود بمستوى فيرمي؟ وما موقعه في الموصلات وفي شبه الموصل النقي؟","answer":"أعلى مستوى طاقة مسموح يشغله الإلكترون عند 0K؛ فوق حزمة التوصيل بالموصلات، ومنتصف الفجوة بشبه الموصل النقي — مستوى فيرمي: أعلى مستوى طاقة مسموح يشغله الإلكترون عند 0K. يقع فوق المنطقة المملوءة بالموصلات (ضمن حزمة التوصيل)، وفي منتصف الفجوة المحظورة بشبه الموصل النقي.","type":"سؤال","ministerial":true},{"question":"(صح أو خطأ وزاري) «في الموصلات وعند درجة 0K تكون مستويات الطاقة تحت مستوى فيرمي مشغولة بالإلكترونات» — العبارة:","answer":"صحيحة — مستوى فيرمي أعلى مستوى يشغله الإلكترون عند 0K، فكل ما تحته مشغول بالإلكترونات، وكل ما فوقه خالٍ.","type":"سؤال","ministerial":true},{"question":"لتكوين شبه موصل من النوع n، أي عنصر يجب تطعيم السيليكون به؟","answer":"عنصر خماسي التكافؤ كالزرنيخ أو الفوسفور — الشائبة الخماسية التكافؤ تمنح إلكتروناً خامساً زائداً بعد تكوين ٤ روابط، فينتج فائض إلكترونات حرة (النوع n).","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) علّل: إذا كان التأثير الحراري يزيد توصيلية شبه الموصل النقي، فلماذا نلجأ لتطعيمه بشوائب؟","answer":"لأنه لا يمكن السيطرة على التوصيلية بالتأثير الحراري وحده، بينما التطعيم يتيح تحكماً دقيقاً ومضبوطاً بها — التأثير الحراري يزيد التوصيلية لكن بلا تحكم دقيق أو منضبط؛ التطعيم يتيح ضبط نوع وكمية حاملات الشحنة بدقة.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) علّل: الأيون الموجب المتولّد من الذرّة المانحة لا يُعدّ من حاملات الشحنة.","answer":"لأنه يرتبط بالهيكل البلوري ارتباطاً وثيقاً وثابتاً فلا يتحرك، فلا يسهم بالتوصيل — الأيون الموجب (الذرة المانحة بعد فقدان إلكترونها) ثابت ضمن الهيكل البلوري، فلا يسهم بالتوصيل رغم شحنته.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) هل يمكن أن توجد فجوات في بلورة سيليكون نوع n؟ ولماذا؟","answer":"نعم، لكنها قليلة جداً (أقلية) ومنشؤها حراري بحت، لا من التطعيم — التطعيم بخماسية التكافؤ يزيد الإلكترونات فقط؛ الفجوات القليلة تتولد حرارياً كما بالبلورة النقية، وتُعد أقلية.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — قارن) ما الفرق بين نوع N ونوع P من حيث نوع الشائبة وحاملات الشحنة؟","answer":"النوع N: شائبة خماسية (مانحة) وأغلبية إلكترونات. النوع P: شائبة ثلاثية (قابلة) وأغلبية فجوات — النوع N: شائبة خماسية التكافؤ (مانحة)، وحاملات الأغلبية إلكترونات. النوع P: شائبة ثلاثية التكافؤ (قابلة)، وحاملات الأغلبية فجوات.","type":"سؤال","ministerial":true},{"question":"أين يقع المستوى المانح (Donor Level) ضمن الفجوة الطاقية المحظورة، وماذا يحدث لمستوى فيرمي عند تولّده؟","answer":"تحت حزمة التوصيل مباشرة، ويرتفع فيرمي نحو الأعلى — المستوى المانح يتولّد بالتطعيم بشوائب خماسية (النوع n)، ويقع تحت حزمة التوصيل مباشرة، فيرتفع فيرمي نحو الأعلى.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري متكرر) علّل: سبب تولّد منطقة الاستنزاف في الثنائي البلوري pn.","answer":"لأن حوامل الأغلبية تنتشر عبر الملتقى وتلتحم قربه، تاركة أيونات ثابتة خالية من حاملات الشحنة الحرة — انتشار حوامل الأغلبية (إلكترونات من N وفجوات من P) عبر الملتقى والتحامها قربه يترك أيونات ثابتة خالية من حاملات الشحنة الحرة — هي منطقة الاستنزاف.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري متكرر) علامَ يعتمد مقدار حاجز الجهد الكهربائي في الثنائي البلوري pn؟","answer":"على نوع مادة شبه الموصل، ونسبة الشوائب، ودرجة حرارة المادة — حاجز الجهد يعتمد على ثلاثة عوامل: نوع مادة شبه الموصل (Si أم Ge)، نسبة التطعيم، ودرجة الحرارة.","type":"سؤال","ministerial":true},{"question":"ما القيمة التقريبية لجهد الحاجز عند التوازن في ثنائي مصنوع من الجرمانيوم؟","answer":"≈0.3 V — جهد الحاجز النموذجي لثنائي الجرمانيوم عند التوازن يساوي تقريباً 0.3V (مقابل ≈0.7V للسيليكون).","type":"سؤال","ministerial":false},{"question":"لتوصيل ثنائي pn توصيلاً أمامياً (Forward Bias)، كيف يجب ربط أقطاب البطارية؟","answer":"الموجب لجهة p، والسالب لجهة n — الانحياز الأمامي يتطلب ربط الموجب بجهة p والسالب بجهة n، ليعاكس المجال الخارجي المجال الداخلي بمنطقة الاستنزاف.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) علّل: ينساب تيار كبير في دائرة الثنائي pn عندما تزداد فولطية الانحياز بالاتجاه الأمامي.","answer":"لأن المجال الخارجي يعاكس مجال حاجز الجهد ويصبح أكبر منه، فتضيق منطقة الاستنزاف ويسهل عبور حوامل الأغلبية — المجال الخارجي بالانحياز الأمامي معاكس لمجال حاجز الجهد وأكبر منه، فتضيق منطقة الاستنزاف ويقلّ حاجز الجهد، فيسهل عبور حوامل الأغلبية.","type":"سؤال","ministerial":true},{"question":"(اختيار وزاري) عند زيادة حاجز الجهد في ثنائي pn منحاز أمامياً، فإن مقدار التيار الأمامي:","answer":"يقلّ — زيادة حاجز الجهد تعني زيادة إعاقة عبور حوامل الأغلبية، فيقلّ التيار الأمامي المنساب.","type":"سؤال","ministerial":true},{"question":"دائرة فيها بطارية 4.7V وثنائي سيليكون منحاز أمامياً (V₀=0.7V) ومقاومة R=200Ω على التوالي. جد التيار المار.","answer":"≈20 mA — I=(EMF−V₀)/R=(4.7−0.7)/200=4/200=0.02A=20mA.","type":"سؤال","ministerial":false},{"question":"ما وظيفة الثنائي المقوّم (Rectifier) بأبسط تعريف؟","answer":"تحويل التيار المتردد (AC) إلى تيار مستمر (DC) بالسماح بالمرور باتجاه واحد فقط — خاصية السماح بالمرور باتجاه واحد فقط تجعل الثنائي أساس أي دائرة تقويم تحوّل AC إلى DC.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري متكرر — قارن) ما الفرق بين الثنائي الباعث للضوء (LED) والثنائي المتحسّس للضوء (Photodiode)؟","answer":"LED بانحياز أمامي يحوّل كهرباء لضوء؛ Photodiode بانحياز عكسي يحوّل ضوءاً لكهرباء — LED يُربَط بالانحياز الأمامي ويحوّل الكهرباء لضوء؛ Photodiode يُربَط بالانحياز العكسي ويحوّل الضوء لكهرباء (يزداد تياره مع شدة الضوء).","type":"سؤال","ministerial":true},{"question":"كيف يعمل ثنائي الخلية الشمسية (Solar Cell)؟","answer":"يُربَط بانحياز عكسي ويحوّل الطاقة الضوئية الساقطة إلى طاقة كهربائية مباشرة — ثنائي الخلية الشمسية يُربَط بانحياز عكسي ويحوّل طاقة الفوتونات الساقطة على الملتقى مباشرة إلى طاقة كهربائية (قوة دافعة كهربائية).","type":"سؤال","ministerial":false},{"question":"ثنائي LED فجوته الطاقية Eg=2.0eV. جد الطول الموجي التقريبي للضوء المنبعث منه.","answer":"≈622 nm (أحمر برتقالي) — λ=hc/Eg=(6.63×10⁻³⁴×3×10⁸)/(2×1.6×10⁻¹⁹)≈6.22×10⁻⁷m=622nm.","type":"سؤال","ministerial":false},{"question":"ما الأطراف الثلاثة للترانزستور ثنائي القطبية (BJT)؟","answer":"الباعث والقاعدة والمجمع — أطراف الترانزستور الثلاثة: الباعث (Emitter)، القاعدة (Base)، والمجمع (Collector).","type":"سؤال","ministerial":false},{"question":"(صح أو خطأ وزاري) «تيار الباعث IE يكون دائماً أكبر من تيار القاعدة وأكبر من تيار المجمع» — العبارة:","answer":"صحيحة، لأن IE=IC+IB — بما أن IE=IC+IB، فإن تيار الباعث هو الأكبر دائماً بين التيارات الثلاثة.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — علّل) لماذا ممانعة ملتقى (المجمع-قاعدة) عالية بينما ممانعة ملتقى (الباعث-قاعدة) واطئة؟","answer":"لأن ملتقى الباعث-قاعدة محيّز أمامياً (استنزاف ضيق، مقاومة واطئة)، وملتقى المجمع-قاعدة محيّز عكسياً (استنزاف واسع، مقاومة عالية) — الباعث-قاعدة محيّز أمامياً فتضيق منطقة استنزافه (ممانعة واطئة)؛ المجمع-قاعدة محيّز عكسياً فتتّسع منطقة استنزافه (ممانعة عالية).","type":"سؤال","ministerial":true},{"question":"(مسألة وزارية) في مضخّم قاعدة مشتركة: IE=3mA، Rin=500Ω، Rout=400kΩ، IC=2.94mA. جد ربح الفولطية Av تقريباً.","answer":"≈784 — Vin=IE·Rin=3×10⁻³×500=1.5V. Vout=IC·Rout=2.94×10⁻³×400000=1176V. Av=Vout/Vin=1176/1.5=784.","type":"سؤال","ministerial":true},{"question":"(مسألة وزارية) مضخّم قاعدة مشتركة: ربح القدرة G=768، ربح الفولطية Av=784. جد ربح التيار α.","answer":"≈0.98 — G=α×Av ⟹ α=G/Av=768/784≈0.98.","type":"سؤال","ministerial":true},{"question":"(اختيار وزاري) ربح التيار α بمضخّم الباعث المشترك يساوي نسبة:","answer":"IC/IB — بمضخّم الباعث المشترك، ربح التيار = تيار الخروج (المجمع) على تيار الدخول (القاعدة) = IC/IB.","type":"سؤال","ministerial":true},{"question":"ما وجه الشبه الأساسي بين الترانزستور كـ«مفتاح إلكتروني» والبوابات المنطقية الرقمية (0 و1)؟","answer":"وضعا التشبّع (تشغيل تام) والقطع (إيقاف تام) يقابلان مباشرة الحالتين الرقميتين 1 و0 — بتيار قاعدة كافٍ يعمل الترانزستور بوضع التشبّع (≈1 رقمياً)، وبلا تيار قاعدة بوضع القطع (≈0 رقمياً) — أساس البوابات المنطقية.","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":1,"lesson_title":"فشل أنموذج رذرفورد وفرضيات بور","order_index":1,"hook":"هذا الفصل يفتح بابين مختلفين تماماً في الظاهر: طيف الذرّة الذي يكشف أسرار بنيتها الداخلية، والليزر الذي يستثمر هذه الأسرار نفسها لصنع ضوء لا مثيل له. كلاهما يبدأ من نفس النقطة: فهم كيف تتوزّع الإلكترونات على مستويات طاقة داخل الذرّة.","concepts":[{"term":"① الانهيار الحلزوني:","text":"الإلكترون الدائر جسيم معجَّل (يغيّر اتجاه حركته باستمرار)، ووفق الكهرومغناطيسية الكلاسيكية أي شحنة معجَّلة تُشعّ طاقة باستمرار. فيجب أن يفقد الإلكترون طاقته تدريجياً وينهار حلزونياً نحو النواة خلال زمن قصير جداً — أي تنهار الذرّة كلياً!","ministerial":false},{"term":"② طيف متصل لا خطّي:","text":"تناقص طاقة الإلكترون تدريجياً يستوجب طيفاً مستمراً. لكن التجارب أثبتت أن طيف ذرّة الهيدروجين طيف خطّي — خطوط منفصلة، لا طيف متصل.","ministerial":false},{"term":"","text":"① تدور الإلكترونات حول النواة بمدارات محددة المواقع (مستويات طاقة)، دون أن تشعّ طاقة. أقل طاقة للإلكترون عند أقرب مستوى للنواة، وعندها الذرّة مستقرّة.\n② الذرّة متعادلة كهربائياً: شحنة الإلكترونات = شحنة النواة الموجبة.\n③ لا تشعّ الذرّة طاقة بسبب حركة الإلكترون بمداره المحدد؛ تبقى مستقرّة.\n④ عند اكتساب الإلكترون كمّاً من الطاقة، يقفز من مستوى استقراره (Eᵢ) إلى مستوى أعلى (Ef) فتصير الذرّة متهيّجة، ثم يعود الإلكترون باعثاً فوتوناً تردده f.\n⑤ تنطبق على مجال الذرّة: قانون كولوم على الشحنات، وقانون نيوتن الثاني على القوى الميكانيكية.\n⑥ زخم الإلكترون الزاوي في مداره L=mvr يساوي أعداداً صحيحة من h/2π.","ministerial":false}],"laws":[{"name":"شرط الانتقال بين مستويين (الفرضية الرابعة)","formula":"hf = Ef − Eᵢ","variables_note":""},{"name":"تكميم الزخم الزاوي (الفرضية السادسة)","formula":"Lₙ = n(h/2π)","variables_note":"n = 1, 2, 3, … العدد الكمّي الرئيس"}],"notes":[{"heading":"⚠️ لكن الذرّات موجودة فعلاً!","items":["الذرّة تحت الظروف الطبيعية مستقرّة تماماً، لا تبعث أي إشعاع إلا تحت شروط خاصة (تسخين، أو تعريضها لجهد كهربائي بأنبوب مفرّغ).","بقي هذا اللغز محيّراً إلى أن اقترح بور عام ١٩١٣ أنموذجاً جديداً — بالاستغناء عن قوانين الكهرومغناطيسية الكلاسيكية عند حدود الذرّة، واستبدالها بفكرة جديدة كلياً: الكم."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"عندما تُثار الذرّة بطاقة إشعاعية متصلة، فإنها:","answer":"تمتصّ الطاقة المناسبة فقط لإثارة ذرّاتها، وفق فرضية بور الرابعة — لا يمكن للذرّة امتصاص أي كمّ طاقة عشوائي، بل فقط المقدار الذي يساوي بالضبط فرق الطاقة بين مستويين محدَّدين.","type":"وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":2,"lesson_title":"طيف ذرّة الهيدروجين وسلاسله","order_index":2,"hook":"درس بور طيف ذرّة الهيدروجين لأنها أبسط ذرّة (إلكترون واحد)، وخرج باستنتاجات صارت أساس فهمنا الحديث لكل الذرّات.","concepts":[{"term":"المستوى الأرضي (Ground State):","text":"أوطأ مستوى طاقة للذرّة E₁. أما المستويات الأعلى E₂, E₃, E₄, … فتُسمى المستويات المتهيّجة (Excited States). كل طاقات هذه المستويات سالبة؛ لذا لا يمتلك الإلكترون تحت الظروف الطبيعية طاقة كافية للهروب من الذرّة.","ministerial":false}],"laws":[],"notes":[{"heading":"🌈 لماذا سلسلة بالمر وحدها مرئية؟","items":["لأن فرق الطاقة بين المستويات العليا والمستوى الثاني (n=2) يقابل فوتونات بأطوال موجية تقع ضمن المدى المرئي (~400–700nm)، بينما فروق الطاقة نحو المستوى الأول أكبر (فوق بنفسجي) ونحو المستويات الثالث وما فوق أصغر (تحت أحمر)."],"ministerial":false}],"tables":[{"caption":"📉 المستوى الأرضي والمستويات المتهيّجة","ministerial":false,"headers":["السلسلة","الانتقال إلى المستوى","المنطقة الطيفية","مرئية؟"],"rows":[["لايمان Lyman","n = 1","فوق البنفسجية (UV)","غير مرئية"],["بالمر Balmer","n = 2","المرئية، وتمتد حتى فوق البنفسجية","مرئية"],["باشن Paschen","n = 3","تحت الحمراء","غير مرئية"],["براكت Brackett","n = 4","تحت الحمراء","غير مرئية"],["فوند Pfund","n = 5","تحت الحمراء","غير مرئية"]]}],"examples":[{"problem":"إلكترون في ذرّة هيدروجين انتقل من مستوى الطاقة E₄=−0.85eV إلى مستوى الطاقة E₂=−3.4eV. جد مقدار تردد الفوتون المنبعث.","givens":"المعطيات: E₄=−0.85eV — E₂=−3.4eV — h=6.63×10⁻³⁴J.s — 1eV=1.6×10⁻¹⁹J","solution_steps":["الخطوة ١: طاقة الفوتون تساوي الفرق المطلق بين المستويين: hf = E₄ − E₂ = (−0.85) − (−3.4) = 2.55 eV = 2.55 × 1.6×10⁻¹⁹ = 4.08×10⁻¹⁹ J","الخطوة ٢: نوجد التردد: f = 4.08×10⁻¹⁹ / 6.63×10⁻³⁴ ≈ 6.15×10¹⁴ Hz 💡 هذا الانتقال (من n=4 إلى n=2) ينتمي إلى سلسلة بالمر المرئية."],"ministerial":true}],"qa":[{"question":"طيف ذرّة الهيدروجين هو طيف:","answer":"طيف خطّي — لأن الإلكترونات تنتقل بين مستويات طاقة منفصلة ومحددة، فتُبعث فوتونات ذات ترددات (وبالتالي أطوال موجية) محددة تماماً تظهر كخطوط منفصلة على خلفية سوداء، لا كطيف متصل.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"⚛️ مختبر أنموذج بور لذرّة الهيدروجين"},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":3,"lesson_title":"الأنطياف وأنواعها","order_index":3,"hook":"تحليل الإشعاع المنبعث من مادة ودراسة طيفها بجهاز يُسمى المطياف من أهم الطرق لمعرفة التركيب الذرّي والجزيئي لتلك المادة — إذ يختلف الطيف باختلاف نوع الغاز الباعث تماماً.","concepts":[{"term":"أ) الطيف المستمر:","text":"نحصل عليه من الأجسام الصلبة والسائلة المتوهّجة، أو الغازات المتوهّجة عند ضغط عالٍ جداً. يحتوي مدى واسعاً متصلاً من الترددات (كطيف مصباح التنكستن).","ministerial":false},{"term":"ب) الطيف الخطي:","text":"نحصل عليه من توهّج الغازات والأبخرة عند الضغط الاعتيادي أو الواطئ. يتألّف من خطوط ملوّنة براقة منفصلة على خلفية سوداء، كل خط يمثّل طولاً موجياً معيّناً — صفة مميّزة لكل عنصر لا تتكرّر عند غيره (كبصمة الإصبع). طيف الصوديوم البرّاق: خطّان أصفران متقاربان. طيف الهيدروجين الخطي: أربعة خطوط (أحمر، أخضر، نيلي، بنفسجي).","ministerial":false},{"term":"ج) الطيف الحزمي:","text":"يحتوي حزمة أو عدداً من الحزم الملوّنة على أرضية سوداء — صفة مميّزة للمواد ذات التركيب الجزيئي (كغاز ثنائي أوكسيد الكربون).","ministerial":false}],"laws":[],"notes":[{"heading":"☀️ خطوط فراونهوفر","items":["الجو الغازي المحيط بالشمس يمتصّ قسماً من طيفها المستمر (الأطوال الموجية التي يبعثها فيما لو كان متوهّجاً)، فلاحظ العالِم فراونهوفر خطوطاً سوداء ضمن طيف الشمس المستمر — سُميت خطوط فراونهوفر، واكتشف نحو ٦٠٠ خط منها."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"مم يتكوّن كل من الطيف الخطي البرّاق للصوديوم والطيف الخطي للهيدروجين؟","answer":"الطيف الخطي البرّاق للصوديوم يتكوّن من خطّين أصفرين برّاقين متقاربين جداً. أما الطيف الخطي للهيدروجين فيتكوّن من أربعة خطوط برّاقة بالألوان (أحمر، أخضر، نيلي، بنفسجي).","type":"وزاري","ministerial":true},{"question":"ماذا تعني خطوط فراونهوفر؟ وما سبب ظهورها؟","answer":"خطوط سوداء تظهر ضمن الطيف المستمر للشمس (نحو ٦٠٠ خط). سببها: أن الغازات المحيطة بالشمس (الأقل توهّجاً من غازات باطنها) تمتصّ من الطيف المستمر الأطوال الموجية التي تبعثها هذه الغازات فيما لو كانت متوهّجة — وهذا يُسمى طيف الامتصاص الخطي للشمس.","type":"وزاري","ministerial":true},{"question":"قارن بين الطيف المستمر والطيف الخطي من حيث كيفية الحصول على كل منهما.","answer":"الطيف المستمر: من الأجسام الصلبة والسائلة المتوهّجة، أو الغازات المتوهّجة عند ضغط عالٍ جداً.\nالطيف الخطي: من توهّج الغازات والأبخرة عند الضغط الاعتيادي أو الواطئ.","type":"وزاري · قارن","ministerial":true}],"has_simulation":true,"simulation_title":"🎨 مختبر: مقارنة أنواع الطيف"},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":4,"lesson_title":"الأشعة السينية","order_index":4,"hook":"الأشعة السينية هي موجات كهرومغناطيسية غير مرئية أطوالها الموجية قصيرة جداً (نحو 0.001–10 nm)، ولا تتأثر بالمجالات الكهربائية والمغناطيسية لأنها ليست دقائق مشحونة.","concepts":[{"term":"المميّزة (خطّي حاد):","text":"الإلكترون المعجَّل ينتزع إلكتروناً من مستوى داخلي بذرّة الهدف (تأيّن)، فيهبط إلكترون من مستوى أعلى ليملأ الفراغ، باعثاً فوتون سيني طاقته hf=E₂−E₁. صفة مميّزة لمادة الهدف.","ministerial":false},{"term":"المستمرة:","text":"تنتج عن تباطؤ الإلكترونات المعجَّلة بتأثير المجال الكهربائي لنوى ذرّات الهدف، ففقدانها تدريجياً لطاقتها الحركية ينتج فوتونات بترددات مختلفة.","ministerial":false}],"laws":[{"name":"أقصر طول موجي للأشعة السينية","formula":"hf_max = Ve ⟹ λ_min = hc / (Ve)","variables_note":""}],"notes":[{"heading":"🌡️ اختيار مادة الهدف بعناية","items":["ينتج عن تصادم الإلكترونات المعجَّلة بالهدف حرارة عالية جداً؛ لذا يُصنع الهدف من مادة انصهارها درجة حرارة عالية جداً (كالتنكستن والمولبدينيوم)، ويُختار من عنصر ذي عدد ذري كبير لزيادة كفاءة توليد الأشعة، وتُستعمل وسائل تبريد خاصة."],"ministerial":false}],"tables":[],"examples":[{"problem":"فرق الجهد المطبق بين قطبي أنبوبة توليد الأشعة السينية 30kV. جد أقصر طول موجي للأشعة السينية المتولّدة.","givens":"المعطيات: V=30kV=30000V — h=6.63×10⁻³⁴J.s — e=1.6×10⁻¹⁹C — c=3×10⁸m/s","solution_steps":["الخطوة ١: نطبّق القانون مباشرة: λ_min = hc/(Ve) = (6.63×10⁻³⁴ × 3×10⁸) / (30000 × 1.6×10⁻¹⁹)","الخطوة ٢: نحسب: λ_min ≈ 4.14×10⁻¹¹ m 💡 هذا يقع ضمن مدى الأشعة السينية المعروف تماماً (0.001–10nm، أي 10⁻¹²–10⁻⁸m)."],"ministerial":true}],"qa":[{"question":"علّل: يُصنع هدف أنبوبة الأشعة السينية من مادة انصهارها درجة حرارة عالية جداً.","answer":"لأن الإلكترونات المعجَّلة تصطدم بالهدف بسرعات عالية جداً، فينتج عن هذا التصادم حرارة عالية جداً في الهدف؛ فلو كانت مادة الهدف منخفضة درجة الانصهار لانصهرت وتلفت أثناء التشغيل.","type":"وزاري متكرر جداً","ministerial":true},{"question":"علّل: لا تتأثر الأشعة السينية بالمجالات الكهربائية والمغناطيسية.","answer":"لأن الأشعة السينية موجات كهرومغناطيسية غير مرئية ليست دقائق مشحونة (لا تحمل شحنة كهربائية)، والمجالات الكهربائية والمغناطيسية لا تؤثر إلا في الدقائق المشحونة المتحركة.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"⚡ مختبر: فرق الجهد وأقصر طول موجي"},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":5,"lesson_title":"تأثير كومبتن","order_index":5,"hook":"هذا الدرس دليل حاسم آخر (بعد الظاهرة الكهروضوئية بالفصل السادس) على أن الضوء يسلك أحياناً سلوك الجسيمات لا الموجات فقط.","concepts":[],"laws":[{"name":"علاقة كومبتن: الزيادة بالطول الموجي تعتمد على زاوية الاستطارة θ فقط","formula":"λ′ − λ = (h / mₑc)(1 − cos θ)","variables_note":"mₑ=9.11×10⁻³¹kg كتلة الإلكترون. الكمّية h/mₑc تُسمى طول موجة كومبتن وتساوي 0.24×10⁻¹¹m — قيمة ثابتة تحفظها."}],"notes":[{"heading":"💡 التفسير:","items":["فسّر كومبتن ذلك بأن الفوتون الساقط يتصادم مع إلكترون حر من إلكترونات ذرّات الهدف، فاقداً مقداراً من طاقته لصالح الإلكترون (الذي يكتسب طاقة حركية تمكّنه من الإفلات).","هذا يعني أن الفوتون يسلك سلوك الجسيمات.","وافترض كومبتن أن التصادم مرن (elastic)، يخضع لقانونَي حفظ الزخم وحفظ الطاقة معاً — تماماً كتصادم كرتي بلياردو."],"ministerial":false}],"tables":[],"examples":[{"problem":"ما مقدار الزيادة الحاصلة في طول موجة الفوتون المستطار (بتأثير كومبتن) إذا استطار بزاوية 60°؟","givens":"المعطيات: θ=60° — mₑ=9.11×10⁻³¹kg — c=3×10⁸m/s — h=6.63×10⁻³⁴J.s","solution_steps":["الخطوة ١: نطبّق علاقة كومبتن: Δλ = (h/mₑc)(1 − cos60°) = [6.63×10⁻³⁴ / (9.11×10⁻³¹ × 3×10⁸)] × (1 − 0.5)","الخطوة ٢: نحسب: Δλ = 0.24×10⁻¹¹ × 0.5 ≈ 1.2×10⁻¹² m = 1.2×10⁻³ nm 💡 لاحظ صغر هذه الزيادة جداً — لهذا لا يُلاحَظ تأثير كومبتن إلا بأشعة قصيرة الطول الموجي جداً كالأشعة السينية، لا بالضوء المرئي (حيث تكون Δλ نسبة ضئيلة جداً من λ الأصلي فلا تُلاحَظ عملياً)."],"ministerial":true}],"qa":[{"question":"علّل: يُعدّ تأثير كومبتن أحد الأدلة المهمة التي تؤكّد السلوك الدقائقي (الجسيمي) للأشعة الكهرومغناطيسية.","answer":"لأن تفسير الزيادة الحاصلة في الطول الموجي لفوتونات الأشعة السينية المستطارة بوساطة الإلكترونات الحرة لا يمكن تفسيره إلا بافتراض أن الفوتون يسلك سلوك الجسيمات ويتصادم تصادماً مرناً مع الإلكترون الحر خاضعاً لقانونَي حفظ الزخم وحفظ الطاقة — وهذا سلوك دقائقي بحت لا تفسّره النظرية الموجية الكلاسيكية للضوء.","type":"وزاري متكرر","ministerial":true}],"has_simulation":true,"simulation_title":"📐 مختبر: زاوية الاستطارة θ ومقدار الزيادة Δλ"},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":6,"lesson_title":"الليزر — التسمية والخصائص وآلية العمل","order_index":6,"hook":"في مصباح عادي، تبعث الذرّات فوتوناتها عشوائياً تماماً. الليزر يستثمر آلية مختلفة كلياً تجعل كل الفوتونات الخارجة متطابقة تماماً.","concepts":[{"term":"LASER","text":"= Light Amplification by Stimulated Emission of Radiation = تضخيم الضوء بوساطة الانبعاث المحفَّز للإشعاع. وضع ألبرت أينشتاين عام ١٩١٧ الأساس النظري لعملية الانبعاث المحفَّز، وصُمِّم أول جهاز ليزر فعلياً عام ١٩٦٠ من قِبَل T.H. Maiman باستعمال بلورة الياقوت (يُعرف بليزر الياقوت Ruby Laser).","ministerial":false},{"term":"① أحادي الطول الموجي (Monochromatic):","text":"له طول موجي واحد بنقاء طيفي يفوق أي مصدر آخر — بينما الضوء الاعتيادي يحوي مدى واسعاً من الأطوال الموجية.","ministerial":false},{"term":"② التشاكه (Coherency):","text":"كل موجات الحزمة بنفس الطور والاتجاه والطاقة، فتتداخل تداخلاً بنّاءً فيما بينها.","ministerial":false},{"term":"③ الاتجاهية (Directionality):","text":"تبقى الموجات متوازية لمسافات بعيدة بانفراجية قليلة جداً. حزمة ليزر مرسَلة للقمر (384000km) تفرش بقعة قطرها ~1km فقط؛ الضوء الاعتيادي كان سيفرش بقعة قطرها ~4376km!","ministerial":false},{"term":"④ السطوع (Brightness):","text":"تتركّز الطاقة بمساحة صغيرة جداً، فيكون الليزر أسطع من الشمس بمليون مرة. مصباح تنكستن 100W: ~2000 W/cm²؛ ليزر بنفس القدرة: ~2×10⁹ W/cm².","ministerial":false}],"laws":[],"notes":[{"heading":"📻 قريب من الليزر: الميزر MASER","items":["Microwave Amplification by Stimulated Emission of Radiation = تضخيم الموجات الدقيقة بوساطة الانبعاث المحفَّز للإشعاع.","صمّم العالِم تاونس أول جهاز ميزر (أمونيا) عام ١٩٥٤ — أي قبل الليزر نفسه بست سنوات."],"ministerial":false},{"heading":"⭐ الأهم: الانبعاث المحفَّز","items":["عندما يؤثّر فوتون بذرّة متهيّجة (بمستوى E₂)، فإنه يحفّز الإلكترون على النزول لمستوى E₁ باعثاً فوتوناً مماثلاً تماماً للفوتون المحفِّز — بالطاقة والتردد والطور والاتجاه.","النتيجة: فوتونان متشاكهان بدل واحد.","هذا هو أساس تضخيم الليزر: لغرض توليده، يجب أن يكون عدد الذرّات بمستويات التهيّج أكبر مما بالمستويات الواطئة — وتُسمى هذه العملية التوزيع المعكوس (موضوع الدرس القادم)."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"question":"ماذا تعني كلمة (الليزر)؟ وما الذي يميّزه عن المصادر الضوئية الأخرى؟","answer":"الليزر: تضخيم الضوء بوساطة الانبعاث المحفَّز للإشعاع. ويتميّز عن المصادر الضوئية الأخرى بأربع خصائص: أحادية الطول الموجي، التشاكه، الاتجاهية، والسطوع العالي.","type":"وزاري","ministerial":true},{"question":"لماذا لا تنتج المصادر الضوئية الاعتيادية (كالمصباح الكهربائي) شعاعاً متشاكهاً كالليزر رغم أن ذرّاتها تبعث فوتونات أيضاً؟","answer":"لأن ذرّات المصباح الاعتيادي تبعث فوتوناتها بالانبعاث التلقائي فقط، وهو عشوائي تماماً بالطور والاتجاه والتردد، ولا يحصل فيها توزيع معكوس ولا انبعاث محفَّز يُنتج فوتونات متطابقة.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🔀 مختبر: الانتقالات الإلكترونية الثلاثة"},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":7,"lesson_title":"التوزيع المعكوس ومكونات الليزر ومنظوماته","order_index":7,"hook":"بالدرس السابق تعرّفت على الانبعاث المحفَّز. لكن لكي يهيمن هذا الانبعاث ويُنتج تضخيماً حقيقياً، يجب توفّر شرط رياضي دقيق تصفه معادلة بولتزمان.","concepts":[{"term":"","text":"إذا كان النظام الذرّي غير متّزن حرارياً، فقد يصبح عدد الذرّات بالمستويات العليا أكبر مما بالمستويات الواطئة (N₂ > N₁) — عكس التوزيع الطبيعي تماماً. تُسمى هذه الحالة التوزيع المعكوس، وهي التي تزيد احتمالية الانبعاث المحفَّز — أساس توليد الليزر بأكمله. تتحقق بوجود شدة ضخّ كافية ومستوى طاقة ذي عمر زمني أطول نسبياً، يُسمى المستوى شبه المستقر (Metastable State).","ministerial":false},{"term":"١) الوسط الفعال (Active Medium):","text":"ذرّات أو جزيئات أو أيونات المادة (غازية أو سائلة أو صلبة)، التي يمكن أن يحصل فيها التوزيع المعكوس عند تجهيزها بشدة كافية.","ministerial":false},{"term":"٢) المرنان (Resonator):","text":"مرآتان متقابلتان — إحداهما عاكسة كلياً تقريباً، والأخرى عاكسة جزئياً (تسمح بنفاذ شعاع الليزر للخارج). الانعكاسات المتكررة داخل المرنان تُضخِّم الانبعاث المحفَّز.","ministerial":false},{"term":"٣) تقنية الضخّ (Pumping):","text":"تجهّز الطاقة اللازمة لنقل ذرّات الوسط الفعال من الاستقرار إلى التهيّج، لتحقيق التوزيع المعكوس. ثلاثة أنواع: الضخ الضوئي (مصابيح ومضية قوية، كليزر الياقوت) · الضخ الكهربائي (تفريغ كهربائي بالغاز، الأشيع بالليزرات الغازية، يُستعمل أيضاً بليزر أشباه الموصلات) · الضخ الكيميائي (تفاعل كيميائي مباشر يوفّر الطاقة، بلا حاجة مصدر خارجي).","ministerial":false},{"term":"المنظومة ثلاثية المستوى:","text":"E₁ (أرضي)، E₂ (شبه مستقر)، E₃ (تهيّج، عمره القصير ~10⁻⁸s). تنتقل الذرّات إلى E₃ ثم تهبط سريعاً إلى E₂ الأطول عمراً (~10⁻⁶s)، فيتجمّع فيه فائض عن E₁ — تحقّق التوزيع المعكوس. تتطلّب طاقة ضخّ عالية.","ministerial":false},{"term":"المنظومة رباعية المستوى:","text":"E₁ إلى E₄. تُضخّ الذرّات من E₁ إلى E₄، فتهبط سريعاً لـE₃ (شبه مستقر). يتحقّق التوزيع المعكوس بين E₃ وE₂ (شبه فارغ لأن الذرّات تهبط منه سريعاً لـE₁). تتطلّب طاقة ضخّ أقل.","ministerial":false}],"laws":[{"name":"قانون بولتزمان","formula":"N₂/N₁ = exp[−(E₂ − E₁)/kT]","variables_note":"k ثابت بولتزمان، T درجة الحرارة بالكلفن، N₂/N₁ نسبة تركيز الذرّات بالمستويين."}],"notes":[],"tables":[],"examples":[{"problem":"إذا كان فرق الطاقة بين المستويين يساوي kT عند درجة حرارة الغرفة (أي E₂−E₁=kT)، احسب N₂ بدلالة N₁.","givens":"المعطيات: E₂−E₁ = kT","solution_steps":["الخطوة ١: نعوّض بقانون بولتزمان: N₂/N₁ = exp[−(E₂−E₁)/kT] = exp[−kT/kT] = exp(−1)","الخطوة ٢: نحسب: N₂ = 0.37 N₁ 💡 أي N₂ < N₁ دائماً بهذه الحالة — لا يتحقق التوزيع المعكوس (الذي يتطلّب N₂>N₁) بالاتزان الحراري الطبيعي مهما كانت درجة الحرارة؛ لهذا نحتاج آلية ضخّ خارجية فعلية (لا مجرد تسخين)."],"ministerial":true}],"qa":[{"question":"هل يتحقّق التوزيع المعكوس عندما تكون الطاقة الحرارية kT مساوية لطاقة الفوتون الساقط؟ وضّح رياضياً.","answer":"لا، لا يتحقّق. فبوضع kT=hf=E₂−E₁ بقانون بولتزمان نحصل على N₂/N₁=exp(−1)=0.37، أي N₂=0.37N₁<N₁، ولا يتحقّق شرط التوزيع المعكوس (N₂>N₁).","type":"وزاري","ministerial":true},{"question":"أيّهما أفضل لتوليد الليزر: منظومة المستويات الثلاثة أم الأربعة؟ ولماذا؟","answer":"منظومة المستويات الأربعة أفضل؛ لأنها تتطلّب طاقة ضخّ أقل لتحقيق التوزيع المعكوس مقارنةً بمنظومة المستويات الثلاثة، إذ يكون المستوى E₂ فيها شبه فارغ من الذرّات أصلاً (بسبب الهبوط السريع منه)، فلا حاجة لضخّ عدد كبير من الذرّات لتحقيق الفائض بـE₃.","type":"وزاري متكرر حرفياً","ministerial":true},{"question":"تكون قدرة الضخّ عالية عندما تعمل منظومة الليزر بنظام:","answer":"ثلاثة مستويات — لأنها تتطلّب طاقة ضخّ أعلى من منظومة الأربعة مستويات لتحقيق التوزيع المعكوس.","type":"اختيار وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🌡️ مختبر: نسبة بولتزمان N₂/N₁"},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":8,"lesson_title":"أنواع الليزر وتطبيقاته","order_index":8,"hook":"يأتي الليزر بأنواع مختلفة تبعاً لنوع مادة الوسط الفعال المستعمل فيه — فليزر الهيليوم-نيون (He-Ne) يعني أن الوسط الفعال خليط من الهيليوم والنيون، وهكذا.","concepts":[{"term":"١. التطبيقات الصناعية:","text":"تهذيب المكونات الإلكترونية (المقاومات، المتسعات، الترانزستورات)، عمل أقنعة الدوائر المتكاملة، ثقب المعادن وقطعها ولحامها — إذ تنحصر الحرارة بمساحة صغيرة جداً بلا تأثير بالأجزاء المجاورة.","ministerial":false},{"term":"٢. الاتجاهية والانتقال بخطوط مستقيمة:","text":"دور مهم بمسح وترصيف الأعمال الهندسية (تشييد المباني، الإنشاءات الميكانيكية)، ورصف الأنابيب وشق القنوات والأنفاق والطرق ومسح الأراضي.","ministerial":false},{"term":"٣. قياس تلوث البيئة:","text":"ليزرات عديدة لقياس نسبة بخار الماء وثنائي أوكسيد الكربون وثنائي أوكسيد الفسفور بالجو.","ministerial":false},{"term":"٤. التصوير المجسّم (Holography):","text":"تسجيل سعة الموجات الضوئية المنعكسة من الجسم وطورها، لإظهاره بصورة ثلاثية الأبعاد (طول وعرض وارتفاع) أقرب ما تكون للحقيقة.","ministerial":false}],"laws":[],"notes":[],"tables":[{"caption":"🔬 أنواع الليزر","ministerial":false,"headers":["النوع","الوسط الفعال / مثال"],"rows":[["ليزر الحالة الصلبة","ليزر الياقوت Ruby، ليزر النيديميوم"],["ليزر الحالة الغازية","ليزر الهيليوم–نيون، ليزر غاز ثنائي أوكسيد الكربون"],["ليزر الإكسايمر (Excimer)","غازات نبيلة مع هالوجين (ArF, KrF) — فوق بنفسجي"],["ليزر الصبغة (Dye)","محاليل صبغة عضوية (كرودامين 6G) مذابة بمذيب"],["ليزر أشباه الموصلات","مثل ليزر زرنيخيد الكاليوم GaAs"],["الليزر الكيميائي","التوزيع المعكوس بتفاعل كيميائي مباشر، كليزر فلوريد الديتيريوم"]]}],"examples":[],"qa":[{"question":"ما المكونات الرئيسة التي تتضمّنها منظومات الليزرات الغازية؟","answer":"الوسط الفعال (غاز مثل الهيليوم-نيون)، المرنان (مرآتان متقابلتان)، وميكانيكية الضخّ (غالباً الضخّ الكهربائي عن طريق التفريغ الكهربائي للغاز).","type":"وزاري","ministerial":true}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c8","chapter_title":"الأطياف الذرية والليزر","lesson_number":9,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":9,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"لماذا فشل أنموذج رذرفورد للذرّة وفق الكهرومغناطيسية الكلاسيكية؟","answer":"الإلكترون المعجَّل يجب أن يشعّ طاقة باستمرار فينهار حلزونياً نحو النواة، ويتنبّأ بطيف مستمر بينما المُشاهَد خطّي — الإلكترون المعجَّل يشعّ طاقة باستمرار وفق الكهرومغناطيسية الكلاسيكية فينهار حلزونياً، ويتنبأ النموذج بطيف مستمر يخالف الطيف الخطي المُشاهَد فعلياً.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) عندما تُثار الذرّة بطاقة إشعاعية متصلة، فإنها:","answer":"تمتص الطاقة المناسبة لإثارة ذرّاتها فقط — وفق فرضية بور الرابعة، لا يمكن للذرّة امتصاص أي كمّ طاقة عشوائي، بل فقط المقدار المناسب تماماً لإثارتها بين مستويين محدَّدين.","type":"سؤال","ministerial":true},{"question":"ما الصيغة الرياضية لتكميم الزخم الزاوي وفق الفرضية السادسة لبور؟","answer":"L = m/r — الزخم الزاوي للإلكترون بمداره المحدد يساوي أعداداً صحيحة من h/2π: Lₙ=n(h/2π).","type":"سؤال","ministerial":false},{"question":"أوطأ مستوى طاقة لذرّة الهيدروجين يُسمى:","answer":"المستوى الأرضي — أوطأ مستوى طاقة للذرّة (E₁) يُسمى المستوى الأرضي؛ المستويات الأعلى تُسمى مستويات متهيّجة.","type":"سؤال","ministerial":false},{"question":"إلى أي مستوى تنتهي انتقالات سلسلة لايمان (Lyman)، وفي أي منطقة طيفية تقع؟","answer":"n=1، فوق البنفسجية — سلسلة لايمان تنتهي عند n=1 (أوطأ مستوى)، وفرق الطاقة الكبير يقابل فوتونات فوق بنفسجية.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) طيف ذرّة الهيدروجين هو طيف:","answer":"خطّي — الانتقالات بين مستويات منفصلة تُبعث فوتونات بترددات محددة، فتظهر كخطوط منفصلة — طيف خطّي.","type":"سؤال","ministerial":true},{"question":"إلكترون انتقل من E₃=−1.51eV إلى E₁=−13.6eV (انبعاث). جد طاقة الفوتون المنبعث تقريباً.","answer":"≈12.09 eV — hf=|E₁−E₃|=|−13.6−(−1.51)|=12.09eV.","type":"سؤال","ministerial":false},{"question":"لماذا سلسلة بالمر (الانتقال إلى n=2) هي الوحيدة الواقعة (جزئياً) بالمدى المرئي؟","answer":"لأن فرق طاقتها يقابل بالضبط أطوالاً موجية بين ~400-700nm — فرق الطاقة بين المستويات العليا والمستوى الثاني يقابل تحديداً أطوالاً موجية بالمدى المرئي؛ لايمان أكبر طاقة (UV) والباقي أصغر (IR).","type":"سؤال","ministerial":false},{"question":"من أين نحصل على الطيف الخطي (لا المستمر)؟","answer":"من غازات وأبخرة متوهّجة عند ضغط اعتيادي أو واطئ — الطيف الخطي ينتج من توهّج الغازات والأبخرة عند الضغط الاعتيادي أو الواطئ.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) مم يتكوّن الطيف الخطي البرّاق لغاز الصوديوم؟","answer":"خطّان أصفران متقاربان جداً — طيف الصوديوم الخطي البرّاق يتكوّن من خطّين أصفرين متقاربين جداً — بينما طيف الهيدروجين أربعة خطوط ملوّنة.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) ما سبب ظهور خطوط فراونهوفر السوداء بطيف الشمس المستمر؟","answer":"امتصاص الغازات المحيطة بالشمس لأطوال موجية محددة من طيفها المستمر — الغازات الأبرد المحيطة بالشمس تمتصّ من طيفها المستمر تحديداً الأطوال الموجية التي كانت لتبعثها هي نفسها لو كانت متوهّجة.","type":"سؤال","ministerial":true},{"question":"طيف غاز مركّب جزيئياً (كـCO₂) متوهّج يظهر عادة على هيئة:","answer":"طيف حزمي (حزم عريضة) — المواد ذات التركيب الجزيئي تُصدر طيفاً حزمياً (حزم عريضة)، بخلاف الذرّات المفردة (خطوط رفيعة).","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري متكرر جداً) علّل: يُصنع هدف أنبوبة الأشعة السينية من مادة انصهارها درجة حرارة عالية جداً.","answer":"لأن الإلكترونات المعجَّلة تصطدم بالهدف بسرعات عالية منتجةً حرارة عالية جداً قد تُتلف مادة منخفضة الانصهار — التصادم عالي السرعة يولّد حرارة كبيرة جداً؛ مادة منخفضة الانصهار (كالتنكستن العالي الانصهار المُستعمَل فعلياً) ستتلف بسرعة.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) لماذا لا تتأثر الأشعة السينية بالمجالات الكهربائية والمغناطيسية؟","answer":"لأنها موجات كهرومغناطيسية محايدة، ليست دقائق مشحونة — الأشعة السينية موجة كهرومغناطيسية محايدة، والمجالات تؤثر فقط بالدقائق المشحونة المتحركة.","type":"سؤال","ministerial":true},{"question":"فرق جهد 40kV بأنبوبة أشعة سينية. جد أقصر طول موجي تقريباً.","answer":"≈3.1×10⁻¹¹ m — λ_min=hc/(Ve)=(6.63×10⁻³⁴×3×10⁸)/(40000×1.6×10⁻¹⁹)≈3.11×10⁻¹¹m.","type":"سؤال","ministerial":false},{"question":"ما الفرق الجوهري بين الأشعة السينية المميّزة والأشعة السينية ذات الطيف المستمر؟","answer":"المميّزة تنتج من انتقالات إلكترونية داخلية بذرّة الهدف (صفة مادته)؛ المستمرة تنتج من تباطؤ الإلكترونات المعجَّلة — المميّزة صفة ذرّية لمادة الهدف (انتزاع إلكترون داخلي وإعادة ملء)؛ المستمرة تنتج من تباطؤ الإلكترونات بمجال نوى الهدف.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري متكرر) علّل: يُعدّ تأثير كومبتن دليلاً على السلوك الجسيمي للأشعة الكهرومغناطيسية.","answer":"لأن تفسير زيادة الطول الموجي المستطار يتطلّب افتراض تصادم مرن بين الفوتون والإلكترون خاضع لحفظ الزخم والطاقة — سلوك جسيمي بحت — تفسير الزيادة بالطول الموجي يتطلّب معاملة الفوتون كجسيم له زخم محدد يتصادم تصادماً مرناً مع الإلكترون.","type":"سؤال","ministerial":true},{"question":"وفق علاقة كومبتن، على ماذا تعتمد الزيادة بالطول الموجي λ′−λ؟","answer":"على زاوية الاستطارة θ فقط — Δλ=(h/mₑc)(1−cosθ) — تعتمد فقط على زاوية الاستطارة θ، لا على شدة الحزمة أو أي عامل آخر.","type":"سؤال","ministerial":false},{"question":"فوتون استطار بزاوية 90° بتأثير كومبتن. جد مقدار الزيادة بطوله الموجي (طول موجة كومبتن=0.24×10⁻¹¹m).","answer":"≈0.24×10⁻¹¹ m — عند θ=90°: cos90°=0، فإن Δλ=(0.24×10⁻¹¹)(1−0)=0.24×10⁻¹¹m.","type":"سؤال","ministerial":false},{"question":"(مسألة وزارية مركّبة) أقصر طول موجي أشعة سينية عند V=1.24×10⁴V يساوي 0.1nm. إذا استطارت بزاوية 90° بتأثير كومبتن، فما طولها الموجي المستطار؟","answer":"0.1024 nm — λ′=λ+Δλ=0.1nm+0.0024nm=0.1024nm (حيث Δλ=(0.24×10⁻¹¹)(1−cos90°)=0.24×10⁻¹¹m=0.0024nm).","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) ماذا تعني كلمة الليزر (LASER)؟","answer":"تضخيم الضوء بوساطة الانبعاث المحفَّز للإشعاع — LASER = Light Amplification by Stimulated Emission of Radiation = تضخيم الضوء بوساطة الانبعاث المحفَّز للإشعاع.","type":"سؤال","ministerial":true},{"question":"من صمّم أول جهاز ليزر فعلياً عام 1960؟","answer":"T.H. Maiman باستعمال بلورة الياقوت — Maiman صمّم أول ليزر فعلي (ليزر الياقوت) عام 1960؛ أينشتاين وضع الأساس النظري فقط عام 1917، وتاونس صمّم الميزر لا الليزر.","type":"سؤال","ministerial":false},{"question":"أي خاصية من خصائص الليزر تفسّر أن بقعته على سطح القمر أصغر بكثير من بقعة ضوء عادي مرسَل لنفس المسافة؟","answer":"الاتجاهية (بقاء الحزمة متوازية بانفراجية قليلة) — الاتجاهية تجعل حزمة الليزر تبقى شبه متوازية لمسافات هائلة، بعكس الضوء العادي الذي ينتشر بكل الاتجاهات.","type":"سؤال","ministerial":false},{"question":"ما الفرق بين الانبعاث التلقائي والانبعاث المحفَّز؟","answer":"التلقائي عشوائي الطور والاتجاه؛ المحفَّز ينتج فوتوناً مطابقاً تماماً للفوتون المحفِّز — الانبعاث التلقائي عشوائي بلا محفِّز خارجي؛ المحفَّز ينتج فوتوناً مطابقاً تماماً (طور، اتجاه، تردد) للفوتون الذي حفّزه — أساس الليزر.","type":"سؤال","ministerial":false},{"question":"بالتوازن الحراري الطبيعي (بلا ضخّ)، أي علاقة صحيحة بين N₁ وN₂؟","answer":"N₁ أكبر من N₂ دائماً وفق قانون بولتزمان — قانون بولتزمان N₂/N₁=exp[−(E₂−E₁)/kT] يعطي دائماً نسبة أقل من 1 (لأن الأس سالب)، أي N₁>N₂.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) هل يتحقّق التوزيع المعكوس عندما تكون الطاقة الحرارية kT مساوية لطاقة الفوتون الساقط hf؟","answer":"لا، لأن التعويض يعطي N₂/N₁=exp(−1)=0.37<1 — بوضع kT=hf=E₂−E₁ بقانون بولتزمان: N₂/N₁=exp(−1)=0.37<1، أي N₂<N₁ — لا يتحقق شرط التوزيع المعكوس (N₂>N₁).","type":"سؤال","ministerial":true},{"question":"ما اسم مكونات جهاز الليزر الثلاثة؟","answer":"الوسط الفعال، المرنان، وتقنية الضخّ — كل أجهزة الليزر تشترك بثلاثة مكونات: الوسط الفعال، المرنان (مرآتان)، وتقنية الضخّ.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري متكرر حرفياً) أيّهما أفضل لتوليد الليزر: منظومة المستويات الثلاثة أم الأربعة؟","answer":"الأربعة أفضل، لأنها تتطلّب طاقة ضخّ أقل لتحقيق التوزيع المعكوس — المنظومة الرباعية أفضل لأن مستواها الأدنى للانتقال الليزري شبه فارغ أصلاً (هبوط سريع منه)، فتحتاج طاقة ضخّ أقل من الثلاثية.","type":"سؤال","ministerial":true},{"question":"أي نوع ليزر وسطه الفعال بلورة صلبة (كالياقوت أو النيديميوم)؟","answer":"ليزر الحالة الصلبة — ليزر الحالة الصلبة وسطه الفعال بلورة صلبة كالياقوت (أول ليزر بالتاريخ) أو النيديميوم.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) ما مكونات منظومات الليزرات الغازية الرئيسة؟","answer":"الوسط الفعال الغازي، المرنان، وميكانيكية الضخّ (غالباً كهربائي) — الليزرات الغازية (كالهيليوم-نيون) تتضمّن وسطاً فعالاً غازياً، مرناناً (مرآتان)، وضخّاً كهربائياً غالباً (تفريغ كهربائي بالغاز).","type":"سؤال","ministerial":true},{"question":"أي تطبيق للليزر يستثمر خاصيتي الاتجاهية والسطوع معاً بشكل مباشر لثقب المعادن وقطعها؟","answer":"التطبيقات الصناعية (لحام وقطع المعادن بحرارة منحصرة بمساحة صغيرة جداً) — تركّز الطاقة العالية (السطوع) بحزمة ضيقة جداً (الاتجاهية) يسمح بقطع المعادن ولحامها بدقة، بلا تأثير بالمناطق المجاورة.","type":"سؤال","ministerial":false},{"question":"ما الفرق بين ليزر الإكسايمر وليزر الصبغة من حيث الوسط الفعال؟","answer":"الإكسايمر: غازات نبيلة مع هالوجين (فوق بنفسجي)؛ الصبغة: محلول صبغة عضوية مذابة بمذيب — ليزر الإكسايمر يستعمل غازات نبيلة مع هالوجين (كـArF أو KrF)؛ ليزر الصبغة يستعمل محلول صبغة عضوية (كرودامين 6G) مذاباً بمذيب.","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":1,"lesson_title":"نموذج النواة وتركيبها وخصائصها","order_index":1,"hook":"هذا آخر فصل بمنهج السادس الإعدادي التجريبي على شرارة — ويأخذك إلى أصغر مقياس بالطبيعة: نواة الذرّة، مصدر أعظم طاقة اكتشفها الإنسان.","concepts":[{"term":"الأعداد الثلاثة المميِّزة للنواة:","text":"• العدد الذري Z: عدد البروتونات.\n• العدد النيوتروني N: عدد النيوترونات.\n• العدد الكتلي A: مجموع النيوكليونات = عدد البروتونات + عدد النيوترونات.","ministerial":false},{"term":"خصائص القوة النووية:","text":"① تربط وتمسك بنيوكليونات النواة معاً.\n② لا تعتمد على الشحنة — تؤثّر بين بروتون-بروتون، ونيوترون-نيوترون، وبروتون-نيوترون على حدٍّ سواء.\n③ ذات مدى قصير جداً — تؤثّر فقط ضمن أبعاد النواة نفسها.\n④ الأقوى في الطبيعة — أقوى من الكهرومغناطيسية والجاذبية والقوة النووية الضعيفة.","ministerial":false}],"laws":[{"name":"العدد الكتلي وشحنة النواة","formula":"A = Z + N\nq = Ze","variables_note":"حيث e=1.6×10⁻¹⁹C شحنة البروتون الواحدة. تُكتب رموز النواة على الصورة ₂A X (A أعلى يسار الرمز، Z أسفل يسار الرمز)."},{"name":"نصف قطر النواة","formula":"R = r₀ A^(1/3)","variables_note":"حيث r₀=1.2×10⁻¹⁵m ثابت نصف القطر. لصغر الأبعاد النووية نستعمل غالباً وحدة الفيرمي: 1F=10⁻¹⁵m، فتصبح R=1.2A^(1/3) (F)."}],"notes":[{"heading":"📐 تذكّر:","items":["بما أن R∝A^(1/3)، فمقارنة نصفي قطر نواتين تعني مقارنة الجذر التكعيبي لعدديهما الكتليين فقط.","مثال: نواة اليورانيوم (A=238) ونواة الهيليوم (A=4) — النسبة بين نصفي قطريهما تساوي (238/4)^(1/3)≈3.9 مرة فقط، رغم أن العدد الكتلي زاد ~60 ضعفاً!","(لأن الحجم يتناسب مع مكعّب R، فزيادة صغيرة نسبياً في R تعني سعة أكبر بكثير لعدد النيوكليونات)."],"ministerial":false}],"tables":[],"examples":[{"problem":"جد مقدار شحنة نواة الذهب (¹⁹⁸₇₉Au)، مع العلم أن شحنة البروتون تساوي 1.6×10⁻¹⁹C.","givens":"المعطيات: Z=79 (العدد الذري للذهب) — e=1.6×10⁻¹⁹C","solution_steps":["الخطوة: نطبّق القانون q=Ze مباشرة: q = 79 × 1.6×10⁻¹⁹ = 126.4×10⁻¹⁹ C"],"ministerial":false},{"problem":"جد نصف قطر نواة النحاس (⁶⁴₂₉Cu) بوحدة المتر ثم بوحدة الفيرمي.","givens":"المعطيات: A=64 — r₀=1.2×10⁻¹⁵m","solution_steps":["الخطوة ١: بوحدة المتر: R = 1.2×10⁻¹⁵ × (64)^(1/3) = 1.2×10⁻¹⁵ × 4 = 4.8×10⁻¹⁵ m","الخطوة ٢: بوحدة الفيرمي: R = 1.2 × (64)^(1/3) = 1.2 × 4 = 4.8 F"],"ministerial":false}],"qa":[{"question":"علّل: لا تتنافر بروتونات النواة على الرغم من تشابهها بالشحنة.","answer":"لأن هناك قوة نووية قوية تربط وتمسك بنيوكليونات النواة (القوة النووية القوية)، وهي واحدة من القوى الأربع الأساسية بالطبيعة، وهي أقوى بكثير من قوة التنافر الكهربائية الكولومية بين البروتونات، فتتغلّب عليها وتحافظ على تماسك النواة.","type":"وزاري","ministerial":true},{"question":"اذكر خصائص القوى النووية.","answer":"تربط وتمسك بنيوكليونات النواة، لا تعتمد على الشحنة، ذات مدى قصير جداً، والأقوى في الطبيعة.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"⚛️ مختبر: بانِ النواة"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":2,"lesson_title":"طاقة الربط النووية","order_index":2,"hook":"هذا \"النقص الكتلي\" هو بالضبط الطاقة التي تُبقي النواة متماسكة (القوة النووية القوية من الدرس السابق لها ثمن طاقي، ندفعه هنا). فهمه هو مفتاح كل الفصل القادم: من الانحلال الإشعاعي إلى الانشطار والاندماج.","concepts":[],"laws":[{"name":"النقص الكتلي (بكتل الذرّات)","formula":"Δm = Z·M_H + N·mₙ − M","variables_note":"حيث M_H كتلة ذرّة الهيدروجين، mₙ كتلة النيوترون، M كتلة الذرّة المعنية."},{"name":"طاقة الربط النووية","formula":"Eb = Δm·c² = (Z·M_H + N·mₙ − M)·c²","variables_note":"بما أن الكتل الذرّية تُقاس بوحدة الكتلة الذرّية (u)، فطاقة الربط تُقاس بـMeV باستعمال: c²=931 MeV/u."}],"notes":[{"heading":"🔮 لماذا هذا مهم لبقية الفصل؟","items":["أي نواة (خفيفة جداً أو ثقيلة جداً) تستطيع أن \"تتحرك\" نحو منطقة النوى المتوسطة الأكثر استقراراً تُحرّر طاقة أثناء ذلك.","النوى الثقيلة جداً تنشطر إلى نوى متوسطة (الانشطار)، والنوى الخفيفة جداً تندمج لتكوين نوى أثقل قليلاً (الاندماج) — وفي كلتا الحالتين تتحرر طاقة هائلة.","هذا بالضبط ما ستدرسه لاحقاً بهذا الفصل."],"ministerial":false}],"tables":[],"examples":[{"problem":"جد طاقة الربط النووية لنواة النيتروجين (¹⁴₇N) بوحدة MeV، ثم معدل طاقة الربط لكل نيوكليون. الكتل الذرّية: N=14.003074u، H=1.007825u، النيوترون=1.008665u.","givens":"المعطيات: Z=7 — A=14 → N=A−Z=7","solution_steps":["الخطوة ١: نطبّق القانون: Eb = [7×1.007825 + 7×1.008665 − 14.003074] × 931","الخطوة ٢: نحسب الحد داخل القوس أولاً: = [7.054775 + 7.060655 − 14.003074] × 931 = 0.112356 × 931 ≈ 104.6 MeV","الخطوة ٣: معدل الربط لكل نيوكليون: Eb' = Eb/A = 104.6/14 ≈ 7.47 MeV/nucleon"],"ministerial":false}],"qa":[{"question":"ما المقصود بطاقة الربط النووية؟","answer":"هي الطاقة المتحررة عند جمع أعداد مناسبة من البروتونات والنيوترونات لتشكيل نواة معيّنة، أو هي الطاقة اللازمة لتفكيك النواة إلى مكوّناتها من البروتونات والنيوترونات.","type":"وزاري","ministerial":true},{"question":"تكون قيم معدل طاقة الربط النووية لكل نيوكليون:","answer":"أكبر لنوى العناصر المتوسطة — مثل نواة الحديد ⁵⁶Fe، وهذا يجعلها الأكثر استقراراً بين كل نوى العناصر.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"📊 مختبر: منحنى معدل طاقة الربط"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":3,"lesson_title":"انحلال ألفا","order_index":3,"hook":"من هنا يبدأ الدرس الأول من ثلاثة عن الانحلال الإشعاعي — الطرائق التلقائية الثلاث (ألفا وبيتا وكاما) التي تسعى بها نواة غير مستقرة إلى الاستقرار.","concepts":[],"laws":[{"name":"المعادلة النووية العامة لانحلال ألفا","formula":"₂A X → ₂A⁻⁴Y⁻² + ⁴₂He","variables_note":"مثال حقيقي: ²⁴⁰₉₄Pu → ²³⁶₉₂U + ⁴₂He (البلوتونيوم ينحل إلى يورانيوم باعثاً جسيمة ألفا)"},{"name":"طاقة انحلال ألفا وشرط الانحلال التلقائي","formula":"Qα = [Mp − Md − Mα] c²","variables_note":"الشرط اللازم لانحلال النواة تلقائياً بألفا: أن تكون Qα موجبة (Qα > 0)."}],"notes":[{"heading":"📐 قاعدة ثابتة:","items":["ينحل انحلال ألفا العدد الكتلي A بمقدار ٤، والعدد الذري Z بمقدار ٢ — دائماً.","هذا يصحّ على كل انحلالات ألفا والتفاعلات النووية المشابهة، باستثناء انحلال كاما وحده (كما سترى بالدرس القادم)."],"ministerial":false}],"tables":[],"examples":[{"problem":"برهن على أن نواة الراديوم (²²⁶₈₈Ra) تحقّق شرط الانحلال التلقائي إلى نواة الرادون (²²²₈₆Rn) بوساطة انحلال ألفا، واكتب المعادلة النووية. الكتل الذرّية: He=4.002603u، Ra=226.025406u، Rn=222.017574u.","givens":"المعادلة: ²²⁶₈₈Ra → ²²²₈₆Rn + ⁴₂He","solution_steps":["الخطوة ١: نطبّق القانون: Qα = [Mp − Md − Mα] × 931","الخطوة ٢: نعوّض: Qα = [226.025406 − 222.017574 − 4.002603] × 931 = 0.005229 × 931","الخطوة ٣: Qα ≈ 4.868 MeV بما أن Qα>0، إذن تحقّق شرط الانحلال التلقائي. ∎"],"ministerial":false}],"qa":[{"question":"في المعادلة النووية: ²²⁶₈₈Ra → A₈₆Rn + ⁴₂He، جد قيمة العدد (A).","answer":"بحفظ العدد الكتلي بين طرفي المعادلة: 226 = A + 4 ⟹ A = 222.","type":"وزاري","ministerial":true},{"question":"تنحلّ نواة نظير البولونيوم (²¹⁸₈₄Po) تلقائياً إلى نواة نظير الرصاص (²¹⁴₈₂Pb). ما نوع الانحلال؟","answer":"انحلال ألفا. تحقّق: ΔA=218−214=4، وΔZ=84−82=2 — يطابق تماماً تأثير انحلال ألفا (ينقص A بمقدار 4 وZ بمقدار 2).","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🟠 مختبر: محوّل انحلال ألفا"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":4,"lesson_title":"انحلال بيتا وكاما","order_index":4,"hook":"بعكس ألفا (حل مشكلة الحجم والكتلة الزائدين)، يحل انحلال بيتا مشكلة مختلفة: خلل بنسبة النيوترونات إلى البروتونات. وانحلال كاما يحل مشكلة ثالثة: فائض طاقة فقط، بلا أي خلل بالتركيب.","concepts":[],"laws":[{"name":"انحلال النيوترون داخل النواة (بيتا السالبة)","formula":"¹₀n → ¹₁p + β⁻ + ⁰₀ν̄","variables_note":"مثال: ⁶⁴₂₉Cu → ⁶⁴₃₀Zn + β⁻ + ν̄ — لاحظ: A ثابت (64)، وZ يزداد بمقدار 1 (من 29 إلى 30)."},{"name":"انحلال البروتون داخل النواة (بيتا الموجبة)","formula":"¹₁p → ¹₀n + β⁺ + ⁰₀ν","variables_note":"مثال: ¹³₇N → ¹³₆C + β⁺ + ν. طريقة ثالثة بديلة لنفس المشكلة: الأسر الإلكتروني — تأسر النواة أحد إلكترونات مداراتها الداخلية مباشرة: ⁴¹₂₀Ca + ⁰₋₁e → ⁴¹₁₉K + ν."},{"name":"المعادلة النووية لانحلال كاما وطاقة الفوتون","formula":"²⁴⁰₉₄Pu* → ²⁴⁰₉₄Pu + ⁰₀γ\nE = hf","variables_note":"إشارة النجمة (*) تعني نواة مثارة. لاحظ: العدد الكتلي والعدد الذري يبقيان ثابتين تماماً في انحلال كاما وحده — خلافاً لكل الانحلالات والتفاعلات النووية الأخرى."}],"notes":[{"heading":"👻 النيوترينو ومضاده:","items":["جسيمان شحنتهما وكتلتهما السكونية تساويان صفراً (عددهما الذري والكتلي كلاهما صفر) — يرافقان انحلال بيتا لضمان تحقّق قوانين الحفظ (الطاقة والزخم) بدقّة."],"ministerial":false},{"heading":"🛡️ القدرة على الاختراق والتأيّن","items":["جسيمات ألفا (كتلتها كبيرة نسبياً وشحنتها +2e) لها أكبر قدرة على التأيّن لكن أقل قدرة على اختراق المواد (لا تخترق حتى ورقة أو جلد الإنسان).","أشعة كاما (متعادلة الشحنة، طاقة عالية) عكسها تماماً: أكبر قدرة على الاختراق (تحتاج دروع رصاص أو خرسانة سميكة) وأقل قدرة على التأيّن.","بيتا في المنتصف تقريباً."],"ministerial":false}],"tables":[{"caption":"💫 انحلال كاما (γ)","ministerial":false,"headers":["نوع الانحلال","التغيّر بـA","التغيّر بـZ","الجسيم المنبعث"],"rows":[["ألفا (α)","ينقص 4","ينقص 2","⁴₂He"],["بيتا سالبة (β⁻)","ثابت","يزيد 1","إلكترون + مضاد نيوترينو"],["بيتا موجبة (β⁺)","ثابت","ينقص 1","بوزترون + نيوترينو"],["كاما (γ)","ثابت","ثابت","فوتون عالي الطاقة"]]}],"examples":[],"qa":[{"question":"ما المقصود بالنيوترينو؟","answer":"جسيم يرافق انبعاث جسيمة بيتا الموجبة، شحنته وكتلته السكونية تساويان صفراً، وعدده الذري وعدده الكتلي يساويان صفراً أيضاً.","type":"وزاري","ministerial":true},{"question":"لا تنحرف أشعة كاما بتأثير المجال الكهربائي أو المغناطيسي، بينما تنحرف جسيمات ألفا وبيتا.","answer":"لأن أشعة كاما فوتونات كهرومغناطيسية متعادلة الشحنة تماماً (شحنتها صفر)، والمجالات الكهربائية والمغناطيسية لا تؤثّر إلا في الجسيمات المشحونة المتحركة — بينما جسيمات ألفا موجبة الشحنة وجسيمات بيتا سالبة أو موجبة الشحنة، فتنحرف كلتاهما تحت تأثير هذه المجالات.","type":"علل","ministerial":false}],"has_simulation":true,"simulation_title":"🔍 مختبر: مصنّف نوع الانحلال"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":5,"lesson_title":"التفاعلات النووية","order_index":5,"hook":"هذا الدرس هو الجسر بين \"ما يحدث تلقائياً\" (الدرسان السابقان) و\"ما نصنعه نحن عمداً\" — أساس الانشطار والاندماج اللذين ستدرسهما بالدرسين القادمين.","concepts":[{"term":"قوانين الحفظ الخمسة:","text":"① حفظ (الطاقة–الكتلة).\n② حفظ الزخم الخطي.\n③ حفظ الزخم الزاوي.\n④ حفظ الشحنة الكهربائية (أي حفظ العدد الذري Z).\n⑤ حفظ عدد النيوكليونات (أي حفظ العدد الكتلي A).","ministerial":false}],"laws":[{"name":"أول تفاعل نووي محتث","formula":"⁴₂He + ¹⁴₇N → ¹⁷₈O + ¹₁H","variables_note":"(جسيمة ألفا) + (نواة نيتروجين) → (نواة أوكسجين) + (بروتون). المعادلة موزونة: مجموع الأعداد الذرية ومجموع الأعداد الكتلية متساويان بطرفيها (2+7=9=8+1، و4+14=18=17+1)."},{"name":"طاقة التفاعل النووي","formula":"Q = [(Ma + Mx) − (MY + Mb)] c²","variables_note":"Q موجبة ⟵ تفاعل محرِّر للطاقة. Q سالبة ⟵ تفاعل ماص للطاقة (يحتاج طاقة خارجية ليحدث)."}],"notes":[{"heading":"⚪ لماذا النيوترون قذيفة مثالية؟","items":["شحنة النيوترون تساوي صفراً، فهو يستطيع أن يدخل إلى النواة بسهولة كبيرة جداً — أكبر بكثير من جسيمات ألفا أو البروتونات (الموجبتين الشحنة) — وذلك لعدم وجود قوة كولوم الكهربائية التنافرية بينه وبين النواة الموجبة الشحنة."],"ministerial":false}],"tables":[],"examples":[{"problem":"في التفاعل النووي: ⁴₂He + ¹⁴₇N → ¹⁷₈O + ¹₁H، جد قيمة طاقة التفاعل بوحدة MeV، وبيّن نوعيته. الكتل الذرّية: N=14.003074u، He=4.002603u، O=16.999132u، H=1.007825u.","givens":"المعطيات: Ma=4.002603 — Mx=14.003074 — MY=16.999132 — Mb=1.007825","solution_steps":["الخطوة ١: نطبّق القانون: Q = [4.002603 + 14.003074 − 16.999132 − 1.007825] × 931","الخطوة ٢: Q = (−0.001280) × 931 ≈ −1.19 MeV","الخطوة ٣: بما أن Q سالبة، إذن التفاعل ماص للطاقة — يحتاج جسيمة ألفا ساقطة بطاقة حركية كافية لتعويض هذا العجز حتى يحدث فعلياً."],"ministerial":false}],"qa":[{"question":"علّل: تُعدّ النيوترونات قذائف مهمة في التفاعلات النووية.","answer":"لأن شحنة النيوترون تساوي صفراً، فهو يستطيع أن يدخل إلى النواة بسهولة كبيرة جداً (أكثر من جسيمات ألفا أو البروتونات)، وذلك لعدم وجود قوة كولوم الكهربائية التنافرية بينه وبين النواة الموجبة الشحنة.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"⚖️ مختبر: موازن المعادلة النووية"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":6,"lesson_title":"الانشطار النووي","order_index":6,"hook":"تذكّر من الدرس الثاني: النوى المتوسطة (كالحديد) هي الأكثر استقراراً. الانشطار يستثمر هذه الحقيقة بالضبط: يكسر نواة ثقيلة جداً (غير مستقرة نسبياً) إلى نواتين متوسطتين (أكثر استقراراً)، محرِّراً الفرق كطاقة هائلة.","concepts":[],"laws":[{"name":"معادلة انشطار اليورانيوم النموذجية","formula":"¹₀n + ²³⁵₉₂U → ²³⁶₉₂U* → ¹⁴¹₅₆Ba + ⁹²₃₆Kr + 3¹₀n","variables_note":"²³⁶₉₂U* هي نواة اليورانيوم المركّبة المتهيّجة، تنشطر فوراً تقريباً إلى الباريوم والكريبتون + ثلاثة نيوترونات جديدة."}],"notes":[{"heading":"⚡ من أين الطاقة الهائلة؟","items":["مجموع كتل النواتج أقل من مجموع كتل المتفاعلين — الفرق يتحوّل إلى طاقة وفق E=mc².","تتحرر طاقة تُقدَّر بنحو 200 MeV عند انشطار نواة يورانيوم واحدة فقط — أكبر بكثير من أي تفاعل كيميائي (احتراق مثلاً) لنفس الكتلة."],"ministerial":false}],"tables":[],"examples":[],"qa":[],"has_simulation":true,"simulation_title":"🔗 مختبر: التفاعل النووي المتسلسل"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":7,"lesson_title":"الاندماج النووي","order_index":7,"hook":"إن كان الانشطار (الدرس السابق) يكسر نواة ثقيلة إلى نواتين أخف، فالاندماج يفعل العكس تماماً: يدمج نواتين خفيفتين في نواة واحدة أثقل قليلاً — وكلاهما يستثمر نفس الحقيقة: النوى المتوسطة هي الأكثر استقراراً.","concepts":[],"laws":[{"name":"مثال على اندماج نظائر الهيدروجين","formula":"²₁H + ³₁H → ⁴₂He + n + 17.6 MeV","variables_note":""}],"notes":[{"heading":"🧲 حصر البلازما: التوكاماك","items":["لا يوجد وعاء مادي يتحمّل ملامسة بلازما بهذه الحرارة الهائلة!","لذا يسعى العلماء لحصرها بلا تلامس مباشر، غالباً باستعمال مجال مغناطيسي قوي يحبس البلازما بعيداً عن جدران الحاوية — كما بجهاز التوكاماك (Tokamak)."],"ministerial":false}],"tables":[{"caption":"💣 القنبلة الهيدروجينية","ministerial":false,"headers":["المقارنة","الانشطار","الاندماج"],"rows":[["النوى المتفاعلة","نواة ثقيلة واحدة تنقسم","نواتان خفيفتان تتحدان"],["الناتج","نواتان متوسطتان + نيوترونات","نواة أثقل قليلاً (+جسيم أحياناً)"],["الطاقة لكل وحدة كتلة وقود","كبيرة","أكبر من الانشطار"],["النفايات المشعة","نوى وليدة مشعة، خطرة لفترات طويلة","نواتج غالباً غير مشعة (كالهيليوم)"]]}],"examples":[],"qa":[],"has_simulation":true,"simulation_title":"🌡️ مختبر: التغلّب على حاجز كولوم"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":8,"lesson_title":"مخاطر وفوائد الإشعاع النووي","order_index":8,"hook":"هذا آخر درس بمنهج السادس الإعدادي التجريبي بأكمله على شرارة — يختم رحلة بدأت من مستويات الطاقة بالذرّة (الفصل السابع)، مروراً بالأطياف والليزر (الفصل الثامن)، وانتهاءً بأعمق أعماق المادة: نواة الذرّة.","concepts":[{"term":"① الإشعاع الخلفي الطبيعي:","text":"الأشعة الكونية، والإشعاع النووي من القشرة الأرضية، والنشاط الإشعاعي داخل جسم الإنسان نفسه.","ministerial":false},{"term":"② الإشعاع الاصطناعي:","text":"المصادر الطبية (تشخيص وعلاج)، النفايات النووية المشعة، الغبار المتساقط من اختبارات الأسلحة النووية، إشعاعات المفاعلات، ومصادر البحوث والدراسات.","ministerial":false},{"term":"نوعا التأثير:","text":"• تأثيرات جسدية: ضرر بالخلايا الاعتيادية — مبكرة (كالتهاب الجلد) أو متأخرة (كمرض السرطان).\n• تأثيرات وراثية: ضرر بالخلايا التناسلية — قد يسبب ولادات مشوّهة، وينتقل إلى الأجيال اللاحقة.","ministerial":false}],"laws":[],"notes":[{"heading":"⚖️ خلاصة الفصل: الطاقة نفسها، استعمالان متناقضان","items":["نفس مبدأ E=mc² الذي يُبقي النواة متماسكة (طاقة الربط)، ويُطلق طاقة هائلة بالانشطار والاندماج، وينقل النواة نحو الاستقرار بالانحلال الإشعاعي — هو ما يُنتج الطاقة الكهربائية بالمفاعلات السلمية، ويُشخِّص الأورام ويعالجها بالطب، لكنه أيضاً القوة المدمِّرة بالأسلحة النووية.","الفارق ليس بالفيزياء نفسها، بل بكيفية استعمال الإنسان لها."],"ministerial":false}],"tables":[{"caption":"💚 الاستعمالات السلمية المفيدة","ministerial":false,"headers":["المجال","الاستعمال"],"rows":[["🏥 المجال الطبي","القضاء على كائنات مرضية مسبِّبة لأمراض (كالفيروسات)، وتعقيم المستلزمات الطبية، وتشخيص وعلاج بعض الأورام"],["🌾 المجال الزراعي","دراسة فسلجة النبات وتغذيته، وحفظ المواد الغذائية (تعقيم إشعاعي يطيل صلاحيتها)"],["🏭 المجال الصناعي","تسيير المركبات الفضائية، والسفن البحرية، والغواصات (طاقة نووية طويلة الأمد)"]]}],"examples":[],"qa":[{"question":"ما الإجراء الاحترازي اللازم اتخاذه لكي نقي أنفسنا من مخاطر الإشعاع النووي الخارجي الذي قد نتعرّض له اضطرارياً؟","answer":"يجب إبقاء التعرّض إلى أقل ما يمكن، من خلال: تقليل زمن التعرّض للإشعاع النووي إلى أقل ما يمكن، الابتعاد عن مصدر الإشعاع أكثر ما يمكن، واستعمال الحواجز الواقية الملائمة (درع، كمادة الرصاص مثلاً) بين الإنسان ومصدر الإشعاع.","type":"وزاري","ministerial":true}],"has_simulation":true,"simulation_title":"🛡️ مختبر: الإجراءات الاحترازية الثلاثة"},{"chapter_number":"g6c9","chapter_title":"الفيزياء النووية","lesson_number":9,"lesson_title":"أسئلة ومسائل نهاية الفصل","order_index":9,"hook":"","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"question":"(سؤال وزاري متكرر) نصف قطر النواة (R) يتغيّر: <span class='wz'>تمهيدي 2017 · الدور الأول 2019 · تمهيدي 2022</span>","answer":"طردياً مع A^(1/3) — R=r₀A^(1/3) — علاقة طردية مع الجذر التكعيبي للعدد الكتلي.","type":"سؤال","ministerial":true},{"question":"جد شحنة نواة عنصر عدده الذري Z=26 (شحنة البروتون 1.6×10⁻¹⁹C).","answer":"41.6×10⁻¹⁹C — q=Ze=26×1.6×10⁻¹⁹=41.6×10⁻¹⁹C.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري — علّل) لا تتنافر بروتونات النواة على الرغم من تشابهها بالشحنة. <span class='wz'>تمهيدي 2021 · الدور الأول 2019 و2022 و2023-2024</span>","answer":"لأن هناك قوة نووية قوية أقوى بكثير من التنافر الكهربائي الكولومي تربط وتمسك بنيوكليونات النواة — القوة النووية القوية أقوى بكثير من قوة التنافر الكهربائي الكولومي بين البروتونات، فتتغلّب عليها وتحافظ على تماسك النواة.","type":"سؤال","ministerial":true},{"question":"جد نصف قطر نواة الحديد (⁵⁶₂₆Fe) بوحدة الفيرمي تقريباً (استعمل (56)^(1/3)≈3.83).","answer":"≈4.6 F — R=1.2×(56)^(1/3)≈1.2×3.83≈4.6F.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) ما المقصود بطاقة الربط النووية؟ <span class='wz'>تمهيدي 2020</span>","answer":"الطاقة المتحررة عند جمع البروتونات والنيوترونات لتشكيل نواة، أو الطاقة اللازمة لتفكيك النواة إلى مكوّناتها — طاقة الربط النووية: الطاقة المتحررة عند تكوّن النواة من مكوّناتها منفصلة، أو المطلوبة لتفكيكها إليها ثانية.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — اختيار) تكون قيم معدل طاقة الربط النووية لكل نيوكليون أكبر لنوى: <span class='wz'>الدور الثالث 2018</span>","answer":"العناصر المتوسطة (كالحديد ⁵⁶Fe) — معدل طاقة الربط Eb' يبلغ ذروته عند النوى المتوسطة، فتكون الأكثر استقراراً.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — تطابق تام بنفس الأرقام) جد طاقة الربط النووية لنواة النيتروجين (¹⁴₇N)، علماً أن كتلة ذرّته 14.003074u، وكتلة الهيدروجين 1.007825u، وكتلة النيوترون 1.008665u. <span class='wz'>الدور الأول 2021-2022</span>","answer":"≈104.6 MeV — Eb=[7×1.007825+7×1.008665−14.003074]×931=0.112356×931≈104.6MeV.","type":"سؤال","ministerial":true},{"question":"نواة عددها الكتلي A=20 وطاقة ربطها الكلية Eb=140MeV. جد معدل طاقة الربط لكل نيوكليون Eb'.","answer":"7 MeV/nucleon — Eb'=Eb/A=140/20=7 MeV/nucleon.","type":"سؤال","ministerial":false},{"question":"ما جسيمة ألفا (α) في الحقيقة؟","answer":"نواة ذرّة الهيليوم (⁴₂He): بروتونان ونيوترونان — جسيمة ألفا هي نواة الهيليوم بالضبط، شحنتها +2e.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) في المعادلة: ²²⁶₈₈Ra → A₈₆Rn + ⁴₂He، جد قيمة العدد A. <span class='wz'>تمهيدي 2017</span>","answer":"222 — بحفظ العدد الكتلي: 226=A+4 ⟹ A=222.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — برهان بنفس الأرقام حرفياً) نواة الراديوم (²²⁶₈₈Ra) تنحلّ إلى نواة الرادون (²²²₈₆Rn) بألفا. الكتل: He=4.002603u، Ra=226.025406u، Rn=222.017574u. جد طاقة الانحلال Qα، وهل يحدث تلقائياً؟ <span class='wz'>تمهيدي 2019</span>","answer":"Qα≈4.868 MeV؛ يحدث تلقائياً (Qα>0) — Qα=[226.025406−222.017574−4.002603]×931≈4.868MeV، وبما أنها موجبة فالانحلال تلقائي.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) تنحلّ نواة البولونيوم (²¹⁸₈₄Po) إلى نواة الرصاص (²¹⁴₈₂Pb). ما نوع هذا الانحلال؟ <span class='wz'>الدور الثالث 2019 · الدور الثاني 2019</span>","answer":"ألفا — ΔA=218−214=4 وΔZ=84−82=2 — يطابق تماماً نمط انحلال ألفا.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري — اختيار) عندما تعاني نواة انحلال بيتا السالبة تلقائياً، فإن عددها الذري: <span class='wz'>الدور الأول 2017 · تمهيدي 2018</span>","answer":"يزداد بمقدار واحد — أحد نيوترونات النواة يتحوّل إلى بروتون، فيزداد Z بمقدار 1، بينما A يبقى ثابتاً.","type":"سؤال","ministerial":true},{"question":"(سؤال وزاري) ما المقصود بالنيوترينو؟ <span class='wz'>الدور الثاني 2019</span>","answer":"جسيم يرافق بيتا الموجبة، شحنته وكتلته السكونية صفر، وعدداه الذري والكتلي صفر — النيوترينو جسيم متعادل عديم الكتلة السكونية تقريباً، يرافق انحلال بيتا الموجبة لضمان قوانين الحفظ.","type":"سؤال","ministerial":true},{"question":"ما الذي يبقى ثابتاً تماماً في انحلال كاما وحده، خلافاً لكل الانحلالات الأخرى؟","answer":"العدد الكتلي A والعدد الذري Z معاً — انحلال كاما لا يغيّر تركيب النواة، بل يحرّر فائض طاقة فقط (فوتون) — فيبقى A وZ ثابتين.","type":"سؤال","ministerial":false},{"question":"(علل) لا تنحرف أشعة كاما بتأثير المجال الكهربائي أو المغناطيسي، بينما تنحرف جسيمات ألفا وبيتا.","answer":"لأن كاما فوتونات متعادلة الشحنة تماماً، والمجالات لا تؤثر إلا بالجسيمات المشحونة المتحركة — غياب أي شحنة عن فوتونات كاما يجعلها غير متأثرة بالمجالات الكهربائية والمغناطيسية، بعكس ألفا (+2e) وبيتا (±e).","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري — علّل) تُعدّ النيوترونات قذائف مهمة في التفاعلات النووية. <span class='wz'>2023-2024 الدور الأول</span>","answer":"لأن شحنة النيوترون صفر، فلا تصدّه قوة كولوم التنافرية عند اقترابه من النواة الموجبة — غياب الشحنة عن النيوترون يلغي التنافر الكهربائي مع النواة، فيدخلها بسهولة أكبر بكثير من الجسيمات المشحونة.","type":"سؤال","ministerial":true},{"question":"ما قوانين الحفظ الخمسة التي يجب أن تتحقق في أي تفاعل نووي؟","answer":"حفظ الطاقة-الكتلة، الزخم الخطي، الزخم الزاوي، الشحنة (Z)، وعدد النيوكليونات (A) — التفاعل النووي يجب أن يحقق معاً: حفظ الطاقة-الكتلة، الزخم الخطي، الزخم الزاوي، الشحنة الكهربائية، وعدد النيوكليونات.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري — بنفس الأرقام) في التفاعل: ⁴₂He + ¹⁴₇N → ¹⁷₈O + ¹₁H، جد طاقة التفاعل Q. الكتل: N=14.003074u، He=4.002603u، O=16.999132u، H=1.007825u. <span class='wz'>تمهيدي 2018</span>","answer":"Q≈−1.19 MeV؛ ماص للطاقة — Q=[4.002603+14.003074−16.999132−1.007825]×931≈−1.19MeV؛ القيمة سالبة فالتفاعل ماص للطاقة.","type":"سؤال","ministerial":true},{"question":"في تفاعل: ¹₀n + ²⁷₁₃Al → ²⁴₁₁Na + Y، ما الجسيم الناتج Y؟","answer":"جسيمة ألفا ⁴₂He — حفظ A: 1+27=24+A_Y ⟹ A_Y=4. حفظ Z: 0+13=11+Z_Y ⟹ Z_Y=2. إذن Y=⁴₂He (جسيمة ألفا).","type":"سؤال","ministerial":false},{"question":"ما تعريف الانشطار النووي؟","answer":"انقسام نواة ثقيلة إلى نواتين متوسطتي الكتلة، عادة بقصفها بنيوترون بطيء — الانشطار يقسّم نواة ثقيلة كاليورانيوم إلى نواتين متوسطتين، بامتصاص نيوترون حراري بطيء.","type":"سؤال","ministerial":false},{"question":"كم نيوتروناً جديداً يُنتَج تقريباً من كل انشطار نموذجي لليورانيوم؟","answer":"اثنان أو ثلاثة نيوترونات تقريباً — الانشطار ينتج نموذجياً 2 أو 3 نيوترونات جديدة، أساس استمرار التفاعل المتسلسل.","type":"سؤال","ministerial":false},{"question":"ماذا يعني أن معامل التضاعف k يساوي 1 بالضبط بتفاعل متسلسل؟","answer":"حالة حرجة مضبوطة، تفاعل ثابت متحكَّم به كما بالمفاعل النووي — k=1 يعني إنتاج نيوترون فعّال واحد بالمتوسط لكل انشطار، فيستمر التفاعل بمعدل ثابت — هذا مبدأ عمل المفاعل النووي.","type":"سؤال","ministerial":false},{"question":"من حقّق أول تفاعل نووي انشطاري متسلسل مسيطر عليه، وأين وفي أي عام؟","answer":"فيرمي وفريقه، بشيكاغو، 1942 — حقّق إنريكو فيرمي وفريقه أول تفاعل نووي متسلسل مسيطر عليه بأول مفاعل نووي بجامعة شيكاغو عام 1942.","type":"سؤال","ministerial":false},{"question":"ما العملية الرئيسة المسؤولة عن إنتاج طاقة الشمس؟","answer":"دورة بروتون-بروتون: اندماج نوى الهيدروجين لتكوين الهيليوم — دورة بروتون-بروتون (اندماج نوى الهيدروجين لتكوين الهيليوم) هي مصدر طاقة الشمس الرئيس، عند حرارة باطنها ~1.5×10⁷K.","type":"سؤال","ministerial":false},{"question":"ما العائق الرئيس أمام تحقيق اندماج نووي مفيد؟","answer":"قوة تنافر كولوم الكهربائية الكبيرة بين النوى الموجبة عند المسافات القصيرة — تنافر كولوم بين النوى الموجبة يمنعها من الاقتراب كفاية لدخول مدى القوة النووية القوية، إلا بطاقة حركية هائلة (حرارة عالية جداً).","type":"سؤال","ministerial":false},{"question":"ما الفرق الأساسي بين نفايات الانشطار والاندماج النوويين؟","answer":"نواتج الانشطار غالباً مشعة وخطرة لفترات طويلة، ونواتج الاندماج (كالهيليوم) غالباً غير مشعة — نواتج الانشطار عادة نوى مشعة تبقى خطرة طويلاً، بينما نواتج الاندماج (كالهيليوم) نظير مستقر غير مشعّ عادة.","type":"سؤال","ministerial":false},{"question":"(سؤال وزاري) ما الإجراء الاحترازي اللازم لتقليل التعرّض الاضطراري للإشعاع النووي الخارجي؟ <span class='wz'>الدور الثالث 2019</span>","answer":"تقليل زمن التعرّض، الابتعاد عن المصدر، واستعمال درع واقٍ ملائم — الإجراءات الثلاثة: تقليل زمن التعرّض، الابتعاد عن المصدر، واستعمال حواجز واقية ملائمة (كالرصاص).","type":"سؤال","ministerial":true},{"question":"ما الفرق بين التأثيرات الجسدية والوراثية للإشعاع النووي على جسم الإنسان؟","answer":"الجسدية ضرر بالخلايا الاعتيادية (كالسرطان)، والوراثية ضرر بالخلايا التناسلية ينتقل للأجيال اللاحقة — الجسدية تصيب خلايا الجسم الاعتيادية (مبكرة أو متأخرة كالسرطان)؛ الوراثية تصيب الخلايا التناسلية وتنتقل للنسل.","type":"سؤال","ministerial":false},{"question":"أي مادة كثيفة تُستعمل غالباً كدرع واقٍ فعّال ضد أشعة كاما عالية الاختراق؟","answer":"الرصاص أو الخرسانة السميكة — المواد الكثيفة كالرصاص أو الخرسانة السميكة قادرة على امتصاص جزء كبير من أشعة كاما، بعكس الورق الذي يوقف ألفا فقط.","type":"سؤال","ministerial":false}],"has_simulation":false,"simulation_title":""}]);